INSERT INTO exercises (id, name, slug, description, category, difficulty, instructions, media_object_key) VALUES
('01a0baa8-423b-7721-b2b6-bb0ff6177fed', 'cable standing lift', 'cable-standing-lift', 'cable standing lift using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing the cable machine with your feet shoulder-width apart.', 'Hold the cable handle with both hands and position it at waist height.', 'Engage your core and maintain a straight back throughout the exercise.', 'Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.', 'Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/qFpAkpP.gif'),
('01a0baa8-423b-7721-b2b7-f1ffa19704f5', 'weighted standing curl', 'weighted-standing-curl', 'weighted standing curl using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.', 'Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.', 'Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/M5Y7GPg.gif'),
('01a0baa8-423b-7721-b2b8-84fdd3bc9ce4', 'dumbbell lying on floor rear delt raise', 'dumbbell-lying-on-floor-rear-delt-raise', 'dumbbell lying on floor rear delt raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on the floor with a dumbbell in each hand, palms facing each other.', 'Extend your arms straight out in front of you, keeping a slight bend in your elbows.', 'Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Ion0XWz.gif'),
('01a0baa8-423b-7721-b2b9-dc15ac08fcb6', 'band one arm overhead biceps curl', 'band-one-arm-overhead-biceps-curl', 'band one arm overhead biceps curl using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place one end of the band under your foot.', 'Hold the other end of the band with your arm fully extended overhead, palm facing forward.', 'Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.', 'Pause for a moment at the top, then slowly lower your forearm back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/UNAB8ak.gif'),
('01a0baa8-423b-7721-b2ba-2e5287687511', 'dumbbell biceps curl squat', 'dumbbell-biceps-curl-squat', 'dumbbell biceps curl squat using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.', 'Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/niXESDw.gif'),
('01a0baa8-423b-7721-b2bb-e532eef80a82', 'barbell lying preacher curl', 'barbell-lying-preacher-curl', 'barbell lying preacher curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/SYJ4Bkt.gif'),
('01a0baa8-423b-7721-b2bc-1bbac4e77387', 'dumbbell one arm hammer preacher curl', 'dumbbell-one-arm-hammer-preacher-curl', 'dumbbell one arm hammer preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.', 'Hold the dumbbell with a neutral grip (palms facing your body).', 'Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/4dF3maG.gif'),
('01a0baa8-423b-7721-b2bd-c23e5a8a24f1', 'dumbbell incline one arm hammer press on exercise ball', 'dumbbell-incline-one-arm-hammer-press-on-exercise-ball', 'dumbbell incline one arm hammer press on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with a dumbbell in one hand.', 'Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.', 'Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.', 'Press the dumbbell up towards the ceiling, straightening your arm.', 'Lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/jDnrkar.gif'),
('01a0baa8-423b-7721-b2be-44d51b34d2b0', 'shoulder grip pull-up', 'shoulder-grip-pull-up', 'shoulder grip pull-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Grab the pull-up bar with a shoulder-width grip, palms facing away from you.', 'Hang freely with your arms fully extended.', 'Engage your back muscles and pull your body up towards the bar until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/YtgD7Xq.gif'),
('01a0baa8-423b-7721-b2bf-164d57297682', 'cable reverse-grip straight back seated high row', 'cable-reverse-grip-straight-back-seated-high-row', 'cable reverse-grip straight back seated high row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the seat facing the cable machine with your feet flat on the floor.', 'Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.', 'Keep your back straight and lean slightly forward from your hips.', 'Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.', 'Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/PNtsX17.gif'),
('01a0baa8-423b-7721-b2c0-066465185173', 'smith seated shoulder press', 'smith-seated-shoulder-press', 'smith seated shoulder press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height so that the handles are at shoulder level.', 'Sit on the machine with your back against the pad and your feet flat on the floor.', 'Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.', 'Lower the handles down to shoulder level, keeping your elbows slightly bent.', 'Press the handles up overhead until your arms are fully extended.', 'Pause for a moment at the top, then slowly lower the handles back down to shoulder level.', 'Repeat for the desired number of repetitions.'], 'exercises/xUwnBMT.gif'),
('01a0baa8-423b-7721-b2c1-ebd13b4a7b92', 'muscle-up (on vertical bar)', 'muscle-up-on-vertical-bar', 'muscle-up (on vertical bar) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.', 'Engage your core and pull your body up towards the bar, leading with your chest.', 'As you pull yourself up, lean back slightly and bring your elbows towards your sides.', 'Continue pulling until your chest reaches the bar and your elbows are fully bent.', 'Pause for a moment at the top, then slowly lower yourself back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Af0EW2I.gif'),
('01a0baa8-423b-7721-b2c2-807315845f2e', 'sled 45 degrees one leg press', 'sled-45-degrees-one-leg-press', 'sled 45 degrees one leg press using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the sled machine to a 45-degree angle.', 'Sit on the sled machine with your back against the pad and your feet on the footplate.', 'Place one foot on the footplate and extend your leg, pushing the sled away from you.', 'Slowly bend your knee and lower the sled back to the starting position.', 'Repeat with the other leg.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/WWD6FzI.gif'),
('01a0baa8-423b-7721-b2c3-5338376c1f31', 'band wrist curl', 'band-wrist-curl', 'band wrist curl using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the ground.', 'Hold the band with both hands, palms facing up, and rest your forearms on your thighs.', 'Slowly curl your wrists upward, squeezing your forearms.', 'Pause for a moment at the top, then slowly lower your wrists back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vUTfFHw.gif'),
('01a0baa8-423b-7721-b2c4-3ccdbc5dadb9', 'dumbbell decline bench press', 'dumbbell-decline-bench-press', 'dumbbell decline bench press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie down on a decline bench with your feet secured and your head lower than your hips.', 'Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.', 'Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.', 'Push the dumbbells back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/DwhEmmE.gif'),
('01a0baa8-423b-7721-b2c5-61bec66c03df', 'triceps press', 'triceps-press', 'triceps press using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Extend your arms straight out in front of you, parallel to the ground.', 'Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.', 'Pause for a moment at the bottom, then push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/fSrPP6B.gif'),
('01a0baa8-423b-7721-b2c6-b4c7571589fa', 'cable seated overhead curl', 'cable-seated-overhead-curl', 'cable seated overhead curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench facing the cable machine with your feet flat on the ground.', 'Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.', 'Keep your upper arms stationary and your elbows close to your sides.', 'Exhale and curl the cable attachment towards your shoulders, contracting your biceps.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/DpWMFP5.gif'),
('01a0baa8-423b-7721-b2c7-8bb763ed7a37', 'dumbbell incline one arm press', 'dumbbell-incline-one-arm-press', 'dumbbell incline one arm press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in one hand, resting on your thigh.', 'Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.', 'Press the dumbbell upward and slightly inward, extending your arm fully.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/rDAiRf9.gif'),
('01a0baa8-423b-7721-b2c8-31c02daa3c4c', 'cable kneeling crunch', 'cable-kneeling-crunch', 'cable kneeling crunch using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope handle to a high pulley and kneel down facing away from the machine.', 'Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.', 'Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.', 'Pause for a moment at the bottom, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/WW95auq.gif'),
('01a0baa8-423b-7721-b2c9-320805665720', 'chair leg extended stretch', 'chair-leg-extended-stretch', 'chair leg extended stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the edge of a chair with your back straight and feet flat on the ground.', 'Extend one leg straight out in front of you, keeping your heel on the ground.', 'Lean forward slightly, feeling a stretch in your quadriceps.', 'Hold this position for 20-30 seconds.', 'Switch legs and repeat the stretch.'], 'exercises/xGgAGPm.gif'),
('01a0baa8-423b-7721-b2ca-7aa3e3b82201', 'band vertical pallof press', 'band-vertical-pallof-press', 'band vertical pallof press using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.', 'Hold the band with both hands and step away from the anchor point, creating tension in the band.', 'Position yourself perpendicular to the anchor point, with your side facing the band.', 'Extend your arms straight out in front of you, keeping your hands at chest height.', 'Engage your core and press the band away from your chest, fully extending your arms.', 'Hold the position for a few seconds, then slowly bring the band back towards your chest.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/G7PXMlT.gif'),
('01a0baa8-423b-7721-b2cb-17273268f2fa', 'push-up to side plank', 'push-up-to-side-plank', 'push-up to side plank using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands shoulder-width apart and your body in a straight line.', 'Lower your body towards the ground by bending your elbows, keeping your core engaged.', 'Push back up to the starting position.', 'Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.', 'Hold the side plank position for a few seconds, then return to the starting position.', 'Repeat the push-up and side plank on the opposite side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/KhHJ338.gif'),
('01a0baa8-423c-7170-8a10-40e084f3209e', 'dumbbell seated one arm bicep curl on exercise ball with leg raised', 'dumbbell-seated-one-arm-bicep-curl-on-exercise-ball-with-leg-raised', 'dumbbell seated one arm bicep curl on exercise ball with leg raised using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in one hand with your palm facing up and your arm fully extended.', 'Place your other hand on your hip for stability.', 'Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.', 'Pause for a moment at the top of the movement, squeezing your bicep.', 'Slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.', 'Switch arms and repeat the exercise.'], 'exercises/84sESNy.gif'),
('01a0baa8-423c-7170-8a11-402996b65625', 'barbell sitted alternate leg raise (female)', 'barbell-sitted-alternate-leg-raise-female', 'barbell sitted alternate leg raise (female) using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and hold a barbell across your thighs.', 'Place your hands on the sides of the bench for support.', 'Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.', 'Lower the leg back down and repeat with the other leg.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/BCs0G2F.gif'),
('01a0baa8-423c-7170-8a12-4443e0de5e52', 'dumbbell seated calf raise', 'dumbbell-seated-calf-raise', 'dumbbell seated calf raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.', 'Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.', 'Hold onto the dumbbell for stability.', 'Raise your heels as high as possible, lifting your body weight onto the balls of your feet.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/r29jP7S.gif'),
('01a0baa8-423c-7170-8a13-4b2fea1fb50b', 'dumbbell cuban press', 'dumbbell-cuban-press', 'dumbbell cuban press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.', 'Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.', 'Rotate your wrists so that your palms are facing forward.', 'Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.', 'Repeat for the desired number of repetitions.'], 'exercises/QfAKy1G.gif'),
('01a0baa8-423c-7170-8a14-4c762f4916da', 'elevator', 'elevator', 'elevator using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Place your hands on your hips or cross them in front of your chest.', 'Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.', 'Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/zYmNaoY.gif'),
('01a0baa8-423c-7170-8a15-532977cb17a2', 'smith deadlift', 'smith-deadlift', 'smith deadlift using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up the smith machine with the bar at hip height.', 'Stand with your feet shoulder-width apart, toes pointing slightly outward.', 'Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.', 'Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.', 'Stand up straight, fully extending your hips and knees.', 'Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.', 'Repeat for the desired number of repetitions.'], 'exercises/UfePqpx.gif'),
('01a0baa8-423c-7170-8a16-9a7ec947ad3f', 'band standing rear delt row', 'band-standing-rear-delt-row', 'band standing rear delt row using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place the band under your feet.', 'Hold the band handles with your palms facing each other and your arms extended in front of you.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Pull the band towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/tc5dYrf.gif'),
('01a0baa8-423c-7170-8a17-9d909fad5f5a', 'ski ergometer', 'ski-ergometer', 'ski ergometer using skierg machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and footrests to a comfortable position.', 'Grasp the handles with an overhand grip, palms facing down.', 'Sit up straight with your feet flat on the footrests.', 'Extend your arms straight out in front of you, keeping your elbows slightly bent.', 'Engage your triceps and push the handles down towards your thighs.', 'Pause for a moment at the bottom, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vpQaQkH.gif'),
('01a0baa8-423c-7170-8a18-b624e42764b9', 'side lying floor stretch', 'side-lying-floor-stretch', 'side lying floor stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie on your side with your legs straight and your bottom arm extended straight overhead.', 'Bend your top knee and place your foot on the ground in front of your bottom leg.', 'Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.', 'Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.', 'Hold the stretch for 20-30 seconds, then slowly lower your leg back down.', 'Repeat on the other side.'], 'exercises/jDOKRM5.gif'),
('01a0baa8-423c-7170-8a19-8c5010fea77b', 'dumbbell peacher hammer curl', 'dumbbell-peacher-hammer-curl', 'dumbbell peacher hammer curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your torso.', 'Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.', 'This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.'], 'exercises/F1KxjBa.gif'),
('01a0baa8-423c-7170-8a1a-88c88d4d0f70', 'barbell good morning', 'barbell-good-morning', 'barbell good morning using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.', 'Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.', 'Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.', 'Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.', 'Repeat for the desired number of repetitions.'], 'exercises/XlZ4lAC.gif'),
('01a0baa8-423c-7170-8a1b-4facc5c4d45d', 'power point plank', 'power-point-plank', 'power point plank using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.', 'Engage your core and squeeze your glutes to maintain a stable position.', 'Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.', 'Hold this position for the desired amount of time, keeping your core and glutes engaged.', 'To return to the starting position, push through your forearms and lift your body back up into a high plank position.', 'Repeat for the desired number of repetitions.'], 'exercises/hCjGsRQ.gif'),
('01a0baa8-423c-7170-8a1c-09ec4f7d5b5d', 'barbell drag curl', 'barbell-drag-curl', 'barbell drag curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.', 'Let the barbell hang at arm''s length in front of your thighs.', 'Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/IENzBdA.gif'),
('01a0baa8-423c-7170-8a1d-33637d5f7c90', 'prisoner half sit-up (male)', 'prisoner-half-sit-up-male', 'prisoner half sit-up (male) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/mgejmGP.gif'),
('01a0baa8-423c-7170-8a1e-56cca72e1c57', 'roller hip stretch', 'roller-hip-stretch', 'roller hip stretch using roller.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Start by sitting on the ground with your legs extended in front of you.', 'Place the roller under your glutes, just above your knees.', 'Lean back and place your hands on the ground behind you for support.', 'Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.', 'Pause for a moment at the end of the movement, feeling a stretch in your glutes.', 'Slowly roll the roller back to the starting position, extending your legs.', 'Repeat for the desired number of repetitions.'], 'exercises/oMypNrz.gif'),
('01a0baa8-423c-7170-8a1f-032b21d0ed0a', 'squat on bosu ball', 'squat-on-bosu-ball', 'squat on bosu ball using bosu ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place the bosu ball on the ground with the flat side up.', 'Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.', 'Lower your body down by bending your knees and hips, as if sitting back into a chair.', 'Keep your chest up and your weight on your heels.', 'Lower yourself until your thighs are parallel to the ground.', 'Pause for a moment, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/T2fA5Ir.gif'),
('01a0baa8-423c-7170-8a20-dc0fefa83721', 'barbell reverse grip bent over row', 'barbell-reverse-grip-bent-over-row', 'barbell reverse grip bent over row using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.', 'Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.', 'Pull the barbell towards your lower chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/SzX3uzM.gif'),
('01a0baa8-423c-7170-8a21-bf914c37104d', 'scapula push-up', 'scapula-push-up', 'scapula push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Lower your chest towards the ground, keeping your elbows close to your body.', 'As you lower, squeeze your shoulder blades together and push your chest forward.', 'Pause for a moment at the bottom, then push back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/jV65tKx.gif'),
('01a0baa8-423c-7170-8a22-69e71d0b86f1', 'dumbbell hammer curl on exercise ball', 'dumbbell-hammer-curl-on-exercise-ball', 'dumbbell hammer curl on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/fY68AyX.gif'),
('01a0baa8-423c-7170-8a23-13b04052c335', 'barbell seated behind head military press', 'barbell-seated-behind-head-military-press', 'barbell seated behind head military press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Lift the barbell off the rack and bring it down to shoulder level, behind your head.', 'Press the barbell upward until your arms are fully extended.', 'Lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ngPpyRS.gif'),
('01a0baa8-423c-7170-8a24-fb1077204052', 'smith close-grip bench press', 'smith-close-grip-bench-press', 'smith close-grip bench press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the bench with your feet flat on the ground.', 'Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.', 'Lower the barbell towards your chest, keeping your elbows close to your body.', 'Pause for a moment at the bottom, then push the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/WcHl7ru.gif'),
('01a0baa8-423c-7170-8a25-d582fa9adb96', 'dumbbell one arm standing curl', 'dumbbell-one-arm-standing-curl', 'dumbbell one arm standing curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.', 'Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.', 'Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/ffQsyBj.gif'),
('01a0baa8-423c-7170-8a26-e76e7ba7ab5b', 'dumbbell seated one arm rotate', 'dumbbell-seated-one-arm-rotate', 'dumbbell seated one arm rotate using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.', 'Raise the dumbbell up to shoulder height, keeping your elbow close to your body.', 'Rotate your forearm outward, away from your body, while keeping your upper arm stationary.', 'Pause for a moment at the top, then slowly rotate your forearm back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/7f2jsqP.gif'),
('01a0baa8-423c-7170-8a27-78a902d4d993', 'dumbbell iron cross', 'dumbbell-iron-cross', 'dumbbell iron cross using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.', 'Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.', 'Pause for a moment, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/cALkHHX.gif'),
('01a0baa8-423c-7170-8a28-e5889aba0596', 'lever shoulder press v. 2', 'lever-shoulder-press-v-2', 'lever shoulder press v. 2 using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and backrest of the leverage machine to a comfortable position.', 'Sit on the machine with your back against the backrest and your feet flat on the floor.', 'Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.', 'Push the handles upward and forward until your arms are fully extended, but not locked.', 'Pause for a moment at the top, then slowly lower the handles back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vqsbmL0.gif'),
('01a0baa8-423c-7170-8a29-ef96b610296b', 'smith wide grip bench press', 'smith-wide-grip-bench-press', 'smith wide grip bench press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the bench to a comfortable position on the smith machine.', 'Lie down on the bench with your feet flat on the ground.', 'Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.', 'Pause for a moment when the barbell touches your chest.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/zoOvPcx.gif'),
('01a0baa8-423c-7170-8a2a-80ec2e079568', 'band bicycle crunch', 'band-bicycle-crunch', 'band bicycle crunch using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your hands behind your head and your knees bent.', 'Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.', 'Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.', 'Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/tZkGYZ9.gif'),
('01a0baa8-423c-7170-8a2b-42352636e141', 'exercise ball prone leg raise', 'exercise-ball-prone-leg-raise', 'exercise ball prone leg raise using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.', 'Place your hands on the ground, shoulder-width apart, and engage your core muscles.', 'Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/lCKm4Rs.gif'),
('01a0baa8-423c-7170-8a2c-89873870d470', 'sledge hammer', 'sledge-hammer', 'sledge hammer using hammer.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.', 'Engage your core and keep your back straight.', 'Swing the sledge hammer down towards the ground, using your core and upper body strength.', 'As you swing down, pivot your hips and transfer the force to the hammer.', 'Repeat for the desired number of repetitions.'], 'exercises/REXmfVC.gif'),
('01a0baa8-423c-7170-8a2d-e305cee037ca', '45Â° side bend', '45-side-bend', '45Â° side bend using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your arms extended straight down by your sides.', 'Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.', 'Pause for a moment at the bottom, then slowly return to the starting position.', 'Repeat on the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/Hy9D21L.gif'),
('01a0baa8-423c-7170-8a2e-06281f566969', 'arm slingers hanging bent knee legs', 'arm-slingers-hanging-bent-knee-legs', 'arm slingers hanging bent knee legs using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.', 'Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.', 'Slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/uWpxD4v.gif'),
('01a0baa8-423c-7170-8a2f-366094f79f33', 'push-up plus', 'push-up-plus', 'push-up plus using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.', 'Lower your body towards the ground by bending your elbows, keeping them close to your sides.', 'Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.', 'At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.', 'Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/pvBMLHA.gif'),
('01a0baa8-423c-7170-8a30-0e44c5c779ec', 'band shrug', 'band-shrug', 'band shrug using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.', 'Keep your arms straight and relaxed, and let the band hang in front of your thighs.', 'Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.', 'Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/trmte8s.gif'),
('01a0baa8-423c-7170-8a31-b05d3a8e667b', 'dumbbell incline rear lateral raise', 'dumbbell-incline-rear-lateral-raise', 'dumbbell incline rear lateral raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.', 'Extend your arms straight down with your palms facing each other.', 'Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vYk8lqw.gif'),
('01a0baa8-423c-7170-8a32-cb2c976d49c6', 'body-up', 'body-up', 'body-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.', 'Extend your legs out in front of you, keeping your heels on the ground and your body straight.', 'Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.', 'Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/U6G2gk9.gif'),
('01a0baa8-423c-7170-8a33-e650a83ae9cb', 'band fixed back underhand pulldown', 'band-fixed-back-underhand-pulldown', 'band fixed back underhand pulldown using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a sturdy anchor point above your head.', 'Stand facing the anchor point with your feet shoulder-width apart.', 'Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.', 'Step back to create tension in the band, keeping your arms fully extended.', 'Engage your core and squeeze your shoulder blades together.', 'Pull the band down towards your chest, leading with your elbows.', 'Pause for a moment at the bottom of the movement, feeling the contraction in your lats.', 'Slowly release the tension in the band and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ZH68exZ.gif'),
('01a0baa8-423c-7170-8a34-46ed8341287f', 'dumbbell lying hammer press', 'dumbbell-lying-hammer-press', 'dumbbell lying hammer press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.', 'Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.', 'Press the dumbbells back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/7gdLIXa.gif'),
('01a0baa8-423d-75e7-851d-ad8cd00e6641', 'monster walk', 'monster-walk', 'monster walk using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place a resistance band around your ankles.', 'Stand with your feet shoulder-width apart and slightly bend your knees.', 'Take a step to the side with your right foot, maintaining tension on the resistance band.', 'Follow with your left foot, stepping to the side to return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/O95afRA.gif'),
('01a0baa8-423d-75e7-851e-86bcdc960729', 'cable seated high row (v-bar)', 'cable-seated-high-row-v-bar', 'cable seated high row (v-bar) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the cable machine with your feet flat on the floor and your knees slightly bent.', 'Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.', 'Keep your back straight and lean slightly forward from the hips.', 'Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.', 'Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/pwt0pnM.gif'),
('01a0baa8-423d-75e7-851f-2de73222e24a', 'exercise ball pike push up', 'exercise-ball-pike-push-up', 'exercise ball pike push up using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands on the floor and your shins resting on the stability ball.', 'Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.', 'Keep your legs straight and your body in a pike position, forming an inverted V shape.', 'Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.', 'Push through your hands and extend your arms to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/sVvXT5J.gif'),
('01a0baa8-423d-75e7-8520-b0d5bfec8749', 'close-grip push-up (on knees)', 'close-grip-push-up-on-knees', 'close-grip push-up (on knees) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.', 'Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.', 'Pause for a moment when your chest is just above the ground.', 'Push through your palms to straighten your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/v3vLFW0.gif'),
('01a0baa8-423d-75e7-8521-d719693c5384', 'barbell guillotine bench press', 'barbell-guillotine-bench-press', 'barbell guillotine bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.', 'Pause for a moment when the barbell is just above your neck.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/GXoaSgn.gif'),
('01a0baa8-423d-75e7-8522-e4db74447eca', 'barbell standing calf raise', 'barbell-standing-calf-raise', 'barbell standing calf raise using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place a barbell across your upper back.', 'Raise your heels off the ground as high as possible, using only your toes.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/8ozhUIZ.gif'),
('01a0baa8-423d-75e7-8523-5199370771aa', 'standing behind neck press', 'standing-behind-neck-press', 'standing behind neck press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.', 'Keep your back straight and core engaged.', 'Press the barbell overhead by extending your arms, fully extending your elbows.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/xDh0lJr.gif'),
('01a0baa8-423d-75e7-8524-e4231e4d84ec', 'dumbbell palm rotational bent over row', 'dumbbell-palm-rotational-bent-over-row', 'dumbbell palm rotational bent over row using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', 'Bend forward at the hips, keeping your back straight and your knees slightly bent.', 'Let your arms hang straight down, palms facing your body.', 'Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.', 'As you pull the dumbbells up, rotate your palms so they face away from your body.', 'Squeeze your shoulder blades together at the top of the movement.', 'Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/wt6rwjk.gif'),
('01a0baa8-423d-75e7-8525-3277e750ae75', 'dumbbell incline bench press', 'dumbbell-incline-bench-press', 'dumbbell incline bench press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.', 'Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.', 'Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.', 'Push the dumbbells back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/ns0SIbU.gif'),
('01a0baa8-423d-75e7-8526-3c3cda412d50', 'cable reverse grip triceps pushdown (sz-bar) (with arm blaster)', 'cable-reverse-grip-triceps-pushdown-sz-bar-with-arm-blaster', 'cable reverse grip triceps pushdown (sz-bar) (with arm blaster) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to the cable machine at the highest setting.', 'Stand facing the cable machine with your feet shoulder-width apart.', 'Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.', 'Keep your elbows close to your sides and your upper arms stationary throughout the exercise.', 'Engage your triceps and slowly push the bar down until your arms are fully extended.', 'Pause for a moment at the bottom, then slowly return the bar to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ThKP69G.gif'),
('01a0baa8-423d-75e7-8527-a4848c87476d', 'seated lower back stretch', 'seated-lower-back-stretch', 'seated lower back stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the edge of a chair with your feet flat on the ground.', 'Place your hands on your thighs or on the sides of the chair for support.', 'Slowly lean forward from your hips, keeping your back straight.', 'Feel the stretch in your lower back and hold for 20-30 seconds.', 'Slowly return to the starting position and repeat for the desired number of repetitions.'], 'exercises/QFmz6ch.gif'),
('01a0baa8-423d-75e7-8528-da85a2caab2e', 'dumbbell standing alternating tricep kickback', 'dumbbell-standing-alternating-tricep-kickback', 'dumbbell standing alternating tricep kickback using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Extend your arms straight back, keeping your elbows close to your body.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat with the other arm, alternating sides with each repetition.'], 'exercises/Gi2BXfK.gif'),
('01a0baa8-423d-75e7-8529-789fe4bd93cc', 'biceps leg concentration curl', 'biceps-leg-concentration-curl', 'biceps leg concentration curl using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your legs spread apart and your feet flat on the ground.', 'Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.', 'With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.', 'Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/sJFIDIp.gif'),
('01a0baa8-423d-75e7-852a-881c9edd3567', 'sled 45Ð²Â° leg press', 'sled-45-leg-press', 'sled 45Ð²Â° leg press using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat and footplate of the sled machine to a comfortable position.', 'Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.', 'Grip the handles on the sides of the seat for stability.', 'Push the footplate away from your body by extending your legs, keeping your heels on the footplate.', 'Continue pushing until your legs are almost fully extended, but without locking your knees.', 'Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.', 'Repeat for the desired number of repetitions.'], 'exercises/10Z2DXU.gif'),
('01a0baa8-423d-75e7-852b-c976b3a40001', 'sled closer hack squat', 'sled-closer-hack-squat', 'sled closer hack squat using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.', 'Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.', 'Grip the handles on the sides of the machine for stability.', 'Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.', 'Continue lowering until your thighs are parallel to the ground or slightly below.', 'Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/gf3ZjB9.gif'),
('01a0baa8-423d-75e7-852c-56fa59cd1061', 'smith one arm row', 'smith-one-arm-row', 'smith one arm row using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the height of the smith machine bar to waist level.', 'Stand facing the smith machine with your feet shoulder-width apart.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Grasp the bar with one hand using an overhand grip, with your palm facing down.', 'Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/Q4DSJPC.gif'),
('01a0baa8-423d-75e7-852d-ce4ffd30f6be', 'sled one leg calf press on leg press', 'sled-one-leg-calf-press-on-leg-press', 'sled one leg calf press on leg press using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.', 'Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.', 'Place your toes and the balls of your feet on the sled, keeping your heels off.', 'Push the sled forward by extending your ankles, keeping your knees slightly bent.', 'Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.', 'Repeat for the desired number of repetitions.'], 'exercises/u0pLNgz.gif'),
('01a0baa8-423d-75e7-852e-ea8465a600fd', 'dumbbell reverse grip incline bench one arm row', 'dumbbell-reverse-grip-incline-bench-one-arm-row', 'dumbbell reverse grip incline bench one arm row using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Place a dumbbell on the floor next to the bench.', 'Stand facing the bench with your feet shoulder-width apart.', 'Bend at the waist and place your left knee and left hand on the bench for support.', 'Pick up the dumbbell with your right hand using a reverse grip (palm facing down).', 'Keep your back straight and your core engaged.', 'Pull the dumbbell up towards your chest, keeping your elbow close to your body.', 'Squeeze your back muscles at the top of the movement.', 'Lower the dumbbell back down to the starting position in a controlled manner.', 'Repeat for the desired number of repetitions.', 'Switch sides and repeat the exercise with your left arm.'], 'exercises/ZIViNh1.gif'),
('01a0baa8-423d-75e7-852f-1316d1d51120', 'standing single leg curl', 'standing-single-leg-curl', 'standing single leg curl using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart and your hands on your hips.', 'Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.', 'Slowly curl your right heel towards your glutes, squeezing your hamstring.', 'Pause for a moment at the top, then slowly lower your right foot back down to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/C5jncD2.gif'),
('01a0baa8-423d-75e7-8530-a4ba619e7fd5', 'dumbbell one arm incline chest press', 'dumbbell-one-arm-incline-chest-press', 'dumbbell one arm incline chest press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the incline bench to a 45-degree angle.', 'Sit on the bench with your back against the pad and feet flat on the ground.', 'Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.', 'Push the dumbbell up and away from your body, extending your arm fully.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/PDaMuyV.gif'),
('01a0baa8-423d-75e7-8531-382c2d73028f', 'dumbbell over bench wrist curl', 'dumbbell-over-bench-wrist-curl', 'dumbbell over bench wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.', 'Allow your wrists to hang over the edge of the bench.', 'Slowly curl your wrists upward, squeezing your forearms at the top of the movement.', 'Pause for a moment, then slowly lower your wrists back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/D1xYJAU.gif'),
('01a0baa8-423d-75e7-8532-92037802798f', 'weighted bench dip', 'weighted-bench-dip', 'weighted bench dip using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your hands gripping the edge, fingers pointing forward.', 'Slide your butt off the bench, supporting your weight with your hands.', 'Lower your body by bending your elbows until your upper arms are parallel to the floor.', 'Push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/MU9HnE7.gif'),
('01a0baa8-423d-75e7-8533-e7f0f005ffa1', 'barbell overhead squat', 'barbell-overhead-squat', 'barbell overhead squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and toes slightly turned out.', 'Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.', 'Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/gfk9kD4.gif'),
('01a0baa8-423d-75e7-8534-34e302dd681a', 'two toe touch (male)', 'two-toe-touch-male', 'two toe touch (male) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your arms extended out to the sides.', 'Bend forward at the waist, keeping your back straight and your knees slightly bent.', 'Reach down towards your toes with both hands, keeping your legs straight.', 'Pause for a moment at the bottom, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/p195zsJ.gif'),
('01a0baa8-423d-75e7-8535-361e7be44326', 'weighted crunch', 'weighted-crunch', 'weighted crunch using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Hold a weight plate or dumbbell on your chest.', 'Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/s8nrDXF.gif'),
('01a0baa8-423d-75e7-8536-4def0526e293', 'smith machine reverse decline close grip bench press', 'smith-machine-reverse-decline-close-grip-bench-press', 'smith machine reverse decline close grip bench press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the smith machine to a decline position.', 'Lie down on the bench with your feet secured under the foot pads.', 'Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.', 'Pause for a moment at the bottom, then push the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/QyO6Uma.gif'),
('01a0baa8-423d-75e7-8537-d1cda106a318', 'weighted lunge with swing', 'weighted-lunge-with-swing', 'weighted lunge with swing using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a weight in each hand.', 'Take a step forward with your right foot, lowering your body into a lunge position.', 'As you lunge forward, swing the weights forward and upward, keeping your arms straight.', 'Push off with your right foot and return to the starting position, swinging the weights back down.', 'Repeat with your left foot and continue alternating legs for the desired number of repetitions.'], 'exercises/5WiFcYk.gif'),
('01a0baa8-423d-75e7-8538-ee8b43ec9975', 'tire flip', 'tire-flip', 'tire flip using tire.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, facing the tire.', 'Bend your knees and hinge at the hips, lowering into a squat position.', 'Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.', 'Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.', 'As the tire flips over, use your upper body strength to guide it and maintain control.', 'Once the tire is fully flipped, quickly step back and reset your stance.', 'Repeat for the desired number of repetitions.'], 'exercises/oZjMu1t.gif'),
('01a0baa8-423d-75e7-8539-6c5a9bcb5c9e', 'weighted side bend (on stability ball)', 'weighted-side-bend-on-stability-ball', 'weighted side bend (on stability ball) using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a stability ball with your feet shoulder-width apart and flat on the ground.', 'Hold a weight in one hand and place your other hand on your hip.', 'Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.', 'Pause for a moment at the bottom, then slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/6bOA1Oi.gif'),
('01a0baa8-423d-75e7-853a-b073c3b9352d', 'cable pull through (with rope)', 'cable-pull-through-with-rope', 'cable pull through (with rope) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing away from the cable machine with your feet shoulder-width apart.', 'Grab the rope attachment with both hands and step forward, creating tension in the cable.', 'Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.', 'Engage your glutes and hamstrings to pull your body back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/OM46QHm.gif'),
('01a0baa8-423d-75e7-853b-51e7d323368a', 'cable standing pulldown (with rope)', 'cable-standing-pulldown-with-rope', 'cable standing pulldown (with rope) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope to the cable machine at the highest setting.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the rope with an overhand grip, palms facing down.', 'Keep your back straight and core engaged throughout the exercise.', 'Pull the rope down towards your thighs, squeezing your biceps.', 'Pause for a moment at the bottom, then slowly release the rope back up.', 'Repeat for the desired number of repetitions.'], 'exercises/CvPn9WV.gif'),
('01a0baa8-423d-75e7-853c-a5b8873c07a9', 'stability ball crunch (full range hands behind head)', 'stability-ball-crunch-full-range-hands-behind-head', 'stability ball crunch (full range hands behind head) using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.', 'Pause for a moment at the top, then slowly lower your upper body back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Gn5FwYT.gif'),
('01a0baa8-423d-75e7-853d-d2b270be4f4c', 'cable one arm decline chest fly', 'cable-one-arm-decline-chest-fly', 'cable one arm decline chest fly using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.', 'Lie down on the bench with your head towards the machine and grab the handle with your right hand.', 'Extend your arm straight up above your chest, keeping a slight bend in your elbow.', 'With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.', 'Pause for a moment, then reverse the motion and bring your arm back to the starting position.', 'Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise.'], 'exercises/w4dLzSx.gif'),
('01a0baa8-423d-75e7-853e-6213720d1a32', 'cable preacher curl', 'cable-preacher-curl', 'cable preacher curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine so that the preacher curl pad is at chest height.', 'Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.', 'Keep your back straight and your elbows tucked in at your sides.', 'Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.', 'Pause for a moment, then slowly lower the cable attachment back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/P2lNrGL.gif'),
('01a0baa8-423d-75e7-853f-bbc525ad0154', 'dumbbell reverse grip row (female)', 'dumbbell-reverse-grip-row-female', 'dumbbell reverse grip row (female) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Hold a dumbbell in each hand with an overhand grip, palms facing your body.', 'Bend forward at the waist, keeping your back straight and your core engaged.', 'Let your arms hang straight down, fully extended, with a slight bend in your elbows.', 'Pull the dumbbells up towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Nh3mvOO.gif'),
('01a0baa8-423d-75e7-8540-874e1c519bc4', 'smith low bar squat', 'smith-low-bar-squat', 'smith low bar squat using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.', 'Stand with your feet shoulder-width apart, toes slightly turned outwards.', 'Step under the bar and position it across your upper back, resting it on your traps.', 'Grip the bar with your hands slightly wider than shoulder-width apart.', 'Unrack the bar by straightening your legs and stepping back from the rack.', 'Take a deep breath and brace your core.', 'Initiate the squat by pushing your hips back and bending your knees.', 'Lower your body until your thighs are parallel to the ground or slightly below.', 'Keep your chest up and your back straight throughout the movement.', 'Drive through your heels to stand back up, extending your hips and knees.', 'Repeat for the desired number of repetitions.'], 'exercises/RGLscZM.gif'),
('01a0baa8-423d-75e7-8541-53feb25ae5c6', 'dumbbell incline curl v. 2', 'dumbbell-incline-curl-v-2', 'dumbbell incline curl v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/RaflbWD.gif'),
('01a0baa8-423d-75e7-8542-536539e0121f', 'pelvic tilt into bridge', 'pelvic-tilt-into-bridge', 'pelvic tilt into bridge using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your back with your knees bent and feet flat on the ground.', 'Place your arms by your sides with your palms facing down.', 'Engage your glutes and core muscles.', 'Tilt your pelvis upward, lifting your hips off the ground.', 'Hold the bridge position for a few seconds.', 'Slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/D9qe7CM.gif'),
('01a0baa8-423d-75e7-8543-60c70db8decf', 'dumbbell incline fly on exercise ball', 'dumbbell-incline-fly-on-exercise-ball', 'dumbbell incline fly on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.', 'Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.', 'Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.', 'Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/HYe1ZqR.gif'),
('01a0baa8-423d-75e7-8544-2179e7fbb5cf', 'dumbbell one arm bent-over row', 'dumbbell-one-arm-bent-over-row', 'dumbbell one arm bent-over row using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.', 'Let the dumbbell hang straight down towards the floor, with your arm fully extended.', 'Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/C0MA9bC.gif'),
('01a0baa8-423d-75e7-8545-0f9214c9bc83', 'seated leg raise', 'seated-leg-raise', 'seated leg raise using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a flat bench with your back straight and your feet flat on the ground.', 'Place your hands on the sides of the bench for support.', 'Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Hgs6Nl1.gif'),
('01a0baa8-423d-75e7-8546-8011f8e84add', 'smith incline shoulder raises', 'smith-incline-shoulder-raises', 'smith incline shoulder raises using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the smith machine to an incline position.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.', 'Keep your back straight and core engaged.', 'Raise the barbell up towards the ceiling, leading with your elbows.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ayAHcEm.gif'),
('01a0baa8-423d-75e7-8547-a5f78d7b0aeb', 'low glute bridge on floor', 'low-glute-bridge-on-floor', 'low glute bridge on floor using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your arms by your sides, palms facing down.', 'Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.', 'Pause for a moment at the top, squeezing your glutes.', 'Slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/u0cNiij.gif'),
('01a0baa8-423d-75e7-8548-5b71724f8403', 'smith machine bicep curl', 'smith-machine-bicep-curl', 'smith machine bicep curl using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the height of the smith machine bar to be at waist level.', 'Stand facing the smith machine with your feet shoulder-width apart.', 'Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.', 'Keep your elbows close to your sides and your upper arms stationary.', 'Exhale and curl the bar up towards your shoulders, contracting your biceps.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Inhale and slowly lower the bar back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/zILLZ98.gif'),
('01a0baa8-423d-75e7-8549-906d52582d21', 'alternate heel touchers', 'alternate-heel-touchers', 'alternate heel touchers using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Extend your arms straight out to the sides, parallel to the ground.', 'Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.', 'Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/qaZVsGk.gif'),
('01a0baa8-423d-75e7-854a-d4424ed9a701', 'butt-ups', 'butt-ups', 'butt-ups using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands by your sides, palms facing down.', 'Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.', 'At the top of the movement, squeeze your abs and pause for a moment.', 'Slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/qcNN2FN.gif'),
('01a0baa8-423d-75e7-854b-3a363ae330fd', 'exercise ball on the wall calf raise (tennis ball between ankles)', 'exercise-ball-on-the-wall-calf-raise-tennis-ball-between-ankles', 'exercise ball on the wall calf raise (tennis ball between ankles) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a wall with your feet shoulder-width apart.', 'Place an exercise ball between the wall and your lower back.', 'Hold a dumbbell in each hand, with your arms extended by your sides.', 'Place a tennis ball between your ankles.', 'Raise your heels off the ground, lifting your body up onto your toes.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/FY3UdNT.gif'),
('01a0baa8-423e-70b1-9ec4-5708ce4b8f27', 'dumbbell seated inner biceps curl', 'dumbbell-seated-inner-biceps-curl', 'dumbbell seated inner biceps curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.', 'Rest your upper arms on your thighs, allowing the dumbbells to hang down.', 'Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/KXyoEtA.gif'),
('01a0baa8-423e-70b1-9ec5-067d34091d9d', 'standing hamstring and calf stretch with strap', 'standing-hamstring-and-calf-stretch-with-strap', 'standing hamstring and calf stretch with strap using rope.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand upright with your feet shoulder-width apart.', 'Hold the strap with both hands and place it around the ball of your foot.', 'Keep your leg straight and slowly lean forward from your hips, keeping your back straight.', 'Feel the stretch in your hamstring and calf muscles.', 'Hold the stretch for 20-30 seconds.', 'Release the stretch and repeat with the other leg.', 'Repeat for the desired number of repetitions.'], 'exercises/xTjr103.gif'),
('01a0baa8-423e-70b1-9ec6-0b0788b0043d', 'single leg bridge with outstretched leg', 'single-leg-bridge-with-outstretched-leg', 'single leg bridge with outstretched leg using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your back with your knees bent and feet flat on the ground.', 'Extend one leg straight out in front of you.', 'Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.', 'Hold for a moment at the top, then slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/rmEukuS.gif'),
('01a0baa8-423e-70b1-9ec7-5eaf0d8772d8', 'rocky pull-up pulldown', 'rocky-pull-up-pulldown', 'rocky pull-up pulldown using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand in front of a pull-up bar with your feet shoulder-width apart.', 'Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.', 'Hang from the bar with your arms fully extended and your body straight.', 'Engage your back muscles and pull your body up towards the bar, leading with your chest.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/cQ19bBP.gif'),
('01a0baa8-423e-70b1-9ec8-8d994691693d', 'rope climb', 'rope-climb', 'rope climb using rope.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing the rope with your feet shoulder-width apart.', 'Grab the rope with both hands, palms facing towards you.', 'Bend your knees slightly and engage your core.', 'Begin pulling yourself up the rope by alternating hand-over-hand movements.', 'Use your legs to assist in the upward movement.', 'Continue climbing until you reach the desired height or the top of the rope.', 'To descend, reverse the hand-over-hand movement while controlling your descent.', 'Repeat for the desired number of repetitions.'], 'exercises/yaAxcQr.gif'),
('01a0baa8-423e-70b1-9ec9-30e4d39d2f67', 'walk elliptical cross trainer', 'walk-elliptical-cross-trainer', 'walk elliptical cross trainer using elliptical machine.', 'CARDIO', 'INTERMEDIATE', ARRAY['Adjust the resistance level and incline of the elliptical machine to your desired settings.', 'Step onto the pedals of the machine and grip the handles lightly.', 'Begin by pushing down with your feet and pulling the handles towards your body.', 'Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.', 'Maintain a steady pace and keep your core engaged throughout the exercise.', 'Continue for the desired duration of your cardio workout.', 'Gradually decrease the intensity and speed of the machine before stepping off.'], 'exercises/rjtuP6X.gif'),
('01a0baa8-423e-70b1-9eca-ab5513318297', 'barbell lying extension', 'barbell-lying-extension', 'barbell lying extension using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', 'Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.', 'Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.', 'Pause for a moment, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/EMpUwRI.gif'),
('01a0baa8-423e-70b1-9ecb-5a6c4583b7d2', 'barbell straight leg deadlift', 'barbell-straight-leg-deadlift', 'barbell straight leg deadlift using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your toes pointing forward.', 'Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.', 'Lower the barbell until you feel a stretch in your hamstrings.', 'Engage your hamstrings and glutes to lift the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/hrVQWvE.gif'),
('01a0baa8-423e-70b1-9ecc-51ed52c01832', 'dumbbell bicep curl on exercise ball with leg raised', 'dumbbell-bicep-curl-on-exercise-ball-with-leg-raised', 'dumbbell bicep curl on exercise ball with leg raised using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.', 'Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.', 'Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.', 'While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.', 'Repeat for the desired number of repetitions, then switch legs and repeat.'], 'exercises/2NImIAG.gif'),
('01a0baa8-423e-70b1-9ecd-8c8abb8e2e8e', 'overhead triceps stretch', 'overhead-triceps-stretch', 'overhead triceps stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand or sit upright with your feet shoulder-width apart.', 'Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.', 'With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.', 'Hold the stretch for 15-30 seconds, then release.', 'Repeat on the other side.'], 'exercises/Z5YStHW.gif'),
('01a0baa8-423e-70b1-9ece-904ce6b844dd', 'crab twist toe touch', 'crab-twist-toe-touch', 'crab twist toe touch using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by sitting on the ground with your knees bent and feet flat on the floor.', 'Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.', 'Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.', 'Return to the starting position and repeat on the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/xgsGFVM.gif'),
('01a0baa8-423e-70b1-9ecf-e25517df45b3', 'dumbbell pullover on exercise ball', 'dumbbell-pullover-on-exercise-ball', 'dumbbell pullover on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.', 'Slowly lower the dumbbell behind your head while keeping your arms straight.', 'Pause for a moment, then raise the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/FSD6PGL.gif'),
('01a0baa8-423e-70b1-9ed0-1982cc78a305', 'barbell high bar squat', 'barbell-high-bar-squat', 'barbell high bar squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes slightly turned out.', 'Place the barbell on your upper back, resting it on your traps.', 'Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.', 'Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Drive through your heels to stand back up, extending your hips and knees.', 'Repeat for the desired number of repetitions.'], 'exercises/Gnfo4FM.gif'),
('01a0baa8-423e-70b1-9ed1-8aac99de9126', 'walking on incline treadmill', 'walking-on-incline-treadmill', 'walking on incline treadmill using leverage machine.', 'CARDIO', 'INTERMEDIATE', ARRAY['Adjust the incline level on the treadmill to your desired intensity.', 'Stand on the treadmill with your feet shoulder-width apart.', 'Start walking at a comfortable pace, ensuring that you maintain proper form.', 'Engage your core muscles and keep your back straight throughout the exercise.', 'Continue walking on the incline treadmill for the desired duration of your cardio workout.', 'Gradually decrease the incline and speed of the treadmill to cool down before stopping.'], 'exercises/rjiM4L3.gif'),
('01a0baa8-423e-70b1-9ed2-443a5f0c8029', 'band horizontal pallof press', 'band-horizontal-pallof-press', 'band horizontal pallof press using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a sturdy anchor point at waist height.', 'Stand perpendicular to the anchor point with your feet shoulder-width apart.', 'Grasp the band handle with both hands and step away from the anchor point to create tension in the band.', 'Bring your hands to your chest, keeping your elbows bent and close to your body.', 'Engage your core and maintain a stable stance.', 'Extend your arms straight out in front of you, pushing the band away from your body.', 'Hold the extended position for a few seconds, focusing on maintaining tension in your core.', 'Slowly bring your hands back to your chest, resisting the pull of the band.', 'Repeat for the desired number of repetitions.'], 'exercises/9pa4H5m.gif'),
('01a0baa8-423e-70b1-9ed3-83713f492c21', 'cable cross-over lateral pulldown', 'cable-cross-over-lateral-pulldown', 'cable cross-over lateral pulldown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a cable handle to each side of a cable machine at shoulder height.', 'Stand in the middle of the machine with your feet shoulder-width apart.', 'Grasp the handles with an overhand grip and step back to create tension in the cables.', 'Lean forward slightly from the hips, keeping your back straight and your chest up.', 'Pull the handles down and across your body, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/OQ1otBN.gif'),
('01a0baa8-423e-70b1-9ed4-b16ed5914b5d', 'wrist rollerer', 'wrist-rollerer', 'wrist rollerer using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a weight to one end of a rope or bar.', 'Hold the other end of the rope or bar with both hands, palms facing down.', 'Stand with your feet shoulder-width apart and your arms fully extended in front of you.', 'Slowly roll the weight up towards your hands by flexing your wrists.', 'Pause for a moment at the top, then slowly lower the weight back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/bd5b860.gif'),
('01a0baa8-423e-70b1-9ed5-1566645b3535', 'weighted stretch lunge', 'weighted-stretch-lunge', 'weighted stretch lunge using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Take a step forward with your right foot, keeping your back straight.', 'Lower your body by bending your knees until your right thigh is parallel to the ground.', 'Push through your right heel to return to the starting position.', 'Repeat with your left leg.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/13VW2VO.gif'),
('01a0baa8-423e-70b1-9ed6-6eb5c12642de', 'barbell thruster', 'barbell-thruster', 'barbell thruster using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.', 'Lower into a squat position by bending your knees and pushing your hips back.', 'As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.', 'Lower the barbell back to shoulder height as you lower back into the squat position.', 'Repeat for the desired number of repetitions.'], 'exercises/f7Y9eDZ.gif'),
('01a0baa8-423e-70b1-9ed7-0a138ce52a53', 'run', 'run', 'run using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Start by standing upright with your feet hip-width apart.', 'Engage your core and keep your upper body relaxed.', 'Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.', 'Maintain a steady pace and continue jogging for the desired duration or distance.', 'Remember to breathe deeply and maintain good posture throughout the exercise.'], 'exercises/oLrKqDH.gif'),
('01a0baa8-423e-70b1-9ed8-7c20209876ff', 'band kneeling twisting crunch', 'band-kneeling-twisting-crunch', 'band kneeling twisting crunch using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a sturdy anchor point at waist height.', 'Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.', 'Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.', 'Pause for a moment, then slowly return to the starting position.', 'Repeat on the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/225x2Vd.gif'),
('01a0baa8-423e-70b1-9ed9-f96076661d63', 'assisted standing pull-up', 'assisted-standing-pull-up', 'assisted standing pull-up using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the machine to your desired weight and height settings.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.', 'Engage your lats and biceps, and pull yourself up towards the handles.', 'Pause for a moment at the top, squeezing your back muscles.', 'Slowly lower yourself back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/f4xtKBj.gif'),
('01a0baa8-423e-70b1-9eda-eb8e8acaea76', 'dumbbell incline two arm extension', 'dumbbell-incline-two-arm-extension', 'dumbbell incline two arm extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in each hand, resting on your thighs.', 'Slowly lie back on the bench, keeping the dumbbells close to your chest.', 'Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/U7D9Fx3.gif'),
('01a0baa8-423e-70b1-9edb-10e35bcb6e7f', 'walking on stepmill', 'walking-on-stepmill', 'walking on stepmill using stepmill machine.', 'CARDIO', 'INTERMEDIATE', ARRAY['Adjust the stepmill machine to a comfortable level.', 'Step onto the machine and place your hands on the handrails for support.', 'Start walking by placing one foot on a step and then the other, alternating between legs.', 'Maintain an upright posture and engage your core muscles.', 'Continue walking for the desired duration or distance.', 'Gradually increase the intensity or speed as you become more comfortable with the exercise.', 'Remember to cool down and stretch after completing the exercise.'], 'exercises/j9Q5crt.gif'),
('01a0baa8-423e-70b1-9edc-afceda357b51', 'dumbbell seated bicep curl', 'dumbbell-seated-bicep-curl', 'dumbbell seated bicep curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.', 'Keep your back straight and your elbows close to your torso.', 'Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/xiA6lRr.gif'),
('01a0baa8-423e-70b1-9edd-02a107c268b6', 'cable pulldown bicep curl', 'cable-pulldown-bicep-curl', 'cable pulldown bicep curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to the cable machine at the highest setting.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the bar with an underhand grip, hands shoulder-width apart.', 'Keep your elbows close to your sides and your upper arms stationary.', 'Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.', 'Pause for a moment at the bottom of the movement, squeezing your biceps.', 'Inhale and slowly return the bar to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/QTXKWPh.gif'),
('01a0baa8-423e-70b1-9ede-2c9917571ec0', 'otis up', 'otis-up', 'otis up using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/UVL20oz.gif'),
('01a0baa8-423e-70b1-9edf-c551addedad3', 'suspended row', 'suspended-row', 'suspended row using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up a suspension trainer at an appropriate height.', 'Stand facing the anchor point with your feet shoulder-width apart.', 'Hold the handles with an overhand grip, palms facing each other.', 'Lean back, keeping your body straight and your heels on the ground.', 'Pull your chest towards the handles, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower yourself back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/4OaumBr.gif'),
('01a0baa8-423e-70b1-9ee0-6ff936d461c6', 'dumbbell palms in incline bench press', 'dumbbell-palms-in-incline-bench-press', 'dumbbell palms in incline bench press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Sit on the bench with your back against the backrest and feet flat on the ground.', 'Hold a dumbbell in each hand with an overhand grip, palms facing inwards.', 'Extend your arms straight up above your chest, keeping a slight bend in your elbows.', 'Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.', 'Pause for a moment at the bottom, then press the dumbbells back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/8eqjhOl.gif'),
('01a0baa8-423e-70b1-9ee1-e23bd8a52202', 'barbell pullover to press', 'barbell-pullover-to-press', 'barbell pullover to press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your head at one end and your feet on the ground.', 'Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.', 'Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.', 'Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.', 'Repeat for the desired number of repetitions.'], 'exercises/znLogoF.gif'),
('01a0baa8-423e-70b1-9ee2-a17e3cd37b7a', 'smith wide grip decline bench press', 'smith-wide-grip-decline-bench-press', 'smith wide grip decline bench press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the decline bench to the desired angle.', 'Lie down on the bench with your feet secured under the foot pads.', 'Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.', 'Pause for a moment when the barbell touches your chest.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/wi2H9QX.gif'),
('01a0baa8-423e-70b1-9ee3-2f7410183b3a', 'dumbbell incline triceps extension', 'dumbbell-incline-triceps-extension', 'dumbbell incline triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in each hand, palms facing inwards.', 'Extend your arms fully overhead, keeping your elbows close to your head.', 'Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.', 'Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/OVIKwsd.gif'),
('01a0baa8-423e-70b1-9ee4-d4dab61f32ce', 'dumbbell over bench one arm reverse wrist curl', 'dumbbell-over-bench-one-arm-reverse-wrist-curl', 'dumbbell over bench one arm reverse wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.', 'Rest your forearm on the bench with your wrist hanging off the edge.', 'Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/4Jc36XM.gif'),
('01a0baa8-423e-70b1-9ee5-2ea21d35a3bb', 'rear pull-up', 'rear-pull-up', 'rear pull-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.', 'Hang from the bar with your arms fully extended and your body straight.', 'Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/CbFSYC1.gif'),
('01a0baa8-423e-70b1-9ee6-4f97242306ce', 'band side triceps extension', 'band-side-triceps-extension', 'band side triceps extension using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.', 'Extend your arms straight out to the sides, keeping them parallel to the ground.', 'Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.', 'Pause for a moment, then slowly extend your arms back out to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/obe5LMq.gif'),
('01a0baa8-423e-70b1-9ee7-9b30a532a7ea', 'cable hammer curl (with rope)', 'cable-hammer-curl-with-rope', 'cable hammer curl (with rope) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand upright with your feet shoulder-width apart and a slight bend in your knees.', 'Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the cable rope attachment back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/HPlPoQA.gif'),
('01a0baa8-423e-70b1-9ee8-a60a69fb531c', 'dumbbell seated curl', 'dumbbell-seated-curl', 'dumbbell seated curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.', 'Keep your back straight and your elbows close to your torso.', 'Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/TiaZTxx.gif'),
('01a0baa8-423e-70b1-9ee9-1c05a6525657', 'seated side crunch (wall)', 'seated-side-crunch-wall', 'seated side crunch (wall) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the floor with your back against a wall and your legs extended in front of you.', 'Bend your knees and place your feet flat on the floor, hip-width apart.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engage your abs and lean to one side, bringing your elbow towards your hip.', 'Pause for a moment, then return to the starting position.', 'Repeat on the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/Y9hNPcN.gif'),
('01a0baa8-423e-70b1-9eea-b7001cac9025', 'barbell reverse wrist curl', 'barbell-reverse-wrist-curl', 'barbell reverse wrist curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.', 'Rest your forearms on your thighs, allowing your wrists to hang off the edge.', 'Slowly curl your wrists upward, bringing the barbell towards your body.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/LsZkfU6.gif'),
('01a0baa8-423e-70b1-9eeb-c6f1cf6a914d', 'push-up on lower arms', 'push-up-on-lower-arms', 'push-up on lower arms using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a plank position with your forearms on the ground and elbows directly below your shoulders.', 'Engage your core and keep your body in a straight line from head to toe.', 'Lower your chest towards the ground by bending your elbows, keeping them close to your body.', 'Pause for a moment at the bottom, then push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/4Jt8QsQ.gif'),
('01a0baa8-423e-70b1-9eec-7e3c1de97c5b', 'dumbbell lying rear lateral raise', 'dumbbell-lying-rear-lateral-raise', 'dumbbell lying rear lateral raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.', 'Extend your arms straight down towards the floor, keeping a slight bend in your elbows.', 'Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/53Ttlck.gif'),
('01a0baa8-423e-70b1-9eed-9c0a563966ad', 'band front raise', 'band-front-raise', 'band front raise using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.', 'Keep your arms straight and slowly raise them forward until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/TFA88iB.gif'),
('01a0baa8-423e-70b1-9eee-53b76e437a56', 'smith sumo squat', 'smith-sumo-squat', 'smith sumo squat using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up the smith machine with the barbell at hip height.', 'Stand with your feet wider than shoulder-width apart, toes pointing outwards.', 'Position yourself under the barbell, resting it on your upper back and shoulders.', 'Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.', 'Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/dzz6BiV.gif'),
('01a0baa8-423e-70b1-9eef-9ca35ca3e7cf', 'bodyweight incline side plank', 'bodyweight-incline-side-plank', 'bodyweight incline side plank using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying on your side with your legs extended and stacked on top of each other.', 'Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.', 'Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.', 'Hold this position for the desired amount of time.', 'Lower your hips back down to the ground and repeat on the other side.'], 'exercises/5VXmnV5.gif'),
('01a0baa8-423e-70b1-9ef0-33fe35b1f5b1', 'weighted hanging leg-hip raise', 'weighted-hanging-leg-hip-raise', 'weighted hanging leg-hip raise using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', 'Engage your core and lift your legs up in front of you, keeping them straight.', 'Continue lifting until your legs are parallel to the ground or slightly higher.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/QOA0FD0.gif'),
('01a0baa8-423e-70b1-9ef1-251fe88bec22', 'box jump down with one leg stabilization', 'box-jump-down-with-one-leg-stabilization', 'box jump down with one leg stabilization using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand in front of a box or platform with your feet shoulder-width apart.', 'Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.', 'Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.', 'Hold this position for a few seconds, engaging your calf muscles to maintain balance.', 'Slowly step down with the foot that is on the box, returning to the starting position.', 'Repeat the exercise with the other leg.'], 'exercises/iPm26QU.gif'),
('01a0baa8-423e-70b1-9ef2-20007db074fd', 'dumbbell standing around world', 'dumbbell-standing-around-world', 'dumbbell standing around world using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', 'Extend your arms straight out to the sides at shoulder height, palms facing down.', 'Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.', 'Continue the circular motion, bringing the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/RSOsp5d.gif'),
('01a0baa8-423e-70b1-9ef3-3a73208e8763', 'squat to overhead reach', 'squat-to-overhead-reach', 'squat to overhead reach using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and toes slightly turned out.', 'Lower your body down into a squat position by bending your knees and pushing your hips back.', 'As you come up from the squat, extend your arms overhead, reaching towards the ceiling.', 'Return to the starting position by lowering your arms and bending your knees to squat down again.', 'Repeat for the desired number of repetitions.'], 'exercises/QChZi3x.gif'),
('01a0baa8-423e-70b1-9ef4-b519a671f3ad', 'barbell side bent v. 2', 'barbell-side-bent-v-2', 'barbell side bent v. 2 using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.', 'Keep your back straight and core engaged throughout the exercise.', 'Slowly bend your torso to the right side, lowering the barbell towards your right knee.', 'Pause for a moment, then return to the starting position.', 'Repeat the movement on the left side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/i4JkUaL.gif'),
('01a0baa8-423e-70b1-9ef5-664e34d1bcaa', 'weighted tricep dips', 'weighted-tricep-dips', 'weighted tricep dips using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.', 'Slide your butt off the front of the bench with your legs extended in front of you.', 'Keep your back close to the bench and your elbows slightly bent.', 'Lower your body by bending your elbows until your upper arms are parallel to the floor.', 'Push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/bZq4bwK.gif'),
('01a0baa8-423e-70b1-9ef6-c6fbcaf8ea9d', 'cable lateral pulldown with v-bar', 'cable-lateral-pulldown-with-v-bar', 'cable lateral pulldown with v-bar using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.', 'Adjust the knee pad so that your thighs are secured under it.', 'Keep your back straight and lean back slightly.', 'Pull the v-bar down towards your upper chest while keeping your elbows close to your body.', 'Squeeze your back muscles at the bottom of the movement.', 'Slowly return the v-bar to the starting position and repeat for the desired number of repetitions.'], 'exercises/4c9BhzB.gif'),
('01a0baa8-423e-70b1-9ef7-ce1c38feb021', 'ez bar lying close grip triceps extension behind head', 'ez-bar-lying-close-grip-triceps-extension-behind-head', 'ez bar lying close grip triceps extension behind head using ez barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', 'Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.', 'Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.', 'Pause for a moment, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/6CKUx7o.gif'),
('01a0baa8-423e-70b1-9ef8-7cdfcd0fb1b8', 'barbell full squat (side pov)', 'barbell-full-squat-side-pov', 'barbell full squat (side pov) using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes slightly turned out.', 'Hold the barbell across your upper back, resting it on your traps or rear delts.', 'Engage your core and keep your chest up as you begin to lower your body down.', 'Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.', 'Lower your body until your thighs are parallel to the ground or slightly below.', 'Keep your knees in line with your toes and your weight in your heels.', 'Drive through your heels to stand back up, extending your hips and knees.', 'Repeat for the desired number of repetitions.'], 'exercises/iYzB0Cz.gif'),
('01a0baa8-423f-7501-8acb-992eb116d1c9', 'barbell wrist curl v. 2', 'barbell-wrist-curl-v-2', 'barbell wrist curl v. 2 using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and your knees bent.', 'Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.', 'Rest your forearms on your thighs, allowing your wrists to hang off the edge.', 'Slowly curl your wrists upward, bringing the barbell towards your forearms.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/6kSxYnw.gif'),
('01a0baa8-423f-7501-8acc-c01a0cf91388', 'dumbbell rear fly', 'dumbbell-rear-fly', 'dumbbell rear fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Extend your arms straight down towards the ground, palms facing each other.', 'Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/8DiFDVA.gif'),
('01a0baa8-423f-7501-8acd-e321571315d3', 'weighted hyperextension (on stability ball)', 'weighted-hyperextension-on-stability-ball', 'weighted hyperextension (on stability ball) using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.', 'Place your hands behind your head or cross them over your chest.', 'Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/8urJS9b.gif'),
('01a0baa8-423f-7501-8ace-db95dbbc64f4', 'band reverse wrist curl', 'band-reverse-wrist-curl', 'band reverse wrist curl using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the ground.', 'Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.', 'Rest your forearms on your thighs, with your wrists hanging off the edge.', 'Slowly curl your wrists upward, squeezing your forearms.', 'Pause for a moment at the top, then slowly lower your wrists back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Ezpnw9d.gif'),
('01a0baa8-423f-7501-8acf-321f548ca2f3', 'wheel run', 'wheel-run', 'wheel run using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a plank position with your hands on the wheel and your body straight.', 'Engage your core and start rolling the wheel forward by extending your arms.', 'Continue rolling until your body is fully extended and your arms are overhead.', 'Reverse the movement by pulling the wheel back towards your body, using your core and arms.', 'Repeat for the desired number of repetitions.'], 'exercises/km2Ljzj.gif'),
('01a0baa8-423f-7501-8ad0-cd80217f15d4', 'dumbbell supported squat', 'dumbbell-supported-squat', 'dumbbell supported squat using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.', 'Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.', 'Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/r5DgrW9.gif'),
('01a0baa8-423f-7501-8ad1-256f0e9e0801', 'chest dip', 'chest-dip', 'chest dip using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Position yourself on parallel bars with your arms fully extended and your body straight.', 'Lower your body by bending your elbows until your shoulders are below your elbows.', 'Push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/9WTm7dq.gif'),
('01a0baa8-423f-7501-8ad2-fa5cd64044e2', 'exercise ball back extension with hands behind head', 'exercise-ball-back-extension-with-hands-behind-head', 'exercise ball back extension with hands behind head using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.', 'Position your feet against a wall or other stable surface for support.', 'Cross your arms behind your head, with your hands touching the back of your head.', 'Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.', 'Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/o1HGDSq.gif'),
('01a0baa8-423f-7501-8ad3-40d265c4d5b2', 'assisted prone lying quads stretch', 'assisted-prone-lying-quads-stretch', 'assisted prone lying quads stretch using assisted.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie face down on the ground with your legs extended.', 'Bend your left knee and reach back with your left hand to grab your left foot or ankle.', 'Gently pull your left foot towards your glutes, feeling a stretch in your left quad.', 'Hold the stretch for 20-30 seconds, then release.', 'Repeat with your right leg.'], 'exercises/YUYAMEj.gif'),
('01a0baa8-423f-7501-8ad4-cc6e5990507d', 'sit-up v. 2', 'sit-up-v-2', 'sit-up v. 2 using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Bn6TXyO.gif'),
('01a0baa8-423f-7501-8ad5-d7ae4697e61f', 'dumbbell incline alternate press', 'dumbbell-incline-alternate-press', 'dumbbell incline alternate press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in each hand, resting on your thighs.', 'Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.', 'Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.', 'Push the dumbbells up with your chest and shoulders, extending your arms fully.', 'Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.', 'Repeat for the desired number of repetitions, alternating arms.'], 'exercises/TVdivgY.gif'),
('01a0baa8-423f-7501-8ad6-f6a4a1340f5f', 'runners stretch', 'runners-stretch', 'runners stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart.', 'Take a step forward with your right foot, keeping your left foot planted.', 'Bend your right knee and lower your body down, keeping your left leg straight.', 'Place your hands on your right thigh for support.', 'Hold the stretch for 20-30 seconds, then switch sides and repeat.'], 'exercises/0mB6wHO.gif'),
('01a0baa8-423f-7501-8ad7-fcbb4026c56e', 'vertical leg raise (on parallel bars)', 'vertical-leg-raise-on-parallel-bars', 'vertical leg raise (on parallel bars) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from the parallel bars with your arms fully extended and your body straight.', 'Engage your core and lift your legs up in front of you, keeping them straight.', 'Continue lifting until your legs are parallel to the ground or slightly higher.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ZNgOYQU.gif'),
('01a0baa8-423f-7501-8ad8-6d2d6f726d8c', 'curl-up', 'curl-up', 'curl-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/g2oKspu.gif'),
('01a0baa8-423f-7501-8ad9-9d92b7939946', 'push up on bosu ball', 'push-up-on-bosu-ball', 'push up on bosu ball using bosu ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place the bosu ball on the ground with the flat side facing up.', 'Position yourself in a push-up position with your hands on the outer edges of the bosu ball.', 'Engage your core and lower your body down towards the bosu ball by bending your elbows.', 'Push yourself back up to the starting position by extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/wVompEp.gif'),
('01a0baa8-423f-7501-8ada-f8b792c59aaf', 'barbell full squat', 'barbell-full-squat', 'barbell full squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes slightly turned out.', 'Hold the barbell across your upper back, resting it on your traps or rear delts.', 'Engage your core and keep your chest up as you begin to lower your body down.', 'Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.', 'Lower yourself until your thighs are parallel to the ground or slightly below.', 'Keep your knees in line with your toes and your weight in your heels.', 'Drive through your heels to stand back up, extending your hips and knees.', 'Repeat for the desired number of repetitions.'], 'exercises/qXTaZnJ.gif'),
('01a0baa8-423f-7501-8adb-98515bd4bbd5', 'barbell floor calf raise', 'barbell-floor-calf-raise', 'barbell floor calf raise using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place a barbell on the floor in front of you.', 'Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.', 'Hold onto a stable object for balance if needed.', 'Raise your heels as high as possible, using your calves to lift your body.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/2IHEa2T.gif'),
('01a0baa8-423f-7501-8adc-610c7f0c74fa', 'dumbbell over bench revers wrist curl', 'dumbbell-over-bench-revers-wrist-curl', 'dumbbell over bench revers wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.', 'Rest your forearms on the bench, allowing your wrists to hang off the edge.', 'Slowly curl your wrists upward, bringing the dumbbells towards your body.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/3tAXPQ6.gif'),
('01a0baa8-423f-7501-8add-0bf650ecf08f', 'dumbbell upright row', 'dumbbell-upright-row', 'dumbbell upright row using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', 'Let the dumbbells hang in front of your thighs, with your arms fully extended.', 'Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ainizkb.gif'),
('01a0baa8-423f-7501-8ade-694cb3cc9195', 'sled lying squat', 'sled-lying-squat', 'sled lying squat using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the sled machine to a comfortable weight.', 'Lie on your back on the sled machine with your feet on the footplate.', 'Position your feet shoulder-width apart and slightly angled outwards.', 'Grip the handles of the sled machine for stability.', 'Engage your glutes and core muscles.', 'Push through your heels and extend your legs to lift the sled.', 'Lower the sled back down by bending your knees and hips.', 'Repeat for the desired number of repetitions.'], 'exercises/9n2149Z.gif'),
('01a0baa8-423f-7501-8adf-5cbdae3ce87b', 'dumbbell incline twisted flyes', 'dumbbell-incline-twisted-flyes', 'dumbbell incline twisted flyes using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.', 'Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.', 'Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.', 'As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.', 'Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.', 'Repeat for the desired number of repetitions.'], 'exercises/1PLE8e9.gif'),
('01a0baa8-423f-7501-8ae0-01f8aadcd94f', 'smith machine decline close grip bench press', 'smith-machine-decline-close-grip-bench-press', 'smith machine decline close grip bench press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the bench on the smith machine to a decline position.', 'Lie down on the bench with your feet firmly planted on the ground.', 'Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.', 'Pause for a moment when the barbell is just above your chest.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/yB9SvIF.gif'),
('01a0baa8-423f-7501-8ae1-ff8762ab0f6b', 'dumbbell alternate hammer preacher curl', 'dumbbell-alternate-hammer-preacher-curl', 'dumbbell alternate hammer preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.', 'Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.'], 'exercises/fy7Tgy4.gif'),
('01a0baa8-423f-7501-8ae2-b773575d90b8', 'exercise ball back extension with knees off ground', 'exercise-ball-back-extension-with-knees-off-ground', 'exercise ball back extension with knees off ground using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.', 'Position your hands behind your head or crossed over your chest.', 'Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/WME869U.gif'),
('01a0baa8-423f-7501-8ae3-48eff1f2ae12', 'lever standing calf raise', 'lever-standing-calf-raise', 'lever standing calf raise using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the machine to your height and stand with your feet shoulder-width apart.', 'Place your shoulders under the pads and hold onto the handles for stability.', 'Raise your heels as high as possible by extending your ankles.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ykUOVze.gif'),
('01a0baa8-423f-7501-8ae4-f5d8ee86bb48', 'dumbbell seated shoulder press', 'dumbbell-seated-shoulder-press', 'dumbbell seated shoulder press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with a dumbbell in each hand, resting on your thighs.', 'Raise the dumbbells to shoulder height, palms facing forward.', 'Press the dumbbells upward until your arms are fully extended overhead.', 'Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.', 'Repeat for the desired number of repetitions.'], 'exercises/znQUdHY.gif'),
('01a0baa8-423f-7501-8ae5-4850f186a143', 'potty squat', 'potty-squat', 'potty squat using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes pointing slightly outward.', 'Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.', 'Keep your chest up and your back straight throughout the movement.', 'Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/75Bgtjy.gif'),
('01a0baa8-423f-7501-8ae6-f8b470708730', 'cable seated one arm alternate row', 'cable-seated-one-arm-alternate-row', 'cable seated one arm alternate row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.', 'Grasp the handle with one hand and keep your arm fully extended in front of you.', 'Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.', 'Pause for a moment at the top of the movement, squeezing your back muscles.', 'Slowly release the handle back to the starting position.', 'Repeat with the other arm.', 'Alternate between arms for the desired number of repetitions.'], 'exercises/vpp9Ku2.gif'),
('01a0baa8-423f-7501-8ae7-01b53a44da58', 'dumbbell hammer curl v. 2', 'dumbbell-hammer-curl-v-2', 'dumbbell hammer curl v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your torso.', 'Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.', 'This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.'], 'exercises/2NpxjC1.gif'),
('01a0baa8-423f-7501-8ae8-dc2ad0544078', 'dumbbell lateral raise', 'dumbbell-lateral-raise', 'dumbbell lateral raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.', 'Keep your back straight and engage your core.', 'Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/DsgkuIt.gif'),
('01a0baa8-423f-7501-8ae9-12c7559ae5d1', 'weighted drop push up', 'weighted-drop-push-up', 'weighted drop push up using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.', 'Lower your chest towards the ground, keeping your elbows close to your body.', 'Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.', 'As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.', 'Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.', 'Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.', 'Continue alternating between the wider and narrower hand positions for the desired number of repetitions.'], 'exercises/PSlvNMs.gif'),
('01a0baa8-423f-7501-8aea-96f7c03b5dcb', 'dumbbell one arm seated neutral wrist curl', 'dumbbell-one-arm-seated-neutral-wrist-curl', 'dumbbell one arm seated neutral wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.', 'Rest your forearm on your thigh, allowing your wrist to hang off the edge.', 'Keeping your forearm stationary, curl your wrist upward as far as possible.', 'Pause for a moment at the top, then slowly lower your wrist back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other hand.'], 'exercises/YtaCTYl.gif'),
('01a0baa8-423f-7501-8aeb-ecb83c77608e', 'resistance band seated straight back row', 'resistance-band-seated-straight-back-row', 'resistance band seated straight back row using resistance band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the floor with your legs extended and loop the resistance band around your feet.', 'Hold the ends of the resistance band with your hands, palms facing each other.', 'Keep your back straight and lean slightly back, engaging your core.', 'Pull the resistance band towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Nu7jqFE.gif'),
('01a0baa8-423f-7501-8aec-34d9e2951a47', 'rocking frog stretch', 'rocking-frog-stretch', 'rocking frog stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Start by kneeling on the ground with your knees hip-width apart.', 'Place your hands on the ground in front of you for support.', 'Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.', 'Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.', 'Hold this position for a few seconds, feeling a stretch in your glutes.', 'Slowly return to the starting position by bending your knees and lowering your hips back down.', 'Repeat for the desired number of repetitions.'], 'exercises/2Dk4xQV.gif'),
('01a0baa8-423f-7501-8aed-b78851423518', 'barbell full squat (back pov)', 'barbell-full-squat-back-pov', 'barbell full squat (back pov) using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes slightly turned out.', 'Hold the barbell across your upper back, resting it on your traps or rear delts.', 'Engage your core and keep your chest up as you begin to lower your body down.', 'Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.', 'Lower your body until your thighs are parallel to the ground or slightly below.', 'Keep your knees in line with your toes and your weight in your heels.', 'Drive through your heels to stand back up, extending your hips and knees.', 'Repeat for the desired number of repetitions.'], 'exercises/DhMl549.gif'),
('01a0baa8-423f-7501-8aee-1b51efa8dc8d', 'barbell standing wide grip biceps curl', 'barbell-standing-wide-grip-biceps-curl', 'barbell standing wide grip biceps curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.', 'Keep your back straight and your elbows close to your torso.', 'Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the barbell back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/faHKVkK.gif'),
('01a0baa8-423f-7501-8aef-b08c71084d5d', 'modified push up to lower arms', 'modified-push-up-to-lower-arms', 'modified push up to lower arms using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands directly under your shoulders and your body in a straight line.', 'Lower your body down towards the ground by bending your elbows, keeping them close to your sides.', 'Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.', 'Pause for a moment, then push through your palms to lift your forearms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/arvaszz.gif'),
('01a0baa8-423f-7501-8af0-61ed5045a07b', 'dumbbell arnold press v. 2', 'dumbbell-arnold-press-v-2', 'dumbbell arnold press v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.', 'Press the dumbbells upward until your arms are fully extended and your palms are facing forward.', 'Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/eOrFCnx.gif'),
('01a0baa8-423f-7501-8af1-ff3409f3aeeb', 'medicine ball chest push single response', 'medicine-ball-chest-push-single-response', 'medicine ball chest push single response using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding the medicine ball at chest level.', 'Extend your arms forward, pushing the medicine ball away from your chest.', 'Pause for a moment, then slowly bring the medicine ball back to your chest.', 'Repeat for the desired number of repetitions.'], 'exercises/jeHtrlO.gif'),
('01a0baa8-423f-7501-8af2-cd924790e62f', 'band y-raise', 'band-y-raise', 'band y-raise using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.', 'Keep your arms straight and lift them up and out to the sides, forming a ''Y'' shape with your body.', 'Squeeze your shoulder blades together at the top of the movement.', 'Slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/aHDy5O5.gif'),
('01a0baa8-423f-7501-8af3-d95bfe3dbaff', 'smith decline reverse-grip press', 'smith-decline-reverse-grip-press', 'smith decline reverse-grip press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the smith machine to a decline position.', 'Lie down on the bench with your feet secured under the foot pads.', 'Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.', 'Pause for a moment at the bottom, then push the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/MY9P1WA.gif'),
('01a0baa8-423f-7501-8af4-ce51c2e14880', 'roller body saw', 'roller-body-saw', 'roller body saw using roller.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a plank position with your forearms on the roller and your body in a straight line.', 'Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.', 'Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/XeMvLgE.gif'),
('01a0baa8-423f-7501-8af5-c320bd397d57', 'band seated twist', 'band-seated-twist', 'band seated twist using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the ground with your legs extended in front of you and your back straight.', 'Wrap the band around your waist and hold the ends with both hands.', 'Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.', 'Pause for a moment at the end of the twist, then slowly return to the starting position.', 'Repeat the twist to the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/S1JXDAG.gif'),
('01a0baa8-4240-7265-89bc-9801d13715fa', 'power clean', 'power-clean', 'power clean using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start with the barbell on the ground in front of you, with your feet shoulder-width apart.', 'Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.', 'As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.', 'As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.', 'Stand up with the barbell, fully extending your hips and knees.', 'Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/SiWCcTN.gif'),
('01a0baa8-4240-7265-89bd-952f3935d610', 'barbell standing bradford press', 'barbell-standing-bradford-press', 'barbell standing bradford press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.', 'Press the barbell overhead, fully extending your arms.', 'Lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/dCPESfR.gif'),
('01a0baa8-4240-7265-89be-710d626b5740', 'behind head chest stretch', 'behind-head-chest-stretch', 'behind head chest stretch using assisted.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand tall with your feet shoulder-width apart.', 'Interlace your fingers behind your head with your elbows pointing outwards.', 'Slowly squeeze your shoulder blades together and push your chest forward.', 'Hold the stretch for 15-30 seconds.', 'Release the stretch and repeat as desired.'], 'exercises/QoHIhPl.gif'),
('01a0baa8-4240-7265-89bf-16c4e2756d26', 'barbell rollerout', 'barbell-rollerout', 'barbell rollerout using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Kneel on the floor and hold a barbell with both hands, shoulder-width apart.', 'Roll the barbell forward, extending your arms and keeping your core engaged.', 'Continue rolling forward until your body is fully extended and your arms are overhead.', 'Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.', 'Repeat for the desired number of repetitions.'], 'exercises/7M66AVi.gif'),
('01a0baa8-4240-7265-89c0-f953d70720fc', 'lever t bar row', 'lever-t-bar-row', 'lever t bar row using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and footplate position to ensure proper alignment.', 'Sit on the machine with your chest against the pad and your feet flat on the footplate.', 'Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.', 'Keep your back straight and engage your core.', 'Pull the handles towards your torso, squeezing your shoulder blades together.', 'Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/aaXr7ld.gif'),
('01a0baa8-4240-7265-89c1-d92f2f004440', 'cable curl', 'cable-curl', 'cable curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing the cable machine with your feet shoulder-width apart.', 'Grasp the cable attachment with an underhand grip, palms facing up.', 'Keep your elbows close to your sides and your upper arms stationary.', 'Exhale and curl the cable attachment towards your shoulders, contracting your biceps.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Inhale and slowly lower the cable attachment back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/G08RZcQ.gif'),
('01a0baa8-4240-7265-89c2-41a1f061c519', 'march sit (wall)', 'march-sit-wall', 'march sit (wall) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your back against a wall and your feet hip-width apart.', 'Slowly slide your back down the wall until your knees are bent at a 90-degree angle.', 'Lift your right foot off the ground and bring your knee towards your chest.', 'Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.', 'Continue alternating between lifting your right and left foot for the desired number of repetitions.'], 'exercises/sVQCCeG.gif'),
('01a0baa8-4240-7265-89c3-72ea9d2ceb3c', 'dumbbell incline row', 'dumbbell-incline-row', 'dumbbell incline row using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Grab a dumbbell in each hand and sit on the bench with your chest against the incline.', 'Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.', 'Pull the dumbbells up towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/7vG5o25.gif'),
('01a0baa8-4240-7265-89c4-e0a5d073b2d6', 'barbell reverse close-grip bench press', 'barbell-reverse-close-grip-bench-press', 'barbell reverse close-grip bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Grasp the barbell with a reverse grip, hands shoulder-width apart.', 'Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'Slowly lower the barbell down towards your chest, keeping your elbows close to your body.', 'Pause for a moment when the barbell is just above your chest.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/YqJw82s.gif'),
('01a0baa8-4240-7265-89c5-03582cf23604', 'machine inner chest press', 'machine-inner-chest-press', 'machine inner chest press using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the machine with your back flat against the pad.', 'Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.', 'Push the handles forward until your arms are fully extended, exhaling during the movement.', 'Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.', 'Repeat for the desired number of repetitions.'], 'exercises/wDN97Ca.gif'),
('01a0baa8-4240-7265-89c6-ebcba6f3b210', 'push to run', 'push-to-run', 'push to run using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands shoulder-width apart and your body in a straight line.', 'Lower your chest towards the ground by bending your elbows, keeping your body straight.', 'Push through your hands to extend your arms and return to the starting position.', 'Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.', 'Continue alternating knees as fast as you can while maintaining good form.', 'Continue for the desired duration or number of repetitions.'], 'exercises/PrQbjvB.gif'),
('01a0baa8-4240-7265-89c7-bfe4687a0b79', 'barbell sitted alternate leg raise', 'barbell-sitted-alternate-leg-raise', 'barbell sitted alternate leg raise using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and hold a barbell across your thighs.', 'Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.', 'Lower the raised leg back down and repeat with the other leg.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/G7xoEzr.gif'),
('01a0baa8-4240-7265-89c8-b0048bc48778', 'band stiff leg deadlift', 'band-stiff-leg-deadlift', 'band stiff leg deadlift using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place the band around your ankles.', 'Hold the band with both hands in front of your thighs, palms facing your body.', 'Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.', 'As you lower, push your hips back and allow your knees to bend slightly.', 'Lower the band towards the ground, feeling a stretch in your hamstrings.', 'Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/kuMiR2T.gif'),
('01a0baa8-4240-7265-89c9-ae527036f3e4', 'band v-up', 'band-v-up', 'band v-up using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs straight and your arms extended overhead, holding the band.', 'Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.', 'Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/H6ETwO9.gif'),
('01a0baa8-4240-7265-89ca-8d0aa501b8c6', 'barbell jm bench press', 'barbell-jm-bench-press', 'barbell jm bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Lower the barbell to your chest, keeping your elbows tucked in close to your body.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/ZsiqXYa.gif'),
('01a0baa8-4240-7265-89cb-0c5d6dad710a', 'astride jumps (male)', 'astride-jumps-male', 'astride jumps (male) using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Bend your knees and lower your body into a squat position.', 'Jump explosively upwards, extending your legs and arms.', 'While in the air, spread your legs apart and bring your arms out to the sides.', 'Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.', 'Repeat for the desired number of repetitions.'], 'exercises/f9lVSSI.gif'),
('01a0baa8-4240-7265-89cc-186a1e63faef', 'cable two arm curl on incline bench', 'cable-two-arm-curl-on-incline-bench', 'cable two arm curl on incline bench using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with your back against the pad and your feet flat on the ground.', 'Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Inhale and slowly lower the handles back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/H9y3Dkr.gif'),
('01a0baa8-4240-7265-89cd-d5741b7e17fe', 'lever seated reverse fly', 'lever-seated-reverse-fly', 'lever seated reverse fly using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.', 'Grasp the handles with an overhand grip and keep your arms slightly bent.', 'Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.', 'Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/myfUsKf.gif'),
('01a0baa8-4240-7265-89ce-70feecbae937', 'cable pushdown', 'cable-pushdown', 'cable pushdown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a high pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.', 'Grasp the bar with an overhand grip, hands shoulder-width apart.', 'Keep your elbows close to your sides and your upper arms stationary.', 'Exhale and push the bar down until your elbows are fully extended.', 'Pause for a moment, then inhale and slowly return the bar to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/3ZflifB.gif'),
('01a0baa8-4240-7265-89cf-c0f6dc8af5d1', 'dumbbell seated preacher curl', 'dumbbell-seated-preacher-curl', 'dumbbell seated preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher curl bench with your feet flat on the floor.', 'Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.', 'Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/7D5bgLT.gif'),
('01a0baa8-4240-7265-89d0-493ee9485b3c', 'dumbbell lying supination on floor', 'dumbbell-lying-supination-on-floor', 'dumbbell lying supination on floor using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.', 'Rotate your palms to face up, keeping your elbows close to your sides.', 'Slowly curl the dumbbells towards your shoulders, squeezing your forearms.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/rEhi2o5.gif'),
('01a0baa8-4240-7265-89d1-b1a590ed4484', 'dumbbell single arm overhead carry', 'dumbbell-single-arm-overhead-carry', 'dumbbell single arm overhead carry using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.', 'Raise the dumbbell overhead, fully extending your arm.', 'Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.', 'Continue walking for the desired distance or time.', 'Switch hands and repeat the exercise.'], 'exercises/mWBtgmb.gif'),
('01a0baa8-4240-7265-89d2-bbe1a468caca', 'dumbbell incline breeding', 'dumbbell-incline-breeding', 'dumbbell incline breeding using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Sit on the bench with your back against the pad and feet flat on the ground.', 'Hold a dumbbell in each hand with an overhand grip, palms facing forward.', 'Start with your arms fully extended, perpendicular to the ground.', 'Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.', 'Pause for a moment at the bottom, then push the dumbbells back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/B3Rxp6L.gif'),
('01a0baa8-4240-7265-89d3-df547f376fa5', 'one arm slam (with medicine ball)', 'one-arm-slam-with-medicine-ball', 'one arm slam (with medicine ball) using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.', 'Bend your knees slightly and engage your core.', 'Raise the medicine ball above your head, fully extending your arm.', 'Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.', 'Catch the medicine ball on the bounce and repeat for the desired number of repetitions.'], 'exercises/jCrtE9b.gif'),
('01a0baa8-4240-7265-89d4-b02c0545b742', 'russian twist', 'russian-twist', 'russian twist using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the ground with your knees bent and feet flat on the floor.', 'Lean back slightly while keeping your back straight and your core engaged.', 'Hold your hands together in front of your chest or hold a weight if desired.', 'Lift your feet off the ground, balancing on your sit bones.', 'Twist your torso to the right, bringing your hands or weight towards the right side of your body.', 'Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/XVDdcoj.gif'),
('01a0baa8-4240-7265-89d5-1d9657142817', 'smith narrow row', 'smith-narrow-row', 'smith narrow row using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the machine with your feet flat on the floor.', 'Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.', 'Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/JGKowMS.gif'),
('01a0baa8-4240-7265-89d6-c1289798deef', 'bodyweight standing one arm row', 'bodyweight-standing-one-arm-row', 'bodyweight standing one arm row using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.', 'Bend forward at the hips, keeping your back straight and your core engaged.', 'Let the dumbbell hang straight down in front of you, with your arm fully extended.', 'Pull the dumbbell up towards your chest, keeping your elbow close to your body.', 'Squeeze your shoulder blades together at the top of the movement.', 'Lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/xbkPfaw.gif'),
('01a0baa8-4240-7265-89d7-4e9516a13161', 'suspended abdominal fallout', 'suspended-abdominal-fallout', 'suspended abdominal fallout using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a suspension trainer to a high anchor point and adjust the straps to waist height.', 'Stand facing away from the anchor point and hold the handles with your arms extended in front of you.', 'Lean forward at the waist, keeping your body straight and your core engaged.', 'Lower your body as far as you can while maintaining control and tension in your abs.', 'Pause for a moment at the bottom, then slowly raise your body back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/X3TCNEU.gif'),
('01a0baa8-4241-726c-82cb-cc465bdef30b', 'dumbbell biceps curl', 'dumbbell-biceps-curl', 'dumbbell biceps curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/NbVPDMW.gif'),
('01a0baa8-4241-726c-82cc-53658be4cadf', 'pike-to-cobra push-up', 'pike-to-cobra-push-up', 'pike-to-cobra push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.', 'Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.', 'Lower your upper body towards the ground by bending your elbows, keeping them close to your body.', 'As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.', 'Reverse the movement by bending your elbows and lowering your chest back down towards the ground.', 'Push through your hands to return to the inverted V position.', 'Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.', 'Repeat for the desired number of repetitions.'], 'exercises/XPUDTt7.gif'),
('01a0baa8-4241-726c-82cd-07700e882c14', 'cable seated rear lateral raise', 'cable-seated-rear-lateral-raise', 'cable seated rear lateral raise using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench facing the cable machine with your feet flat on the ground.', 'Grasp the cable handles with an overhand grip and extend your arms straight in front of you.', 'Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.', 'Pause for a moment at the top, then slowly lower your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/x825CZm.gif'),
('01a0baa8-4241-726c-82ce-8b7810eaaf05', 'cable one arm lateral raise', 'cable-one-arm-lateral-raise', 'cable one arm lateral raise using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, facing the cable machine.', 'Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.', 'Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arm back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/wEulIzp.gif'),
('01a0baa8-4241-726c-82cf-38f01e475566', 'arm slingers hanging straight legs', 'arm-slingers-hanging-straight-legs', 'arm slingers hanging straight legs using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your arms fully extended and your legs straight down.', 'Engage your core and lift your legs up in front of you until they are parallel to the ground.', 'Hold for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/PXTIwgu.gif'),
('01a0baa8-4241-726c-82d0-9e0e23b69d55', 'cable judo flip', 'cable-judo-flip', 'cable judo flip using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing the cable machine with your feet shoulder-width apart.', 'Hold the cable handle with both hands at chest level, palms facing down.', 'Engage your core and rotate your torso to the right, pulling the cable across your body.', 'As you rotate, pivot your back foot and allow your hips to rotate naturally.', 'Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.', 'Return to the starting position by reversing the movement, rotating your torso back to the center.', 'Repeat the movement on the opposite side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/MvQPqVW.gif'),
('01a0baa8-4241-726c-82d1-1c940a4990c0', 'dumbbell incline raise', 'dumbbell-incline-raise', 'dumbbell incline raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in each hand, resting on your thighs.', 'Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.', 'Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.', 'Repeat for the desired number of repetitions.'], 'exercises/nxW6BkN.gif'),
('01a0baa8-4241-726c-82d2-f435a806e90d', 'barbell split squat v. 2', 'barbell-split-squat-v-2', 'barbell split squat v. 2 using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.', 'Take a large step forward with your right foot, keeping your torso upright.', 'Lower your body by bending your knees and hips until your right thigh is parallel to the ground.', 'Pause for a moment, then push through your right heel to return to the starting position.', 'Repeat with your left leg forward for the desired number of repetitions.'], 'exercises/HBYyX94.gif'),
('01a0baa8-4241-726c-82d3-154aa76cc6b9', 'pelvic tilt', 'pelvic-tilt', 'pelvic tilt using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands by your sides.', 'Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.', 'Hold this position for a few seconds, focusing on contracting your abs.', 'Release the tilt and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/NKJ8o6x.gif'),
('01a0baa8-4241-726c-82d4-170334479a2e', 'weighted muscle up (on bar)', 'weighted-muscle-up-on-bar', 'weighted muscle up (on bar) using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.', 'Engage your core and pull your shoulder blades down and back.', 'Bend your elbows and pull your chest towards the bar, keeping your body straight.', 'Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.', 'Pause at the top of the movement, then slowly lower yourself back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/MCkqdKE.gif'),
('01a0baa8-4241-726c-82d5-3524d63f29fc', 'cable rope extension incline bench row', 'cable-rope-extension-incline-bench-row', 'cable rope extension incline bench row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.', 'Attach a rope handle to the cable machine and sit on the incline bench facing the machine.', 'Grab the rope handle with an overhand grip and lean forward, keeping your back straight.', 'Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.', 'Squeeze your shoulder blades together at the end of the movement.', 'Slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/MgKwAAo.gif'),
('01a0baa8-4241-726c-82d6-ad002cce57ba', 'dumbbell rear delt row_shoulder', 'dumbbell-rear-delt-rowshoulder', 'dumbbell rear delt row_shoulder using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Hold a dumbbell in each hand with your palms facing your body.', 'Bend forward at the waist, keeping your back straight and your core engaged.', 'Extend your arms straight down towards the floor, with a slight bend in your elbows.', 'Raise the dumbbells out to the sides, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/EKXOMEh.gif'),
('01a0baa8-4241-726c-82d7-85c6e12c95fa', 'trap bar deadlift', 'trap-bar-deadlift', 'trap bar deadlift using trap bar.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.', 'Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.', 'Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.', 'As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.', 'Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/jQGwmxN.gif'),
('01a0baa8-4241-726c-82d8-a9999a979b12', 'dumbbell one arm zottman preacher curl', 'dumbbell-one-arm-zottman-preacher-curl', 'dumbbell one arm zottman preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.', 'Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.', 'Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.', 'At the top of the curl, rotate your wrist so that your palm faces up.', 'Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/sxY5Biu.gif'),
('01a0baa8-4241-726c-82d9-8e03982dd74c', 'band close-grip push-up', 'band-close-grip-push-up', 'band close-grip push-up using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place a band around your upper arms, just above the elbows.', 'Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.', 'Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.', 'Push through your palms to extend your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ufaxB52.gif'),
('01a0baa8-4241-726c-82da-369856b83401', 'one leg floor calf raise', 'one-leg-floor-calf-raise', 'one leg floor calf raise using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.', 'Lift one foot off the ground and balance on the other foot.', 'Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.', 'Pause for a moment at the top, then slowly lower your heel back down to the starting position.', 'Repeat for the desired number of repetitions, then switch legs and repeat.'], 'exercises/0jp9Rlz.gif'),
('01a0baa8-4241-726c-82db-7a186b8a9ad7', 'quads', 'quads', 'quads using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Lower your body by bending your knees and pushing your hips back as if sitting on a chair.', 'Keep your chest up and your back straight.', 'Lower yourself until your thighs are parallel to the ground.', 'Push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/6YUfHPL.gif'),
('01a0baa8-4241-726c-82dc-d2abca35342e', 'cable rope seated row', 'cable-rope-seated-row', 'cable rope seated row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.', 'Grasp the cable ropes with an overhand grip, palms facing each other.', 'Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.', 'Pull the cable ropes towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/SJqRxOt.gif'),
('01a0baa8-4241-726c-82dd-2a6e005b39ab', 'dumbbell decline twist fly', 'dumbbell-decline-twist-fly', 'dumbbell decline twist fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie down on a decline bench with your head lower than your hips.', 'Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.', 'Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.', 'As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.', 'Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.', 'Repeat for the desired number of repetitions.'], 'exercises/reFHapa.gif'),
('01a0baa8-4241-726c-82de-8f84c233e771', 'dumbbell standing triceps extension', 'dumbbell-standing-triceps-extension', 'dumbbell standing triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in one hand.', 'Raise the dumbbell overhead, keeping your arm straight.', 'Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.', 'Extend your arm back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/PdmaD0N.gif'),
('01a0baa8-4241-726c-82df-ceccca88cb2b', 'barbell one arm floor press', 'barbell-one-arm-floor-press', 'barbell one arm floor press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back on the floor with your knees bent and feet flat on the ground.', 'Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.', 'Slowly lower the barbell towards your chest, keeping your elbow close to your body.', 'Pause for a moment at the bottom, then push the barbell back up to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/vtusOWT.gif'),
('01a0baa8-4241-726c-82e0-74847bc131b4', 'cable squat row (with rope attachment)', 'cable-squat-row-with-rope-attachment', 'cable squat row (with rope attachment) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope to a cable machine at waist height.', 'Stand facing the cable machine with your feet shoulder-width apart.', 'Bend your knees and lower your body into a squat position, keeping your back straight and chest up.', 'Grasp the rope with an overhand grip, with your hands shoulder-width apart.', 'Engage your core and pull the rope towards your body, squeezing your shoulder blades together.', 'Keep your elbows close to your body and continue pulling until your hands reach your chest.', 'Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/f7fnAIB.gif'),
('01a0baa8-4241-726c-82e1-a1378a94430b', 'barbell standing close grip curl', 'barbell-standing-close-grip-curl', 'barbell standing close grip curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.', 'Keep your elbows close to your torso and your upper arms stationary throughout the movement.', 'Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale as you slowly begin to bring the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/4dUn2iv.gif'),
('01a0baa8-4241-726c-82e2-5f815ed56951', 'roller seated single leg shoulder flexor depresor retractor', 'roller-seated-single-leg-shoulder-flexor-depresor-retractor', 'roller seated single leg shoulder flexor depresor retractor using roller.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a flat surface with your legs extended in front of you.', 'Hold the roller with both hands, palms facing down, and place it on your thighs.', 'Lean back slightly and engage your core muscles.', 'Raise the roller up to shoulder level, keeping your arms straight.', 'Slowly lower the roller back down to your thighs.', 'Repeat for the desired number of repetitions.'], 'exercises/CjETvlw.gif'),
('01a0baa8-4241-726c-82e3-e322e1f838ea', 'barbell standing twist', 'barbell-standing-twist', 'barbell standing twist using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.', 'Engage your core and keep your back straight throughout the exercise.', 'Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.', 'Pause for a moment at the end of the twist, then slowly return to the starting position.', 'Repeat the twist to the left side.', 'Continue alternating twists for the desired number of repetitions.'], 'exercises/yQe5HpE.gif'),
('01a0baa8-4241-726c-82e4-5ce63af7ef56', 'dumbbell seated triceps extension', 'dumbbell-seated-triceps-extension', 'dumbbell seated triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a dumbbell with both hands and extend your arms straight up overhead.', 'Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.', 'Pause for a moment, then straighten your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/kont8Ut.gif'),
('01a0baa8-4241-726c-82e5-fcb2aa316e71', 'ez bar seated close grip concentration curl', 'ez-bar-seated-close-grip-concentration-curl', 'ez bar seated close grip concentration curl using ez barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.', 'Rest your elbow on the inside of your thigh, just above the knee.', 'Curl the barbell up towards your shoulder while keeping your upper arm stationary.', 'Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Dsfz0Id.gif'),
('01a0baa8-4241-726c-82e6-1c95f93e1819', 'medicine ball catch and overhead throw', 'medicine-ball-catch-and-overhead-throw', 'medicine ball catch and overhead throw using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.', 'Bend your knees slightly and engage your core.', 'Lower your body into a squat position, keeping your back straight and chest up.', 'Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.', 'Release the ball at the top of the movement and catch it on the way down.', 'Lower your body back into the squat position and repeat for the desired number of repetitions.'], 'exercises/PsVS1QP.gif'),
('01a0baa8-4241-726c-82e7-edebc259f547', 'oblique crunches floor', 'oblique-crunches-floor', 'oblique crunches floor using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your back with your knees bent and feet flat on the floor.', 'Place your hands behind your head or cross them over your chest.', 'Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.', 'Pause for a moment, then lower your shoulder blades back down to the floor.', 'Repeat on the other side, alternating sides with each repetition.'], 'exercises/QUDd8WS.gif'),
('01a0baa8-4241-726c-82e8-63260ab84378', 'ring dips', 'ring-dips', 'ring dips using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by hanging from the rings with your arms fully extended and your body straight.', 'Lower your body by bending your elbows until your shoulders are below your elbows.', 'Push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/ezTvXcr.gif'),
('01a0baa8-4241-726c-82e9-b6d0e3b889cf', 'dumbbell lying one arm deltoid rear', 'dumbbell-lying-one-arm-deltoid-rear', 'dumbbell lying one arm deltoid rear using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.', 'Extend your arm straight down towards the floor, keeping it close to your body.', 'Raise your arm up and back, squeezing your shoulder blade towards your spine.', 'Pause for a moment at the top, then slowly lower your arm back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/gSw59a4.gif'),
('01a0baa8-4241-726c-82ea-08d430742742', 'weighted round arm', 'weighted-round-arm', 'weighted round arm using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Raise your arms out to the sides, keeping a slight bend in your elbows.', 'Continue lifting your arms until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/VLYXo8S.gif'),
('01a0baa8-4241-726c-82eb-cc852c139966', 'barbell standing leg calf raise', 'barbell-standing-leg-calf-raise', 'barbell standing leg calf raise using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place a barbell across your upper back.', 'Raise your heels off the ground as high as possible, using your calves.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/rGwhJ5o.gif'),
('01a0baa8-4241-726c-82ec-01660ec0a0aa', 'crunch (on stability ball, arms straight)', 'crunch-on-stability-ball-arms-straight', 'crunch (on stability ball, arms straight) using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.', 'Place your hands behind your head or cross them over your chest.', 'Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Sn8wxAI.gif'),
('01a0baa8-4241-726c-82ed-4b236c8c590f', 'single arm push-up', 'single-arm-push-up', 'single arm push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.', 'Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.', 'As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.', 'Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.', 'Repeat the movement, alternating the arm you extend with each repetition.'], 'exercises/MUic5zN.gif'),
('01a0baa8-4241-726c-82ee-944964b4c42d', 'dumbbell pullover hip extension on exercise ball', 'dumbbell-pullover-hip-extension-on-exercise-ball', 'dumbbell pullover hip extension on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.', 'Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.', 'Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.', 'Lower the dumbbell behind your head, keeping your arms straight and maintaining control.', 'Pause for a moment, then raise the dumbbell back to the starting position.', 'While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.', 'Lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/lI7easp.gif'),
('01a0baa8-4241-726c-82ef-136d2d5cde21', 'one arm dip', 'one-arm-dip', 'one arm dip using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing away from a bench or chair, with your feet shoulder-width apart.', 'Place one hand on the bench or chair behind you, fingers pointing towards your body.', 'Extend your legs out in front of you, keeping your heels on the ground.', 'Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.', 'Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides and repeat with the other arm.'], 'exercises/FAoIFMw.gif'),
('01a0baa8-4241-726c-82f0-87f327481008', 'barbell upright row v. 3', 'barbell-upright-row-v-3', 'barbell upright row v. 3 using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Let the barbell hang in front of your thighs, arms fully extended.', 'Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.', 'Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/fI18Rbc.gif'),
('01a0baa8-4241-726c-82f1-768f873f050b', 'dumbbell single leg deadlift', 'dumbbell-single-leg-deadlift', 'dumbbell single leg deadlift using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart, holding a dumbbell in your right hand.', 'Shift your weight onto your left leg and lift your right foot slightly off the ground.', 'Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.', 'At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.', 'Lower the dumbbell until your torso and right leg are parallel to the ground.', 'Pause for a moment, then engage your glutes and hamstrings to return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/gKozT8X.gif'),
('01a0baa8-4241-726c-82f2-1bd436f848fc', 'bodyweight standing close-grip row', 'bodyweight-standing-close-grip-row', 'bodyweight standing close-grip row using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Bend forward at the waist, keeping your back straight and your core engaged.', 'Extend your arms straight in front of you, gripping the bar or handles with a close grip.', 'Pull the bar or handles towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement, then slowly release and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/tig3PXb.gif'),
('01a0baa8-4241-726c-82f3-33b2c20afd9a', 'lunge with jump', 'lunge-with-jump', 'lunge with jump using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart.', 'Take a step forward with your right foot, lowering your body into a lunge position.', 'Push off with your right foot and jump into the air, switching the position of your feet mid-air.', 'Land softly with your left foot forward and immediately lower your body into a lunge position.', 'Continue alternating between lunges and jumps for the desired number of repetitions.'], 'exercises/PM1PZjg.gif'),
('01a0baa8-4242-7bf9-848e-d2af0074dc87', 'dumbbell plyo squat', 'dumbbell-plyo-squat', 'dumbbell plyo squat using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.', 'Lower your body into a squat position by bending your knees and pushing your hips back.', 'As you reach the bottom of the squat, explode upward, jumping off the ground.', 'While in the air, quickly switch the position of your feet, landing with your opposite foot forward.', 'Immediately lower your body back into a squat position and repeat the jump, switching your feet again.', 'Continue alternating the position of your feet with each jump for the desired number of repetitions.'], 'exercises/S4pwGlc.gif'),
('01a0baa8-4242-7bf9-848f-cfb79c6d4888', 'band front lateral raise', 'band-front-lateral-raise', 'band front lateral raise using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.', 'Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.', 'Pause for a moment at the top, then slowly lower the band back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/sTg7iys.gif'),
('01a0baa8-4242-7bf9-8490-4b3793a4b97e', 'dumbbell straight leg deadlift', 'dumbbell-straight-leg-deadlift', 'dumbbell straight leg deadlift using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', 'Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.', 'Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.', 'Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/oom75KC.gif'),
('01a0baa8-4242-7bf9-8491-58e2d0b8694b', 'lever shoulder press', 'lever-shoulder-press', 'lever shoulder press using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the machine with your back against the backrest.', 'Grasp the handles with an overhand grip and position your hands at shoulder level.', 'Push the handles upward until your arms are fully extended, but do not lock your elbows.', 'Pause for a moment at the top, then slowly lower the handles back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/67n3r98.gif'),
('01a0baa8-4242-7bf9-8492-9d8b7a7fcb43', 'reclining big toe pose with rope', 'reclining-big-toe-pose-with-rope', 'reclining big toe pose with rope using rope.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie on your back with your legs extended and your arms by your sides.', 'Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.', 'Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.', 'Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.', 'Repeat with your left leg.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/K5xgdvI.gif'),
('01a0baa8-4242-7bf9-8493-15fc315801d8', 'band jack knife sit-up', 'band-jack-knife-sit-up', 'band jack knife sit-up using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs straight and your arms extended overhead, holding the band.', 'Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.', 'Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/KCBKjma.gif'),
('01a0baa8-4242-7bf9-8494-7b5c785cfb8c', 'assisted hanging knee raise with throw down', 'assisted-hanging-knee-raise-with-throw-down', 'assisted hanging knee raise with throw down using assisted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', 'Engage your core and lift your knees towards your chest, keeping your legs together.', 'Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.', 'Allow your legs to swing back up and repeat the movement for the desired number of repetitions.'], 'exercises/8K0w2yA.gif'),
('01a0baa8-4242-7bf9-8495-4f7e94201135', 'chest dip (on dip-pull-up cage)', 'chest-dip-on-dip-pull-up-cage', 'chest dip (on dip-pull-up cage) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the dip bars to a height that allows you to comfortably grip them.', 'Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.', 'Jump up and straighten your arms, supporting your body weight on the bars.', 'Bend your knees and cross your ankles behind you.', 'Lower your body by bending your elbows, keeping your chest up and your shoulders down.', 'Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.', 'Push through your palms and extend your elbows to raise your body back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/XgWyAiA.gif'),
('01a0baa8-4242-7bf9-8496-66a61599747f', 'dumbbell w-press', 'dumbbell-w-press', 'dumbbell w-press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with a dumbbell in each hand, palms facing forward.', 'Raise the dumbbells to shoulder height, elbows bent and palms facing forward.', 'Press the dumbbells upward until your arms are fully extended overhead.', 'Lower the dumbbells back to shoulder height.', 'Repeat for the desired number of repetitions.'], 'exercises/vmwLyCg.gif'),
('01a0baa8-4242-7bf9-8497-f9a1a6a4336a', 'cable pulldown (pro lat bar)', 'cable-pulldown-pro-lat-bar', 'cable pulldown (pro lat bar) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.', 'Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.', 'Sit down and lean back slightly, keeping your chest up and your back straight.', 'Pull the bar down towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/qdRxqCj.gif'),
('01a0baa8-4242-7bf9-8498-7dab2491fba5', 'dumbbell rear lateral raise (support head)', 'dumbbell-rear-lateral-raise-support-head', 'dumbbell rear lateral raise (support head) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/UzkLrem.gif'),
('01a0baa8-4242-7bf9-8499-9e05a5cca6c1', 'twisted leg raise (female)', 'twisted-leg-raise-female', 'twisted leg raise (female) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs extended and your arms by your sides.', 'Bend your knees and lift your legs off the ground, bringing them towards your chest.', 'As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat the movement, this time twisting your hips to the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/yT9tk17.gif'),
('01a0baa8-4242-7bf9-849a-ddbf4df6e319', 'wide hand push up', 'wide-hand-push-up', 'wide hand push up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands wider than shoulder-width apart.', 'Keep your body in a straight line from head to toe.', 'Lower your chest towards the ground by bending your elbows, keeping them close to your sides.', 'Push through your palms to extend your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/JmMVpR3.gif'),
('01a0baa8-4242-7bf9-849b-f9bd7d478905', 'ankle circles', 'ankle-circles', 'ankle circles using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the ground with your legs extended in front of you.', 'Lift one leg off the ground and rotate your ankle in a circular motion.', 'Perform the desired number of circles in one direction, then switch to the other direction.', 'Repeat with the other leg.'], 'exercises/uL9CsKm.gif'),
('01a0baa8-4242-7bf9-849c-93079cbe0615', 'cable one arm incline fly on exercise ball', 'cable-one-arm-incline-fly-on-exercise-ball', 'cable one arm incline fly on exercise ball using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.', 'Hold a cable handle in one hand with your arm extended and palm facing inward.', 'Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.', 'Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/P14Dz9D.gif'),
('01a0baa8-4242-7bf9-849d-e875bad28c59', 'barbell standing reverse grip curl', 'barbell-standing-reverse-grip-curl', 'barbell standing reverse grip curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.', 'Keep your elbows close to your torso and your upper arms stationary.', 'Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/LWuA3aZ.gif'),
('01a0baa8-4242-7bf9-849e-891bf5038f98', 'cable close grip curl', 'cable-close-grip-curl', 'cable close grip curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a low pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.', 'Grasp the bar with an underhand grip, hands shoulder-width apart.', 'Keep your elbows close to your sides and your upper arms stationary throughout the exercise.', 'Exhale and curl the bar up towards your shoulders, contracting your biceps.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Inhale and slowly lower the bar back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/BCGQ6J5.gif'),
('01a0baa8-4242-7bf9-849f-6c03231b7cbe', 'cable incline fly', 'cable-incline-fly', 'cable incline fly using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine to a low position and attach the handles.', 'Sit on an incline bench with your back against the pad and feet flat on the floor.', 'Grasp the handles with an overhand grip and extend your arms straight out in front of you.', 'Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.', 'Pause for a moment at the fully extended position, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/tBWXbIT.gif'),
('01a0baa8-4242-7bf9-84a0-73eae9aa8721', 'cable incline fly (on stability ball)', 'cable-incline-fly-on-stability-ball', 'cable incline fly (on stability ball) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up a stability ball at an incline angle.', 'Attach the cable handles to the high pulleys of a cable machine.', 'Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.', 'Grasp the cable handles with an overhand grip, palms facing forward.', 'Lean forward slightly, keeping your back straight and core engaged.', 'With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.', 'Continue the motion until your arms are parallel to the ground.', 'Pause for a moment, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/27NNGFr.gif'),
('01a0baa8-4242-7bf9-84a1-122ed9dcc041', 'dumbbell bench press', 'dumbbell-bench-press', 'dumbbell bench press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.', 'Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.', 'Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/SpYC0Kp.gif'),
('01a0baa8-4242-7bf9-84a2-9dfd994152c9', 'dumbbell over bench one arm wrist curl', 'dumbbell-over-bench-one-arm-wrist-curl', 'dumbbell over bench one arm wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.', 'Rest your forearm on the bench with your wrist hanging off the edge.', 'Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/KI1DjNN.gif'),
('01a0baa8-4242-7bf9-84a3-3f6605d4fbf3', 'donkey calf raise', 'donkey-calf-raise', 'donkey calf raise using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your toes on an elevated surface, such as a step or block.', 'Place your hands on a stable support, such as a wall or railing, for balance.', 'Raise your heels as high as possible, lifting your body weight onto the balls of your feet.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/u5ESqzH.gif'),
('01a0baa8-4242-7bf9-84a4-a39c29b4b5e3', 'cable rope lying on floor tricep extension', 'cable-rope-lying-on-floor-tricep-extension', 'cable rope lying on floor tricep extension using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope to a cable machine and set it to the lowest position.', 'Lie on the floor facing up, with your head towards the cable machine.', 'Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.', 'Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.', 'Pause for a moment, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/U3ffHlY.gif'),
('01a0baa8-4242-7bf9-84a5-75a58bcf9404', 'stalder press', 'stalder-press', 'stalder press using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart and your arms extended overhead.', 'Bend your knees slightly and engage your core.', 'Lower your body down into a squat position while keeping your arms extended overhead.', 'As you squat down, press your arms down towards the ground, engaging your triceps.', 'Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.', 'Repeat for the desired number of repetitions.'], 'exercises/zd4P4B2.gif'),
('01a0baa8-4242-7bf9-84a6-3e0dfbdbb3c8', 'dumbbell standing overhead press', 'dumbbell-standing-overhead-press', 'dumbbell standing overhead press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.', 'Press the dumbbells upward until your arms are fully extended overhead.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.', 'Repeat for the desired number of repetitions.'], 'exercises/A6wtbuL.gif'),
('01a0baa8-4242-7bf9-84a7-cdf6f85e52e2', 'medicine ball close grip push up', 'medicine-ball-close-grip-push-up', 'medicine ball close grip push up using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands on the medicine ball, shoulder-width apart.', 'Lower your body towards the ground by bending your elbows, keeping them close to your sides.', 'Push back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/8K7m2SS.gif'),
('01a0baa8-4242-7bf9-84a8-dcb9d2ccc6ba', 'barbell revers wrist curl v. 2', 'barbell-revers-wrist-curl-v-2', 'barbell revers wrist curl v. 2 using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and your knees bent.', 'Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.', 'Rest your forearms on your thighs, allowing your wrists to hang off the edge.', 'Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.', 'Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/qDnGfDb.gif'),
('01a0baa8-4242-7bf9-84a9-7f42d97a4be9', 'cable low fly', 'cable-low-fly', 'cable low fly using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the handles to the low pulleys of a cable machine and select an appropriate weight.', 'Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.', 'Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.', 'Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.', 'Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.', 'Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.', 'Repeat for the desired number of repetitions.'], 'exercises/FVmZVhk.gif'),
('01a0baa8-4242-7bf9-84aa-646e535eb455', 'cable assisted inverse leg curl', 'cable-assisted-inverse-leg-curl', 'cable assisted inverse leg curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine so that the ankle attachment is at the lowest setting.', 'Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.', 'Hold onto the handles of the bench for stability.', 'Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.', 'Pause for a moment at the top of the movement, squeezing your hamstrings.', 'Inhale and slowly lower your legs back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/zHEpuuc.gif'),
('01a0baa8-4242-7bf9-84ab-9fef4d9e14e0', 'dumbbell lying one arm supinated triceps extension', 'dumbbell-lying-one-arm-supinated-triceps-extension', 'dumbbell lying one arm supinated triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your back and head supported, and your feet flat on the ground.', 'Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.', 'Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.', 'Pause for a moment at the bottom, then extend your arm back up to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/zZlORz6.gif'),
('01a0baa8-4242-7bf9-84ac-3bf0e5e04d21', 'band concentration curl', 'band-concentration-curl', 'band concentration curl using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your legs spread apart and your feet flat on the ground.', 'Hold one end of the band in your hand and step on the other end with your foot on the same side.', 'Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.', 'With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.', 'Pause for a moment at the top, then slowly lower your hand back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/kmVVAfu.gif'),
('01a0baa8-4242-7bf9-84ad-dc9c7f90fa53', 'dumbbell one arm chest fly on exercise ball', 'dumbbell-one-arm-chest-fly-on-exercise-ball', 'dumbbell one arm chest fly on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.', 'Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.', 'Extend your arm with the dumbbell straight up above your chest, palm facing inward.', 'Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.', 'Pause for a moment when your arm is parallel to the ground.', 'Engage your chest muscles to bring the dumbbell back up to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/Bpkf41o.gif'),
('01a0baa8-4242-7bf9-84ae-8417bcdf4cdc', 'posterior step to overhead reach', 'posterior-step-to-overhead-reach', 'posterior step to overhead reach using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart and your arms by your sides.', 'Take a step back with your right foot, landing on the ball of your foot.', 'Bend your left knee and lower your body into a lunge position.', 'As you lower into the lunge, simultaneously reach your arms overhead.', 'Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.', 'Repeat the movement on the other side, stepping back with your left foot and bending your right knee.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/ErqK3UL.gif'),
('01a0baa8-4242-7bf9-84af-88d273e37324', 'dumbbell close-grip press', 'dumbbell-close-grip-press-v2', 'dumbbell close-grip press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a flat bench with a dumbbell in each hand, resting on your thighs.', 'Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.', 'As you exhale, use your triceps to lift the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/RxayqAZ.gif'),
('01a0baa8-4242-7bf9-84b0-b7ce2aa4fecd', 'dumbbell standing calf raise', 'dumbbell-standing-calf-raise', 'dumbbell standing calf raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', 'Raise your heels off the ground as high as possible, using your calves.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/dPmaUaU.gif'),
('01a0baa8-4242-7bf9-84b1-b6123086591d', 'assisted sit-up', 'assisted-sit-up', 'assisted sit-up using assisted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the edge of a bench or have someone hold your feet down.', 'Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/aumB2IV.gif'),
('01a0baa8-4242-7bf9-84b2-e8e22f66b6ec', 'dumbbell lunge', 'dumbbell-lunge', 'dumbbell lunge using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', 'Take a step forward with your right foot, lowering your body into a lunge position.', 'Keep your back straight and your chest up as you lower your body.', 'Push through your right heel to return to the starting position.', 'Repeat with your left leg.', 'Alternate legs for the desired number of repetitions.'], 'exercises/RRWFUcw.gif'),
('01a0baa8-4242-7bf9-84b3-706216cb82b6', 'dumbbell standing bent over one arm triceps extension', 'dumbbell-standing-bent-over-one-arm-triceps-extension', 'dumbbell standing bent over one arm triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in one hand.', 'Bend forward at the waist, keeping your back straight and parallel to the ground.', 'Extend your arm straight back, keeping your elbow close to your body.', 'Slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/CJwa0vD.gif'),
('01a0baa8-4242-7bf9-84b4-eedcfef3c359', 'lever seated reverse fly (parallel grip)', 'lever-seated-reverse-fly-parallel-grip', 'lever seated reverse fly (parallel grip) using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.', 'Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.', 'Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.', 'Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/xiHiJcA.gif'),
('01a0baa8-4242-7bf9-84b5-6d8420c56e9e', 'assisted lying gluteus and piriformis stretch', 'assisted-lying-gluteus-and-piriformis-stretch', 'assisted lying gluteus and piriformis stretch using assisted.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie on your back with your legs extended.', 'Bend your right knee and place your right ankle on your left thigh, just above the knee.', 'Grasp your left thigh with both hands and gently pull it towards your chest.', 'Hold the stretch for 20-30 seconds.', 'Release the stretch and repeat on the other side.'], 'exercises/RQNVT10.gif'),
('01a0baa8-4242-7bf9-84b6-fed5b686bb42', 'back and forth step', 'back-and-forth-step', 'back and forth step using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Step forward with your right foot, bending your knee and lowering your body into a lunge position.', 'Push off with your right foot and step back to the starting position.', 'Repeat the movement with your left foot, alternating legs with each step.', 'Continue stepping back and forth, maintaining a steady pace.', 'Repeat for the desired duration or number of repetitions.'], 'exercises/fNGumX0.gif'),
('01a0baa8-4243-7616-a6e5-61ef6d32fa7f', 'exercise ball hip flexor stretch', 'exercise-ball-hip-flexor-stretch', 'exercise ball hip flexor stretch using stability ball.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Place the stability ball on the ground and kneel in front of it.', 'Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.', 'Extend your left leg behind you, keeping it straight.', 'Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.', 'Hold the stretch for 20-30 seconds, then switch sides and repeat.'], 'exercises/2LQkNPW.gif'),
('01a0baa8-4243-7616-a6e6-1f74c1432b75', 'band straight leg deadlift', 'band-straight-leg-deadlift', 'band straight leg deadlift using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place the band around your feet.', 'Hold the band with both hands, palms facing your body, and keep your arms straight.', 'Engage your core and maintain a slight bend in your knees.', 'Slowly hinge forward at your hips, keeping your back straight and chest lifted.', 'Lower the band towards the ground while keeping your legs straight.', 'Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/KUaoUV8.gif'),
('01a0baa8-4243-7616-a6e7-ed19fd280c5d', 'dumbbell cross body hammer curl v. 2', 'dumbbell-cross-body-hammer-curl-v-2', 'dumbbell cross body hammer curl v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your body.', 'Keep your elbows close to your torso and your upper arms stationary.', 'Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/HDYiZcY.gif'),
('01a0baa8-4243-7616-a6e8-573466a3a3dc', 'barbell incline row', 'barbell-incline-row', 'barbell incline row using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Lie face down on the bench with your chest against the pad and your feet flat on the ground.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Keep your back straight and your core engaged.', 'Pull the barbell towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/dmgMp3n.gif'),
('01a0baa8-4243-7616-a6e9-d446aa6a5977', 'barbell palms up wrist curl over a bench', 'barbell-palms-up-wrist-curl-over-a-bench', 'barbell palms up wrist curl over a bench using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.', 'Rest your forearms on the bench, allowing your wrists to hang off the edge.', 'Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.', 'Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/SJAA2IQ.gif'),
('01a0baa8-4243-7616-a6ea-1fd628f54ca0', 'dumbbell incline shoulder raise', 'dumbbell-incline-shoulder-raise', 'dumbbell incline shoulder raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.', 'Rest the dumbbells on your thighs and lean back onto the bench.', 'Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.', 'Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.', 'Repeat for the desired number of repetitions.'], 'exercises/6e2DcYX.gif'),
('01a0baa8-4243-7616-a6eb-a36c0f0f1cde', 'barbell upright row v. 2', 'barbell-upright-row-v-2', 'barbell upright row v. 2 using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Let the barbell hang in front of your thighs, arms fully extended.', 'Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.', 'Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/83HoW9X.gif'),
('01a0baa8-4243-7616-a6ec-00b5aa096961', 'barbell squat jump step rear lunge', 'barbell-squat-jump-step-rear-lunge', 'barbell squat jump step rear lunge using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.', 'Lower your body into a squat position by bending your knees and pushing your hips back.', 'Explode upwards, jumping off the ground as high as you can.', 'Land softly on your feet and immediately step back with one leg into a reverse lunge.', 'Lower your body down until your front thigh is parallel to the ground, keeping your back straight.', 'Push through your front heel to return to the starting position.', 'Repeat the jump and lunge sequence on the other leg.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/RYcV1kH.gif'),
('01a0baa8-4243-7616-a6ed-2cae32e98828', 'triceps dip (bench leg)', 'triceps-dip-bench-leg', 'triceps dip (bench leg) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.', 'Walk your feet forward, sliding your butt off the bench, and straighten your arms.', 'Bend your elbows and lower your body towards the ground, keeping your back close to the bench.', 'Push through your palms to straighten your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/VuoerH0.gif'),
('01a0baa8-4243-7616-a6ee-6a2f8e972793', 'weighted svend press', 'weighted-svend-press', 'weighted svend press using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.', 'Keep your elbows slightly bent and your palms facing each other.', 'Press the weight plate straight out in front of you, fully extending your arms.', 'Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/I1OBLnn.gif'),
('01a0baa8-4243-7616-a6ef-c0935f1114d5', 'dumbbell upright row (back pov)', 'dumbbell-upright-row-back-pov', 'dumbbell upright row (back pov) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', 'Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.', 'Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.', 'Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Iptlv6x.gif'),
('01a0baa8-4243-7616-a6f0-bdbc37e173e3', 'olympic barbell hammer curl', 'olympic-barbell-hammer-curl', 'olympic barbell hammer curl using olympic barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.', 'Let the barbell hang at arm''s length in front of your thighs, with your palms facing your body.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/o1ntciW.gif'),
('01a0baa8-4243-7616-a6f1-9825e23610d6', 'cable thibaudeau kayak row', 'cable-thibaudeau-kayak-row', 'cable thibaudeau kayak row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.', 'Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.', 'Lean forward from your hips, keeping your back straight and your abs engaged.', 'Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.', 'Squeeze your back muscles at the top of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides and perform with your left arm.'], 'exercises/ZgwWBoC.gif'),
('01a0baa8-4243-7616-a6f2-d82ec00c524e', 'chest and front of shoulder stretch', 'chest-and-front-of-shoulder-stretch', 'chest and front of shoulder stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand tall with your feet shoulder-width apart.', 'Extend your arms straight out in front of you at shoulder height.', 'Cross your arms in front of your body, with your right arm on top of your left arm.', 'Interlace your fingers and press your palms together.', 'Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.', 'Hold the stretch for 20-30 seconds, then release.', 'Repeat for the desired number of repetitions.'], 'exercises/Uto7l43.gif'),
('01a0baa8-4243-7616-a6f3-1f003405d02c', 'dumbbell seated reverse grip one arm overhead tricep extension', 'dumbbell-seated-reverse-grip-one-arm-overhead-tricep-extension', 'dumbbell seated reverse grip one arm overhead tricep extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a dumbbell with an underhand grip and extend your arm straight up overhead.', 'Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.', 'Pause for a moment, then extend your arm back up to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/5fKX7wi.gif'),
('01a0baa8-4243-7616-a6f4-e5fb95a34703', 'mixed grip chin-up', 'mixed-grip-chin-up', 'mixed grip chin-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.', 'Hang from the bar with your arms fully extended and your feet off the ground.', 'Engage your back muscles and pull your body up towards the bar, leading with your chest.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position with control.', 'Repeat for the desired number of repetitions.'], 'exercises/T8UpLkb.gif'),
('01a0baa8-4243-7616-a6f5-30494c9fde4e', 'dumbbell full can lateral raise', 'dumbbell-full-can-lateral-raise', 'dumbbell full can lateral raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.', 'Keep your back straight and engage your core.', 'Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/AQ0mC4Y.gif'),
('01a0baa8-4243-7616-a6f6-96176a2e982b', 'sissy squat', 'sissy-squat', 'sissy squat using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your toes pointing slightly outward.', 'Hold onto a stable object for balance if needed.', 'Slowly lower your body by bending your knees and leaning back, keeping your torso upright.', 'Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.', 'Pause for a moment, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/xdYPUtE.gif'),
('01a0baa8-4243-7616-a6f7-a103c422e223', 'cable incline pushdown', 'cable-incline-pushdown', 'cable incline pushdown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a high pulley cable machine.', 'Stand facing away from the machine with your feet shoulder-width apart.', 'Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.', 'Lean forward slightly and keep your back straight.', 'Pull the bar down towards your thighs by extending your elbows.', 'Pause for a moment at the bottom, then slowly return the bar to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/1PK5Uo3.gif'),
('01a0baa8-4243-7616-a6f8-5effe4dbfb2b', 'cable rope high pulley overhead tricep extension', 'cable-rope-high-pulley-overhead-tricep-extension', 'cable rope high pulley overhead tricep extension using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope to a high pulley and adjust the weight accordingly.', 'Stand facing away from the pulley machine with your feet shoulder-width apart.', 'Grasp the rope with both hands, palms facing down, and bring your hands above your head.', 'Keep your upper arms close to your head and perpendicular to the floor.', 'Slowly lower the rope behind your head by bending your elbows.', 'Pause for a moment, then extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/NN8nSNT.gif'),
('01a0baa8-4243-7616-a6f9-80af0fe29592', 'superman push-up', 'superman-push-up', 'superman push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.', 'Engage your core and lower your body towards the ground, keeping your elbows close to your sides.', 'As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.', 'Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.', 'Repeat the movement, this time lifting your left arm and right leg.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/4GqRrAk.gif'),
('01a0baa8-4243-7616-a6fa-c6e2353accc0', 'dumbbell alternate biceps curl', 'dumbbell-alternate-biceps-curl', 'dumbbell alternate biceps curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions, alternating arms.'], 'exercises/BU15nH4.gif'),
('01a0baa8-4243-7616-a6fb-51c10193bd6b', 'dumbbell incline palm-in press', 'dumbbell-incline-palm-in-press', 'dumbbell incline palm-in press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Sit on the bench with a dumbbell in each hand, palms facing each other.', 'Plant your feet firmly on the ground and keep your back straight against the bench.', 'Start with the dumbbells at shoulder level, elbows bent and palms facing each other.', 'Press the dumbbells up and away from your body, extending your arms fully.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/OVLmUuL.gif'),
('01a0baa8-4243-7616-a6fc-50c0f46eca84', 'band close-grip pulldown', 'band-close-grip-pulldown', 'band close-grip pulldown using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.', 'Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.', 'Step back to create tension in the band, keeping your feet hip-width apart.', 'Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/DptumMx.gif'),
('01a0baa8-4243-7616-a6fd-0a1ba189c303', 'exercise ball lat stretch', 'exercise-ball-lat-stretch', 'exercise ball lat stretch using stability ball.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on a stability ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in one hand and extend your arm straight up overhead.', 'Slowly lean to the opposite side, feeling a stretch in your lat muscle.', 'Hold the stretch for 20-30 seconds, then return to the starting position.', 'Repeat on the other side.'], 'exercises/sM84pE4.gif'),
('01a0baa8-4243-7616-a6fe-3897a244705e', 'band standing crunch', 'band-standing-crunch', 'band standing crunch using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a sturdy anchor point at waist height.', 'Stand facing away from the anchor point with your feet shoulder-width apart.', 'Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.', 'Engage your abs and slowly crunch forward, bringing your chest towards your knees.', 'Pause for a moment at the top of the crunch, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Kzg30R7.gif'),
('01a0baa8-4243-7616-a6ff-203afc639eb0', 'dumbbell seated revers grip concentration curl', 'dumbbell-seated-revers-grip-concentration-curl', 'dumbbell seated revers grip concentration curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.', 'Rest your elbow on the inside of your thigh, just above the knee.', 'Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/lyKCLmK.gif'),
('01a0baa8-4243-7616-a700-90a6783b721f', 'dumbbell decline shrug', 'dumbbell-decline-shrug', 'dumbbell decline shrug using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up a decline bench at a 45-degree angle.', 'Lie face down on the bench with your chest and stomach resting against it.', 'Hold a dumbbell in each hand with your arms fully extended towards the floor.', 'Keeping your arms straight, raise your shoulders towards your ears as high as possible.', 'Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/cwsAI4G.gif'),
('01a0baa8-4243-7616-a701-7b0429122040', 'dumbbell one arm reverse wrist curl', 'dumbbell-one-arm-reverse-wrist-curl', 'dumbbell one arm reverse wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the ground.', 'Hold a dumbbell in one hand with an overhand grip, palm facing down.', 'Rest your forearm on your thigh, with your wrist hanging off the edge.', 'Slowly lower the dumbbell towards the ground by flexing your wrist.', 'Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/BwSNDGt.gif'),
('01a0baa8-4243-7616-a702-dcc78d81b8f2', 'cable standing hip extension', 'cable-standing-hip-extension', 'cable standing hip extension using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a cable to a low pulley and stand facing away from the machine.', 'Place the cable around your ankle and stand with your feet shoulder-width apart.', 'Keep your core engaged and your back straight throughout the exercise.', 'Slowly extend your leg straight back, squeezing your glutes at the top of the movement.', 'Pause for a moment, then return to the starting position.', 'Repeat for the desired number of repetitions.', 'Switch sides and repeat with the other leg.'], 'exercises/Kpajagk.gif'),
('01a0baa8-4243-7616-a703-1c569273e374', 'weighted overhead crunch (on stability ball)', 'weighted-overhead-crunch-on-stability-ball', 'weighted overhead crunch (on stability ball) using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Hold a weight plate or dumbbell with both hands and extend your arms overhead.', 'Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.', 'Pause for a moment at the top, then slowly lower your torso back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/xmM75XG.gif'),
('01a0baa8-4243-7616-a704-b622d7cf3382', 'cable front shoulder raise', 'cable-front-shoulder-raise', 'cable front shoulder raise using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.', 'Keep your back straight and your core engaged.', 'Raise the cable handle in front of you, keeping your arms straight and your palms facing down.', 'Continue lifting until your arms are parallel to the floor.', 'Pause for a moment at the top, then slowly lower the cable handle back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/mTT3KLn.gif'),
('01a0baa8-4243-7616-a705-1eafdf7aba9e', 'dumbbell zottman curl', 'dumbbell-zottman-curl', 'dumbbell zottman curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your body.', 'Keep your elbows close to your torso and rotate your palms to face forward.', 'Curl the dumbbells up to your shoulders while keeping your upper arms stationary.', 'At the top of the movement, rotate your wrists so that your palms are facing away from your body.', 'Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.', 'Repeat for the desired number of repetitions.'], 'exercises/kXaIn5A.gif'),
('01a0baa8-4243-7616-a706-dcbc14b4aa15', 'mountain climber', 'mountain-climber', 'mountain climber using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.', 'Continue alternating legs in a running motion, keeping your hips low and your core engaged.', 'Maintain a steady pace and breathe evenly throughout the exercise.', 'Repeat for the desired number of repetitions.'], 'exercises/RJgzwny.gif'),
('01a0baa8-4243-7616-a707-b0556f2a936b', 'dumbbell incline one arm fly on exercise ball', 'dumbbell-incline-one-arm-fly-on-exercise-ball', 'dumbbell incline one arm fly on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with a dumbbell in one hand.', 'Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.', 'Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.', 'Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.', 'Pause for a moment when your arm is parallel to the ground.', 'Engage your chest muscles to bring the dumbbell back up to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/LLNh6q5.gif'),
('01a0baa8-4243-7616-a708-2bb2acb3c7fb', 'barbell stiff leg good morning', 'barbell-stiff-leg-good-morning', 'barbell stiff leg good morning using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Hold the barbell across your upper back, resting it on your traps.', 'Keeping your back straight, hinge forward at the hips, pushing your glutes back.', 'Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.', 'Engage your glutes and hamstrings to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/JrOHAZc.gif'),
('01a0baa8-4243-7616-a709-3e7120c19981', 'smith leg press', 'smith-leg-press', 'smith leg press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat and footplate of the smith machine to a comfortable position.', 'Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.', 'Grasp the handles or sides of the machine for stability.', 'Push the footplate away from you by extending your legs, keeping your back against the backrest.', 'Pause for a moment at the fully extended position.', 'Slowly bend your knees and lower the footplate back towards you, returning to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/7zdxRTl.gif'),
('01a0baa8-4243-7616-a70a-43a1447c9af3', 'cable decline press', 'cable-decline-press', 'cable decline press using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine to a decline position.', 'Sit on the decline bench facing the cable machine.', 'Grasp the handles with an overhand grip and position them at chest level.', 'Keep your feet flat on the ground and your back firmly against the bench.', 'Exhale and push the handles away from your body, extending your arms fully.', 'Pause for a moment at the end of the movement, squeezing your chest muscles.', 'Inhale and slowly return the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/2Pya1cP.gif'),
('01a0baa8-4243-7616-a70b-4f300ee8b4d2', 'dumbbell step-up lunge', 'dumbbell-step-up-lunge', 'dumbbell step-up lunge using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.', 'Place your right foot on the step, ensuring your entire foot is on the surface.', 'Push through your right heel and lift your body up onto the step, bringing your left foot up as well.', 'Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.', 'Repeat the movement, alternating which foot you step up with each time.', 'Continue for the desired number of repetitions.'], 'exercises/gFyFj9z.gif'),
('01a0baa8-4244-7d10-a1ef-b17c5356afa6', 'bodyweight drop jump squat', 'bodyweight-drop-jump-squat', 'bodyweight drop jump squat using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Lower your body into a squat position by bending your knees and pushing your hips back.', 'Jump up explosively, extending your hips, knees, and ankles.', 'While in mid-air, quickly bring your feet together.', 'Land softly on the balls of your feet and immediately drop back into a squat position.', 'Repeat for the desired number of repetitions.'], 'exercises/wfotm7S.gif'),
('01a0baa8-4244-7d10-a1f0-78b7b0c6e5ac', 'cable cross-over variation', 'cable-cross-over-variation', 'cable cross-over variation using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable pulleys to chest height.', 'Stand in the center of the cable machine with one foot in front of the other.', 'Grasp the handles with your palms facing down and your arms extended out to the sides.', 'Take a step forward, keeping your arms slightly bent.', 'With a slight bend in your elbows, bring your hands together in front of your chest.', 'Pause for a moment, then slowly return your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/0CXGHya.gif'),
('01a0baa8-4244-7d10-a1f1-6744604731d6', 'side push-up', 'side-push-up', 'side push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying on your side with your legs extended and stacked on top of each other.', 'Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.', 'Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.', 'Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.', 'Lower your body back down to the starting position with control.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/wpbD28t.gif'),
('01a0baa8-4244-7d10-a1f2-1e10193f5f1f', 'suspended reverse crunch', 'suspended-reverse-crunch', 'suspended reverse crunch using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', 'Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.', 'Pause for a moment at the top, then slowly lower your knees back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/R1WYG5D.gif'),
('01a0baa8-4244-7d10-a1f3-60dbba314e25', 'assisted prone hamstring', 'assisted-prone-hamstring', 'assisted prone hamstring using assisted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a mat or bench with your legs fully extended.', 'Have a partner or use a resistance band to secure your ankles.', 'Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/VedGSby.gif'),
('01a0baa8-4244-7d10-a1f4-540ea68890a5', 'dumbbell single leg calf raise', 'dumbbell-single-leg-calf-raise', 'dumbbell single leg calf raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand on the edge of a step or platform with your heels hanging off and your toes on the step.', 'Hold a dumbbell in one hand and place your other hand on a wall or railing for support.', 'Raise your heel as high as possible, lifting your body up onto your toes.', 'Pause for a moment at the top, then slowly lower your heel back down below the step.', 'Repeat for the desired number of repetitions, then switch to the other leg.'], 'exercises/1kB3Wmk.gif'),
('01a0baa8-4244-7d10-a1f5-2d98468b347e', 'weighted front raise', 'weighted-front-raise', 'weighted front raise using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.', 'Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/e4aFmFY.gif'),
('01a0baa8-4244-7d10-a1f6-24da979cb424', 'barbell full zercher squat', 'barbell-full-zercher-squat', 'barbell full zercher squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and toes slightly turned out.', 'Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.', 'Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.', 'Keep your knees in line with your toes and your weight in your heels.', 'Lower until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Drive through your heels to stand back up, squeezing your glutes at the top of the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/vR1vold.gif'),
('01a0baa8-4244-7d10-a1f7-a5ac7ff25978', 'lever seated row', 'lever-seated-row', 'lever seated row using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and footrests to a comfortable position.', 'Sit on the machine with your chest against the pad and your feet on the footrests.', 'Grasp the handles with an overhand grip, shoulder-width apart.', 'Keep your back straight and your core engaged.', 'Pull the handles towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement.', 'Slowly release the handles and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/7I6LNUG.gif'),
('01a0baa8-4244-7d10-a1f8-baabc6850897', 'side hip (on parallel bars)', 'side-hip-on-parallel-bars', 'side hip (on parallel bars) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand between two parallel bars with your feet shoulder-width apart.', 'Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.', 'Engage your abs and slowly lift your legs to the side, keeping them straight.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/jTkSc6o.gif'),
('01a0baa8-4244-7d10-a1f9-6fbfe14580c1', 'cable hip adduction', 'cable-hip-adduction', 'cable hip adduction using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the ankle cuff to your ankle and stand facing the cable machine.', 'Position yourself far enough away from the machine so that there is tension on the cable.', 'Place your hands on the machine for support.', 'Keeping your leg straight, slowly move your leg across your body towards the midline.', 'Pause for a moment at the end of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/hBGWILP.gif'),
('01a0baa8-4244-7d10-a1fa-bc944b5febd5', 'band one arm standing low row', 'band-one-arm-standing-low-row', 'band one arm standing low row using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a stable anchor point at waist height.', 'Stand facing the anchor point with your feet shoulder-width apart.', 'Hold the band with one hand, palm facing inward, and step back to create tension in the band.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Pull the band towards your waist, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement, then slowly release the band back to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/km0sQC0.gif'),
('01a0baa8-4244-7d10-a1fb-bfc069a8e8bc', 'dumbbell cuban press v. 2', 'dumbbell-cuban-press-v-2', 'dumbbell cuban press v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.', 'Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.', 'Rotate your wrists so that your palms are facing forward.', 'Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/BqgCRif.gif'),
('01a0baa8-4244-7d10-a1fc-e90fe152b5af', 'assisted standing triceps extension (with towel)', 'assisted-standing-triceps-extension-with-towel', 'assisted standing triceps extension (with towel) using assisted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.', 'Keep your elbows close to your ears and your upper arms stationary.', 'Slowly extend your forearms upward, squeezing your triceps at the top.', 'Pause for a moment, then slowly lower the towel back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/7HcfMBP.gif'),
('01a0baa8-4244-7d10-a1fd-6f1373647c5f', 'dumbbell seated lateral raise', 'dumbbell-seated-lateral-raise', 'dumbbell seated lateral raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.', 'Keep your back straight and core engaged.', 'Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/hxyTtWj.gif'),
('01a0baa8-4244-7d10-a1fe-867e3ed293a5', 'resistance band hip thrusts on knees (female)', 'resistance-band-hip-thrusts-on-knees-female', 'resistance band hip thrusts on knees (female) using resistance band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by kneeling on the ground with your knees hip-width apart and your feet flexed.', 'Wrap the resistance band around your thighs, just above your knees.', 'Place your hands on your hips or extend them out in front of you for balance.', 'Engage your glutes and core muscles.', 'Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.', 'Hold the position for a moment, then slowly lower your knees back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Pjbc0Kt.gif'),
('01a0baa8-4244-7d10-a1ff-ad554d77030d', 'cable bar lateral pulldown', 'cable-bar-lateral-pulldown', 'cable bar lateral pulldown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable pulley to a high position and attach a straight bar.', 'Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.', 'Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.', 'Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.', 'Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/eYnzaCm.gif'),
('01a0baa8-4244-7d10-a200-fa220b0f0d82', 'dumbbell preacher curl', 'dumbbell-preacher-curl', 'dumbbell preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.', 'Hold a dumbbell in each hand with your palms facing up and your arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/jivWf8n.gif'),
('01a0baa8-4244-7d10-a201-c621e7638baa', 'smith machine incline tricep extension', 'smith-machine-incline-tricep-extension', 'smith machine incline tricep extension using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat of the smith machine so that the bar is at shoulder height.', 'Sit on the bench with your back against the pad and your feet flat on the ground.', 'Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.', 'Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.', 'Lower the bar slowly towards your forehead, keeping your elbows close to your head.', 'Pause for a moment at the bottom, then push the bar back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/o8aOcrz.gif'),
('01a0baa8-4244-7d10-a202-1fea0880e13d', 'smith single leg split squat', 'smith-single-leg-split-squat', 'smith single leg split squat using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand in front of the smith machine with your feet shoulder-width apart.', 'Place one foot behind you on a bench or step, with your toes pointing forward.', 'Hold onto the smith machine bar for stability.', 'Bend your front knee and lower your body down into a lunge position, keeping your back straight.', 'Pause for a moment at the bottom, then push through your front heel to return to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/wWFspEi.gif'),
('01a0baa8-4244-7d10-a203-cb7b26fa66ca', 'smith upright row', 'smith-upright-row', 'smith upright row using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, facing the smith machine.', 'Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Keep your back straight and your core engaged.', 'Pull the barbell up towards your chin, leading with your elbows.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/1DN3iz4.gif'),
('01a0baa8-4244-7d10-a204-a9ae54cd5f57', 'cable seated chest press', 'cable-seated-chest-press', 'cable seated chest press using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and cable handles to a comfortable position.', 'Sit on the bench with your back straight and feet flat on the floor.', 'Grasp the cable handles with an overhand grip at shoulder height.', 'Push the handles forward and away from your body, extending your arms fully.', 'Pause for a moment, then slowly bring the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/nIR4Rwl.gif'),
('01a0baa8-4244-7d10-a205-01ba1817741a', 'cable bench press', 'cable-bench-press', 'cable bench press using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine to chest height and attach the handles.', 'Stand facing away from the machine with your feet shoulder-width apart.', 'Grasp the handles with an overhand grip and step forward to create tension in the cables.', 'Position your feet firmly on the ground and engage your core.', 'Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.', 'Push the handles forward, extending your arms fully in front of you.', 'Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.', 'Repeat for the desired number of repetitions.'], 'exercises/7xI5MXA.gif'),
('01a0baa8-4244-7d10-a206-965d06439407', 'band underhand pulldown', 'band-underhand-pulldown', 'band underhand pulldown using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.', 'Stand facing the anchor point with your feet shoulder-width apart.', 'Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.', 'Extend your arms fully overhead, keeping your elbows slightly bent.', 'Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/k6tUeqS.gif'),
('01a0baa8-4244-7d10-a207-1587112c2e57', 'barbell decline wide-grip press', 'barbell-decline-wide-grip-press', 'barbell decline wide-grip press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with your feet secured and your head lower than your hips.', 'Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.', 'Lower the barbell to your chest, keeping your elbows out to the sides.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/hl8DUh8.gif'),
('01a0baa8-4244-7d10-a208-059ab54d2585', 'dumbbell standing zottman preacher curl', 'dumbbell-standing-zottman-preacher-curl', 'dumbbell standing zottman preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing forward.', 'Place your upper arms against the preacher bench and keep your elbows slightly bent.', 'Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.', 'At the top of the movement, rotate your wrists so that your palms are facing downward.', 'Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.', 'Repeat for the desired number of repetitions.'], 'exercises/P2nRiUa.gif'),
('01a0baa8-4244-7d10-a209-3d7006bf392a', 'barbell one arm bent over row', 'barbell-one-arm-bent-over-row', 'barbell one arm bent over row using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.', 'Bend forward at the hips, keeping your back straight and your head in a neutral position.', 'Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.', 'Lower the barbell back down to the starting position in a controlled manner.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/Jsgsc27.gif'),
('01a0baa8-4244-7d10-a20a-81bbee999493', 'outside leg kick push-up', 'outside-leg-kick-push-up', 'outside leg kick push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.', 'Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.', 'As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.', 'Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.', 'Continue alternating leg kicks and push-ups for the desired number of repetitions.'], 'exercises/jNU1gFQ.gif'),
('01a0baa8-4244-7d10-a20b-b89de6461a3c', 'back lever', 'back-lever', 'back lever using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.', 'Engage your core and pull your shoulder blades down and back.', 'Bend your knees and tuck them towards your chest.', 'Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.', 'Hold this position for a few seconds, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/GaSzzuh.gif'),
('01a0baa8-4244-7d10-a20c-4cb2ca4a1899', 'barbell reverse grip incline bench press', 'barbell-reverse-grip-incline-bench-press', 'barbell reverse grip incline bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Lie down on the bench with your feet flat on the ground.', 'Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.', 'Pause for a moment when the barbell touches your chest.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/DU7I633.gif'),
('01a0baa8-4244-7d10-a20d-6a67b09db4da', 'cable press on exercise ball', 'cable-press-on-exercise-ball', 'cable press on exercise ball using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.', 'Hold the cable handles at chest height with your palms facing down and your elbows bent.', 'Engage your core and press the cable handles forward until your arms are fully extended.', 'Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vAwm6rK.gif'),
('01a0baa8-4244-7d10-a20e-37c492dd0622', 'cable standing one leg calf raise', 'cable-standing-one-leg-calf-raise', 'cable standing one leg calf raise using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Hold onto the cable machine for support.', 'Lift one leg off the ground and balance on the other leg.', 'Slowly raise your heel off the ground, lifting your body up onto your toes.', 'Pause for a moment at the top, then slowly lower your heel back down to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/fgc9Xdl.gif'),
('01a0baa8-4244-7d10-a20f-5e012eb9b036', 'cable seated twist', 'cable-seated-twist', 'cable seated twist using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a cable machine with your feet flat on the ground and your knees slightly bent.', 'Hold the cable handle with both hands and extend your arms straight in front of you.', 'Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.', 'Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.', 'Repeat on the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/UEjSrKI.gif'),
('01a0baa8-4244-7d10-a210-c62bf71b7763', 'cable two arm tricep kickback', 'cable-two-arm-tricep-kickback', 'cable two arm tricep kickback using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.', 'Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.', 'Pause for a moment, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vvNjDJS.gif'),
('01a0baa8-4245-7590-ab2b-c1bf6589da31', 'dumbbell lying elbow press', 'dumbbell-lying-elbow-press', 'dumbbell lying elbow press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.', 'Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.', 'Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.', 'Repeat for the desired number of repetitions.'], 'exercises/eOCOwIR.gif'),
('01a0baa8-4245-7590-ab2c-bbfabc320bc1', 'dynamic chest stretch (male)', 'dynamic-chest-stretch-male', 'dynamic chest stretch (male) using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand tall with your feet shoulder-width apart.', 'Extend your arms straight out to the sides, parallel to the ground.', 'Slowly bring your arms forward, crossing them in front of your body.', 'Feel the stretch in your chest muscles.', 'Hold the stretch for 10-30 seconds.', 'Return to the starting position and repeat for the desired number of repetitions.'], 'exercises/3uj0Ozg.gif'),
('01a0baa8-4245-7590-ab2d-8c2c6850b4e2', 'dumbbell rear lunge', 'dumbbell-rear-lunge', 'dumbbell rear lunge using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', 'Take a step backward with your right foot, lowering your body into a lunge position.', 'Bend your left knee and lower your body until your left thigh is parallel to the ground.', 'Pause for a moment, then push through your left heel to return to the starting position.', 'Repeat on the other side, stepping back with your left foot.'], 'exercises/SSsBDwB.gif'),
('01a0baa8-4245-7590-ab2e-5a2ff4ab1fa2', 'cable standing cross-over high reverse fly', 'cable-standing-cross-over-high-reverse-fly', 'cable standing cross-over high reverse fly using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a D-handle to each side of a cable machine at shoulder height.', 'Stand in the middle of the cable machine with your feet shoulder-width apart.', 'Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.', 'Keep a slight bend in your elbows and maintain a straight back throughout the exercise.', 'Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.', 'Pause for a moment at the peak of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/P5p0j8B.gif'),
('01a0baa8-4245-7590-ab2f-8f91d39b34f5', 'dumbbell standing one arm extension', 'dumbbell-standing-one-arm-extension', 'dumbbell standing one arm extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in one hand.', 'Raise the dumbbell overhead, fully extending your arm.', 'Keep your upper arm close to your head and perpendicular to the ground.', 'Slowly lower the dumbbell behind your head, bending your elbow.', 'Pause for a moment, then raise the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/BCUR88E.gif'),
('01a0baa8-4245-7590-ab30-69e1633c439c', 'dumbbell contralateral forward lunge', 'dumbbell-contralateral-forward-lunge', 'dumbbell contralateral forward lunge using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', 'Take a step forward with your right foot, keeping your back straight and core engaged.', 'Lower your body by bending both knees until your right thigh is parallel to the ground.', 'Push through your right heel to return to the starting position.', 'Repeat with your left leg.', 'Alternate legs for the desired number of repetitions.'], 'exercises/ecl28tP.gif'),
('01a0baa8-4245-7590-ab31-e1292a870228', 'cable standing crunch (with rope attachment)', 'cable-standing-crunch-with-rope-attachment', 'cable standing crunch (with rope attachment) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope to a cable machine at chest height.', 'Stand facing away from the machine with your feet shoulder-width apart.', 'Hold the rope with both hands and bring it behind your head, keeping your elbows bent.', 'Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.', 'Pause for a moment at the top of the crunch, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/XU3ePuv.gif'),
('01a0baa8-4245-7590-ab32-66ea2995712a', 'sled lying calf press', 'sled-lying-calf-press', 'sled lying calf press using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the sled machine to a comfortable weight.', 'Sit on the sled machine with your back against the pad and your feet on the platform.', 'Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.', 'Push the platform away from you by extending your ankles, keeping your knees slightly bent.', 'Continue pushing until your calves are fully contracted.', 'Hold the contraction for a moment, then slowly lower the platform back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/g376LuL.gif'),
('01a0baa8-4245-7590-ab33-3daccce8d288', 'resistance band seated hip abduction', 'resistance-band-seated-hip-abduction', 'resistance band seated hip abduction using resistance band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a chair or bench with your back straight and feet flat on the ground.', 'Wrap the resistance band around your thighs, just above your knees.', 'Place your hands on the sides of the chair or bench for support.', 'Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.', 'Pause for a moment at the end of the movement, then slowly bring your knees back together.', 'Repeat for the desired number of repetitions.'], 'exercises/0xDpB4L.gif'),
('01a0baa8-4245-7590-ab34-54b066bb4473', 'cable standing inner curl', 'cable-standing-inner-curl', 'cable standing inner curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Grasp the cable handle with an underhand grip, palms facing up.', 'Keep your elbows close to your sides and your upper arms stationary.', 'Exhale and curl the cable handle towards your shoulders, contracting your biceps.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Inhale and slowly lower the cable handle back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/YwnI4ja.gif'),
('01a0baa8-4245-7590-ab35-38a26bd78206', 'band squat row', 'band-squat-row', 'band squat row using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a sturdy anchor point at waist height.', 'Stand facing the anchor point with your feet shoulder-width apart.', 'Hold the band handles with your palms facing each other and your arms extended in front of you.', 'Bend your knees and lower into a squat position, keeping your back straight and chest lifted.', 'From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/w1NOByi.gif'),
('01a0baa8-4245-7590-ab36-8808083653a5', 'side push neck stretch', 'side-push-neck-stretch', 'side push neck stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand or sit up straight with your shoulders relaxed.', 'Tilt your head to the right, bringing your right ear towards your right shoulder.', 'Place your right hand on the left side of your head and gently apply pressure to increase the stretch.', 'Hold the stretch for 15-30 seconds.', 'Repeat on the other side, tilting your head to the left and applying pressure with your left hand.', 'Repeat the stretch 2-3 times on each side.'], 'exercises/oQRJYkC.gif'),
('01a0baa8-4245-7590-ab37-c0c77a3515df', 'smith hack squat', 'smith-hack-squat', 'smith hack squat using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the barbell on the smith machine to an appropriate height for your body.', 'Stand with your feet shoulder-width apart, toes slightly pointed outwards.', 'Position yourself under the barbell, resting it on your upper traps and shoulders.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Engage your core and keep your chest up as you unrack the barbell.', 'Take a step back and position your feet slightly wider than shoulder-width apart.', 'Bend your knees and lower your body down, keeping your chest up and back straight.', 'Continue descending until your thighs are parallel to the ground or slightly below.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ZuPXtCK.gif'),
('01a0baa8-4245-7590-ab38-634ac1e1f135', 'cable seated one arm concentration curl', 'cable-seated-one-arm-concentration-curl', 'cable seated one arm concentration curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the floor and your back straight.', 'Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.', 'Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Slowly lower the cable handle back to the starting position while inhaling.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/rZ80Gbp.gif'),
('01a0baa8-4245-7590-ab39-617d8144395d', 'barbell pin presses', 'barbell-pin-presses', 'barbell pin presses using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up a barbell on a power rack at chest height.', 'Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.', 'Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.', 'Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.', 'Pause for a moment when the barbell touches your chest.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/bndCa3Q.gif'),
('01a0baa8-4245-7590-ab3a-b96f3ad2a792', 'dumbbell kickbacks on exercise ball', 'dumbbell-kickbacks-on-exercise-ball', 'dumbbell kickbacks on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.', 'Extend your arms straight back, squeezing your triceps at the top of the movement.', 'Pause for a moment, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/cAvTaSg.gif'),
('01a0baa8-4245-7590-ab3b-58f2c52ff1d2', 'weighted russian twist v. 2', 'weighted-russian-twist-v-2', 'weighted russian twist v. 2 using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the ground with your knees bent and feet flat on the floor.', 'Hold the weight with both hands in front of your chest.', 'Lean back slightly to engage your core muscles.', 'Twist your torso to the right, bringing the weight towards the right side of your body.', 'Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/YIUAtYf.gif'),
('01a0baa8-4245-7590-ab3c-a44a362c9275', 'assisted lying glutes stretch', 'assisted-lying-glutes-stretch', 'assisted lying glutes stretch using assisted.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie on your back with your legs extended.', 'Bend your right knee and place your right ankle on your left thigh, just above the knee.', 'Grasp your left thigh with both hands and gently pull it towards your chest.', 'Hold the stretch for 20-30 seconds.', 'Release and repeat on the other side.'], 'exercises/yn0LjwL.gif'),
('01a0baa8-4245-7590-ab3d-a0a00c089839', 'dumbbell step up single leg balance with bicep curl', 'dumbbell-step-up-single-leg-balance-with-bicep-curl', 'dumbbell step up single leg balance with bicep curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.', 'Place your right foot on the step, ensuring your entire foot is in contact with the surface.', 'Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.', 'At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.', 'Lower the dumbbells back down and simultaneously lower your left foot back to the ground.', 'Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/76vfTdU.gif'),
('01a0baa8-4245-7590-ab3e-98a1fe002e38', 'dumbbell rear lateral raise', 'dumbbell-rear-lateral-raise', 'dumbbell rear lateral raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.', 'Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/v1qBec9.gif'),
('01a0baa8-4245-7590-ab3f-131aa81c4e91', 'dumbbell incline curl', 'dumbbell-incline-curl', 'dumbbell incline curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.', 'Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ae9UoXQ.gif'),
('01a0baa8-4245-7590-ab40-3799b3a4571a', 'neck side stretch', 'neck-side-stretch', 'neck side stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand or sit up straight with your shoulders relaxed.', 'Tilt your head to one side, bringing your ear towards your shoulder.', 'Hold the stretch for 15-30 seconds.', 'Repeat on the other side.', 'Perform 2-4 sets on each side.'], 'exercises/x2chWLO.gif'),
('01a0baa8-4245-7590-ab41-b146aa04df3f', 'barbell standing wide-grip curl', 'barbell-standing-wide-grip-curl', 'barbell standing wide-grip curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.', 'Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body.', 'Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.', 'Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/NdIb5Z1.gif'),
('01a0baa8-4245-7590-ab42-e4830c5feb2c', 'resistance band seated shoulder press', 'resistance-band-seated-shoulder-press', 'resistance band seated shoulder press using resistance band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a chair or bench with your back straight and feet flat on the ground.', 'Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.', 'Press the band overhead, extending your arms fully.', 'Pause for a moment at the top, then slowly lower the band back down to shoulder level.', 'Repeat for the desired number of repetitions.'], 'exercises/S93zLTG.gif'),
('01a0baa8-4245-7590-ab43-cdbbfcf4e03c', 'barbell clean-grip front squat', 'barbell-clean-grip-front-squat', 'barbell clean-grip front squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.', 'Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.', 'Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.', 'Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.', 'Repeat for the desired number of repetitions.'], 'exercises/qi996YS.gif'),
('01a0baa8-4245-7590-ab44-9730bba3dcaf', 'barbell seated calf raise', 'barbell-seated-calf-raise', 'barbell seated calf raise using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.', 'Place the balls of your feet on a raised platform, such as a block or step.', 'Position the barbell across your thighs and hold it securely with your hands.', 'Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ktsFQAZ.gif'),
('01a0baa8-4245-7590-ab45-9eb42f2306c1', 'cable side bend', 'cable-side-bend', 'cable side bend using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and grasp the cable handle with one hand.', 'Keep your back straight and your core engaged.', 'Slowly bend sideways at the waist, lowering the cable handle towards your knee.', 'Pause for a moment, then return to the starting position.', 'Repeat on the other side.', 'Alternate sides for the desired number of repetitions.'], 'exercises/wPypxFY.gif'),
('01a0baa8-4245-7590-ab46-f112d89c8772', 'cable straight back seated row', 'cable-straight-back-seated-row', 'cable straight back seated row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.', 'Grasp the cable handles with an overhand grip, palms facing down.', 'Keep your back straight and lean slightly forward from the hips.', 'Pull the cable handles towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Tq6gbK6.gif'),
('01a0baa8-4245-7590-ab47-faa37f9fe836', 'wide-grip chest dip on high parallel bars', 'wide-grip-chest-dip-on-high-parallel-bars', 'wide-grip chest dip on high parallel bars using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.', 'Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.', 'Pause for a moment, then push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/O2K9Vb5.gif'),
('01a0baa8-4245-7590-ab48-8496f2e6c965', 'back pec stretch', 'back-pec-stretch', 'back pec stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand tall with your feet shoulder-width apart.', 'Extend your arms straight out in front of you, parallel to the ground.', 'Cross your arms in front of your body, with your right arm over your left arm.', 'Interlock your fingers and rotate your palms away from your body.', 'Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.', 'Hold the stretch for 15-30 seconds, then release.', 'Repeat on the opposite side.'], 'exercises/chfnQnM.gif'),
('01a0baa8-4245-7590-ab49-49ff8d0aa02b', 'dumbbell reverse spider curl', 'dumbbell-reverse-spider-curl', 'dumbbell reverse spider curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/6sMAmNv.gif'),
('01a0baa8-4245-7590-ab4a-9a62cc25ce9c', 'bench pull-ups', 'bench-pull-ups', 'bench pull-ups using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Position yourself under a bar or a sturdy horizontal surface that is at chest height.', 'Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.', 'Hang with your arms fully extended and your body straight.', 'Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.', 'Continue pulling until your chin is above the bar or surface.', 'Lower yourself back down to the starting position with control.', 'Repeat for the desired number of repetitions.'], 'exercises/mExgrF9.gif'),
('01a0baa8-4245-7590-ab4b-24cff1676194', 'lever standing chest press', 'lever-standing-chest-press', 'lever standing chest press using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the machine with your feet flat on the ground.', 'Grasp the handles with an overhand grip and position your hands at chest level.', 'Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.', 'Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/WbNq5Xu.gif'),
('01a0baa8-4245-7590-ab4c-8ae87b412a7a', 'smith sprint lunge', 'smith-sprint-lunge', 'smith sprint lunge using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up the smith machine with the barbell at hip height.', 'Stand facing away from the machine with your feet shoulder-width apart.', 'Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.', 'Bend your left knee and lower your body into a lunge position, keeping your back straight.', 'Push through your left heel to return to the starting position.', 'Repeat on the other side, stepping back with your left foot.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/HsjbB1z.gif'),
('01a0baa8-4245-7590-ab4d-964844bb3599', 'cable side crunch', 'cable-side-crunch', 'cable side crunch using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a cable handle to a low pulley and stand sideways to the machine.', 'Grasp the handle with the hand furthest from the machine and place your other hand on your hip.', 'Keep your feet shoulder-width apart and your knees slightly bent.', 'With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.', 'Pause for a moment at the bottom, then slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/q2ADGqV.gif'),
('01a0baa8-4245-7590-ab4e-efc2f226d99d', 'cable straight arm pulldown (with rope)', 'cable-straight-arm-pulldown-with-rope', 'cable straight arm pulldown (with rope) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope to the cable machine at the highest setting.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the rope with both hands, palms facing down.', 'Extend your arms fully in front of you, keeping your elbows slightly bent.', 'Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.', 'Pause for a moment at the bottom, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/DT14T9T.gif'),
('01a0baa8-4245-7590-ab4f-51372fd9ef05', 'self assisted inverse leg curl', 'self-assisted-inverse-leg-curl', 'self assisted inverse leg curl using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back on a mat or bench with your legs extended.', 'Place your hands by your sides or under your glutes for support.', 'Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.', 'Pause for a moment at the top, then slowly lower your legs back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/GwYwElT.gif'),
('01a0baa8-4245-7590-ab50-993f19e26b86', 'barbell reverse curl', 'barbell-reverse-curl', 'barbell reverse curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.', 'Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.', 'Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.', 'Repeat for the desired number of repetitions.'], 'exercises/xNrS20v.gif'),
('01a0baa8-4245-7590-ab51-0a1192421e29', 'dumbbell lying extension (across face)', 'dumbbell-lying-extension-across-face', 'dumbbell lying extension (across face) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', 'Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.', 'Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.', 'Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/L2V5Nan.gif'),
('01a0baa8-4245-7590-ab52-172e084482fd', 'smith decline bench press', 'smith-decline-bench-press', 'smith decline bench press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the decline bench to the desired angle.', 'Lie down on the bench with your feet secured under the foot pads.', 'Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.', 'Pause for a moment at the bottom, then push the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ETZfAbZ.gif'),
('01a0baa8-4245-7590-ab53-57257f1800e9', 'weighted close grip chin-up on dip cage', 'weighted-close-grip-chin-up-on-dip-cage', 'weighted close grip chin-up on dip cage using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.', 'Hang from the bars with your arms fully extended, feet off the ground, and body straight.', 'Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.', 'Continue pulling until your chin is above the bars, then pause for a moment.', 'Slowly lower your body back down to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/Gk1r408.gif'),
('01a0baa8-4245-7590-ab54-a59ef0472613', 'captains chair straight leg raise', 'captains-chair-straight-leg-raise', 'captains chair straight leg raise using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.', 'Keep your upper body stable and your back straight.', 'Engage your abs and lift your legs up in front of you, keeping them straight.', 'Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/weoDEpH.gif'),
('01a0baa8-4245-7590-ab55-179e3e4deda2', 'skin the cat', 'skin-the-cat', 'skin the cat using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by hanging from a bar with your arms fully extended and your body relaxed.', 'Engage your core and lift your legs up, bringing your knees towards your chest.', 'Continue to lift your legs up and over your head, allowing your body to pass through the arms.', 'Once your legs are fully extended over your head, begin to lower them back down towards the starting position.', 'As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.', 'Repeat for the desired number of repetitions.'], 'exercises/MSfvriJ.gif'),
('01a0baa8-4245-7590-ab56-006735bbcae7', 'cable reverse crunch', 'cable-reverse-crunch', 'cable reverse crunch using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a cable to a low pulley and lie down facing up on a mat.', 'Hold the cable with both hands and extend your arms straight up towards the ceiling.', 'Bend your knees and lift your legs up, bringing your thighs towards your chest.', 'While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.', 'Pause for a moment at the top, then slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/RqOtqD7.gif'),
('01a0baa8-4245-7590-ab57-2ebe4142797d', 'barbell incline reverse-grip press', 'barbell-incline-reverse-grip-press', 'barbell incline reverse-grip press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.', 'Pause for a moment at the bottom, then push the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/641mIfk.gif'),
('01a0baa8-4245-7590-ab58-92d143159a48', 'dumbbell one arm prone hammer curl', 'dumbbell-one-arm-prone-hammer-curl', 'dumbbell one arm prone hammer curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.', 'Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/LIGZSTA.gif'),
('01a0baa8-4245-7590-ab59-321b51d23699', 'barbell rear lunge v. 2', 'barbell-rear-lunge-v-2', 'barbell rear lunge v. 2 using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell across your upper back.', 'Take a step backward with your right foot, landing on the ball of your foot.', 'Bend both knees to lower your body until your left thigh is parallel to the ground.', 'Push through your left heel to return to the starting position.', 'Repeat with the other leg.'], 'exercises/62Nw60O.gif'),
('01a0baa8-4245-7590-ab5a-fc2daf7650e1', 'scapula dips', 'scapula-dips', 'scapula dips using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart and your arms extended in front of you.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.', 'Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/7xeukSt.gif'),
('01a0baa8-4245-7590-ab5b-36dcc8fef1bd', 'barbell glute bridge', 'barbell-glute-bridge', 'barbell glute bridge using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.', 'Place a barbell across your hips, holding it securely with both hands.', 'Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.', 'Pause for a moment at the top, squeezing your glutes.', 'Slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/qKBpF7I.gif'),
('01a0baa8-4245-7590-ab5c-a95f50bc8a41', 'dumbbell single leg squat', 'dumbbell-single-leg-squat', 'dumbbell single leg squat using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', 'Extend one leg forward and keep it off the ground throughout the exercise.', 'Bend your standing leg and lower your body down as if sitting back into a chair.', 'Keep your chest up and your back straight.', 'Pause for a moment at the bottom, then push through your heel to return to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/H6ybluc.gif'),
('01a0baa8-4245-7590-ab5d-53a3155c8525', 'barbell lateral lunge', 'barbell-lateral-lunge', 'barbell lateral lunge using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a barbell across your upper back.', 'Take a big step to the side with your right foot, keeping your left foot planted.', 'Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.', 'Push off with your right foot and return to the starting position.', 'Repeat on the other side, stepping with your left foot.'], 'exercises/py1HSzx.gif'),
('01a0baa8-4245-7590-ab5e-fee008041622', 'push-up (on stability ball)', 'push-up-on-stability-ball', 'push-up (on stability ball) using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.', 'Extend your legs straight out behind you, balancing on your toes.', 'Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.', 'Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/Y4BRNQF.gif'),
('01a0baa8-4246-70a2-8b94-1d649dacaf8e', 'three bench dip', 'three-bench-dip', 'three bench dip using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your hands gripping the edge, fingers pointing forward.', 'Slide your butt off the bench, supporting your weight with your hands.', 'Bend your elbows and lower your body until your upper arms are parallel to the ground.', 'Push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/DQ0cqkT.gif'),
('01a0baa8-4246-70a2-8b95-79f0391e65e2', 'barbell skier', 'barbell-skier', 'barbell skier using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.', 'Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.', 'As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/4Leypho.gif'),
('01a0baa8-4246-70a2-8b96-3678faf6335f', 'bench dip (knees bent)', 'bench-dip-knees-bent', 'bench dip (knees bent) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.', 'Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.', 'Bend your elbows and lower your body towards the ground, keeping your back close to the bench.', 'Pause for a moment at the bottom, then push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/RrLske5.gif'),
('01a0baa8-4246-70a2-8b97-84b774b626c9', 'push-up', 'push-up', 'push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.', 'Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.', 'Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/I4hDWkc.gif'),
('01a0baa8-4246-70a2-8b98-6b8de8816d2d', 'smith standing leg calf raise', 'smith-standing-leg-calf-raise', 'smith standing leg calf raise using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.', 'Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.', 'Place your hands on the bar for stability.', 'Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/6MaEjVA.gif'),
('01a0baa8-4246-70a2-8b99-8dd8d71aa56e', 'dumbbell around pullover', 'dumbbell-around-pullover', 'dumbbell around pullover using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your head at one end and your feet firmly on the ground.', 'Hold a dumbbell with both hands and extend your arms straight above your chest.', 'Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.', 'Pause for a moment at the bottom, then raise the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vi8EhoE.gif'),
('01a0baa8-4246-70a2-8b9a-bf427c81fde8', 'cable reverse preacher curl', 'cable-reverse-preacher-curl', 'cable reverse preacher curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine so that the preacher curl pad is at chest height.', 'Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.', 'Grab the cable handles with an underhand grip, shoulder-width apart.', 'Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Inhale and slowly lower the handles back to the starting position, fully extending your elbows.', 'Repeat for the desired number of repetitions.'], 'exercises/IwX5NqK.gif'),
('01a0baa8-4246-70a2-8b9b-d42729718ea5', 'decline crunch', 'decline-crunch', 'decline crunch using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.', 'Place your hands behind your head or across your chest.', 'Engage your abs and lift your upper body towards your knees, curling your torso.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/9Ap7miY.gif'),
('01a0baa8-4246-70a2-8b9c-3e2dbd52de91', 'dumbbell prone incline hammer curl', 'dumbbell-prone-incline-hammer-curl', 'dumbbell prone incline hammer curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the bench to a 45-degree incline.', 'Lie face down on the bench with a dumbbell in each hand, palms facing each other.', 'Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/cWemPG8.gif'),
('01a0baa8-4246-70a2-8b9d-2c95e9c31003', 'band push sit-up', 'band-push-sit-up', 'band push sit-up using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band securely to a stable anchor point.', 'Lie flat on your back with your knees bent and feet flat on the ground.', 'Hold the band with both hands and extend your arms straight up towards the ceiling.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/zFzbBfL.gif'),
('01a0baa8-4246-70a2-8b9e-b84f1cf6f924', 'dumbbell lying triceps extension', 'dumbbell-lying-triceps-extension', 'dumbbell lying triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with a dumbbell in each hand, palms facing each other.', 'Extend your arms straight up over your chest, keeping your elbows close to your body.', 'Lower the dumbbells down towards your forehead, bending your elbows.', 'Pause for a moment, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/mpKZGWz.gif'),
('01a0baa8-4246-70a2-8b9f-8c9a0e9e79e6', 'arms apart circular toe touch (male)', 'arms-apart-circular-toe-touch-male', 'arms apart circular toe touch (male) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and arms extended to the sides.', 'Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.', 'As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.', 'Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/RtyAsy1.gif'),
('01a0baa8-4246-70a2-8ba0-8b493726cb28', 'cable rear pulldown', 'cable-rear-pulldown', 'cable rear pulldown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine so that the pulley is at the highest position.', 'Sit facing the machine with your feet flat on the ground and your knees slightly bent.', 'Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.', 'Lean back slightly, keeping your back straight and your chest up.', 'Pull the cable attachment down towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/SpsOSXk.gif'),
('01a0baa8-4246-70a2-8ba1-6f548604e51b', 'cable standing shoulder external rotation', 'cable-standing-shoulder-external-rotation', 'cable standing shoulder external rotation using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Hold the cable handle with your arm extended in front of you, parallel to the ground.', 'Keep your elbow slightly bent and your shoulder blades pulled back.', 'Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.', 'Pause for a moment at the end of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/FWdVhcW.gif'),
('01a0baa8-4246-70a2-8ba2-158d0aef1d0e', 'dumbbell zottman preacher curl', 'dumbbell-zottman-preacher-curl', 'dumbbell zottman preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.', 'Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.', 'At the top of the curl, rotate your wrists so that your palms are facing down.', 'Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.', 'Repeat for the desired number of repetitions.'], 'exercises/y5U5B9Y.gif'),
('01a0baa8-4246-70a2-8ba3-9543bd55ed06', 'dumbbell incline one arm press on exercise ball', 'dumbbell-incline-one-arm-press-on-exercise-ball', 'dumbbell incline one arm press on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.', 'Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.', 'Hold the dumbbell at shoulder height with your palm facing forward.', 'Press the dumbbell upward until your arm is fully extended.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/Bg5JKSH.gif'),
('01a0baa8-4246-70a2-8ba4-8415aef033a8', 'barbell reverse grip decline bench press', 'barbell-reverse-grip-decline-bench-press', 'barbell reverse grip decline bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with your feet secured and your head lower than your hips.', 'Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.', 'Pause for a moment at the bottom, then push the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/DotAgEF.gif'),
('01a0baa8-4246-70a2-8ba5-63d70f96869a', 'barbell preacher curl', 'barbell-preacher-curl', 'barbell preacher curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.', 'Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.', 'Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/qOgPVf6.gif'),
('01a0baa8-4246-70a2-8ba6-1942d2e3ef40', 'bodyweight side lying biceps curl', 'bodyweight-side-lying-biceps-curl', 'bodyweight side lying biceps curl using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your side with your legs extended and your head supported by your arm.', 'Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.', 'Pause for a moment at the top, then slowly lower your forearm back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/gscGLOU.gif'),
('01a0baa8-4246-70a2-8ba7-efb39e2014c7', 'cable seated curl', 'cable-seated-curl', 'cable seated curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a cable machine with your feet flat on the ground and your back straight.', 'Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/8oYqOt9.gif'),
('01a0baa8-4246-70a2-8ba8-b8ac9b90a60f', 'barbell bench press', 'barbell-bench-press', 'barbell bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.', 'Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'Lower the barbell slowly towards your chest, keeping your elbows tucked in.', 'Pause for a moment when the barbell touches your chest.', 'Push the barbell back up to the starting position by extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/EIeI8Vf.gif'),
('01a0baa8-4246-70a2-8ba9-e7e28e95713f', 'dumbbell pullover', 'dumbbell-pullover', 'dumbbell pullover using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your head at one end and your feet on the floor.', 'Hold a dumbbell with both hands and extend your arms straight above your chest.', 'Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.', 'Pause for a moment, then raise the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/9XjtHvS.gif'),
('01a0baa8-4246-70a2-8baa-f2ffb69d204c', 'dumbbell one arm upright row', 'dumbbell-one-arm-upright-row', 'dumbbell one arm upright row using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.', 'Let the dumbbell hang at arm''s length in front of your thighs, with your palm facing your body.', 'Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/6cKQC5E.gif'),
('01a0baa8-4246-70a2-8bab-df9c2ea8bcfc', 'standing pelvic tilt', 'standing-pelvic-tilt', 'standing pelvic tilt using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Place your hands on your hips or let them hang by your sides.', 'Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.', 'Hold the position for a few seconds, then release and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/cuKYxhu.gif'),
('01a0baa8-4246-70a2-8bac-78d42d23f4de', 'cable standing twist row (v-bar)', 'cable-standing-twist-row-v-bar', 'cable standing twist row (v-bar) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a v-bar attachment to a cable machine at chest height.', 'Stand facing the cable machine with your feet shoulder-width apart.', 'Grasp the v-bar with an overhand grip, palms facing down.', 'Take a step back to create tension in the cable.', 'Keep your back straight and core engaged throughout the exercise.', 'Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.', 'As you pull, twist your torso to one side, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement, feeling the contraction in your upper back.', 'Slowly release the tension and return to the starting position, untwisting your torso.', 'Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep.'], 'exercises/JOZhu2h.gif'),
('01a0baa8-4246-70a2-8bad-cbfb865754c1', 'barbell squat (on knees)', 'barbell-squat-on-knees', 'barbell squat (on knees) using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.', 'Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.', 'Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.', 'Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/oR7O9LW.gif'),
('01a0baa8-4246-70a2-8bae-653477620ed4', 'twisted leg raise', 'twisted-leg-raise', 'twisted leg raise using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs extended and your arms by your sides.', 'Place your hands under your glutes for support.', 'Engage your abs and lift both legs off the ground, keeping them straight.', 'As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat the movement, this time twisting your hips to the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/C0eCeEt.gif'),
('01a0baa8-4246-70a2-8baf-51360990ccd9', 'lever unilateral row', 'lever-unilateral-row', 'lever unilateral row using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself facing the machine.', 'Grasp the handles with an overhand grip and keep your back straight.', 'Pull the handles towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/oROuvrX.gif'),
('01a0baa8-4246-70a2-8bb0-4272c7b02ed7', 'band one arm twisting chest press', 'band-one-arm-twisting-chest-press', 'band one arm twisting chest press using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a sturdy anchor point at chest height.', 'Stand with your side facing the anchor point and grab the band with one hand.', 'Step away from the anchor point to create tension in the band.', 'Position your feet shoulder-width apart and slightly bend your knees.', 'Bring your hand holding the band across your body, towards the opposite shoulder.', 'While maintaining tension in the band, push your hand forward and away from your body, extending your arm.', 'Slowly return to the starting position and repeat for the desired number of repetitions.', 'Switch sides and repeat the exercise with the other hand.'], 'exercises/c16nYGA.gif'),
('01a0baa8-4246-70a2-8bb1-7da6a44a3848', 'cable kneeling rear delt row (with rope) (male)', 'cable-kneeling-rear-delt-row-with-rope-male', 'cable kneeling rear delt row (with rope) (male) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope handle to a low cable pulley and kneel down facing the machine.', 'Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.', 'Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.', 'Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.', 'Slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/G61cXLk.gif'),
('01a0baa8-4246-70a2-8bb2-61dd3db34a28', 'exercise ball seated triceps stretch', 'exercise-ball-seated-triceps-stretch', 'exercise ball seated triceps stretch using stability ball.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on a stability ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in one hand and extend your arm straight up above your head.', 'Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.', 'Hold the stretch for a few seconds, then return to the starting position.', 'Repeat with the other arm.'], 'exercises/7ePTw4B.gif'),
('01a0baa8-4246-70a2-8bb3-4178e7aa12c6', 'side hip abduction', 'side-hip-abduction', 'side hip abduction using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your hands on your hips.', 'Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.', 'Pause for a moment at the top, then slowly lower your leg back down to the starting position.', 'Repeat on the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/7WaDzyL.gif'),
('01a0baa8-4246-70a2-8bb4-f5b7a8eedeeb', 'star jump (male)', 'star-jump-male', 'star jump (male) using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your arms by your sides.', 'Bend your knees slightly and jump up explosively.', 'As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.', 'Land softly on the balls of your feet with your knees slightly bent.', 'Repeat for the desired number of repetitions.'], 'exercises/HtfCpfi.gif'),
('01a0baa8-4246-70a2-8bb5-998a8c0d600d', 'barbell standing wide military press', 'barbell-standing-wide-military-press', 'barbell standing wide military press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.', 'Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.', 'Press the barbell overhead, extending your arms fully.', 'Lower the barbell back to shoulder height and repeat for the desired number of repetitions.'], 'exercises/Kyd9Rz5.gif'),
('01a0baa8-4246-70a2-8bb6-4c35fc2ed48b', 'dumbbell waiter biceps curl', 'dumbbell-waiter-biceps-curl', 'dumbbell waiter biceps curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing forward.', 'Keep your upper arms close to your body and your elbows tucked in.', 'Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/KOpzGBL.gif'),
('01a0baa8-4246-70a2-8bb7-6c914d1e8045', 'reverse dip', 'reverse-dip', 'reverse dip using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Position yourself between two parallel bars with your arms fully extended and your body straight.', 'Lower your body by bending your elbows until your upper arms are parallel to the ground.', 'Pause for a moment, then push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/NZ5Qqkz.gif'),
('01a0baa8-4246-70a2-8bb8-24171a333365', 'modified hindu push-up (male)', 'modified-hindu-push-up-male', 'modified hindu push-up (male) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.', 'Lower your body towards the ground, bending your elbows and keeping your core engaged.', 'As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.', 'Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/epOSYUZ.gif'),
('01a0baa8-4246-70a2-8bb9-e5844c2a683a', 'push-up (wall) v. 2', 'push-up-wall-v-2', 'push-up (wall) v. 2 using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a wall, about arm''s length away.', 'Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.', 'Step back with your feet, keeping them hip-width apart.', 'Engage your core and keep your body in a straight line from head to heels.', 'Bend your elbows and lower your chest towards the wall, keeping your body straight.', 'Pause for a moment, then push yourself back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/NCmbLCw.gif'),
('01a0baa8-4246-70a2-8bba-80d70a030069', 'dumbbell decline triceps extension', 'dumbbell-decline-triceps-extension', 'dumbbell decline triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.', 'Extend your arms fully, keeping your elbows close to your head.', 'Lower the dumbbells slowly behind your head, bending your elbows.', 'Pause for a moment, then raise the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/OTgkHwR.gif'),
('01a0baa8-4246-70a2-8bbb-a736431abafc', 'peroneals stretch', 'peroneals-stretch', 'peroneals stretch using rope.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the ground with your legs extended in front of you.', 'Loop the rope around the ball of your foot and hold the ends of the rope with your hands.', 'Gently pull the rope towards you, flexing your foot and stretching your calf muscles.', 'Hold the stretch for 15-30 seconds.', 'Release the tension on the rope and repeat the stretch on the other leg.', 'Repeat for the desired number of repetitions.'], 'exercises/XhfS1DZ.gif'),
('01a0baa8-4246-70a2-8bbc-66a37b291555', 'band step-up', 'band-step-up', 'band step-up using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place a band around your thighs, just above your knees.', 'Stand facing a step or platform with your feet hip-width apart.', 'Step up onto the platform with your right foot, pushing through your heel.', 'Extend your left leg behind you, keeping it straight.', 'Lower your left foot back down to the ground.', 'Repeat with your left foot stepping up onto the platform.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/d5bTEPV.gif'),
('01a0baa8-4246-70a2-8bbd-d280d092a006', 'dumbbell push press', 'dumbbell-push-press', 'dumbbell push press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.', 'Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.', 'Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.', 'Repeat for the desired number of repetitions.'], 'exercises/FS63wTN.gif'),
('01a0baa8-4246-70a2-8bbe-7c65ae2bc935', 'cable overhead triceps extension (rope attachment)', 'cable-overhead-triceps-extension-rope-attachment', 'cable overhead triceps extension (rope attachment) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope to a cable machine at a high position.', 'Stand facing away from the machine with your feet shoulder-width apart.', 'Grasp the rope with both hands, palms facing each other, and bring your hands above your head.', 'Keep your upper arms close to your head and your elbows pointing forward.', 'Slowly lower the rope behind your head by bending your elbows.', 'Pause for a moment, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/2IxROQ1.gif'),
('01a0baa8-4246-70a2-8bbf-17fc1fc40e82', 'dumbbell lying femoral', 'dumbbell-lying-femoral', 'dumbbell lying femoral using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.', 'Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/FkBIE6a.gif'),
('01a0baa8-4246-70a2-8bc0-a67156e7b1f7', 'barbell seated close-grip concentration curl', 'barbell-seated-close-grip-concentration-curl', 'barbell seated close-grip concentration curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.', 'Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.', 'Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.', 'Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/1V1gj1u.gif'),
('01a0baa8-4246-70a2-8bc1-7ee7c4356927', 'dumbbell one arm seated hammer curl', 'dumbbell-one-arm-seated-hammer-curl', 'dumbbell one arm seated hammer curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a dumbbell in one hand with a neutral grip (palms facing each other).', 'Rest your elbow on the inside of your thigh, just above the knee.', 'Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/jK2hZ6n.gif'),
('01a0baa8-4246-70a2-8bc2-c62850d64ecf', 'band single leg split squat', 'band-single-leg-split-squat', 'band single leg split squat using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart and place a resistance band around your ankles.', 'Take a big step forward with your right foot and a smaller step back with your left foot.', 'Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.', 'Push through your right heel to return to the starting position.', 'Repeat on the other side.'], 'exercises/y8bYM8w.gif'),
('01a0baa8-4246-70a2-8bc3-9abed4857068', 'cable decline fly', 'cable-decline-fly', 'cable decline fly using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine to a decline position.', 'Stand facing away from the machine with your feet shoulder-width apart.', 'Hold the handles with your palms facing forward and your arms extended straight out in front of you.', 'Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.', 'Pause for a moment at the fully extended position, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/7saC5zz.gif'),
('01a0baa8-4246-70a2-8bc4-cf678afbca40', 'dumbbell one arm seated bicep curl on exercise ball', 'dumbbell-one-arm-seated-bicep-curl-on-exercise-ball', 'dumbbell one arm seated bicep curl on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in one hand with your palm facing up and your arm fully extended.', 'Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/s999Hdo.gif'),
('01a0baa8-4247-72df-85f8-be9a54be11c6', 'band alternating biceps curl', 'band-alternating-biceps-curl', 'band alternating biceps curl using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.', 'Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.', 'Lower the arm back down to the starting position and repeat with the other arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/3omWx6P.gif'),
('01a0baa8-4247-72df-85f9-5ca43bf5f3df', 'band pull through', 'band-pull-through', 'band pull through using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a resistance band to a sturdy anchor point at ground level.', 'Stand facing away from the anchor point with your feet shoulder-width apart.', 'Step forward to create tension in the band, keeping your knees slightly bent.', 'Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.', 'Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.', 'Drive your hips forward and squeeze your glutes to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/VtTbiP3.gif'),
('01a0baa8-4247-72df-85fa-eee4033ca6a0', 'dumbbell rear delt raise', 'dumbbell-rear-delt-raise', 'dumbbell rear delt raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/mu5Guxt.gif'),
('01a0baa8-4247-72df-85fb-3e310ac163e5', 'quick feet v. 2', 'quick-feet-v-2', 'quick feet v. 2 using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your arms by your sides.', 'Begin by rapidly moving your feet up and down, as if you were running in place.', 'Keep your movements quick and light, focusing on staying on the balls of your feet.', 'Continue for the desired duration or number of repetitions.'], 'exercises/mweqJin.gif'),
('01a0baa8-4247-72df-85fc-321d1bf25ab7', 'tuck crunch', 'tuck-crunch', 'tuck crunch using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.', 'Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/BMMolZ3.gif'),
('01a0baa8-4247-72df-85fd-4df02f4c4f4c', 'bridge - mountain climber (cross body)', 'bridge---mountain-climber-cross-body', 'bridge - mountain climber (cross body) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.', 'Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.', 'Continue alternating sides, moving at a controlled pace.', 'Keep your hips level and avoid lifting your hips too high or sagging them too low.', 'Maintain a steady breathing pattern throughout the exercise.', 'Repeat for the desired number of repetitions.'], 'exercises/9c6T1YX.gif'),
('01a0baa8-4247-72df-85fe-03812a9bf89a', 'weighted muscle up', 'weighted-muscle-up', 'weighted muscle up using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.', 'Engage your core and pull your body up towards the bar, leading with your chest.', 'As you reach the top of the movement, transition your grip so that your palms are facing towards you.', 'Continue pulling yourself up until your chest reaches the bar, then pause for a moment.', 'Slowly lower yourself back down to the starting position, maintaining control throughout the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/JsOV1SU.gif'),
('01a0baa8-4247-72df-85ff-be129587cf23', 'band squat', 'band-squat', 'band squat using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, with the band placed just above your knees.', 'Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.', 'Make sure your knees are tracking over your toes and your weight is in your heels.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/TUZLh71.gif'),
('01a0baa8-4247-72df-8600-a02396535c47', 'dumbbell finger curls', 'dumbbell-finger-curls', 'dumbbell finger curls using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the ground and your back straight.', 'Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.', 'Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.', 'Repeat for the desired number of repetitions, then switch to the other hand.'], 'exercises/mtXengz.gif'),
('01a0baa8-4247-72df-8601-0ea06416dec2', 'triceps dips floor', 'triceps-dips-floor', 'triceps dips floor using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.', 'Slide your butt off the front of the chair with your legs extended in front of you.', 'Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.', 'Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.', 'Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/7aVz15j.gif'),
('01a0baa8-4247-72df-8602-f108a722c3d0', 'dumbbell alternate side press', 'dumbbell-alternate-side-press', 'dumbbell alternate side press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.', 'Press one dumbbell overhead while keeping the other dumbbell at shoulder height.', 'Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/izMnLqz.gif'),
('01a0baa8-4247-72df-8603-9fe078d9251c', 'band assisted pull-up', 'band-assisted-pull-up', 'band assisted pull-up using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a pull-up bar or sturdy anchor point.', 'Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.', 'Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.', 'Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.', 'Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/r1XNRYB.gif'),
('01a0baa8-4247-72df-8604-a3ebf8b0ee82', 'band one arm twisting seated row', 'band-one-arm-twisting-seated-row', 'band one arm twisting seated row using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the ground and your back straight.', 'Hold the band with one hand and extend your arm fully in front of you.', 'Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.', 'At the same time, twist your torso towards the side of the pulling arm.', 'Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/DKBwJrL.gif'),
('01a0baa8-4247-72df-8605-53b97266a882', 'dumbbell seated one leg calf raise', 'dumbbell-seated-one-leg-calf-raise', 'dumbbell seated one leg calf raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.', 'Extend your left leg straight out in front of you, keeping your foot flexed.', 'Place the ball of your right foot on an elevated surface, such as a step or weight plate.', 'Using your calf muscles, raise your right heel as high as possible.', 'Pause for a moment at the top, then slowly lower your heel back down to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/Ia7tumC.gif'),
('01a0baa8-4247-72df-8606-b908dac7ecad', 'dumbbell reverse fly', 'dumbbell-reverse-fly', 'dumbbell reverse fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Extend your arms straight down in front of you, palms facing each other.', 'Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/EAs3xL9.gif'),
('01a0baa8-4247-72df-8607-9542c22dd360', 'clap push up', 'clap-push-up', 'clap push up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands slightly wider than shoulder-width apart.', 'Lower your body towards the ground by bending your elbows, keeping your core engaged.', 'Push through your palms explosively to propel your body off the ground.', 'While in mid-air, clap your hands together before landing back in the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/wigSg76.gif'),
('01a0baa8-4247-72df-8608-10fdc5d7df86', 'barbell rear lunge', 'barbell-rear-lunge', 'barbell rear lunge using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.', 'Take a step backward with your right foot, landing on the ball of your foot.', 'Bend both knees to lower your body until your left thigh is parallel to the ground.', 'Push through your left heel to return to the starting position.', 'Repeat with the other leg.'], 'exercises/VaP75jl.gif'),
('01a0baa8-4247-72df-8609-77673b2a82d8', 'exercise ball supine triceps extension', 'exercise-ball-supine-triceps-extension', 'exercise ball supine triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.', 'Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.', 'Pause for a moment, then raise the dumbbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Gm2Uv1z.gif'),
('01a0baa8-4247-72df-860a-cbdb890338ec', 'reverse hyper on flat bench', 'reverse-hyper-on-flat-bench', 'reverse hyper on flat bench using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.', 'Hold onto the bench for stability.', 'Keeping your legs straight, raise them up towards the ceiling as high as you can.', 'Squeeze your glutes at the top of the movement.', 'Slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/OrETs32.gif'),
('01a0baa8-4247-72df-860b-a1c77c0beddc', 'cable middle fly', 'cable-middle-fly', 'cable middle fly using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach cables to both sides of a cable machine at chest height.', 'Stand in the center of the machine with one foot slightly in front of the other.', 'Grasp the handles with an overhand grip and extend your arms out to the sides.', 'Keep a slight bend in your elbows and maintain a slight forward lean.', 'Engage your chest muscles and bring your arms forward in a sweeping motion.', 'Pause for a moment at the center, then slowly return your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/xLYSdtg.gif'),
('01a0baa8-4247-72df-860c-3c15e388d8f4', 'biceps narrow pull-ups', 'biceps-narrow-pull-ups', 'biceps narrow pull-ups using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.', 'Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.', 'Pause for a moment at the top, then slowly lower yourself back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/50BETrz.gif'),
('01a0baa8-4247-72df-860d-71a9a5d8f4e1', 'assisted prone rectus femoris stretch', 'assisted-prone-rectus-femoris-stretch', 'assisted prone rectus femoris stretch using assisted.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie face down on the ground with your legs straight.', 'Bend your right knee and reach back with your right hand to grab your right foot or ankle.', 'Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.', 'Hold the stretch for 20-30 seconds.', 'Release and repeat on the other side.'], 'exercises/2Ryn564.gif'),
('01a0baa8-4247-72df-860e-3bef32bf848e', 'dumbbell lying one arm pronated triceps extension', 'dumbbell-lying-one-arm-pronated-triceps-extension', 'dumbbell lying one arm pronated triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your back and head supported, and your feet flat on the ground.', 'Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.', 'Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.', 'Pause for a moment at the bottom, then extend your arm back up to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/wyaqzOS.gif'),
('01a0baa8-4247-72df-860f-6a79cb81db0d', 'spine twist', 'spine-twist', 'spine twist using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the ground with your legs extended in front of you.', 'Bend your knees and place your feet flat on the ground, hip-width apart.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.', 'Pause for a moment at the end of the twist, then slowly return to the starting position.', 'Repeat the twist to the left side, bringing your left elbow towards your right knee.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/2jl9K55.gif'),
('01a0baa8-4247-72df-8610-13fcf33d4b76', 'barbell press sit-up', 'barbell-press-sit-up', 'barbell press sit-up using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back on a mat with your knees bent and feet flat on the ground.', 'Hold the barbell with an overhand grip, resting it on your chest.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/wnEscH8.gif'),
('01a0baa8-4247-72df-8611-ca933a319ffe', 'band straight back stiff leg deadlift', 'band-straight-back-stiff-leg-deadlift', 'band straight back stiff leg deadlift using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place the band around your upper legs.', 'Hold the band with both hands in front of your thighs, palms facing your body.', 'Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.', 'Feel the stretch in your hamstrings as you lower the band.', 'Engage your glutes and hamstrings to lift your body back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/lHeUULr.gif'),
('01a0baa8-4247-72df-8612-6e3257822c55', 'ez bar french press on exercise ball', 'ez-bar-french-press-on-exercise-ball', 'ez bar french press on exercise ball using ez barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball and hold an EZ barbell with an overhand grip.', 'Extend your arms straight up, keeping your elbows close to your head.', 'Slowly lower the barbell behind your head by bending your elbows.', 'Pause for a moment, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/CFN9P8G.gif'),
('01a0baa8-4247-72df-8613-23dfefd1985d', 'ez bar reverse grip bent over row', 'ez-bar-reverse-grip-bent-over-row', 'ez bar reverse grip bent over row using ez barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.', 'Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.', 'Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/G8dXpNG.gif'),
('01a0baa8-4247-72df-8614-31190f7e6911', 'cable one arm tricep pushdown', 'cable-one-arm-tricep-pushdown', 'cable one arm tricep pushdown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a cable machine with a straight bar attachment at chest height.', 'Grasp the bar with an overhand grip and step back to create tension in the cable.', 'Position your feet shoulder-width apart and slightly bend your knees.', 'Keep your back straight and core engaged throughout the exercise.', 'Start with your arm fully extended and perpendicular to the floor.', 'Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.', 'Pause for a moment, then inhale and slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/qRZ5S1N.gif'),
('01a0baa8-4247-72df-8615-f6666980f9fa', 'cambered bar lying row', 'cambered-bar-lying-row', 'cambered bar lying row using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.', 'Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.', 'Pull the barbell towards your chest, squeezing your shoulder blades together.', 'Lower the barbell back down to the starting position and repeat for the desired number of repetitions.'], 'exercises/R5swFnc.gif'),
('01a0baa8-4247-72df-8616-96b3db3b0e49', 'triceps stretch', 'triceps-stretch', 'triceps stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand or sit upright with your back straight.', 'Extend one arm overhead, bending it at the elbow.', 'Place your opposite hand on the bent elbow and gently pull it towards your head.', 'Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.', 'Release the stretch and repeat on the other arm.'], 'exercises/uOV3Itw.gif'),
('01a0baa8-4247-72df-8617-d8bb204ab9a0', 'muscle up', 'muscle-up', 'muscle up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.', 'Engage your core and pull your body up towards the bar, leading with your chest.', 'As you reach the top of the movement, transition your grip so that your palms are facing towards you.', 'Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.', 'Reverse the movement by slowly lowering yourself back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/yJUHKTn.gif'),
('01a0baa8-4247-72df-8618-27d406950a44', 'dumbbell kneeling bicep curl exercise ball', 'dumbbell-kneeling-bicep-curl-exercise-ball', 'dumbbell kneeling bicep curl exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Kneel on the floor with an exercise ball in front of you.', 'Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.', 'Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/2JCuFTU.gif'),
('01a0baa8-4247-72df-8619-30c30521a760', 'barbell decline bench press', 'barbell-decline-bench-press', 'barbell decline bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with your feet secured and your head lower than your hips.', 'Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.', 'Pause for a moment at the bottom, then push the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/GrO65fd.gif'),
('01a0baa8-4247-72df-861a-5c8758f35c28', 'exercise ball alternating arm ups', 'exercise-ball-alternating-arm-ups', 'exercise ball alternating arm ups using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the stability ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.', 'Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.', 'Pause for a moment at the top, then slowly lower your arm back down to the starting position.', 'Repeat the movement with the other arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/EyLrNC2.gif'),
('01a0baa8-4247-72df-861b-b79d5cd43c95', 'exercise ball on the wall calf raise', 'exercise-ball-on-the-wall-calf-raise', 'exercise ball on the wall calf raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your back against a wall and place an exercise ball between your lower back and the wall.', 'Position your feet shoulder-width apart, with your toes pointing forward.', 'Hold a dumbbell in each hand, with your arms extended by your sides.', 'Raise your heels off the ground, lifting your body weight onto the balls of your feet.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/xo6sENf.gif'),
('01a0baa8-4247-72df-861c-5fb84aac2c6e', 'cable seated shoulder internal rotation', 'cable-seated-shoulder-internal-rotation', 'cable seated shoulder internal rotation using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair facing the cable machine with your feet flat on the ground.', 'Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.', 'Keep your elbow slightly bent and your shoulder blades pulled back and down.', 'Slowly rotate your arm inward, bringing the cable handle towards the center of your body.', 'Pause for a moment at the end of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/YPoVrBi.gif'),
('01a0baa8-4247-72df-861d-5ee1fd005a74', 'weighted seated bicep curl (on stability ball)', 'weighted-seated-bicep-curl-on-stability-ball', 'weighted seated bicep curl (on stability ball) using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a stability ball with your feet flat on the ground and your back straight.', 'Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.', 'Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the medicine ball back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/b4b6afT.gif'),
('01a0baa8-4247-72df-861e-ed090ccf4bd1', 'dumbbell lying pronation', 'dumbbell-lying-pronation', 'dumbbell lying pronation using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.', 'Rotate your palms so they are facing up.', 'Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.', 'Inhale and slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/mym4hJo.gif'),
('01a0baa8-4247-72df-861f-0a613f135cb5', 'chest tap push-up (male)', 'chest-tap-push-up-male', 'chest tap push-up (male) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.', 'Lower your body towards the ground by bending your elbows, keeping them close to your sides.', 'As you lower yourself, tap your chest with your right hand.', 'Push yourself back up to the starting position.', 'Repeat the movement, this time tapping your chest with your left hand.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/7E06s6d.gif'),
('01a0baa8-4247-72df-8620-377f41776d82', 'smith back shrug', 'smith-back-shrug', 'smith back shrug using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Keep your arms straight and allow the barbell to hang in front of your thighs.', 'Lift your shoulders straight up towards your ears, squeezing your traps at the top.', 'Hold for a moment, then lower your shoulders back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/MzNnwx9.gif'),
('01a0baa8-4247-72df-8621-1564fd779032', 'barbell lunge', 'barbell-lunge', 'barbell lunge using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.', 'Take a step forward with your right foot, keeping your torso upright.', 'Lower your body by bending your right knee until your thigh is parallel to the ground.', 'Push through your right heel to return to the starting position.', 'Repeat with your left leg, alternating legs for the desired number of repetitions.'], 'exercises/t8iSghb.gif'),
('01a0baa8-4247-72df-8622-c30479d8f075', 'dumbbell one arm pullover on exercise ball', 'dumbbell-one-arm-pullover-on-exercise-ball', 'dumbbell one arm pullover on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Hold a dumbbell with one hand and extend your arm straight up above your chest.', 'Slowly lower the dumbbell behind your head while keeping your arm straight.', 'Pause for a moment, then raise the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/bQHPBU3.gif'),
('01a0baa8-4247-72df-8623-71d8cb815776', 'cable incline bench press', 'cable-incline-bench-press', 'cable incline bench press using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the bench to a 45-degree incline.', 'Attach the cable handles to the high pulleys.', 'Sit on the bench facing the cable machine with your feet flat on the ground.', 'Grasp the handles with an overhand grip and bring them to shoulder height.', 'Push the handles forward and upward until your arms are fully extended.', 'Pause for a moment, then slowly lower the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Vh0GsK4.gif'),
('01a0baa8-4247-72df-8624-f223ca7b23e1', 'dumbbell seated alternate hammer curl on exercise ball', 'dumbbell-seated-alternate-hammer-curl-on-exercise-ball', 'dumbbell seated alternate hammer curl on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.', 'Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.', 'Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat the movement with the opposite arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/QLRmNeT.gif'),
('01a0baa8-4247-72df-8625-dccf848ee4aa', 'barbell reverse grip incline bench row', 'barbell-reverse-grip-incline-bench-row', 'barbell reverse grip incline bench row using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Sit on the bench facing the backrest with your chest against it.', 'Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.', 'Keep your back straight and core engaged.', 'Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement.', 'Slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/8d8qJQI.gif'),
('01a0baa8-4247-72df-8626-88626ae196da', 'short stride run', 'short-stride-run', 'short stride run using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Find an open space or a treadmill to perform the exercise.', 'Stand tall with your feet hip-width apart.', 'Start jogging in place, lifting your knees high and pumping your arms.', 'After a few seconds, start taking short strides forward, maintaining a quick pace.', 'Continue running with short strides for the desired duration or distance.'], 'exercises/CcWEoWV.gif'),
('01a0baa8-4247-72df-8627-51014478af1b', 'cable wrist curl', 'cable-wrist-curl', 'cable wrist curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a low pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.', 'Rest your forearms on a bench or pad, with your wrists hanging off the edge.', 'Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.', 'Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/LrV4s90.gif'),
('01a0baa8-4247-72df-8628-2088e3714608', 'one arm chin-up', 'one-arm-chin-up', 'one arm chin-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a pull-up bar with your feet shoulder-width apart.', 'Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.', 'Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.', 'Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.', 'Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms and repeat.'], 'exercises/HjdqmZa.gif'),
('01a0baa8-4247-72df-8629-a9a040ccc33b', 'push-up inside leg kick', 'push-up-inside-leg-kick', 'push-up inside leg kick using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.', 'Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.', 'As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.', 'Lower your leg back down and repeat the push-up, then switch to the other leg.', 'Continue alternating leg kicks with each push-up repetition.'], 'exercises/0br45wL.gif'),
('01a0baa8-4247-72df-862a-d0e5f8383be0', 'barbell standing overhead triceps extension', 'barbell-standing-overhead-triceps-extension', 'barbell standing overhead triceps extension using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.', 'Raise the barbell overhead, fully extending your arms.', 'Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.', 'Pause for a moment, then raise the barbell back to the starting position by extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/dZl9Q27.gif'),
('01a0baa8-4247-72df-862b-63bc76568a3d', 'dumbbell one arm reverse grip press', 'dumbbell-one-arm-reverse-grip-press', 'dumbbell one arm reverse grip press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.', 'Place your feet flat on the ground and keep your back straight.', 'Raise the dumbbell to shoulder height, keeping your elbow close to your body.', 'Press the dumbbell upwards until your arm is fully extended.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/Ze7MoIb.gif'),
('01a0baa8-4247-72df-862c-ec60113cf503', 'assisted lying leg raise with throw down', 'assisted-lying-leg-raise-with-throw-down', 'assisted lying leg raise with throw down using assisted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs extended and your arms by your sides.', 'Place your hands under your glutes for support.', 'Engage your core and lift your legs off the ground, keeping them straight.', 'Raise your legs until they are perpendicular to the ground.', 'Lower your legs back down to the starting position.', 'Simultaneously, throw your legs down towards the ground, keeping them straight.', 'Raise your legs back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/VX5YKR5.gif'),
('01a0baa8-4247-72df-862d-6991a22f51ed', 'dumbbell standing bent over two arm triceps extension', 'dumbbell-standing-bent-over-two-arm-triceps-extension', 'dumbbell standing bent over two arm triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', 'Bend forward at the waist, keeping your back straight and your knees slightly bent.', 'Extend your arms straight back, keeping your elbows close to your body.', 'Slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/3T12T87.gif'),
('01a0baa8-4247-72df-862e-dbe1f3139557', 'elbow-to-knee', 'elbow-to-knee', 'elbow-to-knee using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.', 'At the same time, bring your left knee towards your right elbow, creating a twisting motion.', 'Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.', 'Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/jvp6DiD.gif'),
('01a0baa8-4247-72df-862f-92961fcaae52', 'dumbbell one arm shoulder press v. 2', 'dumbbell-one-arm-shoulder-press-v-2', 'dumbbell one arm shoulder press v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.', 'Engage your core and press the dumbbell straight up overhead, fully extending your arm.', 'Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/1TkiAFK.gif'),
('01a0baa8-4247-72df-8630-224bc557f1f2', 'smith hip raise', 'smith-hip-raise', 'smith hip raise using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.', 'Place your hands on the barbell, slightly wider than shoulder-width apart.', 'Engage your core and glutes, then push through your heels to raise your hips off the ground.', 'Continue lifting until your body forms a straight line from your knees to your shoulders.', 'Hold for a moment at the top, then slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/CqhoytW.gif'),
('01a0baa8-4247-72df-8631-46635b31ad42', 'swimmer kicks v. 2 (male)', 'swimmer-kicks-v-2-male', 'swimmer kicks v. 2 (male) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a mat with your arms extended overhead.', 'Engage your core and lift your chest and legs off the ground simultaneously.', 'Kick your legs up and down in a fluttering motion, as if you were swimming.', 'Continue kicking for the desired number of repetitions.', 'Lower your chest and legs back down to the starting position.'], 'exercises/SP3hUez.gif'),
('01a0baa8-4247-72df-8632-c78bd3c83e09', 'dumbbell clean', 'dumbbell-clean', 'dumbbell clean using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', 'Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.', 'Explosively extend your hips and knees, driving through your heels to jump off the ground.', 'As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.', 'Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.', 'Lower the dumbbells back down to the starting position by reversing the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/7Hg55JG.gif'),
('01a0baa8-4247-72df-8633-5f29b011cb3f', 'walking high knees lunge', 'walking-high-knees-lunge', 'walking high knees lunge using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart.', 'Lift your right knee up towards your chest as high as you can while balancing on your left leg.', 'Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.', 'Push off with your right foot and bring your left knee up towards your chest.', 'Step forward with your left foot and lower your body into a lunge position.', 'Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.', 'Repeat for the desired number of repetitions.'], 'exercises/J9zIWig.gif'),
('01a0baa8-4247-72df-8634-f7220336d01a', 'diamond push-up', 'diamond-push-up', 'diamond push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.', 'Keep your body in a straight line from head to toe, engaging your core and glutes.', 'Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.', 'Pause for a moment at the bottom, then push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/soIB2rj.gif'),
('01a0baa8-4247-72df-8635-d76ef3a91c49', 'bench hip extension', 'bench-hip-extension', 'bench hip extension using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back against the bench and your feet flat on the ground.', 'Place your hands on the bench for support.', 'Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.', 'Pause for a moment at the top, then slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/u27Kcdz.gif'),
('01a0baa8-4247-72df-8636-a3ff2923889f', 'dumbbell bent over row', 'dumbbell-bent-over-row', 'dumbbell bent over row using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.', 'Bend forward at the hips, keeping your back straight and your core engaged.', 'Let your arms hang straight down towards the floor, with your elbows slightly bent.', 'Pull the dumbbells up towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/BJ0Hz5L.gif'),
('01a0baa8-4247-72df-8637-0c4295bc3750', 'dumbbell cross body hammer curl', 'dumbbell-cross-body-hammer-curl', 'dumbbell cross body hammer curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your body.', 'Keep your elbows close to your torso and your upper arms stationary.', 'Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Qyk5J3p.gif'),
('01a0baa8-4247-72df-8638-6717edc4e592', 'cable palm rotational row', 'cable-palm-rotational-row', 'cable palm rotational row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a handle to a cable machine at waist height.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the handle with an overhand grip, palms facing down.', 'Step back to create tension on the cable, keeping your back straight and knees slightly bent.', 'Pull the handle towards your body, rotating your palms to face upwards as you do so.', 'Squeeze your shoulder blades together at the end of the movement.', 'Slowly release the handle back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/OmQ8w0p.gif'),
('01a0baa8-4247-72df-8639-065866b529ec', 'skater hops', 'skater-hops', 'skater hops using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Bend your knees slightly and jump to the right, landing on your right foot.', 'As you land, swing your left leg behind your right leg and tap the ground with your left toes.', 'Immediately jump to the left, landing on your left foot.', 'As you land, swing your right leg behind your left leg and tap the ground with your right toes.', 'Continue alternating sides, jumping and tapping the ground with each leg.', 'Repeat for the desired number of repetitions.'], 'exercises/zfNHMN9.gif'),
('01a0baa8-4247-72df-863a-753ef992329b', 'barbell step-up', 'barbell-step-up', 'barbell step-up using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand in front of a bench or step with a barbell resting on your upper back.', 'Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.', 'Push through your heel and step up onto the bench or step, fully extending your hip and knee.', 'Pause briefly at the top, then lower yourself back down to the starting position.', 'Repeat with the opposite leg.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/Kxquu2E.gif'),
('01a0baa8-4247-72df-863b-b6f0e131f656', 'cable low seated row', 'cable-low-seated-row', 'cable low seated row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the machine with your feet flat on the footrests and your knees slightly bent.', 'Grasp the handles with an overhand grip, palms facing down.', 'Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.', 'Pull the handles towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/hvV79Si.gif'),
('01a0baa8-4247-72df-863c-fb36634e7e2f', 'barbell rear delt row', 'barbell-rear-delt-row', 'barbell rear delt row using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Bend forward at the hips, keeping your back straight and chest up.', 'Pull the barbell towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/S9zHIvU.gif'),
('01a0baa8-4247-72df-863d-5ea37ea4f311', 'dumbbell incline biceps curl', 'dumbbell-incline-biceps-curl', 'dumbbell incline biceps curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/F3xgbjF.gif'),
('01a0baa8-4247-72df-863e-68322804a808', 'circles knee stretch', 'circles-knee-stretch', 'circles knee stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your hands on your hips.', 'Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.', 'Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.', 'Perform the movement for the desired number of repetitions.'], 'exercises/X7jbxra.gif'),
('01a0baa8-4247-72df-863f-85ed48c8605d', 'dumbbell standing palms in press', 'dumbbell-standing-palms-in-press', 'dumbbell standing palms in press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.', 'Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/UilDHSs.gif'),
('01a0baa8-4247-72df-8640-36da583414a8', 'dumbbell one arm wrist curl', 'dumbbell-one-arm-wrist-curl', 'dumbbell one arm wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the ground.', 'Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.', 'Allow your wrist to extend, letting the dumbbell roll down towards your fingers.', 'Slowly curl your wrist back up, bringing the dumbbell towards your forearm.', 'Repeat for the desired number of repetitions, then switch to the other hand.'], 'exercises/q8aHNoF.gif'),
('01a0baa8-4247-72df-8641-8eb2d6815304', 'cable one arm bent over row', 'cable-one-arm-bent-over-row', 'cable one arm bent over row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.', 'Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.', 'Pause for a moment, then slowly extend your arm back to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/EIsE3u8.gif'),
('01a0baa8-4247-72df-8642-dd82982d5d31', 'elbow dips', 'elbow-dips', 'elbow dips using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.', 'Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.', 'Bend your elbows and lower your body towards the ground, keeping your back close to the bench.', 'Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/LkoAWAE.gif'),
('01a0baa8-4247-72df-8643-6c89413f0b2a', 'standing wheel rollerout', 'standing-wheel-rollerout', 'standing wheel rollerout using wheel roller.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.', 'Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.', 'Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.', 'Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/KtRomty.gif'),
('01a0baa8-4247-72df-8644-ef744e6ea1da', 'weighted triceps dip on high parallel bars', 'weighted-triceps-dip-on-high-parallel-bars', 'weighted triceps dip on high parallel bars using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.', 'Bend your elbows and lower your body until your upper arms are parallel to the ground.', 'Pause for a moment, then push through your palms to straighten your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/K1vlode.gif'),
('01a0baa8-4247-72df-8645-3997b6d3b865', 'assisted standing chin-up', 'assisted-standing-chin-up', 'assisted standing chin-up using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the machine to your desired assistance level.', 'Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.', 'Keep your chest up and shoulders back, engage your core, and slightly bend your knees.', 'Pull your body up by flexing your elbows and driving your elbows down towards your sides.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/7OeHptV.gif'),
('01a0baa8-4247-72df-8646-8cc118ce5baa', 'chest dip on straight bar', 'chest-dip-on-straight-bar', 'chest dip on straight bar using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Grab the parallel bars with your palms facing down and your arms fully extended.', 'Bend your knees and cross your ankles.', 'Lower your body by bending your arms until your shoulders are below your elbows.', 'Push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/LQFOrMn.gif'),
('01a0baa8-4247-72df-8647-5271960a804c', 'barbell bent arm pullover', 'barbell-bent-arm-pullover', 'barbell bent arm pullover using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your head at one end and your feet on the floor.', 'Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.', 'Lower the barbell behind your head while keeping your arms slightly bent.', 'Pause for a moment, then raise the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/cA9FuWG.gif'),
('01a0baa8-4247-72df-8648-75d4973789b8', 'barbell bench squat', 'barbell-bench-squat', 'barbell bench squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up a barbell on a squat rack at chest height.', 'Stand facing away from the rack, with your feet shoulder-width apart.', 'Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.', 'Lower your body down into a squat, keeping your knees in line with your toes.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/W9pFVv1.gif'),
('01a0baa8-4247-72df-8649-71f0356c520e', 'dumbbell alternate seated hammer curl', 'dumbbell-alternate-seated-hammer-curl', 'dumbbell alternate seated hammer curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.', 'Keep your back straight and your elbows close to your torso.', 'Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.', 'Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.', 'Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.', 'Repeat the movement with your left arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/6em2Dxj.gif'),
('01a0baa8-4247-72df-864a-3233c2caafa3', 'push-up medicine ball', 'push-up-medicine-ball', 'push-up medicine ball using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands on the medicine ball, shoulder-width apart.', 'Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.', 'Push through your palms to extend your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/W8KAlkI.gif'),
('01a0baa8-4247-72df-864b-e0a26ebca2b7', 'cable floor seated wide-grip row', 'cable-floor-seated-wide-grip-row', 'cable floor seated wide-grip row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the floor with your legs extended and your back straight.', 'Attach a cable handle to a low pulley and position the cable machine behind you.', 'Grasp the handle with a wide overhand grip, palms facing down.', 'Lean back slightly, keeping your back straight and your chest lifted.', 'Pull the handle towards your waist, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/veXwo0D.gif'),
('01a0baa8-4247-72df-864c-2274155d6259', 'cable one arm incline press', 'cable-one-arm-incline-press', 'cable one arm incline press using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine to a low pulley position.', 'Sit on an incline bench facing away from the cable machine.', 'Grasp the handle with one hand and bring it up to shoulder height.', 'Position your feet firmly on the ground and maintain a stable position.', 'Press the handle forward and upward, extending your arm fully.', 'Pause for a moment at the top, then slowly lower the handle back to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/GKEH6jj.gif'),
('01a0baa8-4247-72df-864d-042f7caac02b', 'cable triceps pushdown (v-bar) (with arm blaster)', 'cable-triceps-pushdown-v-bar-with-arm-blaster', 'cable triceps pushdown (v-bar) (with arm blaster) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a v-bar attachment to the cable machine at the highest setting.', 'Stand facing the cable machine with your feet shoulder-width apart.', 'Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.', 'Keep your elbows close to your sides and your upper arms stationary throughout the exercise.', 'Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.', 'Pause for a moment at the bottom of the movement, squeezing your triceps.', 'Inhale as you slowly return the v-bar to the starting position, maintaining control.', 'Repeat for the desired number of repetitions.'], 'exercises/OxJk1fg.gif'),
('01a0baa8-4247-72df-864e-68849e07e8b8', 'smith shrug', 'smith-shrug', 'smith shrug using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Keep your arms straight and your shoulders relaxed.', 'Lift your shoulders up towards your ears, squeezing your traps at the top.', 'Hold for a moment, then slowly lower your shoulders back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/OUQ0ZyW.gif'),
('01a0baa8-4247-72df-864f-e35f0ca07bab', 'wheel rollerout', 'wheel-rollerout', 'wheel rollerout using wheel roller.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Kneel on the floor and place the wheel roller in front of you.', 'Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.', 'Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.', 'Continue rolling forward until your body is fully extended and your arms are overhead.', 'Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.', 'Repeat for the desired number of repetitions.'], 'exercises/NAgVB3t.gif'),
('01a0baa8-4247-72df-8650-7a6ed29b14a6', 'suspended split squat', 'suspended-split-squat', 'suspended split squat using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing away from a suspension trainer with your feet shoulder-width apart.', 'Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.', 'Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.', 'Push through your heel to return to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/QpXqiq8.gif'),
('01a0baa8-4247-72df-8651-91902a749479', 'smith squat', 'smith-squat', 'smith squat using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up the smith machine with the barbell at an appropriate height for your squat.', 'Stand with your feet shoulder-width apart, toes slightly turned out.', 'Position yourself under the barbell, resting it on your upper traps and shoulders.', 'Grip the barbell with a wide grip, slightly wider than shoulder-width apart.', 'Engage your core and unrack the barbell, stepping back to clear the rack.', 'Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.', 'Lower your body until your thighs are parallel to the ground or slightly below.', 'Pause for a moment at the bottom, then drive through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/jFtipLl.gif'),
('01a0baa8-4248-74a8-8cbf-16cbd12ff4ec', 'cable rope hammer preacher curl', 'cable-rope-hammer-preacher-curl', 'cable rope hammer preacher curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope attachment to a low pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the rope with a neutral grip (palms facing each other).', 'Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.', 'Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly lower the rope back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/PcPe0P5.gif'),
('01a0baa8-4248-74a8-8cc0-c909f03847d7', 'barbell standing close grip military press', 'barbell-standing-close-grip-military-press', 'barbell standing close grip military press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.', 'Lift the barbell to shoulder height, keeping your elbows close to your body.', 'Press the barbell overhead, extending your arms fully.', 'Lower the barbell back to shoulder height.', 'Repeat for the desired number of repetitions.'], 'exercises/wdRZISl.gif'),
('01a0baa8-4248-74a8-8cc1-e5985c93b69c', 'cable twist', 'cable-twist', 'cable twist using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, facing the cable machine.', 'Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.', 'Engage your core and twist your torso to the right, pulling the cable across your body.', 'Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.', 'Slowly return to the starting position, resisting the cable''s pull.', 'Repeat the movement to the left side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/aVs3BR3.gif'),
('01a0baa8-4248-74a8-8cc2-646d9007fa49', 'dumbbell one arm prone curl', 'dumbbell-one-arm-prone-curl', 'dumbbell one arm prone curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a flat bench with a dumbbell in one hand, palm facing down.', 'Extend your arm fully, letting it hang straight down towards the floor.', 'Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/JWjujiY.gif'),
('01a0baa8-4248-74a8-8cc3-b8b73fdd94c5', 'band one arm single leg split squat', 'band-one-arm-single-leg-split-squat', 'band one arm single leg split squat using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart and place a resistance band around your ankles.', 'Extend one leg forward and rest the top of your foot on a bench or step behind you.', 'Hold onto a support with one hand for balance.', 'Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.', 'Push through your heel to return to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/arsYEd3.gif'),
('01a0baa8-4248-74a8-8cc4-2f689aa4e7a2', 'exercise ball dip', 'exercise-ball-dip', 'exercise ball dip using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Place your hands on the ball beside your hips, fingers pointing forward.', 'Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.', 'Lower your body back down by bending your elbows, keeping them close to your sides.', 'Repeat for the desired number of repetitions.'], 'exercises/kprile3.gif'),
('01a0baa8-4248-74a8-8cc5-96d29df59727', 'band kneeling one arm pulldown', 'band-kneeling-one-arm-pulldown', 'band kneeling one arm pulldown using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a sturdy anchor point above your head.', 'Kneel down and hold the band with one hand, palm facing down.', 'Extend your arm fully overhead, keeping your elbow slightly bent.', 'Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.', 'Pause for a moment at the bottom, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/pmnrOp0.gif'),
('01a0baa8-4248-74a8-8cc6-036ba10df6ad', 'weighted donkey calf raise', 'weighted-donkey-calf-raise', 'weighted donkey calf raise using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand on a raised platform with your toes on the edge and your heels hanging off.', 'Hold onto a stable object for support.', 'Raise your heels as high as possible by extending your ankles.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/LmaFNZS.gif'),
('01a0baa8-4248-74a8-8cc7-c222305d54b3', 'cable standing up straight crossovers', 'cable-standing-up-straight-crossovers', 'cable standing up straight crossovers using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand in the middle of a cable machine with your feet shoulder-width apart.', 'Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.', 'Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.', 'Pause for a moment, then slowly return to the starting position, keeping your arms extended.', 'Repeat for the desired number of repetitions.'], 'exercises/UKWTJWR.gif'),
('01a0baa8-4248-74a8-8cc8-94c3b6b9490d', 'dumbbell lying supine biceps curl', 'dumbbell-lying-supine-biceps-curl', 'dumbbell lying supine biceps curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your back and head supported, and your feet flat on the ground.', 'Hold a dumbbell in each hand with your palms facing up and your arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/XVzF3iZ.gif'),
('01a0baa8-4248-74a8-8cc9-32d88299e381', 'side-to-side chin', 'side-to-side-chin', 'side-to-side chin using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.', 'Hang from the bar with your arms fully extended and your body relaxed.', 'Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.', 'Once your chin is above the bar, lower yourself back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/isAAZWA.gif'),
('01a0baa8-4248-74a8-8cca-f2c8a9724569', 'pull up (neutral grip)', 'pull-up-neutral-grip', 'pull up (neutral grip) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.', 'Engage your core and squeeze your shoulder blades together.', 'Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position with control.', 'Repeat for the desired number of repetitions.'], 'exercises/0V2YQjW.gif'),
('01a0baa8-4248-74a8-8ccb-c061bcd24684', 'dumbbell reverse bench press', 'dumbbell-reverse-bench-press', 'dumbbell reverse bench press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your knees bent.', 'Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.', 'Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.', 'Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.', 'Pause for a moment at the bottom, then push the dumbbells back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/UIbGx6H.gif'),
('01a0baa8-4248-74a8-8ccc-c7093a721cf6', 'cable standing fly', 'cable-standing-fly', 'cable standing fly using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the handles to the cables at chest height.', 'Stand with your feet shoulder-width apart, facing away from the cable machine.', 'Grasp the handles with an overhand grip, palms facing forward.', 'Step forward slightly to create tension in the cables.', 'Keep your core engaged and your back straight throughout the exercise.', 'With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.', 'Squeeze your chest muscles at the peak of the movement.', 'Slowly reverse the movement, returning your arms to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Pr9Rhf4.gif'),
('01a0baa8-4248-74a8-8ccd-b7729ff9910a', 'dumbbell alternate preacher curl', 'dumbbell-alternate-preacher-curl', 'dumbbell alternate preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher bench with a dumbbell in each hand, palms facing up.', 'Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.', 'Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.', 'Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.', 'Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.', 'Repeat the movement with your left arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/NlfIbzq.gif'),
('01a0baa8-4248-74a8-8cce-d2a79d21ed17', 'one arm towel row', 'one-arm-towel-row', 'one arm towel row using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.', 'Bend forward at the waist, keeping your back straight and your core engaged.', 'Extend your arm fully, allowing the towel to hang in front of you.', 'Pull the towel towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the towel back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/bKWbrTA.gif'),
('01a0baa8-4248-74a8-8ccf-ac983591d72d', 'single leg platform slide', 'single-leg-platform-slide', 'single leg platform slide using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with one foot on a platform or slide board.', 'Bend your knee slightly and slide the foot on the platform backward, extending your leg.', 'Keep your core engaged and maintain a straight posture throughout the movement.', 'Slowly return to the starting position by sliding your foot back to the initial position.', 'Repeat the movement for the desired number of repetitions, then switch legs.'], 'exercises/LNE3wfo.gif'),
('01a0baa8-4248-74a8-8cd0-08abad812a58', 'split squats', 'split-squats', 'split squats using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Take a step forward with one foot and place it about two feet in front of the other foot.', 'Lower your body by bending your knees and hips, keeping your back straight.', 'Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.', 'Pause for a moment, then push through your front heel to return to the starting position.', 'Repeat for the desired number of repetitions, then switch legs and repeat.'], 'exercises/9E25EOx.gif'),
('01a0baa8-4248-74a8-8cd1-71eff0948010', 'lying leg raise flat bench', 'lying-leg-raise-flat-bench', 'lying leg raise flat bench using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a flat bench with your back pressed against it.', 'Place your hands under your glutes for support.', 'Keep your legs straight and together, and lift them up towards the ceiling.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/WhuFnR7.gif'),
('01a0baa8-4248-74a8-8cd2-491e2c45bae9', 'spine stretch', 'spine-stretch', 'spine stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the ground with your legs extended in front of you.', 'Place your hands on the ground behind you, fingers pointing towards your body.', 'Engage your core and slowly lean back, keeping your back straight.', 'Continue leaning back until you feel a stretch in your spine.', 'Hold the stretch for a few seconds, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/JbC2iaV.gif'),
('01a0baa8-4248-74a8-8cd3-e043a8ab7397', 'barbell lying close-grip triceps extension', 'barbell-lying-close-grip-triceps-extension', 'barbell lying close-grip triceps extension using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', 'Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.', 'Extend your arms fully, lifting the barbell above your chest.', 'Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.', 'Pause for a moment at the bottom, then extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/HJ63mSO.gif'),
('01a0baa8-4248-74a8-8cd4-df9971bb20a8', 'barbell rear delt raise', 'barbell-rear-delt-raise', 'barbell rear delt raise using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Ln9iTbU.gif'),
('01a0baa8-4248-74a8-8cd5-cb776fec7f66', 'barbell biceps curl (with arm blaster)', 'barbell-biceps-curl-with-arm-blaster', 'barbell biceps curl (with arm blaster) using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.', 'Place your upper arms against the arm blaster, keeping your elbows close to your torso.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/aee2Fcj.gif'),
('01a0baa8-4248-74a8-8cd6-18c208237d19', 'one arm against wall', 'one-arm-against-wall', 'one arm against wall using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand facing a wall with your feet shoulder-width apart.', 'Extend one arm straight out in front of you and place your palm against the wall.', 'Engage your core and lean your body forward, keeping your arm straight and your back flat.', 'Slowly push against the wall with your palm, activating your lat muscles.', 'Hold the position for a few seconds, then release and repeat with the other arm.'], 'exercises/ZZTGMKh.gif'),
('01a0baa8-4248-74a8-8cd7-a4f7a98c2ce1', 'dumbbell fly', 'dumbbell-fly', 'dumbbell fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with a dumbbell in each hand, palms facing each other.', 'Extend your arms straight up over your chest, with a slight bend in your elbows.', 'Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.', 'Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/yz9nUhF.gif'),
('01a0baa8-4248-74a8-8cd8-23638bfa04f9', 'biceps pull-up', 'biceps-pull-up', 'biceps pull-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.', 'Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.', 'Pause at the top of the movement, then slowly lower yourself back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/guT8YnS.gif'),
('01a0baa8-4248-74a8-8cd9-5fa7a310e917', 'reverse hyper extension (on stability ball)', 'reverse-hyper-extension-on-stability-ball', 'reverse hyper extension (on stability ball) using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.', 'Place your hands on the ground in front of you for stability.', 'Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vM5YS2g.gif'),
('01a0baa8-4248-74a8-8cda-6527daa5acb1', 'barbell one leg squat', 'barbell-one-leg-squat', 'barbell one leg squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell across your upper back.', 'Lift one foot off the ground and extend it forward, keeping it parallel to the ground.', 'Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.', 'Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.', 'Repeat for the desired number of repetitions, then switch legs and repeat.'], 'exercises/uKyN64F.gif'),
('01a0baa8-4248-74a8-8cdb-cfd7945cb4ab', 'dumbbell goblet squat', 'dumbbell-goblet-squat', 'dumbbell goblet squat using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.', 'Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.', 'Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/yn8yg1r.gif'),
('01a0baa8-4248-74a8-8cdc-a4c8902f1de8', 'exercise ball on the wall calf raise (tennis ball between knees)', 'exercise-ball-on-the-wall-calf-raise-tennis-ball-between-knees', 'exercise ball on the wall calf raise (tennis ball between knees) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your back against a wall and place an exercise ball between your lower back and the wall.', 'Position your feet shoulder-width apart and slightly in front of you.', 'Hold a dumbbell in each hand, with your arms extended by your sides.', 'Place a tennis ball between your knees.', 'Raise your heels off the ground, lifting your body up onto your toes.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/j74M6Zn.gif'),
('01a0baa8-4248-74a8-8cdd-716931cfc31e', 'barbell seated overhead triceps extension', 'barbell-seated-overhead-triceps-extension', 'barbell seated overhead triceps extension using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.', 'Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.', 'Pause for a moment, then extend your arms to raise the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/5uFK1xr.gif'),
('01a0baa8-4248-74a8-8cde-a229cf428296', 'assisted lying calves stretch', 'assisted-lying-calves-stretch', 'assisted lying calves stretch using assisted.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie on your back with your legs extended.', 'Bend one knee and place your foot flat on the ground.', 'Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.', 'Hold the stretch for 20-30 seconds.', 'Release the stretch and repeat on the other leg.'], 'exercises/GxDwDX0.gif'),
('01a0baa8-4248-74a8-8cdf-5b87792cac30', 'dumbbell neutral grip bench press', 'dumbbell-neutral-grip-bench-press', 'dumbbell neutral grip bench press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.', 'Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.', 'Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/pP8wP2P.gif'),
('01a0baa8-4248-74a8-8ce0-afaa845149aa', 'burpee', 'burpee', 'burpee using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Start in a standing position with your feet shoulder-width apart.', 'Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.', 'Kick your feet back into a push-up position.', 'Perform a push-up, keeping your body in a straight line.', 'Jump your feet back into the squat position.', 'Jump up explosively, reaching your arms overhead.', 'Land softly and immediately lower back into a squat position to begin the next repetition.'], 'exercises/dK9394r.gif'),
('01a0baa8-4248-74a8-8ce1-ab33fb094be2', 'dumbbell step-up split squat', 'dumbbell-step-up-split-squat', 'dumbbell step-up split squat using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.', 'Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.', 'Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.', 'As you step up, simultaneously lift your left knee towards your chest.', 'Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.', 'Repeat the movement with your left foot on the bench or step.', 'Continue alternating between your right and left foot for the desired number of repetitions.'], 'exercises/QjE2DcA.gif'),
('01a0baa8-4248-74a8-8ce2-e5033bbd9a09', 'side wrist pull stretch', 'side-wrist-pull-stretch', 'side wrist pull stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your arms extended in front of you.', 'Extend your right arm out to the side, parallel to the ground, with your palm facing down.', 'With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.', 'Hold the stretch for 15-30 seconds, then release.', 'Repeat on the other side.'], 'exercises/UtmIqcI.gif'),
('01a0baa8-4248-74a8-8ce3-e3fa7084970b', 'dumbbell concentration curl', 'dumbbell-concentration-curl', 'dumbbell concentration curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.', 'Fully extend your arm and hold the dumbbell with an underhand grip.', 'Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.', 'Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/gvsWLQw.gif'),
('01a0baa8-4248-74a8-8ce4-da6ece65a20c', 'smith rear delt row', 'smith-rear-delt-row', 'smith rear delt row using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.', 'Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.', 'Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/nFUwqG6.gif'),
('01a0baa8-4248-74a8-8ce5-e4fae55d119c', 'straddle planche', 'straddle-planche', 'straddle planche using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.', 'Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.', 'Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.', 'Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/BL3GHeY.gif'),
('01a0baa8-4248-74a8-8ce6-6021918e0e28', 'dumbbell single leg split squat', 'dumbbell-single-leg-split-squat', 'dumbbell single leg split squat using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', 'Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.', 'Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.', 'Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.', 'Repeat for the desired number of repetitions, then switch legs and repeat.'], 'exercises/qx4fgX7.gif'),
('01a0baa8-4248-74a8-8ce7-2c1b8fd8fb6d', 'upward facing dog', 'upward-facing-dog', 'upward facing dog using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie face down on the floor with your legs extended behind you.', 'Place your hands on the floor next to your lower ribs, fingers pointing forward.', 'Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.', 'Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.', 'Hold this position for a few breaths, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/01qpYSe.gif'),
('01a0baa8-4248-74a8-8ce8-3b0fa65b1a5e', 'band hip lift', 'band-hip-lift', 'band hip lift using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your back with your knees bent and feet flat on the ground.', 'Place a resistance band just above your knees.', 'Engage your glutes and core muscles.', 'Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.', 'Pause for a moment at the top, then slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/E4R8Hz1.gif'),
('01a0baa8-4248-74a8-8ce9-1556b9fdb470', 'upper back stretch', 'upper-back-stretch', 'upper back stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart.', 'Extend your arms straight in front of you, parallel to the ground.', 'Interlace your fingers and rotate your palms away from your body.', 'Slowly raise your arms overhead, keeping them straight and parallel to each other.', 'As you raise your arms, squeeze your shoulder blades together.', 'Hold the stretch for 15-30 seconds, then release and repeat.'], 'exercises/GSDioYu.gif'),
('01a0baa8-4248-74a8-8cea-8414971746cb', 'squat jerk', 'squat-jerk', 'squat jerk using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start with the barbell resting on your shoulders, with your feet shoulder-width apart.', 'Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.', 'As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.', 'As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.', 'Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.', 'Stand up from the split position, bringing your feet back together.', 'Lower the barbell back to your shoulders and repeat for the desired number of repetitions.'], 'exercises/IMRsOCn.gif'),
('01a0baa8-4248-74a8-8ceb-917e7acf9995', 'barbell decline close grip to skull press', 'barbell-decline-close-grip-to-skull-press', 'barbell decline close grip to skull press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.', 'Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.', 'Pause for a moment, then extend your arms to press the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/LMGXZn8.gif'),
('01a0baa8-4248-74a8-8cec-3d0dfd746bd0', 'barbell upright row', 'barbell-upright-row', 'barbell upright row using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Let the barbell hang in front of your thighs, arms fully extended.', 'Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.', 'Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/UDlhcO8.gif'),
('01a0baa8-4248-74a8-8ced-89e866df5c4b', 'bodyweight standing row (with towel)', 'bodyweight-standing-row-with-towel', 'bodyweight standing row (with towel) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Pull the towel towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/uTv34oq.gif'),
('01a0baa8-4248-74a8-8cee-a762a73a9421', 'barbell side split squat', 'barbell-side-split-squat', 'barbell side split squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.', 'Hold a barbell across your upper back, resting it on your traps.', 'Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.', 'As you lower, push your knees out to the sides and keep your weight on your heels.', 'Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/W31mMjd.gif'),
('01a0baa8-4248-74a8-8cef-870b87d87b99', 'weighted standing hand squeeze', 'weighted-standing-hand-squeeze', 'weighted standing hand squeeze using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a weight in each hand.', 'Extend your arms straight in front of you, palms facing each other.', 'Squeeze your hands together as hard as you can, engaging your forearms.', 'Hold the squeeze for a few seconds, then release.', 'Repeat for the desired number of repetitions.'], 'exercises/bjqbauy.gif'),
('01a0baa8-4248-74a8-8cf0-ebe2725dd21d', 'dumbbell press on exercise ball', 'dumbbell-press-on-exercise-ball', 'dumbbell press on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.', 'Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.', 'Raise the dumbbells to shoulder height, palms facing forward.', 'Press the dumbbells upward until your arms are fully extended.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/O8o7q4d.gif'),
('01a0baa8-4248-74a8-8cf1-31e0619b32cf', 'dumbbell one arm reverse spider curl', 'dumbbell-one-arm-reverse-spider-curl', 'dumbbell one arm reverse spider curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.', 'Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/VdLZ3nB.gif'),
('01a0baa8-4248-74a8-8cf2-2c8f1815e28a', 'potty squat with support', 'potty-squat-with-support', 'potty squat with support using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes pointing slightly outward.', 'Hold onto a stable support, such as a chair or wall, for balance.', 'Lower your body down into a squat position by bending your knees and pushing your hips back.', 'Keep your chest up and your back straight throughout the movement.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/b63ZzGe.gif'),
('01a0baa8-4248-74a8-8cf3-ac82db4b0a4f', 'band shoulder press', 'band-shoulder-press', 'band shoulder press using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place the band under your feet.', 'Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.', 'Press the band overhead, fully extending your arms.', 'Pause for a moment at the top, then slowly lower the band back to shoulder height.', 'Repeat for the desired number of repetitions.'], 'exercises/peAeMR3.gif'),
('01a0baa8-4248-74a8-8cf4-fc4fe9c98a98', 'barbell curl', 'barbell-curl', 'barbell curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.', 'Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.', 'Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale as you slowly begin to lower the bar back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/25GPyDY.gif'),
('01a0baa8-4248-74a8-8cf5-5af825b1515f', 'barbell front raise', 'barbell-front-raise', 'barbell front raise using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.', 'Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/b2Uoz54.gif'),
('01a0baa8-4248-74a8-8cf6-94082e13a437', 'dumbbell seated lateral raise v. 2', 'dumbbell-seated-lateral-raise-v-2', 'dumbbell seated lateral raise v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.', 'Keep your back straight and core engaged.', 'Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/hrrS0Ed.gif'),
('01a0baa8-4248-74a8-8cf7-94285e7c5ac7', 'dumbbell side bend', 'dumbbell-side-bend', 'dumbbell side bend using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.', 'Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.', 'Pause for a moment, then slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides and repeat.'], 'exercises/IpONWYv.gif'),
('01a0baa8-4248-74a8-8cf8-ff1c6909078d', 'one leg squat', 'one-leg-squat', 'one leg squat using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Extend one leg forward, keeping it off the ground.', 'Bend your standing leg and lower your body down as if sitting back into a chair.', 'Keep your chest up and your back straight.', 'Push through your heel to return to the starting position.', 'Repeat with the other leg.'], 'exercises/C31LMnP.gif'),
('01a0baa8-4248-74a8-8cf9-351e1bdd5847', 'dumbbell standing preacher curl', 'dumbbell-standing-preacher-curl', 'dumbbell standing preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.', 'Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/hq2hyDH.gif'),
('01a0baa8-4248-74a8-8cfa-c27be867a39d', 'smith full squat', 'smith-full-squat', 'smith full squat using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up the smith machine with the barbell at shoulder height.', 'Stand with your feet shoulder-width apart, toes slightly turned out.', 'Step under the bar and position it across your upper back, resting on your traps.', 'Grip the bar with your hands slightly wider than shoulder-width apart.', 'Unrack the bar and take a step back, maintaining a stable stance.', 'Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.', 'Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.', 'Pause for a moment at the bottom, then drive through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/NNoHCEA.gif'),
('01a0baa8-4248-74a8-8cfb-d32aef2dfb7c', 'dumbbell incline press on exercise ball', 'dumbbell-incline-press-on-exercise-ball', 'dumbbell incline press on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with a dumbbell in each hand, palms facing forward.', 'Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.', 'Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.', 'Press the dumbbells upward, extending your arms fully.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/bfiHMpI.gif'),
('01a0baa8-4248-74a8-8cfc-90da08f37b1a', 'barbell lying back of the head tricep extension', 'barbell-lying-back-of-the-head-tricep-extension', 'barbell lying back of the head tricep extension using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', 'Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.', 'Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.', 'Pause for a moment, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/yg8Totb.gif'),
('01a0baa8-4248-74a8-8cfd-63bb6ea67d3f', 'dumbbell decline one arm hammer press', 'dumbbell-decline-one-arm-hammer-press', 'dumbbell decline one arm hammer press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with a dumbbell in one hand, resting on your chest.', 'Extend your arm straight up, keeping your elbow slightly bent.', 'Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.', 'Press the dumbbell back up to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/SHUMp5H.gif'),
('01a0baa8-4248-74a8-8cfe-f1b055c05bab', 'dumbbell incline t-raise', 'dumbbell-incline-t-raise', 'dumbbell incline t-raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.', 'Lean forward and let your arms hang straight down, perpendicular to the floor.', 'Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a ''T'' shape with your body.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/jgbvVJ0.gif'),
('01a0baa8-4248-74a8-8cff-9b3a6bd28223', 'dumbbell lying supine curl', 'dumbbell-lying-supine-curl', 'dumbbell lying supine curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/KUaZst7.gif'),
('01a0baa8-4248-74a8-8d00-f57db12104db', 'lever triceps extension', 'lever-triceps-extension', 'lever triceps extension using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the machine with your back against the pad.', 'Grasp the handles with an overhand grip and fully extend your arms in front of you.', 'Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows.', 'Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/Ser9eQp.gif'),
('01a0baa8-4248-74a8-8d01-e73410b060cf', 'barbell one arm snatch', 'barbell-one-arm-snatch', 'barbell one arm snatch using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes pointing slightly outwards.', 'Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.', 'Explosively extend your hips, knees, and ankles, driving the barbell upwards.', 'As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.', 'Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.', 'Lower the barbell back down to the starting position in a controlled manner.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/xHKN2s8.gif'),
('01a0baa8-4248-74a8-8d02-bea125eb9549', 'dumbbell seated neutral wrist curl', 'dumbbell-seated-neutral-wrist-curl', 'dumbbell seated neutral wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.', 'Rest your forearms on your thighs, allowing the dumbbells to hang down.', 'Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/uJmK7Z1.gif'),
('01a0baa8-4248-74a8-8d03-a701e5b73df6', 'cable pulldown', 'cable-pulldown', 'cable pulldown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.', 'Sit on the seat with your back straight and your feet flat on the ground.', 'Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.', 'Lean back slightly and engage your core.', 'Pull the cable bar down towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/RVwzP10.gif'),
('01a0baa8-4248-74a8-8d04-8a6b5c0ada4b', 'barbell hack squat', 'barbell-hack-squat', 'barbell hack squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart and your toes slightly turned out.', 'Hold the barbell behind your legs, resting it on your upper thighs.', 'Lower your body by bending at the knees and hips, keeping your back straight and your chest up.', 'Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/5VCj6iH.gif'),
('01a0baa8-4248-74a8-8d05-0334187f2e54', 'push-up (bosu ball)', 'push-up-bosu-ball', 'push-up (bosu ball) using bosu ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place the bosu ball on the ground with the flat side facing up.', 'Position yourself in a push-up position with your hands on the outer edges of the bosu ball.', 'Engage your core and lower your body down towards the bosu ball by bending your elbows.', 'Push yourself back up to the starting position by extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/2kr2lWy.gif'),
('01a0baa8-4248-74a8-8d06-3b8b010f1c36', 'wide grip pull-up', 'wide-grip-pull-up', 'wide grip pull-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.', 'Engage your core and squeeze your shoulder blades together.', 'Pull your body up towards the bar until your chin is above the bar.', 'Lower your body back down to the starting position with control.', 'Repeat for the desired number of repetitions.'], 'exercises/Qqi7bko.gif'),
('01a0baa8-4248-74a8-8d07-47746a6db6e1', 'cable alternate triceps extension', 'cable-alternate-triceps-extension', 'cable alternate triceps extension using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing the cable machine with your feet shoulder-width apart.', 'Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.', 'Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.', 'Pause for a moment, then slowly return to the starting position.', 'Repeat with your left arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/Gchi5Tr.gif'),
('01a0baa8-4249-7866-ab13-ff89dd28156b', 'cable one arm lateral bent-over', 'cable-one-arm-lateral-bent-over', 'cable one arm lateral bent-over using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, facing a cable machine.', 'Grasp the handle with one hand and step back to create tension on the cable.', 'Bend forward at the waist, keeping your back straight and your core engaged.', 'Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.', 'Slowly bring your arm back to the starting position, maintaining control throughout the movement.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/dB07vDu.gif'),
('01a0baa8-4249-7866-ab14-4ad4dc17434a', 'exercise ball lower back stretch (pyramid)', 'exercise-ball-lower-back-stretch-pyramid', 'exercise ball lower back stretch (pyramid) using stability ball.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.', 'Place your hands behind your head or cross them over your chest.', 'Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.', 'Hold the stretch for a few seconds, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/yU7w7CA.gif'),
('01a0baa8-4249-7866-ab15-9a0413d23d08', 'cable one arm fly on exercise ball', 'cable-one-arm-fly-on-exercise-ball', 'cable one arm fly on exercise ball using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.', 'Keep your elbow slightly bent and your palm facing forward.', 'Slowly bring your arm across your body, squeezing your chest muscles.', 'Pause for a moment at the end of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/hHy8tQG.gif'),
('01a0baa8-4249-7866-ab16-f11afa9ef90c', 'barbell seated overhead press', 'barbell-seated-overhead-press', 'barbell seated overhead press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.', 'Press the barbell overhead by extending your arms fully.', 'Pause for a moment at the top, then slowly lower the barbell back to shoulder level.', 'Repeat for the desired number of repetitions.'], 'exercises/kTbSH9h.gif'),
('01a0baa8-4249-7866-ab17-72aea52048f0', 'cable russian twists (on stability ball)', 'cable-russian-twists-on-stability-ball', 'cable russian twists (on stability ball) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Hold the cable handle with both hands and extend your arms straight out in front of you.', 'Lean back slightly while keeping your back straight and your core engaged.', 'Twist your torso to the right, bringing the cable handle towards your right hip.', 'Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.', 'Continue alternating twists for the desired number of repetitions.'], 'exercises/d9Xaxq6.gif'),
('01a0baa8-4249-7866-ab18-7cb9a2ffaaac', 'spell caster', 'spell-caster', 'spell caster using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in one hand.', 'Bend your knees slightly and hinge forward at the waist, keeping your back straight.', 'Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.', 'Return to the starting position and repeat on the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/p9cCe2r.gif'),
('01a0baa8-4249-7866-ab19-5ccb3d4b050f', 'dumbbell seated one arm kickback', 'dumbbell-seated-one-arm-kickback', 'dumbbell seated one arm kickback using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.', 'Bend your torso forward at the waist, keeping your back straight and parallel to the ground.', 'Extend your arm straight back, keeping your elbow close to your body.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/VQ3sNCn.gif'),
('01a0baa8-4249-7866-ab1a-97410f7e5e2a', 'dumbbell decline fly', 'dumbbell-decline-fly', 'dumbbell decline fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with your feet secured and your head lower than your hips.', 'Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.', 'Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.', 'Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/xXm4nYq.gif'),
('01a0baa8-4249-7866-ab1b-f67431a943b2', 'cable lying triceps extension v. 2', 'cable-lying-triceps-extension-v-2', 'cable lying triceps extension v. 2 using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope handle to a low pulley cable machine.', 'Lie down on a flat bench facing up, with your head towards the cable machine.', 'Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.', 'Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.', 'Pause for a moment at the bottom, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/uxJcFUU.gif'),
('01a0baa8-4249-7866-ab1c-a0a8857053c8', 'assisted side lying adductor stretch', 'assisted-side-lying-adductor-stretch', 'assisted side lying adductor stretch using assisted.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie on your side with your legs straight and stacked on top of each other.', 'Bend your bottom leg slightly for stability.', 'Place your top foot on a stable surface, such as a bench or step.', 'Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.', 'Hold the stretch for 20-30 seconds.', 'Return to the starting position and repeat on the other side.'], 'exercises/hC6oYY5.gif'),
('01a0baa8-4249-7866-ab1d-a16dd226e216', 'dumbbell lying one arm press v. 2', 'dumbbell-lying-one-arm-press-v-2', 'dumbbell lying one arm press v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your back supported and feet flat on the ground.', 'Hold a dumbbell in one hand with your palm facing towards your feet.', 'Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.', 'Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.', 'Pause for a moment at the bottom, then push the dumbbell back up to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/K3dIO25.gif'),
('01a0baa8-4249-7866-ab1e-6df86718ccee', 'barbell incline shoulder raise', 'barbell-incline-shoulder-raise', 'barbell incline shoulder raise using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Sit on the bench with your back against the pad and feet flat on the ground.', 'Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Lift the barbell up to shoulder height, keeping your elbows slightly bent.', 'Slowly raise the barbell overhead, extending your arms fully.', 'Pause for a moment at the top, then slowly lower the barbell back to shoulder height.', 'Repeat for the desired number of repetitions.'], 'exercises/xi0yckC.gif'),
('01a0baa8-4249-7866-ab1f-d3f9d872f896', 'cable standing row (v-bar)', 'cable-standing-row-v-bar', 'cable standing row (v-bar) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing the cable machine with your feet shoulder-width apart.', 'Grasp the v-bar attachment with an overhand grip, palms facing down.', 'Keep your back straight and your core engaged.', 'Pull the v-bar towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/4f8RXP8.gif'),
('01a0baa8-4249-7866-ab20-a4a3190e4e6f', 'spider crawl push up', 'spider-crawl-push-up', 'spider crawl push up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.', 'Bring your right knee towards your right elbow, keeping it off the ground.', 'As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.', 'Push back up to the starting position and repeat with your left knee towards your left elbow.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/P9GFBME.gif'),
('01a0baa8-4249-7866-ab21-cc32a78d8cf4', 'dumbbell hammer curls (with arm blaster)', 'dumbbell-hammer-curls-with-arm-blaster', 'dumbbell hammer curls (with arm blaster) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your torso.', 'Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.', 'This will be your starting position.', 'Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.'], 'exercises/GNhAeJ0.gif'),
('01a0baa8-4249-7866-ab22-dc7c90833c8a', 'barbell prone incline curl', 'barbell-prone-incline-curl', 'barbell prone incline curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Lie face down on the bench with your chest and stomach resting against it.', 'Hold a barbell with an underhand grip, shoulder-width apart.', 'Extend your arms fully, allowing the barbell to hang down towards the floor.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/WLvTAv5.gif'),
('01a0baa8-4249-7866-ab23-55df13c2f0a1', 'barbell lying triceps extension', 'barbell-lying-triceps-extension', 'barbell lying triceps extension using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', 'Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.', 'Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.', 'Pause for a moment at the bottom, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/iZop9xO.gif'),
('01a0baa8-4249-7866-ab24-71b1c9e1587d', 'archer pull up', 'archer-pull-up', 'archer pull up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.', 'Engage your core and pull your shoulder blades down and back.', 'As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.', 'Continue pulling until your chin is above the bar and your bent arm is fully flexed.', 'Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.', 'Alternate sides with each repetition.'], 'exercises/72BC5Za.gif'),
('01a0baa8-4249-7866-ab25-37c0a2037023', 'dumbbell prone incline curl', 'dumbbell-prone-incline-curl', 'dumbbell prone incline curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the bench to a 45-degree incline.', 'Lie face down on the bench with your chest and stomach resting against it.', 'Hold a dumbbell in each hand with your palms facing down and your arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/mwpPcr1.gif'),
('01a0baa8-4249-7866-ab26-bbc1d18091a9', 'barbell close-grip bench press', 'barbell-close-grip-bench-press', 'barbell close-grip bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.', 'Pause for a moment when the barbell touches your chest.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/J6Dx1Mu.gif'),
('01a0baa8-4249-7866-ab27-7cd8f9075ec7', 'cable one arm reverse preacher curl', 'cable-one-arm-reverse-preacher-curl', 'cable one arm reverse preacher curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine so that the pulley is at the lowest position.', 'Stand facing the cable machine with your feet shoulder-width apart.', 'Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.', 'Keep your back straight and your core engaged throughout the exercise.', 'Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.', 'Pause for a moment at the top of the movement, squeezing your bicep.', 'Slowly lower the cable handle back to the starting position.', 'Repeat for the desired number of repetitions.', 'Switch arms and repeat the exercise.'], 'exercises/ZXnjcOQ.gif'),
('01a0baa8-4249-7866-ab28-4268c3624340', 'dumbbell standing one arm concentration curl', 'dumbbell-standing-one-arm-concentration-curl', 'dumbbell standing one arm concentration curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.', 'Place your free hand on your thigh for support.', 'Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.', 'Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/8fgqP5a.gif'),
('01a0baa8-4249-7866-ab29-7911a43affaa', 'smith front squat (clean grip)', 'smith-front-squat-clean-grip', 'smith front squat (clean grip) using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up the smith machine with the barbell at shoulder height.', 'Stand facing the barbell with your feet shoulder-width apart.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.', 'Keep your chest up, back straight, and core engaged.', 'Lower your body by bending at the knees and hips, as if sitting back into a chair.', 'Continue lowering until your thighs are parallel to the ground or slightly below.', 'Pause for a moment, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/lFhb2Rw.gif'),
('01a0baa8-4249-7866-ab2a-3c6447fa3309', 'dumbbell seated kickback', 'dumbbell-seated-kickback', 'dumbbell seated kickback using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.', 'Bend your knees slightly and lean forward from your hips, keeping your back straight.', 'Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.', 'Extend your arms straight back, squeezing your triceps at the top of the movement.', 'Pause for a moment, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/en550rk.gif'),
('01a0baa8-4249-7866-ab2b-c93829b64c14', 'cable one arm pulldown', 'cable-one-arm-pulldown', 'cable one arm pulldown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a single handle to a high pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the handle with an overhand grip and extend your arm fully.', 'Keep your back straight and your core engaged.', 'Pull the handle down towards your side while keeping your elbow close to your body.', 'Pause for a moment at the bottom of the movement, squeezing your lat muscle.', 'Slowly release the handle back to the starting position.', 'Repeat for the desired number of repetitions.', 'Switch sides and repeat the exercise with the other arm.'], 'exercises/U5INZY6.gif'),
('01a0baa8-4249-7866-ab2c-c0acb09f8577', 'dumbbell alternating seated bicep curl on exercise ball', 'dumbbell-alternating-seated-bicep-curl-on-exercise-ball', 'dumbbell alternating seated bicep curl on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.', 'Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat the curl with the other arm.', 'Continue alternating curls for the desired number of repetitions.'], 'exercises/J74XlNf.gif'),
('01a0baa8-4249-7866-ab2d-7984b4e466f3', 'close-grip push-up', 'close-grip-push-up', 'close-grip push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands placed close together, directly under your shoulders.', 'Engage your core and lower your body towards the ground, keeping your elbows close to your sides.', 'Push through your palms to extend your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/x6KpKpq.gif'),
('01a0baa8-4249-7866-ab2e-465066d40729', 'dumbbell incline hammer press', 'dumbbell-incline-hammer-press', 'dumbbell incline hammer press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.', 'Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.', 'Press the dumbbells up and away from your body until your arms are fully extended.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/PG1kcIb.gif'),
('01a0baa8-4249-7866-ab2f-fe467782a854', 'cable lateral raise', 'cable-lateral-raise', 'cable lateral raise using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.', 'Keep your arms straight and your core engaged.', 'Raise your arms out to the sides until they are parallel to the floor.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/goJ6ezq.gif'),
('01a0baa8-4249-7866-ab30-5abb6aed6051', 'cable seated row', 'cable-seated-row', 'cable seated row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.', 'Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.', 'Pull the handles towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/fUBheHs.gif'),
('01a0baa8-4249-7866-ab31-4bddce1e0794', 'side bridge v. 2', 'side-bridge-v-2', 'side bridge v. 2 using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your side with your legs extended and stacked on top of each other.', 'Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.', 'Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.', 'Hold this position for the desired amount of time.', 'Lower your hips back down to the starting position.', 'Repeat on the other side.'], 'exercises/RKjH6Lt.gif'),
('01a0baa8-4249-7866-ab32-559c439530a3', 'swing 360', 'swing-360', 'swing 360 using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Hold your arms straight out in front of you, parallel to the ground.', 'Engage your core and swing your arms in a circular motion, rotating your torso as you do so.', 'Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.', 'Remember to breathe throughout the exercise.'], 'exercises/tnaj0mT.gif'),
('01a0baa8-4249-7866-ab33-d46a6b0112b7', 'dumbbell high curl', 'dumbbell-high-curl', 'dumbbell high curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing forward.', 'Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/qAmNMJY.gif'),
('01a0baa8-4249-7866-ab34-261ed0fa049d', 'dumbbell lateral to front raise', 'dumbbell-lateral-to-front-raise', 'dumbbell lateral to front raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.', 'Keep your back straight and engage your core.', 'Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/xMjBKwn.gif'),
('01a0baa8-4249-7866-ab35-a6b02229e578', 'weighted front plank', 'weighted-front-plank', 'weighted front plank using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying face down on the floor.', 'Place your forearms on the ground, with your elbows directly under your shoulders.', 'Extend your legs straight out behind you, with your toes on the ground.', 'Engage your core and lift your body off the ground, balancing on your forearms and toes.', 'Keep your body in a straight line from your head to your heels.', 'Hold this position for the desired amount of time.', 'Lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/VBAWRPG.gif'),
('01a0baa8-4249-7866-ab36-947d5036cc6e', 'dumbbell standing one arm curl over incline bench', 'dumbbell-standing-one-arm-curl-over-incline-bench-v2', 'dumbbell standing one arm curl over incline bench using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in one hand.', 'Place your other hand on an incline bench for support.', 'Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/EmlJR2y.gif'),
('01a0baa8-4249-7866-ab37-a3ee6b2bd350', 'band fixed back close grip pulldown', 'band-fixed-back-close-grip-pulldown', 'band fixed back close grip pulldown using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.', 'Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.', 'Grasp the band with a close grip, palms facing towards you.', 'Keep your back straight and engage your core.', 'Pull the band down towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, feeling the contraction in your lats.', 'Slowly release the band back to the starting position, maintaining control throughout the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/4LoWllp.gif'),
('01a0baa8-4249-7866-ab38-48fd749bc934', 'cable front raise', 'cable-front-raise', 'cable front raise using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.', 'Keep your back straight and your core engaged.', 'Raise the cable handle in front of you, keeping your arms straight and your palms facing down.', 'Continue lifting until your arms are parallel to the floor.', 'Pause for a moment at the top, then slowly lower the cable handle back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/u2X71Np.gif'),
('01a0baa8-4249-7866-ab39-8695bffc635f', 'assisted hanging knee raise', 'assisted-hanging-knee-raise', 'assisted hanging knee raise using assisted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', 'Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.', 'Pause for a moment at the top of the movement, squeezing your abs.', 'Slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/03lzqwk.gif'),
('01a0baa8-4249-7866-ab3a-9f0ca357a664', 'dumbbell forward lunge triceps extension', 'dumbbell-forward-lunge-triceps-extension', 'dumbbell forward lunge triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', 'Take a step forward with your right foot, lowering your body into a lunge position.', 'Keep your back straight and your chest up.', 'Extend your arms straight overhead, keeping your elbows close to your ears.', 'Lower the dumbbells behind your head by bending your elbows.', 'Pause for a moment, then straighten your arms to return to the starting position.', 'Repeat the movement for the desired number of repetitions, then switch legs and repeat.'], 'exercises/XalXcvM.gif'),
('01a0baa8-4249-7866-ab3b-15eabf270d90', 'cable rope elevated seated row', 'cable-rope-elevated-seated-row', 'cable rope elevated seated row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the elevated seat facing the cable machine.', 'Grab the cable rope handles with an overhand grip, palms facing each other.', 'Keep your back straight and lean slightly back, maintaining a slight bend in your knees.', 'Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.', 'Pause for a moment at the fully contracted position.', 'Slowly release the tension and extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/c8oybX6.gif'),
('01a0baa8-4249-7866-ab3c-f9d91f726150', 'smith reverse-grip press', 'smith-reverse-grip-press', 'smith reverse-grip press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the height of the smith machine bar to chest level.', 'Stand facing the bar with your feet shoulder-width apart.', 'Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.', 'Step back and position yourself with a slight bend in your knees.', 'Keep your chest up and core engaged throughout the exercise.', 'Lower the bar towards your chest, keeping your elbows tucked in.', 'Pause for a moment at the bottom, then push the bar back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/zK8Fu1W.gif'),
('01a0baa8-4249-7866-ab3d-668f0e7aec2f', 'dumbbell standing reverse curl', 'dumbbell-standing-reverse-curl', 'dumbbell standing reverse curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/0IgNjSM.gif'),
('01a0baa8-4249-7866-ab3e-0de29c593c0b', 'shoulder tap', 'shoulder-tap', 'shoulder tap using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.', 'Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.', 'Continue alternating shoulder taps while keeping your hips and torso stable.', 'Repeat for the desired number of repetitions.'], 'exercises/yRpV5TC.gif'),
('01a0baa8-4249-7866-ab3f-3b8d951c05d0', 'dumbbell lying external shoulder rotation', 'dumbbell-lying-external-shoulder-rotation', 'dumbbell lying external shoulder rotation using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.', 'Hold a dumbbell in your hand with your palm facing down.', 'Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.', 'Pause for a moment at the top, then slowly lower your forearm back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/bmBf7LN.gif'),
('01a0baa8-4249-7866-ab40-78b78707de06', 'dumbbell seated shoulder press (parallel grip)', 'dumbbell-seated-shoulder-press-parallel-grip', 'dumbbell seated shoulder press (parallel grip) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with a dumbbell in each hand, palms facing inward.', 'Raise the dumbbells to shoulder height, elbows bent and palms facing forward.', 'Press the dumbbells upward until your arms are fully extended overhead.', 'Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.', 'Repeat for the desired number of repetitions.'], 'exercises/f1jf47L.gif'),
('01a0baa8-4249-7866-ab41-56fa8afbaa56', 'bodyweight standing calf raise', 'bodyweight-standing-calf-raise', 'bodyweight standing calf raise using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes pointing forward.', 'Place your hands on a wall or stable surface for balance.', 'Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/bJYHBIN.gif'),
('01a0baa8-4249-7866-ab42-24e51b786a5b', 'bent knee lying twist (male)', 'bent-knee-lying-twist-male', 'bent knee lying twist (male) using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Extend your arms out to the sides, perpendicular to your body.', 'Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.', 'Pause for a moment, then engage your core and slowly lift your knees back to the starting position.', 'Repeat the movement to the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/6sYyrRX.gif'),
('01a0baa8-4249-7866-ab43-a1ccfa4637c5', 'dumbbell seated alternate shoulder', 'dumbbell-seated-alternate-shoulder', 'dumbbell seated alternate shoulder using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.', 'Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.', 'Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.', 'Continue alternating between arms for the desired number of repetitions.'], 'exercises/q7qkONO.gif'),
('01a0baa8-4249-7866-ab44-a5cd05a14258', 'cable standing one arm triceps extension', 'cable-standing-one-arm-triceps-extension', 'cable standing one arm triceps extension using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, facing the cable machine.', 'Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.', 'Keep your elbow stationary and close to your body.', 'Slowly bend your elbow, lowering the cable handle towards the back of your head.', 'Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.', 'Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm.'], 'exercises/sYCcnon.gif'),
('01a0baa8-4249-7866-ab45-f94db5fe7c2c', 'lying (side) quads stretch', 'lying-side-quads-stretch', 'lying (side) quads stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie on your side with your legs straight.', 'Bend your top leg and grab your ankle or foot with your hand.', 'Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.', 'Hold the stretch for 20-30 seconds.', 'Release the stretch and repeat on the other side.'], 'exercises/BWnJR72.gif'),
('01a0baa8-4249-7866-ab46-a047055e6895', 'single leg calf raise (on a dumbbell)', 'single-leg-calf-raise-on-a-dumbbell', 'single leg calf raise (on a dumbbell) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart and hold a dumbbell in one hand.', 'Lift one foot off the ground and balance on the other foot.', 'Slowly raise your heel as high as possible, using your calf muscles.', 'Pause for a moment at the top, then slowly lower your heel back down.', 'Repeat for the desired number of repetitions, then switch to the other leg.'], 'exercises/fKZgDEO.gif'),
('01a0baa8-4249-7866-ab47-2c903b442101', 'barbell single leg deadlift', 'barbell-single-leg-deadlift', 'barbell single leg deadlift using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.', 'Shift your weight onto your left foot and lift your right foot slightly off the ground.', 'Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.', 'Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.', 'Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/gEyURal.gif'),
('01a0baa8-4249-7866-ab48-ef64be72031b', 'barbell speed squat', 'barbell-speed-squat', 'barbell speed squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes slightly turned out.', 'Hold the barbell across your upper back, resting it on your traps or rear delts.', 'Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.', 'Lower until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Drive through your heels to stand back up, squeezing your glutes at the top.', 'Repeat for the desired number of repetitions.'], 'exercises/euI1BwR.gif'),
('01a0baa8-4249-7866-ab49-2ed915107f34', '3/4 sit-up', '34-sit-up', '3/4 sit-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/2gPfomN.gif'),
('01a0baa8-4249-7866-ab4a-9868ec6639a3', 'dumbbell standing alternate overhead press', 'dumbbell-standing-alternate-overhead-press', 'dumbbell standing alternate overhead press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.', 'Press one dumbbell overhead, fully extending your arm.', 'Lower the dumbbell back to shoulder level.', 'Repeat with the other arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/bBi35y3.gif'),
('01a0baa8-4249-7866-ab4b-46aaf3618a3d', 'reverse grip pull-up', 'reverse-grip-pull-up', 'reverse grip pull-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Grab the pull-up bar with an underhand grip, hands shoulder-width apart.', 'Hang from the bar with your arms fully extended and your body straight.', 'Engage your back muscles and pull your body up towards the bar, leading with your chest.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/YAk5dIw.gif'),
('01a0baa8-4249-7866-ab4c-52cfa66f060f', 'lever t-bar reverse grip row', 'lever-t-bar-reverse-grip-row', 'lever t-bar reverse grip row using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.', 'Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.', 'Keep your back straight and engage your core.', 'Pull the handles towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/FVM1AUZ.gif'),
('01a0baa8-4249-7866-ab4d-f6890855f3e0', 'barbell clean and press', 'barbell-clean-and-press', 'barbell clean and press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and the barbell on the floor in front of you.', 'Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.', 'As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.', 'As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.', 'From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.', 'Lower the barbell back down to the starting position and repeat for the desired number of repetitions.'], 'exercises/SGY8Zui.gif'),
('01a0baa8-4249-7866-ab4e-8465e2bcf8c0', 'dumbbell lying alternate extension', 'dumbbell-lying-alternate-extension', 'dumbbell lying alternate extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with a dumbbell in each hand, palms facing each other.', 'Extend your arms straight up over your chest, keeping a slight bend in your elbows.', 'Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.', 'Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.', 'Repeat with the other arm, alternating sides for the desired number of repetitions.'], 'exercises/NfP83rA.gif'),
('01a0baa8-4249-7866-ab4f-7e62ff9eb67b', 'dumbbell stiff leg deadlift', 'dumbbell-stiff-leg-deadlift', 'dumbbell stiff leg deadlift using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', 'Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.', 'Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/5eLRITT.gif'),
('01a0baa8-4249-7866-ab50-3b746ccf1682', 'dumbbell incline y-raise', 'dumbbell-incline-y-raise', 'dumbbell incline y-raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.', 'Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.', 'Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/PbzNu7c.gif'),
('01a0baa8-4249-7866-ab51-e77f8301df97', 'exercise ball seated hamstring stretch', 'exercise-ball-seated-hamstring-stretch', 'exercise ball seated hamstring stretch using stability ball.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.', 'Place your hands on your hips for support.', 'Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.', 'Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.', 'Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.', 'Repeat for the desired number of repetitions.'], 'exercises/yRYyfdA.gif'),
('01a0baa8-4249-7866-ab52-192c21dc0a49', 'medicine ball chest push with run release', 'medicine-ball-chest-push-with-run-release', 'medicine ball chest push with run release using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a medicine ball at chest level.', 'Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.', 'As you push the ball forward, release it and let it roll forward.', 'Quickly run forward and catch the ball before it hits the ground.', 'Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.', 'Continue alternating legs and repeating the exercise for the desired number of repetitions.'], 'exercises/pX9Elbe.gif'),
('01a0baa8-4249-7866-ab53-4693fdebc5a1', 'air bike', 'air-bike', 'air bike using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your hands placed behind your head.', 'Lift your legs off the ground and bend your knees at a 90-degree angle.', 'Bring your right elbow towards your left knee while simultaneously straightening your right leg.', 'Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.', 'Continue alternating sides in a pedaling motion for the desired number of repetitions.'], 'exercises/1ZFqTDN.gif'),
('01a0baa8-4249-7866-ab54-74780f3d5156', 'standing calves calf stretch', 'standing-calves-calf-stretch', 'standing calves calf stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand facing a wall or sturdy object, about an arm''s length away.', 'Place your hands on the wall or object at shoulder height.', 'Step back with one foot, keeping your heel flat on the ground.', 'Bend your front knee slightly and lean forward, keeping your back leg straight.', 'You should feel a stretch in your calf muscle.', 'Hold the stretch for 20-30 seconds.', 'Repeat on the other leg.'], 'exercises/qOKcgVP.gif'),
('01a0baa8-4249-7866-ab55-dc16c096d8d1', 'cable one arm curl', 'cable-one-arm-curl', 'cable one arm curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing the cable machine with your feet shoulder-width apart.', 'Grasp the cable handle with an underhand grip, palm facing up.', 'Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.', 'Pause for a moment at the top, then slowly lower your forearm back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/YTur5nR.gif'),
('01a0baa8-4249-7866-ab56-5ef4bfcf4b06', 'smith incline reverse-grip press', 'smith-incline-reverse-grip-press', 'smith incline reverse-grip press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat of the smith machine to a comfortable incline angle.', 'Sit on the machine with your back against the pad and your feet flat on the ground.', 'Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.', 'Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.', 'Pause for a moment when the bar is just above your chest.', 'Push the bar back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/78VqWQK.gif'),
('01a0baa8-4249-7866-ab57-5cfce5c55f33', 'sphinx', 'sphinx', 'sphinx using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.', 'Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.', 'Hold this position for a few seconds, making sure to keep your neck in a neutral position.', 'Slowly lower your chest back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/DIVyqrU.gif'),
('01a0baa8-4249-7866-ab58-8ba5363f3668', 'lever shoulder press v. 3', 'lever-shoulder-press-v-3', 'lever shoulder press v. 3 using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and backrest of the leverage machine to a comfortable position.', 'Sit on the machine with your back against the backrest and your feet flat on the floor.', 'Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.', 'Push the handles upward and forward until your arms are fully extended, but not locked.', 'Pause for a moment at the top, then slowly lower the handles back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/dNFYIU1.gif'),
('01a0baa8-4249-7866-ab59-058d9c813c34', 'raise single arm push-up', 'raise-single-arm-push-up', 'raise single arm push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.', 'Extend one arm straight out to the side, parallel to the ground.', 'Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.', 'Push back up to the starting position, using your chest muscles to lift your body.', 'Repeat with the other arm extended.'], 'exercises/13TpY4H.gif'),
('01a0baa8-4249-7866-ab5a-0f19599c9f6e', 'standing calf raise (on a staircase)', 'standing-calf-raise-on-a-staircase', 'standing calf raise (on a staircase) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.', 'Hold onto a railing or wall for balance if needed.', 'Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/6HmFgmx.gif'),
('01a0baa8-4249-7866-ab5b-4ae839fc4d0f', 'assisted wide-grip chest dip (kneeling)', 'assisted-wide-grip-chest-dip-kneeling', 'assisted wide-grip chest dip (kneeling) using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the machine to your desired height and secure your knees on the pad.', 'Grasp the handles with a wide grip and keep your elbows slightly bent.', 'Lower your body by bending your elbows until your upper arms are parallel to the floor.', 'Push yourself back up to the starting position by extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/PnZJIrk.gif'),
('01a0baa8-4249-7866-ab5c-543a60a3bca2', 'cable concentration curl', 'cable-concentration-curl', 'cable concentration curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.', 'Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.', 'Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.', 'Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/NvfE43H.gif'),
('01a0baa8-4249-7866-ab5d-6ad7a2513ad9', 'band twisting overhead press', 'band-twisting-overhead-press', 'band twisting overhead press using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place the band under your feet.', 'Hold the band handles at shoulder height with your palms facing forward.', 'Engage your core and press the band overhead, fully extending your arms.', 'As you press, twist your torso to one side, keeping your hips stable.', 'Pause for a moment at the top, then return to the starting position.', 'Repeat the press and twist on the opposite side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/u4bAmKp.gif'),
('01a0baa8-4249-7866-ab5e-164aad81c018', 'bench dip on floor', 'bench-dip-on-floor', 'bench dip on floor using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.', 'Slide your butt off the bench, supporting your weight with your hands.', 'Lower your body by bending your elbows until your upper arms are parallel to the floor.', 'Push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/9RT8oQW.gif'),
('01a0baa8-4249-7866-ab5f-c292da1270af', 'barbell side split squat v. 2', 'barbell-side-split-squat-v-2', 'barbell side split squat v. 2 using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.', 'Hold a barbell across your upper back, resting it on your shoulders.', 'Take a big step to the side with your right foot, keeping your left foot planted.', 'Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.', 'Push through your right heel to return to the starting position.', 'Repeat on the other side, stepping out with your left foot.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/HUEqZ1y.gif'),
('01a0baa8-4249-7866-ab60-663fdd6309f8', 'cycle cross trainer', 'cycle-cross-trainer', 'cycle cross trainer using leverage machine.', 'CARDIO', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the cycle cross trainer.', 'Place your feet on the pedals and grip the handlebars.', 'Start pedaling in a smooth and controlled motion.', 'Maintain a steady pace and increase the resistance if desired.', 'Continue pedaling for the desired duration of your cardio workout.'], 'exercises/XSCHmiI.gif'),
('01a0baa8-4249-7866-ab61-02eb99edb6db', 'dumbbell incline one arm lateral raise', 'dumbbell-incline-one-arm-lateral-raise', 'dumbbell incline one arm lateral raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.', 'Lean forward and position your upper arm against the inside of your thigh.', 'Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.', 'Continue lifting until your arm is parallel to the floor.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/aTNKZiC.gif'),
('01a0baa8-4249-7866-ab62-f998ab06de85', 'cable one arm incline press on exercise ball', 'cable-one-arm-incline-press-on-exercise-ball', 'cable one arm incline press on exercise ball using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.', 'Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.', 'Press the cable handle forward and upward, extending your arm fully.', 'Pause for a moment at the top, then slowly lower the cable handle back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/6t00BsF.gif'),
('01a0baa8-4249-7866-ab63-2d9ef14ee867', 'side lying hip adduction (male)', 'side-lying-hip-adduction-male', 'side lying hip adduction (male) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your side with your legs straight and stacked on top of each other.', 'Place your bottom arm under your head for support.', 'Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.', 'Pause for a moment at the top, then slowly lower your leg back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/c8f5cSY.gif'),
('01a0baa8-4249-7866-ab64-1c747052fa4d', 'wind sprints', 'wind-sprints', 'wind sprints using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Find an open space or a track to perform the exercise.', 'Start by standing with your feet shoulder-width apart.', 'Begin running as fast as you can, pumping your arms and driving your knees up.', 'Continue sprinting for a specific distance or time period.', 'Rest and repeat for the desired number of repetitions.'], 'exercises/Qoujh3Q.gif'),
('01a0baa8-4249-7866-ab65-7e4fb50aa665', 'barbell seated twist', 'barbell-seated-twist', 'barbell seated twist using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a flat bench with your feet flat on the ground and your knees bent.', 'Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.', 'Engage your core and slowly twist your torso to one side, keeping your back straight.', 'Pause for a moment at the end of the twist, then slowly rotate back to the starting position.', 'Repeat the twist to the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/dFSNDOA.gif'),
('01a0baa8-4249-7866-ab66-bd7e8da90357', 'dumbbell standing one arm reverse curl', 'dumbbell-standing-one-arm-reverse-curl', 'dumbbell standing one arm reverse curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.', 'Keep your arm fully extended and close to your body, with your palm facing down.', 'Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/DU5Kkj2.gif'),
('01a0baa8-4249-7866-ab67-008d3ec0e41a', 'dumbbell seated alternate press', 'dumbbell-seated-alternate-press', 'dumbbell seated alternate press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with a dumbbell in each hand, palms facing forward.', 'Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.', 'Press one dumbbell up overhead, fully extending your arm.', 'Lower the dumbbell back down to shoulder height.', 'Repeat with the other arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/QT5Q0nK.gif'),
('01a0baa8-4249-7866-ab68-3beeb88bda0e', 'cable straight arm pulldown', 'cable-straight-arm-pulldown', 'cable straight arm pulldown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to the high pulley of a cable machine.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.', 'Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.', 'Pause for a moment at the bottom, then slowly return the bar to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/x69MAlq.gif'),
('01a0baa8-4249-7866-ab69-c96330dde55b', 'cable deadlift', 'cable-deadlift', 'cable deadlift using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing the cable machine with your feet shoulder-width apart.', 'Bend at the hips and knees, lowering your torso until your back is parallel to the ground.', 'Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.', 'Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.', 'Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/eGDudUV.gif'),
('01a0baa8-4249-7866-ab6a-dc6a4cc81202', 'dumbbell decline shrug v. 2', 'dumbbell-decline-shrug-v-2', 'dumbbell decline shrug v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up a decline bench at a 45-degree angle.', 'Lie face down on the bench with your chest and stomach resting on it.', 'Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.', 'Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.', 'Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/bRlbdjK.gif'),
('01a0baa8-4249-7866-ab6b-3ca8b1d3f7be', 'weighted seated twist (on stability ball)', 'weighted-seated-twist-on-stability-ball', 'weighted seated twist (on stability ball) using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Hold a weight plate or dumbbell with both hands close to your chest.', 'Engage your core and slowly rotate your torso to one side, keeping your hips stable.', 'Pause for a moment at the end of the rotation, then slowly return to the starting position.', 'Repeat the rotation to the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/s34Y4LR.gif'),
('01a0baa8-4249-7866-ab6c-0d0ad8090723', 'basic toe touch (male)', 'basic-toe-touch-male', 'basic toe touch (male) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your arms by your sides.', 'Bend forward at the waist, keeping your back straight and your knees slightly bent.', 'Reach down towards your toes with your hands, keeping your legs as straight as possible.', 'Pause for a moment at the bottom, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/BbfB8Gb.gif'),
('01a0baa8-4249-7866-ab6d-6c4bbc92217b', 'barbell pendlay row', 'barbell-pendlay-row', 'barbell pendlay row using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Bend forward at the hips, keeping your back straight and your chest up.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.', 'Lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/r0z6xzQ.gif'),
('01a0baa8-4249-7866-ab6e-75c1d43e864a', 'cable one arm press on exercise ball', 'cable-one-arm-press-on-exercise-ball', 'cable one arm press on exercise ball using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a cable handle in one hand and position your arm at chest height, elbow bent.', 'Place your other hand on your hip for stability.', 'Press the cable handle forward, extending your arm fully.', 'Pause for a moment, then slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/MKIelrR.gif'),
('01a0baa8-4249-7866-ab6f-be5ccd71301a', 'dumbbell biceps curl reverse', 'dumbbell-biceps-curl-reverse', 'dumbbell biceps curl reverse using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/nFc4FyV.gif'),
('01a0baa8-4249-7866-ab70-8fcfeb6f7d91', 'smith chair squat', 'smith-chair-squat', 'smith chair squat using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the height of the smith machine bar to a comfortable position.', 'Stand with your feet shoulder-width apart, toes slightly turned out.', 'Place the barbell across your upper back, resting it on your traps.', 'Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.', 'Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Gu2rNJd.gif'),
('01a0baa8-4249-7866-ab71-5b0de748165c', 'dumbbell one arm bench fly', 'dumbbell-one-arm-bench-fly', 'dumbbell one arm bench fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.', 'Lie back on the bench, keeping the dumbbell pressed against your thigh.', 'Using your free hand, help lift the dumbbell up to the starting position.', 'Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.', 'Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.', 'Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms and repeat.'], 'exercises/o5Jsk92.gif'),
('01a0baa8-424a-7b0c-b954-f02f9a724992', 'dumbbell lying wide curl', 'dumbbell-lying-wide-curl', 'dumbbell lying wide curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/qm9veZw.gif'),
('01a0baa8-424a-7b0c-b955-2281b29eb903', 'exercise ball one leg prone lower body rotation', 'exercise-ball-one-leg-prone-lower-body-rotation', 'exercise ball one leg prone lower body rotation using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.', 'Place your hands on the ground in front of you for support.', 'Engage your glutes and core muscles to stabilize your body.', 'Slowly lift one leg off the ground, keeping it straight and parallel to the floor.', 'Rotate your leg outward, away from your body, while keeping your hips and upper body stable.', 'Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.', 'Repeat the rotation with the other leg.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/M72BExt.gif'),
('01a0baa8-424a-7b0c-b956-f75d9cd28cc0', 'dumbbell one arm reverse fly (with support)', 'dumbbell-one-arm-reverse-fly-with-support', 'dumbbell one arm reverse fly (with support) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and your back straight.', 'Hold a dumbbell in one hand with your palm facing inwards.', 'Lean forward and place your free hand on the bench for support.', 'Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arm back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/e25F58f.gif'),
('01a0baa8-424a-7b0c-b957-951a288455f6', 'cable standing rear delt row (with rope)', 'cable-standing-rear-delt-row-with-rope', 'cable standing rear delt row (with rope) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.', 'Keep your back straight and your core engaged.', 'Pull the cable towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ZfyAGhK.gif'),
('01a0baa8-424a-7b0c-b958-55d0ed4a13a4', 'pull-in (on stability ball)', 'pull-in-on-stability-ball', 'pull-in (on stability ball) using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Place your hands on the sides of the stability ball for support.', 'Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.', 'Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/UQr48Oi.gif'),
('01a0baa8-424a-7b0c-b959-f316016554d2', 'push and pull bodyweight', 'push-and-pull-bodyweight', 'push and pull bodyweight using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.', 'Lower your chest towards the ground by bending your elbows, keeping your body straight.', 'Push through your palms to extend your arms and return to the starting position.', 'From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.', 'Push through your palms to extend your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/wXvUZC8.gif'),
('01a0baa8-424a-7b0c-b95a-e6ed94529308', 'barbell lying close-grip press', 'barbell-lying-close-grip-press', 'barbell lying close-grip press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.', 'Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'Slowly lower the barbell towards your chest, keeping your elbows close to your body.', 'Pause for a moment when the barbell touches your chest, then push it back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/EcaV7aL.gif'),
('01a0baa8-424a-7b0c-b95b-2ee02e980348', 'dumbbell revers grip biceps curl', 'dumbbell-revers-grip-biceps-curl', 'dumbbell revers grip biceps curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/e4ojVhP.gif'),
('01a0baa8-424a-7b0c-b95c-a98c6b0b9472', 'cable upper row', 'cable-upper-row', 'cable upper row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a cable machine at chest height.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.', 'Keep your back straight and your core engaged.', 'Pull the bar towards your upper chest, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement.', 'Slowly release the bar back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/PQStVXH.gif'),
('01a0baa8-424a-7b0c-b95d-931a2b8d77ab', 'cable rear delt row (stirrups)', 'cable-rear-delt-row-stirrups', 'cable rear delt row (stirrups) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a stirrup handle to a low cable pulley and stand facing the machine.', 'Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.', 'With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.', 'Pause for a moment at the top of the movement, squeezing your shoulder blade.', 'Slowly release the handle back to the starting position and repeat for the desired number of repetitions.', 'Switch sides and repeat the exercise with your right arm.'], 'exercises/yUdIGNs.gif'),
('01a0baa8-424a-7b0c-b95e-c26af5540e27', 'weighted one hand pull up', 'weighted-one-hand-pull-up', 'weighted one hand pull up using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.', 'Hang from the bar with your arm fully extended and your body straight.', 'Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.', 'Continue pulling until your chin is above the bar.', 'Lower your body back down to the starting position with control.', 'Repeat for the desired number of repetitions.'], 'exercises/fXfqg1E.gif'),
('01a0baa8-424a-7b0c-b95f-277c72f9d6ff', 'cable standing calf raise', 'cable-standing-calf-raise', 'cable standing calf raise using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Hold onto the cable machine handles or attach a cable ankle strap to your ankles.', 'Raise your heels off the ground by extending your ankles as high as possible.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/yl2IYyy.gif'),
('01a0baa8-424a-7b0c-b960-24034c621fb4', 'bodyweight standing close-grip one arm row', 'bodyweight-standing-close-grip-one-arm-row', 'bodyweight standing close-grip one arm row using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.', 'Bend forward at the hips, keeping your back straight and your core engaged.', 'Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/v2DfH14.gif'),
('01a0baa8-424a-7b0c-b961-540cd579fa7e', 'dumbbell standing inner biceps curl v. 2', 'dumbbell-standing-inner-biceps-curl-v-2', 'dumbbell standing inner biceps curl v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your torso.', 'Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.', 'While holding your upper arms stationary, curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Slowly begin to bring the dumbbells back to the starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.'], 'exercises/vKilzz3.gif'),
('01a0baa8-424a-7b0c-b962-53ce20e2c3d9', 'medicine ball overhead slam', 'medicine-ball-overhead-slam', 'medicine ball overhead slam using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.', 'Engage your core and keep your back straight.', 'Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.', 'As you slam the ball down, use your entire body to generate power, including your shoulders and core.', 'Catch the ball on the bounce and repeat for the desired number of repetitions.'], 'exercises/oHg8eop.gif'),
('01a0baa8-424a-7b0c-b963-f71d03e1a54d', 'barbell seated close grip behind neck triceps extension', 'barbell-seated-close-grip-behind-neck-triceps-extension', 'barbell seated close grip behind neck triceps extension using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold the barbell with a close grip behind your neck, palms facing forward.', 'Keep your elbows close to your head and slowly lower the barbell towards the back of your head.', 'Pause for a moment, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/4CBIBOM.gif'),
('01a0baa8-424a-7b0c-b964-3cff0e72dfc9', 'dumbbell seated one leg calf raise - hammer grip', 'dumbbell-seated-one-leg-calf-raise---hammer-grip', 'dumbbell seated one leg calf raise - hammer grip using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.', 'Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.', 'Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.', 'Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.', 'Pause for a moment at the top, then slowly lower your heel back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other leg.'], 'exercises/FxhcxUW.gif'),
('01a0baa8-424a-7b0c-b965-9fe43ef90f7b', 'cable pushdown (with rope attachment)', 'cable-pushdown-with-rope-attachment', 'cable pushdown (with rope attachment) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope attachment to a high pulley on a cable machine.', 'Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.', 'Grasp the rope with an overhand grip, palms facing each other.', 'Keep your elbows close to your sides and your upper arms stationary throughout the exercise.', 'Exhale and push the rope downward by extending your elbows until your arms are fully extended.', 'Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.', 'Repeat for the desired number of repetitions.'], 'exercises/dU605di.gif'),
('01a0baa8-424a-7b0c-b966-a7c516b7d1f2', 'dumbbell front raise v. 2', 'dumbbell-front-raise-v-2', 'dumbbell front raise v. 2 using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.', 'Keep your back straight and engage your core.', 'Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Rr7S3yg.gif'),
('01a0baa8-424a-7b0c-b967-d2653b6fedf9', 'standing lateral stretch', 'standing-lateral-stretch', 'standing lateral stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Extend your arms straight out to the sides, parallel to the ground.', 'Slowly lean your upper body to one side, feeling a stretch in your side and lats.', 'Hold the stretch for 15-30 seconds.', 'Return to the starting position and repeat on the other side.', 'Repeat for the desired number of repetitions.'], 'exercises/1jXLYEw.gif'),
('01a0baa8-424a-7b0c-b968-455440918ddf', 'barbell front chest squat', 'barbell-front-chest-squat', 'barbell front chest squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart, toes slightly turned out.', 'Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.', 'Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.', 'Lower until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/IeTIEqg.gif'),
('01a0baa8-424a-7b0c-b969-0e59c2f52bc5', 'suspended push-up', 'suspended-push-up', 'suspended push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Find a suspension trainer and adjust it to an appropriate height.', 'Stand facing away from the anchor point and hold the handles with an overhand grip.', 'Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.', 'Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.', 'Push through your chest and arms to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/IaGQCrC.gif'),
('01a0baa8-424a-7b0c-b96a-41cd06808dd6', 'cable twisting pull', 'cable-twisting-pull', 'cable twisting pull using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a cable handle to a low pulley and stand facing the machine.', 'Grasp the handle with your left hand and step away from the machine, extending your arm fully.', 'Position your feet shoulder-width apart, with your knees slightly bent.', 'Keep your back straight and your core engaged throughout the exercise.', 'Pull the handle towards your body, rotating your torso to the right as you do so.', 'Squeeze your back muscles at the end of the movement.', 'Slowly return to the starting position, keeping tension on the cable.', 'Repeat for the desired number of repetitions, then switch sides and perform with your right hand.'], 'exercises/zCgxPbV.gif'),
('01a0baa8-424a-7b0c-b96b-1dea5ff389b5', 'clock push-up', 'clock-push-up', 'clock push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Lower your body towards the ground by bending your elbows, keeping them close to your sides.', 'As you lower, rotate your body to the left, extending your left arm straight out to the side.', 'Push back up to the starting position, while rotating your body to the center.', 'Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.', 'Continue alternating sides with each repetition.'], 'exercises/CMAxnsG.gif'),
('01a0baa8-424a-7b0c-b96c-1e7c3b7d224e', 'decline push-up', 'decline-push-up', 'decline push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.', 'Keep your body in a straight line from head to toe, engaging your core muscles.', 'Lower your chest towards the ground by bending your elbows, keeping them close to your body.', 'Push through your palms to extend your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/i5cEhka.gif'),
('01a0baa8-424a-7b0c-b96d-ef037130b163', 'weighted sissy squat', 'weighted-sissy-squat', 'weighted sissy squat using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your toes pointing slightly outward.', 'Hold a weight in front of your chest with both hands, or place a barbell across your upper back.', 'Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.', 'Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/0lQnxMZ.gif'),
('01a0baa8-424a-7b0c-b96e-c7632dd3f9d5', 'ski step', 'ski-step', 'ski step using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Bend your knees slightly and keep your back straight.', 'Jump to the right, landing on your right foot while swinging your left leg behind your right leg.', 'Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.', 'Continue alternating jumps from side to side, mimicking a skiing motion.', 'Repeat for the desired number of repetitions.'], 'exercises/5MRH8H2.gif'),
('01a0baa8-424a-7b0c-b96f-6929da3ac4ef', 'dumbbell side lying one hand raise', 'dumbbell-side-lying-one-hand-raise', 'dumbbell side lying one hand raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your side with your legs extended and your head supported by your arm.', 'Hold a dumbbell in your top hand with your palm facing down.', 'Keeping your arm straight, raise the dumbbell up to shoulder height.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/fTlkJop.gif'),
('01a0baa8-424a-7b0c-b970-aacbe1726c73', 'cable forward raise', 'cable-forward-raise', 'cable forward raise using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.', 'Keeping your arms straight, raise the cable handle up to shoulder level.', 'Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/hvHhCv8.gif'),
('01a0baa8-424a-7b0c-b971-2c01f17d4068', 'barbell incline bench press', 'barbell-incline-bench-press', 'barbell incline bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Lie down on the bench with your feet flat on the ground.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.', 'Pause for a moment at the bottom, then push the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/3TZduzM.gif'),
('01a0baa8-424a-7b0c-b972-64f7ea4a926a', 'triceps dip', 'triceps-dip', 'triceps dip using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.', 'Slide your butt off the bench, supporting your weight with your hands.', 'Bend your elbows and lower your body towards the ground, keeping your back close to the bench.', 'Pause for a moment at the bottom, then push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/X6C6i5Y.gif'),
('01a0baa8-424a-7b0c-b973-18ff01153cef', 'exercise ball one legged diagonal kick hamstring curl', 'exercise-ball-one-legged-diagonal-kick-hamstring-curl', 'exercise ball one legged diagonal kick hamstring curl using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying on your back with your legs extended and your heels resting on top of the stability ball.', 'Place your arms by your sides for stability.', 'Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.', 'Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.', 'Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.', 'Slowly return your right leg to the starting position, maintaining control and stability.', 'Repeat the movement with your left leg, alternating sides for the desired number of repetitions.'], 'exercises/GOJKFfO.gif'),
('01a0baa8-424a-7b0c-b974-969bf89b2d14', 'resistance band seated biceps curl', 'resistance-band-seated-biceps-curl', 'resistance band seated biceps curl using resistance band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a chair or bench with your back straight and feet flat on the ground.', 'Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.', 'Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the resistance band back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/XFc3vpY.gif'),
('01a0baa8-424a-7b0c-b975-e5c5b06deae6', 'assisted seated pectoralis major stretch with stability ball', 'assisted-seated-pectoralis-major-stretch-with-stability-ball', 'assisted seated pectoralis major stretch with stability ball using assisted.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on a stability ball with your feet flat on the ground and your back straight.', 'Hold a stability ball with both hands and extend your arms straight out in front of you.', 'Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.', 'Hold the stretch for a few seconds, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/RoV1Rfa.gif'),
('01a0baa8-424a-7b0c-b976-41ca805fa320', 'dumbbell upright shoulder external rotation', 'dumbbell-upright-shoulder-external-rotation', 'dumbbell upright shoulder external rotation using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.', 'Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.', 'Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/x306lCW.gif'),
('01a0baa8-424a-7b0c-b977-80eac4321132', 'barbell wide-grip upright row', 'barbell-wide-grip-upright-row', 'barbell wide-grip upright row using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.', 'Let the barbell hang in front of your thighs, arms fully extended.', 'Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.', 'Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/RgJDRR1.gif'),
('01a0baa8-424a-7b0c-b978-1e971ba711ec', 'roller reverse crunch', 'roller-reverse-crunch', 'roller reverse crunch using roller.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.', 'Place the roller between your feet and grip it with your toes.', 'Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.', 'Repeat for the desired number of repetitions.'], 'exercises/SKXQAx3.gif'),
('01a0baa8-424a-7b0c-b979-eef6e79456f2', 'medicine ball supine chest throw', 'medicine-ball-supine-chest-throw', 'medicine ball supine chest throw using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back on a bench with your knees bent and feet flat on the ground.', 'Hold the medicine ball with both hands, extending your arms straight up above your chest.', 'Lower the medicine ball towards your chest, keeping your elbows close to your body.', 'Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.', 'Catch the medicine ball and repeat for the desired number of repetitions.'], 'exercises/Al3tP0D.gif'),
('01a0baa8-424a-7b0c-b97a-521ecab53ecd', 'band reverse fly', 'band-reverse-fly', 'band reverse fly using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a stationary object at chest height.', 'Stand with your feet shoulder-width apart and hold the band with both hands in front of you.', 'Keep your arms straight and lift them out to the sides until they are parallel to the ground.', 'Squeeze your shoulder blades together at the top of the movement.', 'Slowly lower your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/sTfvVsG.gif'),
('01a0baa8-424a-7b0c-b97b-377d0683fd08', 'barbell wrist curl', 'barbell-wrist-curl', 'barbell wrist curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.', 'Allow the barbell to roll down to your fingertips, keeping your wrists straight.', 'Slowly curl the barbell up towards your forearms by flexing your wrists.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/82LxxkW.gif'),
('01a0baa8-424a-7b0c-b97c-b76098d74199', 'cable standing reverse grip one arm overhead tricep extension', 'cable-standing-reverse-grip-one-arm-overhead-tricep-extension', 'cable standing reverse grip one arm overhead tricep extension using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing away from the cable machine with your feet shoulder-width apart.', 'Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.', 'Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.', 'Pause for a moment at the bottom, then extend your arm back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/i11JWU7.gif'),
('01a0baa8-424a-7b0c-b97d-7ee1505945ab', 'band assisted wheel rollerout', 'band-assisted-wheel-rollerout', 'band assisted wheel rollerout using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Kneel on the floor and hold the handles of the band with both hands, palms facing down.', 'Place the band on the ground in front of you and position your hands shoulder-width apart.', 'Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.', 'Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/zhF9lW4.gif'),
('01a0baa8-424a-7b0c-b97e-4a8372ce1174', 'cable rear drive', 'cable-rear-drive', 'cable rear drive using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a handle to a low pulley cable machine and stand facing away from the machine.', 'Grasp the handle with an overhand grip and extend your arms straight out in front of you.', 'Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.', 'Slowly return the handle to the starting position and repeat for the desired number of repetitions.'], 'exercises/c3QQLPi.gif'),
('01a0baa8-424a-7b0c-b97f-e3bbef75778b', 'dumbbell sumo pull through', 'dumbbell-sumo-pull-through', 'dumbbell sumo pull through using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet wider than shoulder-width apart, toes pointed outwards.', 'Hold a dumbbell with both hands in front of your body, arms extended.', 'Bend your knees and lower your hips down into a squat position, keeping your back straight.', 'Lower the dumbbell down between your legs, keeping your arms straight.', 'Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.', 'Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.', 'Repeat for the desired number of repetitions.'], 'exercises/BmrwWzo.gif'),
('01a0baa8-424a-7b0c-b980-39173f99e34f', 'smith seated one leg calf raise', 'smith-seated-one-leg-calf-raise', 'smith seated one leg calf raise using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the machine with your back against the pad and your feet on the footrest.', 'Place one leg on the footrest and keep the other leg off the footrest.', 'Using your calf muscles, raise your heel as high as possible.', 'Pause for a moment at the top, then slowly lower your heel back down to the starting position.', 'Repeat for the desired number of repetitions, then switch legs and repeat.'], 'exercises/0S75mYG.gif'),
('01a0baa8-424a-7b0c-b981-598058862a06', 'cable lying bicep curl', 'cable-lying-bicep-curl', 'cable lying bicep curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a low pulley cable machine.', 'Lie face up on a flat bench with your feet flat on the ground.', 'Grasp the bar with an underhand grip, hands shoulder-width apart.', 'Extend your arms fully, keeping your elbows close to your sides.', 'Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the bar back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/otqIxU4.gif'),
('01a0baa8-424a-7b0c-b982-6b7f3c2bd130', 'dumbbell hammer curl', 'dumbbell-hammer-curl', 'dumbbell hammer curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your torso.', 'Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.', 'This will be your starting position.', 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.'], 'exercises/slDvUAU.gif'),
('01a0baa8-424a-7b0c-b983-109a194caa49', 'dumbbell one arm triceps extension (on bench)', 'dumbbell-one-arm-triceps-extension-on-bench', 'dumbbell one arm triceps extension (on bench) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a dumbbell in one hand and place your other hand on the bench for support.', 'Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.', 'Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.', 'Extend your arm back up to the starting position, fully straightening your elbow.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/nAuHPcD.gif'),
('01a0baa8-424a-7b0c-b984-e19505e1cc14', 'dumbbell incline hammer curl', 'dumbbell-incline-hammer-curl', 'dumbbell incline hammer curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.', 'Keep your back against the bench and your feet flat on the floor.', 'While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ByX0WxV.gif'),
('01a0baa8-424a-7b0c-b985-2774317e749e', 'barbell front raise and pullover', 'barbell-front-raise-and-pullover', 'barbell front raise and pullover using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.', 'Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Next, lower the barbell behind your head, keeping your arms straight.', 'Pause for a moment at the bottom, then raise the barbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/33AzZeV.gif'),
('01a0baa8-424a-7b0c-b986-e95f1803d32f', 'balance board', 'balance-board', 'balance board using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Place the balance board on a flat surface.', 'Step onto the balance board with one foot, ensuring it is centered.', 'Slowly shift your weight onto the foot on the balance board, keeping your core engaged.', 'Maintain your balance and stability as you hold the position for a desired amount of time.', 'Repeat the exercise with the other foot.'], 'exercises/xAySMB0.gif'),
('01a0baa8-424a-7b0c-b987-5e9b9ea4b7cf', 'single leg squat (pistol) male', 'single-leg-squat-pistol-male', 'single leg squat (pistol) male using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and arms extended in front of you.', 'Lift your right foot off the ground and extend it forward.', 'Slowly lower your body down by bending your left knee and pushing your hips back.', 'Keep your chest up and your back straight as you lower yourself down.', 'Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your left heel to return to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/nqs5HGV.gif'),
('01a0baa8-424a-7b0c-b988-ada8bc0f6a1b', 'walking lunge', 'walking-lunge', 'walking lunge using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Take a step forward with your right leg, lowering your body into a lunge position.', 'Keep your torso upright and your front knee aligned with your ankle.', 'Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.', 'Continue alternating legs and walking forward, maintaining a controlled and steady pace.', 'Repeat for the desired number of repetitions.'], 'exercises/IZVHb27.gif'),
('01a0baa8-424a-7b0c-b989-e4cca46ce387', 'cable tuck reverse crunch', 'cable-tuck-reverse-crunch', 'cable tuck reverse crunch using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a cable to a low pulley and lie down on a mat facing up.', 'Hold the cable with both hands and extend your arms straight up above your chest.', 'Bend your knees and lift your legs up, bringing your knees towards your chest.', 'At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.', 'Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/TXtXc84.gif'),
('01a0baa8-424a-7b0c-b98a-f452729a0285', 'v-sit on floor', 'v-sit-on-floor', 'v-sit on floor using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the floor with your legs extended in front of you.', 'Lean back slightly and lift your legs off the ground, keeping them straight.', 'Simultaneously, lift your upper body off the ground and reach your arms towards your legs.', 'Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ZuXu4Eq.gif'),
('01a0baa8-424a-7b0c-b98b-bc51063814db', 'smith reverse calf raises', 'smith-reverse-calf-raises', 'smith reverse calf raises using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the smith machine bar to a height just below your shoulders.', 'Stand facing the bar with your feet hip-width apart and toes pointing forward.', 'Place the balls of your feet on the edge of a step or platform, with your heels hanging off.', 'Hold onto the bar for support, keeping your back straight and core engaged.', 'Raise your heels as high as possible, lifting your body weight onto the balls of your feet.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ywaNfuh.gif'),
('01a0baa8-424a-7b0c-b98c-ece58b4571d6', 'dumbbell preacher curl over exercise ball', 'dumbbell-preacher-curl-over-exercise-ball', 'dumbbell preacher curl over exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.', 'Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/hwygydB.gif'),
('01a0baa8-424a-7b0c-b98d-232b209750bb', 'straight leg outer hip abductor', 'straight-leg-outer-hip-abductor', 'straight leg outer hip abductor using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your side with your legs straight and stacked on top of each other.', 'Place your bottom arm under your head for support.', 'Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.', 'Pause for a moment at the top, then slowly lower your leg back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/mQ1tBXn.gif'),
('01a0baa8-424a-7b0c-b98e-510fd409f809', 'band single leg calf raise', 'band-single-leg-calf-raise', 'band single leg calf raise using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart and place the band around the ball of your left foot.', 'Hold onto a stable object for balance if needed.', 'Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.', 'Pause for a moment at the top, then slowly lower your left heel back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the right leg.'], 'exercises/9JprnPh.gif'),
('01a0baa8-424a-7b0c-b98f-f7cbec8031f5', 'chin-up', 'chin-up', 'chin-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.', 'Engage your core and pull your body up towards the bar, leading with your chest.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/T2mxWqc.gif'),
('01a0baa8-424a-7b0c-b990-400fa86b7542', 'barbell lying lifting (on hip)', 'barbell-lying-lifting-on-hip', 'barbell lying lifting (on hip) using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back on a bench with your feet flat on the ground and your knees bent.', 'Hold the barbell with an overhand grip and position it on your hips.', 'Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.', 'Pause for a moment at the top, then slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/SNFfUff.gif'),
('01a0baa8-424a-7b0c-b991-ceced56d039b', 'cable reverse curl', 'cable-reverse-curl', 'cable reverse curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a low pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.', 'Grasp the bar with an underhand grip, hands shoulder-width apart.', 'Keep your elbows close to your sides and your upper arms stationary throughout the exercise.', 'Exhale and curl the bar up towards your shoulders, contracting your biceps.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the bar back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/eOG0r6v.gif'),
('01a0baa8-424a-7b0c-b992-877a4e41d9fb', 'dumbbell seated front raise', 'dumbbell-seated-front-raise', 'dumbbell seated front raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.', 'Keep your back straight and core engaged.', 'Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Ys97II0.gif'),
('01a0baa8-424a-7b0c-b993-de33136f84fc', 'bodyweight standing row', 'bodyweight-standing-row', 'bodyweight standing row using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Grasp a bar or handles with an overhand grip, palms facing down.', 'Keep your back straight and core engaged.', 'Pull the bar or handles towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement.', 'Slowly release and extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/wd4ds3s.gif'),
('01a0baa8-424a-7b0c-b994-1211ab285c51', 'dumbbell single leg deadlift with stepbox support', 'dumbbell-single-leg-deadlift-with-stepbox-support', 'dumbbell single leg deadlift with stepbox support using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart, holding a dumbbell in your right hand.', 'Place your left foot on a stepbox or elevated surface behind you.', 'Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.', 'As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.', 'Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/daBmy1Y.gif'),
('01a0baa8-424a-7b0c-b995-c8d57d4d48cf', 'decline sit-up', 'decline-sit-up', 'decline sit-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with your feet secured and your knees bent.', 'Place your hands behind your head or across your chest.', 'Engage your abs and lift your upper body off the bench, curling forward towards your knees.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/QLL2gdc.gif'),
('01a0baa8-424a-7b0c-b996-316274795aae', 'dumbbell reverse wrist curl', 'dumbbell-reverse-wrist-curl', 'dumbbell reverse wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your feet flat on the ground.', 'Hold a dumbbell in each hand with an overhand grip, palms facing down.', 'Rest your forearms on your thighs, allowing your wrists to hang off the edge.', 'Slowly curl your wrists upward, bringing the dumbbells towards your body.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/BLCvwr2.gif'),
('01a0baa8-424a-7b0c-b997-7d42cee304b0', 'lunge with twist', 'lunge-with-twist', 'lunge with twist using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart.', 'Take a step forward with your right foot, lowering your body into a lunge position.', 'As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.', 'Pause for a moment, then return to the starting position.', 'Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/K9VL0Jq.gif'),
('01a0baa8-424a-7b0c-b998-5dccc6706b30', 'smith incline bench press', 'smith-incline-bench-press', 'smith incline bench press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the bench to a 30-45 degree incline.', 'Sit on the bench with your back flat against the pad and feet firmly on the ground.', 'Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.', 'Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/5v7KYld.gif'),
('01a0baa8-424a-7b0c-b999-0c367826a5d3', 'exercise ball back extension with rotation', 'exercise-ball-back-extension-with-rotation', 'exercise ball back extension with rotation using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.', 'Place your hands behind your head or cross them over your chest.', 'Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.', 'Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.', 'Return to the center and repeat the rotation to the other side.', 'Lower your upper body back down to the starting position and repeat for the desired number of repetitions.'], 'exercises/WVD66ff.gif'),
('01a0baa8-424a-7b0c-b99a-1ef8ef1533be', 'dumbbell seated alternate front raise', 'dumbbell-seated-alternate-front-raise', 'dumbbell seated alternate front raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.', 'Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat with the other arm.', 'Alternate between arms for the desired number of repetitions.'], 'exercises/gH5fRsC.gif'),
('01a0baa8-424a-7b0c-b99b-8859252a6153', 'bottoms-up', 'bottoms-up', 'bottoms-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs extended and your arms by your sides.', 'Bend your knees and bring them towards your chest, keeping your feet off the ground.', 'Engaging your abs, lift your hips off the ground, bringing your knees towards your head.', 'Pause for a moment at the top, then slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/CI6baTY.gif'),
('01a0baa8-424a-7b0c-b99c-537e3773dcab', 'cable drag curl', 'cable-drag-curl', 'cable drag curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/dXz8zjF.gif'),
('01a0baa8-424a-7b0c-b99d-f21e205b8c13', 'bodyweight squatting row (with towel)', 'bodyweight-squatting-row-with-towel', 'bodyweight squatting row (with towel) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.', 'Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.', 'As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/BReCuOn.gif'),
('01a0baa8-424a-7b0c-b99e-77906bdf8274', 'cable lying close-grip curl', 'cable-lying-close-grip-curl', 'cable lying close-grip curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a low pulley cable machine.', 'Lie face up on a flat bench with your feet flat on the ground.', 'Grasp the bar with an underhand grip, hands shoulder-width apart.', 'Extend your arms fully, keeping your elbows close to your sides.', 'Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.', 'Pause for a moment at the top, squeezing your biceps.', 'Slowly lower the bar back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/61GrD55.gif'),
('01a0baa8-424a-7b0c-b99f-d95eb62ce39f', 'cable lat pulldown full range of motion', 'cable-lat-pulldown-full-range-of-motion', 'cable lat pulldown full range of motion using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the lat pulldown machine with your knees positioned under the pads.', 'Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.', 'Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.', 'Pull the bar down towards your upper chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/LEprlgG.gif'),
('01a0baa8-424a-7b0c-b9a0-c484e2f7a388', 'barbell low bar squat', 'barbell-low-bar-squat', 'barbell low bar squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and the barbell resting on your upper back.', 'Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.', 'Continue lowering until your thighs are parallel to the ground or slightly below.', 'Pause for a moment, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/bTpEUcm.gif'),
('01a0baa8-424a-7b0c-b9a1-8035e83d25b4', 'assisted pull-up', 'assisted-pull-up', 'assisted pull-up using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the machine to your desired weight and height settings.', 'Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.', 'Hang with your arms fully extended and your feet off the ground.', 'Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.', 'Continue pulling until your chin is above the handles.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/kiJ4Z2K.gif'),
('01a0baa8-424a-7b0c-b9a2-b4985a807d13', 'cable side bend crunch (bosu ball)', 'cable-side-bend-crunch-bosu-ball', 'cable side bend crunch (bosu ball) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a cable handle in one hand.', 'Place the other hand on your hip.', 'Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.', 'Pause for a moment at the bottom of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/qatbkEd.gif'),
('01a0baa8-424a-7b0c-b9a3-ff00f0659e4b', 'barbell rack pull', 'barbell-rack-pull', 'barbell rack pull using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up a barbell on a rack at knee height.', 'Stand with your feet shoulder-width apart, toes pointing slightly outwards.', 'Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.', 'Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.', 'Lower the barbell back down to the starting position by bending at the hips and knees.', 'Repeat for the desired number of repetitions.'], 'exercises/za9Ni4z.gif'),
('01a0baa8-424a-7b0c-b9a4-7e926744858e', 'stationary bike run', 'stationary-bike-run', 'stationary bike run using stationary bike.', 'CARDIO', 'INTERMEDIATE', ARRAY['Adjust the seat height and position to ensure proper alignment.', 'Place your feet on the pedals and secure them with the straps if available.', 'Start pedaling at a comfortable pace.', 'Maintain a steady rhythm and increase the resistance as desired.', 'Engage your core muscles to maintain stability and proper posture.', 'Continue pedaling for the desired duration of your workout.', 'Gradually decrease the resistance and slow down before coming to a complete stop.', 'Stretch your legs and cool down after the workout.'], 'exercises/H1PESYI.gif'),
('01a0baa8-424a-7b0c-b9a5-f97c6f708a94', 'dumbbell one arm hammer press on exercise ball', 'dumbbell-one-arm-hammer-press-on-exercise-ball', 'dumbbell one arm hammer press on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.', 'Place your other hand on your hip for stability.', 'Press the dumbbell upwards, extending your arm fully.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/VYmYxK5.gif'),
('01a0baa8-424a-7b0c-b9a6-387a3c07fa0b', 'london bridge', 'london-bridge', 'london bridge using rope.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the rope to a high anchor point.', 'Stand facing away from the anchor point with your feet shoulder-width apart.', 'Grasp the rope with an overhand grip, palms facing down.', 'Lean forward slightly, keeping your back straight and core engaged.', 'Pull the rope towards your body, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/bLyQokI.gif'),
('01a0baa8-424a-7b0c-b9a7-9529deb0cdf8', 'snatch pull', 'snatch-pull', 'snatch pull using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and the barbell on the ground in front of you.', 'Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.', 'Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.', 'As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.', 'As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.', 'Catch the barbell overhead with your arms fully extended and your knees bent.', 'Stand up by extending your hips and knees, keeping the barbell overhead.', 'Lower the barbell back down to the starting position by reversing the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/dG5Smob.gif'),
('01a0baa8-424a-7b0c-b9a8-07c8aac93c86', 'smith bent knee good morning', 'smith-bent-knee-good-morning', 'smith bent knee good morning using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart, toes pointing forward.', 'Place the barbell across your upper back, resting it on your traps.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.', 'Engage your glutes and hamstrings to raise your torso back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/1bQkKZK.gif'),
('01a0baa8-424a-7b0c-b9a9-86ef707216ef', 'cable kickback', 'cable-kickback', 'cable kickback using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Hold the cable handle with your right hand and step back to create tension in the cable.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Keep your upper arm close to your body and your elbow bent at a 90-degree angle.', 'Extend your forearm backward, straightening your arm fully.', 'Pause for a moment, then slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/HEJ6DIX.gif'),
('01a0baa8-424a-7b0c-b9aa-eb8104813efa', 'dumbbell arnold press', 'dumbbell-arnold-press', 'dumbbell arnold press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.', 'Press the dumbbells upward until your arms are fully extended and your palms are facing forward.', 'Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Xy4jlWA.gif'),
('01a0baa8-424a-7b0c-b9ab-acd395abfe70', 'dead bug', 'dead-bug', 'dead bug using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your arms extended towards the ceiling.', 'Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.', 'Engage your core and lower back to press your lower back into the ground.', 'Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.', 'Pause for a moment, then return to the starting position.', 'Repeat the movement with your left arm and right leg.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/iny3m5y.gif'),
('01a0baa8-424a-7b0c-b9ac-8a6e7cdba9ce', 'dumbbell bicep curl with stork stance', 'dumbbell-bicep-curl-with-stork-stance', 'dumbbell bicep curl with stork stance using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.', 'Extend one leg behind you, balancing on the toes of that foot.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions, then switch legs and repeat.'], 'exercises/uSkDMYl.gif'),
('01a0baa8-424a-7b0c-b9ad-0b229a47fe3f', 'barbell glute bridge two legs on bench (male)', 'barbell-glute-bridge-two-legs-on-bench-male', 'barbell glute bridge two legs on bench (male) using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.', 'Place a barbell across your hips, holding it securely with both hands.', 'Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.', 'Pause for a moment at the top, squeezing your glutes.', 'Slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/qg2PGl6.gif'),
('01a0baa8-424a-7b0c-b9ae-c1f7748ba980', 'cable concentration extension (on knee)', 'cable-concentration-extension-on-knee', 'cable concentration extension (on knee) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your knees bent and feet flat on the ground.', 'Hold the cable handle with your right hand and place your elbow on the inside of your right knee.', 'Extend your arm fully, keeping your elbow stationary and close to your knee.', 'Pause for a moment at the top, then slowly lower your arm back to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/Db7eEgw.gif'),
('01a0baa8-424a-7b0c-b9af-cdcc21ea5927', 'dumbbell seated bent over alternate kickback', 'dumbbell-seated-bent-over-alternate-kickback', 'dumbbell seated bent over alternate kickback using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with a dumbbell in each hand, palms facing inwards.', 'Bend forward at the waist, keeping your back straight and parallel to the ground.', 'Extend one arm straight back, keeping it close to your body, until your arm is fully extended.', 'Pause for a moment, then slowly lower the dumbbell back to the starting position.', 'Repeat with the other arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/x0lwvfq.gif'),
('01a0baa8-424a-7b0c-b9b0-6051ff1397ae', 'band standing twisting crunch', 'band-standing-twisting-crunch', 'band standing twisting crunch using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.', 'Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.', 'Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.', 'Pause for a moment, then return to the starting position.', 'Repeat on the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/euq4pwp.gif'),
('01a0baa8-424a-7b0c-b9b1-6cd5b20706e5', 'cable wide grip rear pulldown behind neck', 'cable-wide-grip-rear-pulldown-behind-neck', 'cable wide grip rear pulldown behind neck using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine so that the pulldown bar is at a height above your head.', 'Sit down on the seat and grab the pulldown bar with a wide overhand grip.', 'Keep your back straight and your chest up as you lean back slightly.', 'Pull the bar down towards your upper chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/CmEr4pM.gif'),
('01a0baa8-424a-7b0c-b9b2-558e973a062f', 'dumbbell rotation reverse fly', 'dumbbell-rotation-reverse-fly', 'dumbbell rotation reverse fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.', 'Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.', 'Rotate your arms so that your palms are facing downwards.', 'Slowly lower your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/prbWx1D.gif'),
('01a0baa8-424a-7b0c-b9b3-7b8f5e5bf5a6', 'dumbbell lying pronation on floor', 'dumbbell-lying-pronation-on-floor', 'dumbbell lying pronation on floor using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.', 'Rotate your palms so they are facing down towards the floor.', 'Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.', 'Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.', 'Hold for a moment, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/7RWNjiB.gif'),
('01a0baa8-424a-7b0c-b9b4-cc33e011f4b2', 'dumbbell one leg fly on exercise ball', 'dumbbell-one-leg-fly-on-exercise-ball', 'dumbbell one leg fly on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with a dumbbell in each hand, palms facing each other.', 'Place one foot on the ground and extend the other leg straight out in front of you.', 'Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.', 'Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.', 'Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.', 'Repeat for the desired number of repetitions, then switch legs and repeat.'], 'exercises/pH2x2jj.gif'),
('01a0baa8-424a-7b0c-b9b5-eac66b6303b4', 'barbell romanian deadlift', 'barbell-romanian-deadlift', 'barbell romanian deadlift using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your toes pointing forward.', 'Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Bend at the hips, keeping your back straight and your knees slightly bent.', 'Lower the barbell towards the ground, keeping it close to your body.', 'Feel the stretch in your hamstrings as you lower the barbell.', 'Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.', 'Squeeze your glutes at the top of the movement.', 'Lower the barbell back down to the starting position and repeat for the desired number of repetitions.'], 'exercises/wQ2c4XD.gif'),
('01a0baa8-424a-7b0c-b9b6-029ad5e5a786', 'dumbbell biceps curl v sit on bosu ball', 'dumbbell-biceps-curl-v-sit-on-bosu-ball', 'dumbbell biceps curl v sit on bosu ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/H1XAdpk.gif'),
('01a0baa8-424a-7b0c-b9b7-9950449286cb', 'stationary bike walk', 'stationary-bike-walk', 'stationary bike walk using leverage machine.', 'CARDIO', 'INTERMEDIATE', ARRAY['Adjust the seat height and position on the stationary bike to ensure proper alignment.', 'Place your feet on the pedals and secure them with the straps if available.', 'Start pedaling at a comfortable pace, keeping your back straight and core engaged.', 'Maintain a steady rhythm and increase the resistance level if desired.', 'Continue pedaling for the desired duration of your cardio workout.', 'Cool down by gradually reducing your pace and resistance level.', 'Stretch your leg muscles after the workout to prevent tightness and promote recovery.'], 'exercises/a8VDgLw.gif'),
('01a0baa8-424a-7b0c-b9b8-777eaac9cc10', 'dumbbell seated hammer curl', 'dumbbell-seated-hammer-curl', 'dumbbell seated hammer curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/IGtBdNT.gif'),
('01a0baa8-424a-7b0c-b9b9-0d155843dbfd', 'roller side lat stretch', 'roller-side-lat-stretch', 'roller side lat stretch using roller.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.', 'Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/c3Pfhti.gif'),
('01a0baa8-424a-7b0c-b9ba-39417cf1527c', 'wrist circles', 'wrist-circles', 'wrist circles using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Extend your arms straight out in front of you.', 'Make a fist with both hands.', 'Rotate your wrists in a circular motion, keeping your arms still.', 'Continue the wrist circles for the desired number of repetitions.'], 'exercises/2zNKRUB.gif'),
('01a0baa8-424a-7b0c-b9bb-e300f937f20d', 'seated glute stretch', 'seated-glute-stretch', 'seated glute stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the ground with your legs extended in front of you.', 'Bend your right knee and cross your right ankle over your left thigh.', 'Place your right hand on the ground behind you for support.', 'With your left hand, gently press down on your right knee to deepen the stretch.', 'Hold the stretch for 30 seconds to 1 minute.', 'Switch sides and repeat.'], 'exercises/DeDThfG.gif'),
('01a0baa8-424a-7b0c-b9bc-f500a335ed1e', 'barbell standing ab rollerout', 'barbell-standing-ab-rollerout', 'barbell standing ab rollerout using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.', 'Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.', 'Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.', 'Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.', 'Repeat for the desired number of repetitions.'], 'exercises/xnInPfE.gif'),
('01a0baa8-424b-7cd5-839c-b2151c16bccd', 'self assisted inverse leg curl (on floor)', 'self-assisted-inverse-leg-curl-on-floor', 'self assisted inverse leg curl (on floor) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs extended and your arms by your sides.', 'Bend your knees and place your feet flat on the ground, hip-width apart.', 'Lift your hips off the ground, engaging your glutes and hamstrings.', 'Slowly curl your legs towards your glutes, keeping your hips lifted.', 'Pause for a moment at the top, then slowly extend your legs back to the starting position.', 'Lower your hips back down to the ground.', 'Repeat for the desired number of repetitions.'], 'exercises/ZSY3MsL.gif'),
('01a0baa8-424b-7cd5-839d-fdd67f3d906e', 'weighted cossack squats (male)', 'weighted-cossack-squats-male', 'weighted cossack squats (male) using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.', 'Hold a weight in front of your chest with both hands.', 'Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.', 'Go as low as you can while maintaining balance and keeping your chest up.', 'Push through the heel of the bent leg to return to the starting position.', 'Repeat on the other side, alternating between legs.'], 'exercises/GWoKnIm.gif'),
('01a0baa8-424b-7cd5-839e-25bb0fdeb42e', 'smith shoulder press', 'smith-shoulder-press', 'smith shoulder press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.', 'Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.', 'Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.', 'Press the bar upward until your arms are fully extended overhead.', 'Pause for a moment at the top, then slowly lower the bar back down to shoulder level.', 'Repeat for the desired number of repetitions.'], 'exercises/903mzG8.gif'),
('01a0baa8-424b-7cd5-839f-44ad5dcc9068', 'seated calf stretch (male)', 'seated-calf-stretch-male', 'seated calf stretch (male) using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the edge of a chair or bench with your feet flat on the ground.', 'Extend one leg straight out in front of you, keeping your heel on the ground.', 'Lean forward slightly, feeling a stretch in your calf muscle.', 'Hold the stretch for 20-30 seconds.', 'Switch legs and repeat the stretch.'], 'exercises/17bqEXD.gif'),
('01a0baa8-424b-7cd5-83a0-3aa947e10d99', 'dumbbell reverse grip incline bench two arm row', 'dumbbell-reverse-grip-incline-bench-two-arm-row', 'dumbbell reverse grip incline bench two arm row using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Sit on the bench with your chest against the backrest and your feet flat on the ground.', 'Hold a dumbbell in each hand with an underhand grip.', 'Lean forward and let your arms hang straight down, fully extended.', 'Pull the dumbbells up towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/9pQSkH8.gif'),
('01a0baa8-424b-7cd5-83a1-93fdd9ab84dd', 'barbell jefferson squat', 'barbell-jefferson-squat', 'barbell jefferson squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and toes slightly turned out.', 'Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.', 'Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.', 'Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.', 'Push through your heels to stand back up to the starting position.', 'Repeat the movement, alternating your forward and back foot with each repetition.'], 'exercises/pkSoCW9.gif'),
('01a0baa8-424b-7cd5-83a2-e268a8b83dc0', 'cable upright row', 'cable-upright-row', 'cable upright row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.', 'Keep your back straight and your core engaged throughout the exercise.', 'Pull the cable attachment straight up towards your chin, leading with your elbows.', 'Pause for a moment at the top, squeezing your shoulder blades together.', 'Slowly lower the cable attachment back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/cALKspW.gif'),
('01a0baa8-424b-7cd5-83a3-513ddf2d1aa8', 'crunch (on stability ball)', 'crunch-on-stability-ball', 'crunch (on stability ball) using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.', 'Place your hands behind your head or across your chest.', 'Engage your abs and lift your upper body towards your knees, curling your torso forward.', 'Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/MCUhf1F.gif'),
('01a0baa8-424b-7cd5-83a4-c7a69f85a8cc', 'smith standing military press', 'smith-standing-military-press', 'smith standing military press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.', 'Press the barbell upward until your arms are fully extended overhead.', 'Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.', 'Repeat for the desired number of repetitions.'], 'exercises/jjUPrze.gif'),
('01a0baa8-424b-7cd5-83a5-c8d20620d9b8', 'cable kneeling triceps extension', 'cable-kneeling-triceps-extension', 'cable kneeling triceps extension using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope handle to a high pulley and kneel down facing the cable machine.', 'Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.', 'Keep your elbows close to your head and your upper arms stationary throughout the exercise.', 'Extend your forearms by contracting your triceps until your arms are fully extended.', 'Pause for a moment, then slowly return to the starting position by bending your elbows.', 'Repeat for the desired number of repetitions.'], 'exercises/KWdF2JI.gif'),
('01a0baa8-424b-7cd5-83a6-1bd5c9257f84', 'dumbbell one arm reverse preacher curl', 'dumbbell-one-arm-reverse-preacher-curl', 'dumbbell one arm reverse preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.', 'Lower the dumbbell slowly until your arm is fully extended.', 'Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.', 'Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/bWxq4op.gif'),
('01a0baa8-424b-7cd5-83a7-ce600e662a39', 'lever seated squat calf raise on leg press machine', 'lever-seated-squat-calf-raise-on-leg-press-machine', 'lever seated squat calf raise on leg press machine using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.', 'Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.', 'Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.', 'Release the safety handles and push the footplate away from you by extending your knees.', 'Once your knees are fully extended, slowly lower your heels by flexing your calves.', 'Pause for a moment at the bottom, then push the footplate back up by extending your calves.', 'Repeat for the desired number of repetitions.'], 'exercises/IeDEXTe.gif'),
('01a0baa8-424b-7cd5-83a8-9e2a2f803208', 'lying leg-hip raise', 'lying-leg-hip-raise', 'lying leg-hip raise using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs extended and your arms by your sides.', 'Place your hands under your glutes for support.', 'Engage your core and lift your legs off the ground, raising them towards the ceiling.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/9IxJdtC.gif'),
('01a0baa8-424b-7cd5-83a9-b88a393d582a', 'dumbbell standing one arm palm in press', 'dumbbell-standing-one-arm-palm-in-press', 'dumbbell standing one arm palm in press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.', 'Engage your core and keep your back straight.', 'Press the dumbbell upwards until your arm is fully extended.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/ocYc6Db.gif'),
('01a0baa8-424b-7cd5-83aa-b91cf4d527b3', 'bear crawl', 'bear-crawl', 'bear crawl using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Start on all fours with your hands directly under your shoulders and your knees directly under your hips.', 'Lift your knees slightly off the ground, keeping your back flat and your core engaged.', 'Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.', 'Continue crawling forward, alternating your hand and foot movements.', 'Maintain a steady pace and keep your core tight throughout the exercise.', 'Continue for the desired distance or time.'], 'exercises/0Yz8WdV.gif'),
('01a0baa8-424b-7cd5-83ab-26cde22bbd56', 'rear deltoid stretch', 'rear-deltoid-stretch', 'rear deltoid stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand tall with your feet shoulder-width apart.', 'Extend your right arm across your chest, placing your left hand on your right elbow.', 'Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.', 'Hold the stretch for 15-30 seconds, then release.', 'Repeat on the other side.'], 'exercises/xifhB5W.gif'),
('01a0baa8-424b-7cd5-83ac-4d4c72eeb20d', 'cable one arm preacher curl', 'cable-one-arm-preacher-curl', 'cable one arm preacher curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine so that the preacher curl pad is at chest height.', 'Stand facing the cable machine with your feet shoulder-width apart.', 'Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.', 'Keep your back straight and your core engaged.', 'Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.', 'Pause for a moment at the top of the movement, squeezing your biceps.', 'Slowly lower the cable handle back to the starting position.', 'Repeat for the desired number of repetitions.', 'Switch arms and repeat the exercise.'], 'exercises/eHBlPsa.gif'),
('01a0baa8-424b-7cd5-83ad-891e7537e242', 'dumbbell tate press', 'dumbbell-tate-press', 'dumbbell tate press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a flat bench with a dumbbell in each hand, palms facing each other.', 'Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.', 'Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.', 'Rotate your wrists back to the starting position and repeat for the desired number of repetitions.'], 'exercises/s5PdDyY.gif'),
('01a0baa8-424b-7cd5-83ae-cbb7e665a202', 'dumbbell alternating bicep curl with leg raised on exercise ball', 'dumbbell-alternating-bicep-curl-with-leg-raised-on-exercise-ball', 'dumbbell alternating bicep curl with leg raised on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.', 'Place an exercise ball behind you and position one foot on top of it, keeping your balance.', 'With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.', 'Lower the dumbbell back down to the starting position and repeat with the other arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/Zwiw7XR.gif'),
('01a0baa8-424b-7cd5-83af-fffb65e11d2a', 'dumbbells seated triceps extension', 'dumbbells-seated-triceps-extension', 'dumbbells seated triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a dumbbell in both hands with an overhand grip, and raise it above your head.', 'Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.', 'Extend your arms and raise the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/FQXdXzY.gif'),
('01a0baa8-424b-7cd5-83b0-2d9c5266c032', 'cable high pulley overhead tricep extension', 'cable-high-pulley-overhead-tricep-extension', 'cable high pulley overhead tricep extension using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope to a high pulley and stand facing away from the machine.', 'Grasp the rope with both hands and extend your arms overhead.', 'Keep your elbows close to your head and your upper arms stationary.', 'Slowly lower the rope behind your head by bending your elbows.', 'Pause for a moment, then extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/1xHyxys.gif'),
('01a0baa8-424b-7cd5-83b1-6791573ba224', 'alternate lateral pulldown', 'alternate-lateral-pulldown', 'alternate lateral pulldown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the cable machine with your back straight and feet flat on the ground.', 'Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.', 'Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/4IKbhHV.gif'),
('01a0baa8-424b-7cd5-83b2-5847240c85bb', 'exercise ball lying side lat stretch', 'exercise-ball-lying-side-lat-stretch', 'exercise ball lying side lat stretch using stability ball.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Lie on your side with your legs extended and your head supported by the stability ball.', 'Place your top arm on the ball for stability.', 'Reach your top arm overhead and allow your torso to rotate slightly.', 'Feel the stretch in your lat muscles on the side of your body.', 'Hold the stretch for 20-30 seconds, then switch sides and repeat.'], 'exercises/rTbyBYV.gif'),
('01a0baa8-424b-7cd5-83b3-4ab825aea6cd', 'dumbbell seated bench extension', 'dumbbell-seated-bench-extension', 'dumbbell seated bench extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a dumbbell with both hands and extend your arms straight up above your head.', 'Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.', 'Pause for a moment, then raise the dumbbell back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/JhYSVwT.gif'),
('01a0baa8-424b-7cd5-83b4-95a29975aca2', 'dumbbell scott press', 'dumbbell-scott-press', 'dumbbell scott press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with a dumbbell in each hand, palms facing forward.', 'Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.', 'Press the dumbbells upward until your arms are fully extended.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/5vfAI0I.gif'),
('01a0baa8-424b-7cd5-83b5-6b9d1f5072e2', 'cable lying fly', 'cable-lying-fly', 'cable lying fly using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.', 'Hold the handles with your palms facing each other and your arms extended straight above your chest.', 'Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.', 'Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/lJJ7Yq8.gif'),
('01a0baa8-424b-7cd5-83b6-f9cfa0f82cde', 'sled 45Ð²Â° calf press', 'sled-45-calf-press', 'sled 45Ð²Â° calf press using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the sled machine to a 45-degree angle.', 'Place your feet on the sled platform with your toes pointing forward.', 'Push the sled platform away from you by extending your ankles and calves.', 'Pause for a moment at the top, then slowly lower the sled platform back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/qCNVnaU.gif'),
('01a0baa8-424b-7cd5-83b7-5893810e396a', 'cable lateral pulldown (with rope attachment)', 'cable-lateral-pulldown-with-rope-attachment', 'cable lateral pulldown (with rope attachment) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope attachment to the cable machine at a high position.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the rope with an overhand grip, palms facing each other.', 'Keep your back straight and lean slightly back.', 'Pull the rope down towards your sides, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement.', 'Slowly release the tension and allow the rope to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/CuaWCmC.gif'),
('01a0baa8-424b-7cd5-83b8-b02d5e865550', 'seated piriformis stretch', 'seated-piriformis-stretch', 'seated piriformis stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the ground with your legs extended in front of you.', 'Bend your right knee and place your right foot on the outside of your left knee.', 'Place your left elbow on the outside of your right knee and gently twist your torso to the right.', 'Hold the stretch for 20-30 seconds, then switch sides and repeat.'], 'exercises/QY39eBr.gif'),
('01a0baa8-424b-7cd5-83b9-c6da3a1475c5', 'sit-up with arms on chest', 'sit-up-with-arms-on-chest', 'sit-up with arms on chest using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Cross your arms over your chest.', 'Engaging your abs, lift your upper body off the ground towards your knees.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/6ZCiYWQ.gif'),
('01a0baa8-424b-7cd5-83ba-040dc841082b', 'dumbbell incline inner biceps curl', 'dumbbell-incline-inner-biceps-curl', 'dumbbell incline inner biceps curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in each hand, palms facing each other.', 'Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/LCtQPn8.gif'),
('01a0baa8-424b-7cd5-83bb-163499b9a920', 'dumbbell bench seated press', 'dumbbell-bench-seated-press', 'dumbbell bench seated press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with a dumbbell in each hand, resting on your thighs.', 'Lean back and position the dumbbells to the sides of your chest, palms facing forward.', 'Press the dumbbells upward until your arms are fully extended.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/3d7wHyd.gif'),
('01a0baa8-424b-7cd5-83bc-c2dfabd30ba3', 'dumbbell lying supination', 'dumbbell-lying-supination', 'dumbbell lying supination using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground.', 'Hold a dumbbell in each hand with your palms facing up and your arms fully extended.', 'Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/M2Pm3zj.gif'),
('01a0baa8-424b-7cd5-83bd-a1e652d1f0b6', 'dumbbell standing biceps curl', 'dumbbell-standing-biceps-curl', 'dumbbell standing biceps curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/3s4NnTh.gif'),
('01a0baa8-424b-7cd5-83be-92654a91f2f4', 'weighted russian twist', 'weighted-russian-twist', 'weighted russian twist using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the ground with your knees bent and your feet flat on the floor.', 'Hold a weight or medicine ball with both hands in front of your chest.', 'Lean back slightly, keeping your back straight and your core engaged.', 'Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.', 'Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/fZFZ704.gif'),
('01a0baa8-424b-7cd5-83bf-d608f4dbf415', 'dumbbell one arm french press on exercise ball', 'dumbbell-one-arm-french-press-on-exercise-ball', 'dumbbell one arm french press on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.', 'Extend your arm straight up towards the ceiling, keeping your elbow stationary.', 'Slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/ziFKQXP.gif'),
('01a0baa8-424b-7cd5-83c0-e3be61b0deed', 'lever shrug', 'lever-shrug', 'lever shrug using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the leverage machine with your back against the pad.', 'Grasp the handles with an overhand grip and keep your arms straight.', 'Keeping your back straight, lift your shoulders up towards your ears as high as possible.', 'Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ZZKbeMw.gif'),
('01a0baa8-424b-7cd5-83c1-bf9503d84e86', 'twin handle parallel grip lat pulldown', 'twin-handle-parallel-grip-lat-pulldown', 'twin handle parallel grip lat pulldown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself facing the cable machine.', 'Grasp the handles with an overhand grip, hands shoulder-width apart.', 'Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.', 'Lean back slightly and keep your chest up, maintaining a neutral spine.', 'Pull the handles down towards your upper chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, feeling the contraction in your lats.', 'Slowly release the handles and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/rkg41Fb.gif'),
('01a0baa8-424b-7cd5-83c2-c8c92833e375', 'quarter sit-up', 'quarter-sit-up', 'quarter sit-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/enxnJcM.gif'),
('01a0baa8-424b-7cd5-83c3-049623cf0598', 'twist hip lift', 'twist-hip-lift', 'twist hip lift using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your back with your knees bent and feet flat on the ground.', 'Place your hands by your sides for support.', 'Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.', 'While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.', 'Return to the starting position and repeat the twist to the left side.', 'Continue alternating twists for the desired number of repetitions.'], 'exercises/AX1kB0o.gif'),
('01a0baa8-424b-7cd5-83c4-a3007353282f', 'weighted three bench dips', 'weighted-three-bench-dips', 'weighted three bench dips using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.', 'Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.', 'Lower your body by bending your elbows, keeping your back close to the bench.', 'Pause for a moment at the bottom, then push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/gtO1ErP.gif'),
('01a0baa8-424b-7cd5-83c5-ef9130cc8317', 'cable rope crossover seated row', 'cable-rope-crossover-seated-row', 'cable rope crossover seated row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.', 'Grasp the cable ropes with an overhand grip, palms facing each other.', 'Lean back slightly, keeping your back straight and your core engaged.', 'Pull the cable ropes towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/UFGF6gk.gif'),
('01a0baa8-424b-7cd5-83c6-335e071ff0ac', 'sled 45Ð²Â° leg press (back pov)', 'sled-45-leg-press-back-pov', 'sled 45Ð²Â° leg press (back pov) using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat of the sled machine so that your knees are at a 45-degree angle.', 'Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.', 'Grip the handles on the sides of the seat for stability.', 'Push the footplate away from your body by extending your legs, keeping your heels on the footplate.', 'Pause for a moment at the fully extended position.', 'Slowly bend your knees and lower the footplate back towards your body, controlling the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/yn2lLSI.gif'),
('01a0baa8-424b-7cd5-83c7-ecacbfe63f78', 'dumbbell incline one arm fly', 'dumbbell-incline-one-arm-fly', 'dumbbell incline one arm fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the incline bench to a 30-45 degree angle.', 'Sit on the bench with a dumbbell in one hand, resting it on your thigh.', 'Lie back on the bench, keeping your feet flat on the ground.', 'Hold the dumbbell with your arm extended straight up over your chest.', 'Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.', 'Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/Gw2HFvW.gif'),
('01a0baa8-424b-7cd5-83c8-5f5b197de6de', 'resistance band seated chest press', 'resistance-band-seated-chest-press', 'resistance band seated chest press using resistance band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a chair or bench with your back straight and feet flat on the ground.', 'Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.', 'Extend your arms forward, pushing the resistance band away from your chest.', 'Pause for a moment at the end of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/4x5Okof.gif'),
('01a0baa8-424b-7cd5-83c9-863d23dc161e', 'weighted straight bar dip', 'weighted-straight-bar-dip', 'weighted straight bar dip using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Position yourself between parallel bars with your arms fully extended and your body straight.', 'Lower your body by bending your elbows until your upper arms are parallel to the ground.', 'Pause for a moment, then push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/Ff18ItA.gif'),
('01a0baa8-424b-7cd5-83ca-1911250a533a', 'bodyweight standing one arm row (with towel)', 'bodyweight-standing-one-arm-row-with-towel', 'bodyweight standing one arm row (with towel) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.', 'Bend forward at the hips, keeping your back straight and your core engaged.', 'Pull the towel towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the towel back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/O4oIqQD.gif'),
('01a0baa8-424b-7cd5-83cb-f3e43d60aead', 'smith seated wrist curl', 'smith-seated-wrist-curl', 'smith seated wrist curl using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench in front of a Smith machine with your feet flat on the ground.', 'Grasp the barbell with an underhand grip, hands shoulder-width apart.', 'Rest your forearms on your thighs, allowing your wrists to hang off.', 'Slowly curl your wrists upward, bringing the barbell towards your forearms.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/B6dAO1t.gif'),
('01a0baa8-424b-7cd5-83cc-430cfaffa3f3', 'cable incline triceps extension', 'cable-incline-triceps-extension', 'cable incline triceps extension using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine to a low pulley position.', 'Attach a straight bar to the cable.', 'Stand facing away from the machine with your feet shoulder-width apart.', 'Grasp the bar with an overhand grip and extend your arms straight overhead.', 'Lean forward slightly, keeping your back straight and core engaged.', 'Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.', 'Pause for a moment, then extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Hx1WC8I.gif'),
('01a0baa8-424b-7cd5-83cd-639e82e7788f', 'dumbbell one arm lateral raise', 'dumbbell-one-arm-lateral-raise', 'dumbbell one arm lateral raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.', 'Keep your back straight and your core engaged throughout the exercise.', 'Raise the dumbbell to the side, keeping your arm straight and your palm facing down.', 'Continue lifting until your arm is parallel to the ground.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/n5cWCsI.gif'),
('01a0baa8-424b-7cd5-83ce-aa97ebee4a9c', 'dumbbell lying rear delt row', 'dumbbell-lying-rear-delt-row', 'dumbbell lying rear delt row using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.', 'Extend your arms straight down towards the floor, keeping a slight bend in your elbows.', 'Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/XUUD0Fs.gif'),
('01a0baa8-424b-7cd5-83cf-483443f09e83', 'cable incline bench row', 'cable-incline-bench-row', 'cable incline bench row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.', 'Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.', 'Grasp the cable handle with an overhand grip and extend your arms fully in front of you.', 'Lean forward from your hips while keeping your back straight and your core engaged.', 'Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.', 'Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/yaMIo4D.gif'),
('01a0baa8-424b-7cd5-83d0-581780e33a9b', 'bodyweight squatting row', 'bodyweight-squatting-row', 'bodyweight squatting row using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.', 'Lower your body into a squat position, keeping your back straight and your knees behind your toes.', 'From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/3xK09Sk.gif'),
('01a0baa8-424b-7cd5-83d1-ef58c459ed9d', 'dumbbell one arm concentration curl (on stability ball)', 'dumbbell-one-arm-concentration-curl-on-stability-ball', 'dumbbell one arm concentration curl (on stability ball) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.', 'Rest your elbow on the inside of your thigh, just above the knee.', 'Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.', 'Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms and repeat.'], 'exercises/k5IpyHg.gif'),
('01a0baa8-424b-7cd5-83d2-e6603d4d8d3d', 'smith bent over row', 'smith-bent-over-row', 'smith bent over row using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up the smith machine with the bar at hip height.', 'Stand facing the bar with your feet shoulder-width apart.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.', 'Pull the bar towards your lower chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the bar back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ZX9UZmj.gif'),
('01a0baa8-424b-7cd5-83d3-d4285714ea30', 'barbell front squat', 'barbell-front-squat', 'barbell front squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart, toes slightly turned out.', 'Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.', 'Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.', 'Lower until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/zG0zs85.gif'),
('01a0baa8-424b-7cd5-83d4-5b26558cd8d9', 'side-to-side toe touch (male)', 'side-to-side-toe-touch-male', 'side-to-side toe touch (male) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your arms extended to the sides.', 'Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.', 'Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.', 'Repeat the side-to-side bending motion for the desired number of repetitions.'], 'exercises/WCAvOfC.gif'),
('01a0baa8-424b-7cd5-83d5-9b0cbf3f95f6', 'cable cross-over revers fly', 'cable-cross-over-revers-fly', 'cable cross-over revers fly using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.', 'Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.', 'Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.', 'With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.', 'Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/aqvSOQE.gif'),
('01a0baa8-424b-7cd5-83d6-4d9343309776', 'cable decline seated wide-grip row', 'cable-decline-seated-wide-grip-row', 'cable decline seated wide-grip row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.', 'Grasp the cable attachment with a wide overhand grip, palms facing down.', 'Lean back slightly, keeping your back straight and your core engaged.', 'Pull the cable towards your lower chest, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/kesXOpB.gif'),
('01a0baa8-424b-7cd5-83d7-8b85ef5c3d4c', 'assisted chest dip (kneeling)', 'assisted-chest-dip-kneeling', 'assisted chest dip (kneeling) using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the machine to your desired height and secure your knees on the pad.', 'Grasp the handles with your palms facing down and your arms fully extended.', 'Lower your body by bending your elbows until your upper arms are parallel to the floor.', 'Pause for a moment, then push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/PAgTVaK.gif'),
('01a0baa8-424b-7cd5-83d8-5a2b2045a4ef', 'bodyweight kneeling triceps extension', 'bodyweight-kneeling-triceps-extension', 'bodyweight kneeling triceps extension using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Kneel down on the ground with your knees hip-width apart.', 'Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.', 'Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.', 'Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.', 'Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/s0HKO2I.gif'),
('01a0baa8-424b-7cd5-83d9-2c8320efac7f', 'scapular pull-up', 'scapular-pull-up', 'scapular pull-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.', 'Retract your shoulder blades by pulling them down and back.', 'Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/uTBt1HV.gif'),
('01a0baa8-424b-7cd5-83da-38470f0ae567', 'assisted triceps dip (kneeling)', 'assisted-triceps-dip-kneeling', 'assisted triceps dip (kneeling) using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the machine to your desired weight and height.', 'Kneel down on the pad facing the machine, with your hands gripping the handles.', 'Lower your body by bending your elbows, keeping your back straight and close to the machine.', 'Pause for a moment at the bottom, then push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/J60bN17.gif'),
('01a0baa8-424b-7cd5-83db-865dde6aeb1c', 'dumbbell one arm snatch', 'dumbbell-one-arm-snatch', 'dumbbell one arm snatch using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.', 'Lower the dumbbell towards the ground, keeping it close to your body.', 'Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.', 'As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.', 'Catch the dumbbell overhead with a slight bend in your knees and hips.', 'Lower the dumbbell back down to the starting position in a controlled manner.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/6pTkI99.gif'),
('01a0baa8-424b-7cd5-83dc-d26fbf9a0625', 'posterior tibialis stretch', 'posterior-tibialis-stretch', 'posterior tibialis stretch using rope.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the ground with your legs extended in front of you.', 'Loop the rope around the ball of your foot and hold the ends of the rope with your hands.', 'Gently pull the rope towards you, flexing your foot and stretching your calf muscles.', 'Hold the stretch for 20-30 seconds.', 'Release the tension on the rope and relax your foot.', 'Repeat the stretch on the other leg.'], 'exercises/DEEqoI2.gif'),
('01a0baa8-424b-7cd5-83dd-69d0d768e33f', 'side plank hip adduction', 'side-plank-hip-adduction', 'side plank hip adduction using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying on your side with your legs extended and stacked on top of each other.', 'Prop yourself up on your forearm, keeping your elbow directly below your shoulder.', 'Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.', 'While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.', 'Slowly lower your leg back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/VO2qeJg.gif'),
('01a0baa8-424b-7cd5-83de-23630fcccea1', 'medicine ball chest push from 3 point stance', 'medicine-ball-chest-push-from-3-point-stance', 'medicine ball chest push from 3 point stance using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.', 'Extend your legs and position your body in a straight line.', 'Lower your chest towards the ground while keeping your back straight.', 'Push the medicine ball away from your body, extending your arm fully.', 'Return to the starting position and repeat for the desired number of repetitions.'], 'exercises/dCJnuVq.gif'),
('01a0baa8-424b-7cd5-83df-958957500566', 'medicine ball chest push multiple response', 'medicine-ball-chest-push-multiple-response', 'medicine ball chest push multiple response using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a medicine ball at chest level.', 'Extend your arms forward, pushing the medicine ball away from your chest.', 'Pause for a moment, then slowly bring the medicine ball back to your chest.', 'Repeat for the desired number of repetitions.'], 'exercises/7aolH9D.gif'),
('01a0baa8-424b-7cd5-83e0-4c194d2668c3', 'band alternating v-up', 'band-alternating-v-up', 'band alternating v-up using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs straight and your arms extended overhead, holding the band.', 'Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.', 'As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.', 'Repeat the movement, alternating the position of your legs with each repetition.', 'Continue for the desired number of repetitions.'], 'exercises/ztAa1RK.gif'),
('01a0baa8-424b-7cd5-83e1-54547fe93be7', 'prone twist on stability ball', 'prone-twist-on-stability-ball', 'prone twist on stability ball using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.', 'Place your hands behind your head or cross them over your chest.', 'Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.', 'Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.', 'Pause for a moment, then return to the starting position.', 'Repeat the rotation to the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/1IG6gVF.gif'),
('01a0baa8-424b-7cd5-83e2-b207652e9cd7', 'cable shoulder press', 'cable-shoulder-press', 'cable shoulder press using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine so that the handles are at shoulder height.', 'Stand facing away from the machine with your feet shoulder-width apart.', 'Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.', 'Press the handles upwards until your arms are fully extended overhead.', 'Pause for a moment at the top, then slowly lower the handles back down to shoulder level.', 'Repeat for the desired number of repetitions.'], 'exercises/PzQanLE.gif'),
('01a0baa8-424b-7cd5-83e3-56c6b8c26015', 'dumbbell over bench neutral wrist curl', 'dumbbell-over-bench-neutral-wrist-curl', 'dumbbell over bench neutral wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.', 'Rest your forearms on the bench, allowing your wrists to hang off the edge.', 'Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/BKa8dmT.gif'),
('01a0baa8-424b-7cd5-83e4-33d8678de78f', 'dumbbell standing alternate hammer curl and press', 'dumbbell-standing-alternate-hammer-curl-and-press', 'dumbbell standing alternate hammer curl and press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your body.', 'Keep your elbows close to your torso and your back straight.', 'Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.', 'Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat the curl with your left hand.', 'After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.', 'Extend your arm fully and hold for a moment at the top.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat the press with your left hand.', 'Continue alternating between curls and presses for the desired number of repetitions.'], 'exercises/LeaZOIz.gif'),
('01a0baa8-424b-7cd5-83e5-11d487ee51a9', 'cable one arm straight back high row (kneeling)', 'cable-one-arm-straight-back-high-row-kneeling', 'cable one arm straight back high row (kneeling) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a handle to a cable machine at waist height.', 'Kneel down facing the cable machine and grab the handle with one hand.', 'Keep your back straight and your core engaged.', 'Pull the handle towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement.', 'Slowly release the handle back to the starting position.', 'Repeat for the desired number of repetitions.', 'Switch sides and repeat the exercise with the other arm.'], 'exercises/WrYPP2g.gif'),
('01a0baa8-424b-7cd5-83e6-3a876fd44988', 'wide grip rear pull-up', 'wide-grip-rear-pull-up', 'wide grip rear pull-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.', 'Hang from the bar with your arms fully extended and your body straight.', 'Engage your back muscles and pull your body up towards the bar, leading with your chest.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/OYFhXVD.gif'),
('01a0baa8-424b-7cd5-83e7-5afcc62c71bf', 'barbell standing concentration curl', 'barbell-standing-concentration-curl', 'barbell standing concentration curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.', 'Rest your opposite hand on your thigh for support.', 'Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.', 'Pause for a moment at the top, squeezing your biceps.', 'Inhale and slowly lower the weight back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/vsMcDi9.gif'),
('01a0baa8-424b-7cd5-83e8-3c0a0d30eec2', 'all fours squad stretch', 'all-fours-squad-stretch', 'all fours squad stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Start on all fours with your hands directly under your shoulders and your knees directly under your hips.', 'Extend one leg straight back, keeping your knee bent and your foot flexed.', 'Slowly lower your hips towards the ground, feeling a stretch in your quads.', 'Hold this position for 20-30 seconds.', 'Switch legs and repeat the stretch on the other side.'], 'exercises/qBcKorM.gif'),
('01a0baa8-424b-7cd5-83e9-98e66917d63c', 'dumbbell seated biceps curl (on stability ball)', 'dumbbell-seated-biceps-curl-on-stability-ball', 'dumbbell seated biceps curl (on stability ball) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a stability ball with your feet flat on the ground and your back straight.', 'Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.', 'Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.', 'Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/WgJnBH5.gif'),
('01a0baa8-424b-7cd5-83ea-15191766d943', 'barbell decline pullover', 'barbell-decline-pullover', 'barbell decline pullover using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie down on a decline bench with your head lower than your hips and your feet secured.', 'Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.', 'Extend your arms above your chest, keeping a slight bend in your elbows.', 'Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.', 'Pause for a moment, then return the barbell to the starting position by reversing the motion.', 'Repeat for the desired number of repetitions.'], 'exercises/9sgNE2O.gif'),
('01a0baa8-424b-7cd5-83eb-7d9899b9729e', 'elbow lift - reverse push-up', 'elbow-lift---reverse-push-up', 'elbow lift - reverse push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.', 'Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.', 'Pause at the top for a moment, squeezing your upper back muscles.', 'Slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/wbUYILZ.gif'),
('01a0baa8-424b-7cd5-83ec-800ee6ba6538', 'dumbbell step-up', 'dumbbell-step-up', 'dumbbell step-up using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.', 'Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.', 'Push through your right heel and lift your body up onto the bench or step, straightening your right leg.', 'Bring your left foot up onto the bench or step, standing fully upright.', 'Step back down with your left foot, followed by your right foot, returning to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/aXtJhlg.gif'),
('01a0baa8-424b-7cd5-83ed-5ce24f261a81', 'dumbbell twisting bench press', 'dumbbell-twisting-bench-press', 'dumbbell twisting bench press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Hold a dumbbell in each hand with an overhand grip, palms facing away from you.', 'Extend your arms straight up over your chest, keeping a slight bend in your elbows.', 'Lower the dumbbells down towards your chest, keeping your elbows close to your body.', 'As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.', 'Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.', 'As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.', 'Repeat for the desired number of repetitions.'], 'exercises/z6TAHoT.gif'),
('01a0baa8-424b-7cd5-83ee-483fc7af7bc4', 'barbell decline wide-grip pullover', 'barbell-decline-wide-grip-pullover', 'barbell decline wide-grip pullover using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with your head lower than your hips and your feet secured.', 'Hold a barbell with a wide grip and extend your arms straight above your chest.', 'Lower the barbell behind your head in a controlled manner, keeping your arms straight.', 'Pause for a moment, then raise the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Hj4FOCd.gif'),
('01a0baa8-424b-7cd5-83ef-e70a5b5659bd', 'band lying straight leg raise', 'band-lying-straight-leg-raise', 'band lying straight leg raise using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs straight and your feet together.', 'Place the band around the arches of your feet and hold the ends of the band with your hands.', 'Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/bbLR7fB.gif'),
('01a0baa8-424b-7cd5-83f0-f8f33a39bd6a', 'run (equipment)', 'run-equipment', 'run (equipment) using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Start by standing upright with your feet hip-width apart.', 'Engage your core and keep your upper body relaxed.', 'Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.', 'Maintain a steady pace and continue jogging for the desired duration or distance.', 'Remember to breathe deeply and maintain good posture throughout the exercise.'], 'exercises/y5p0H8a.gif'),
('01a0baa8-424b-7cd5-83f1-3f01adc46472', 'oblique crunch v. 2', 'oblique-crunch-v-2', 'oblique crunch v. 2 using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head or cross them over your chest.', 'Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.', 'Pause for a moment, then lower your shoulder blades back down to the starting position.', 'Repeat on the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/cJgSTmh.gif'),
('01a0baa8-424b-7cd5-83f2-53d9b26d5947', 'cable overhead curl', 'cable-overhead-curl', 'cable overhead curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a high pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the bar with an underhand grip, hands shoulder-width apart.', 'Keep your elbows close to your sides and your upper arms stationary.', 'Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.', 'Pause for a moment at the bottom of the movement, squeezing your biceps.', 'Inhale and slowly return the bar to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/wDUqY2u.gif'),
('01a0baa8-424b-7cd5-83f3-67d86a69c923', 'dumbbell lying one arm rear lateral raise', 'dumbbell-lying-one-arm-rear-lateral-raise', 'dumbbell lying one arm rear lateral raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.', 'Keep your arm straight and lift the dumbbell out to the side, away from your body.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/KwFGiEP.gif'),
('01a0baa8-424b-7cd5-83f4-d7666a4e6f6c', 'smith reverse grip bent over row', 'smith-reverse-grip-bent-over-row', 'smith reverse grip bent over row using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up the smith machine with the bar at hip height.', 'Stand facing the bar with your feet shoulder-width apart.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Grasp the bar with an underhand grip, hands shoulder-width apart.', 'Pull the bar towards your lower chest, squeezing your shoulder blades together.', 'Pause for a moment at the top, then slowly lower the bar back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/aaxA3cm.gif'),
('01a0baa8-424b-7cd5-83f5-c62b68feb3cc', 'dumbbell lying pullover on exercise ball', 'dumbbell-lying-pullover-on-exercise-ball', 'dumbbell lying pullover on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball and roll forward until your upper back is resting on the ball.', 'Hold a dumbbell with both hands and extend your arms straight up over your chest.', 'Slowly lower the dumbbell behind your head while keeping your arms straight.', 'Pause for a moment, then raise the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/iK59oEA.gif'),
('01a0baa8-424b-7cd5-83f6-ef60ab4127c7', 'barbell incline close grip bench press', 'barbell-incline-close-grip-bench-press', 'barbell incline close grip bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set up an incline bench at a 45-degree angle.', 'Lie down on the bench with your feet flat on the ground.', 'Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.', 'Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.', 'Pause for a moment when the barbell touches your chest.', 'Push the barbell back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/gx7s7uF.gif'),
('01a0baa8-424b-7cd5-83f7-941b58ea63ef', 'dumbbell burpee', 'dumbbell-burpee', 'dumbbell burpee using dumbbell.', 'CARDIO', 'INTERMEDIATE', ARRAY['Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand.', 'Lower your body into a squat position, placing the dumbbells on the ground in front of you.', 'Kick your feet back into a push-up position, keeping your body in a straight line.', 'Perform a push-up, bending your elbows and lowering your chest towards the ground.', 'Jump your feet back towards your hands, landing in a squat position.', 'Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders.', 'Press the dumbbells overhead, fully extending your arms.', 'Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions.'], 'exercises/0JtKWum.gif'),
('01a0baa8-424b-7cd5-83f8-60337597c107', 'dumbbell seated bent arm lateral raise', 'dumbbell-seated-bent-arm-lateral-raise', 'dumbbell seated bent arm lateral raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.', 'Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/JzQbv7J.gif'),
('01a0baa8-424b-7cd5-83f9-5cb7404f687e', 'dumbbell squat', 'dumbbell-squat', 'dumbbell squat using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.', 'Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.', 'Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/HsvHqgf.gif'),
('01a0baa8-424b-7cd5-83fa-02c0e9d160ee', 'smith behind neck press', 'smith-behind-neck-press', 'smith behind neck press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height of the smith machine so that the bar is at shoulder level.', 'Stand with your feet shoulder-width apart and your knees slightly bent.', 'Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.', 'Lift the bar off the rack and step back, maintaining a stable stance.', 'Lower the bar down to the back of your neck, keeping your elbows pointing forward.', 'Press the bar up overhead until your arms are fully extended.', 'Pause for a moment at the top, then slowly lower the bar back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Gpn4ADc.gif'),
('01a0baa8-424b-7cd5-83fb-9679e1242940', 'plyo push up', 'plyo-push-up', 'plyo push up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands slightly wider than shoulder-width apart.', 'Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.', 'Push explosively off the ground, using your chest muscles to propel your upper body off the ground.', 'Land softly with your hands back in the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Snj1wSv.gif'),
('01a0baa8-424b-7cd5-83fc-0297af774010', 'cable supine reverse fly', 'cable-supine-reverse-fly', 'cable supine reverse fly using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.', 'Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.', 'Keeping your arms straight, raise them out to the sides until they are parallel to the floor.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/PQcUlDi.gif'),
('01a0baa8-424b-7cd5-83fd-c2c21171e82d', 'barbell zercher squat', 'barbell-zercher-squat', 'barbell zercher squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and toes slightly turned out.', 'Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.', 'Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.', 'Keep your knees in line with your toes and your weight in your heels.', 'Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/LSTChY9.gif'),
('01a0baa8-424b-7cd5-83fe-7db648c5590f', 'weighted squat', 'weighted-squat', 'weighted squat using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes pointing slightly outward.', 'Hold a weight in front of your chest or on your shoulders.', 'Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.', 'Lower until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Push through your heels to stand back up, squeezing your glutes at the top.', 'Repeat for the desired number of repetitions.'], 'exercises/JZuApnB.gif'),
('01a0baa8-424b-7cd5-83ff-33d2d55551e4', 'dumbbell reverse preacher curl', 'dumbbell-reverse-preacher-curl', 'dumbbell reverse preacher curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.', 'Hold a dumbbell in each hand with an underhand grip, palms facing up.', 'Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.', 'Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/O8Aq69u.gif'),
('01a0baa8-424b-7cd5-8400-d35acdf7d719', 'medicine ball chest pass', 'medicine-ball-chest-pass', 'medicine ball chest pass using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding the medicine ball at chest level.', 'Extend your arms forward, pushing the medicine ball away from your chest with force.', 'As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.', 'Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.', 'Continue for the desired number of repetitions.'], 'exercises/aDoFKrE.gif'),
('01a0baa8-424b-7cd5-8401-89468e66dc34', 'barbell alternate biceps curl', 'barbell-alternate-biceps-curl', 'barbell alternate biceps curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.', 'Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.', 'Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale as you slowly begin to lower the barbells back to the starting position.', 'Repeat for the desired number of repetitions, alternating arms.'], 'exercises/Yza7XrQ.gif'),
('01a0baa8-424b-7cd5-8402-c31dc39c5682', 'barbell palms down wrist curl over a bench', 'barbell-palms-down-wrist-curl-over-a-bench', 'barbell palms down wrist curl over a bench using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.', 'Hold a barbell with an overhand grip, hands shoulder-width apart.', 'Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.', 'Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.', 'Repeat for the desired number of repetitions.'], 'exercises/yzYH9pI.gif'),
('01a0baa8-424b-7cd5-8403-76024fa31d93', 'squat to overhead reach with twist', 'squat-to-overhead-reach-with-twist', 'squat to overhead reach with twist using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and toes slightly turned out.', 'Lower your body into a squat position by bending your knees and pushing your hips back.', 'As you come up from the squat, raise your arms overhead and twist your torso to one side.', 'Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.', 'Continue alternating sides with each squat repetition.'], 'exercises/5BZHW9s.gif'),
('01a0baa8-424b-7cd5-8404-64b921080b80', 'dumbbell over bench one arm neutral wrist curl', 'dumbbell-over-bench-one-arm-neutral-wrist-curl', 'dumbbell over bench one arm neutral wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.', 'Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/IvV6C9M.gif'),
('01a0baa8-424b-7cd5-8405-a911f22e055e', 'dumbbell raise', 'dumbbell-raise', 'dumbbell raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.', 'Keep your back straight and engage your core.', 'Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.', 'Pause for a moment at the top, then slowly lower your arms back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/c9MnDRp.gif'),
('01a0baa8-424b-7cd5-8406-461e2dbf219d', 'dumbbell incline shrug', 'dumbbell-incline-shrug', 'dumbbell incline shrug using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.', 'Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.', 'Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.', 'Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/JymLInS.gif'),
('01a0baa8-424b-7cd5-8407-7fc2a47ddfcc', 'dumbbell standing concentration curl', 'dumbbell-standing-concentration-curl', 'dumbbell standing concentration curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.', 'Place your opposite hand on your thigh for support.', 'Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.', 'Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/7inpWch.gif'),
('01a0baa8-424b-7cd5-8408-df2471cf12c2', 'barbell seated good morning', 'barbell-seated-good-morning', 'barbell seated good morning using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.', 'Keep your back straight and your chest up.', 'Slowly hinge forward at the hips, lowering your torso towards the ground.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/d960PgE.gif'),
('01a0baa8-424b-7cd5-8409-ac4ca183de53', 'dumbbell straight arm pullover', 'dumbbell-straight-arm-pullover', 'dumbbell straight arm pullover using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your head at one end and your feet planted firmly on the ground.', 'Hold a dumbbell with both hands and extend your arms straight above your chest.', 'Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.', 'Pause for a moment, then raise the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/i8BdLTK.gif'),
('01a0baa8-424b-7cd5-840a-f0f7ce13b857', 'smith standing back wrist curl', 'smith-standing-back-wrist-curl', 'smith standing back wrist curl using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing the smith machine with your feet shoulder-width apart.', 'Grasp the barbell with an overhand grip, hands shoulder-width apart.', 'Keep your back straight and your elbows close to your body.', 'Slowly curl your wrists upwards, bringing the barbell towards your body.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/hfmQ0Tz.gif'),
('01a0baa8-424b-7cd5-840b-249ed962cc86', 'barbell reverse preacher curl', 'barbell-reverse-preacher-curl', 'barbell reverse preacher curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.', 'Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.', 'Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/4LIG9xr.gif'),
('01a0baa8-424b-7cd5-840c-6bbe751d7b45', 'push-up (wall)', 'push-up-wall', 'push-up (wall) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a wall, about arm''s length away.', 'Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.', 'Step back a few feet, keeping your body straight and your feet hip-width apart.', 'Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.', 'Push back up to the starting position, straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/LEH9jxP.gif'),
('01a0baa8-424b-7cd5-840d-1345e7b88191', 'roller hip lat stretch', 'roller-hip-lat-stretch', 'roller hip lat stretch using roller.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Start by kneeling on the ground with the roller positioned under your hips.', 'Place your hands on the roller for support.', 'Slowly roll the roller forward, extending your hips and stretching your glutes.', 'Hold the stretch for a few seconds, then roll back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/0L2KwtI.gif'),
('01a0baa8-424b-7cd5-840e-390451223cde', 'side bridge hip abduction', 'side-bridge-hip-abduction', 'side bridge hip abduction using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your side with your legs extended and stacked on top of each other.', 'Prop yourself up on your forearm, keeping your elbow directly below your shoulder.', 'Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.', 'While keeping your core engaged, lift your top leg as high as possible without rotating your hips.', 'Pause for a moment at the top, then lower your leg back down.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/WL4EmxJ.gif'),
('01a0baa8-424b-7cd5-840f-070b67e76549', 'barbell shrug', 'barbell-shrug', 'barbell shrug using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.', 'Keep your arms straight and your back straight throughout the exercise.', 'Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.', 'Hold for a moment, then slowly lower your shoulders back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/dG7tG5y.gif'),
('01a0baa8-424b-7cd5-8410-32dd781ca25d', 'barbell rollerout from bench', 'barbell-rollerout-from-bench', 'barbell rollerout from bench using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by kneeling on the floor with a barbell placed on a bench in front of you.', 'Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.', 'Continue rolling the barbell forward until your body is fully extended and your arms are overhead.', 'Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Gxg9lDc.gif'),
('01a0baa8-424b-7cd5-8411-448371c7cfc4', 'barbell single leg split squat', 'barbell-single-leg-split-squat', 'barbell single leg split squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a barbell across your upper back.', 'Take a large step forward with one leg, keeping your torso upright.', 'Lower your body by bending your front knee and hip, while keeping your back leg straight.', 'Continue lowering until your front thigh is parallel to the ground.', 'Pause for a moment, then push through your front heel to return to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/gGNQmVt.gif'),
('01a0baa8-424b-7cd5-8412-0568987bc228', 'dumbbell incline one arm hammer press', 'dumbbell-incline-one-arm-hammer-press', 'dumbbell incline one arm hammer press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an incline bench with a dumbbell in one hand, resting on your thigh.', 'Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.', 'Rotate your wrist so that your palm is facing inward, towards your body.', 'Press the dumbbell up and away from your body, extending your arm fully.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/LL1UiTX.gif'),
('01a0baa8-424b-7cd5-8413-691c0b4b2f9d', 'battling ropes', 'battling-ropes', 'battling ropes using rope.', 'CARDIO', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Hold one end of the rope in each hand, with your palms facing each other.', 'Raise your arms to shoulder height, keeping your elbows slightly bent.', 'Begin making alternating waves with the ropes by rapidly raising and lowering each arm.', 'Continue for the desired duration or number of repetitions.'], 'exercises/RJa4tCo.gif'),
('01a0baa8-424b-7cd5-8414-503abd28004f', 'roller back stretch', 'roller-back-stretch', 'roller back stretch using roller.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Start by sitting on the ground with your legs extended in front of you.', 'Place the roller perpendicular to your body, just below your glutes.', 'Slowly roll your body backwards, allowing the roller to move up your back.', 'Continue rolling until the roller reaches your upper back.', 'Pause for a moment, then slowly roll back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/isofgzg.gif'),
('01a0baa8-424b-7cd5-8415-3ca6b9912125', 'standing calves', 'standing-calves', 'standing calves using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes pointing forward.', 'Raise your heels off the ground as high as possible, standing on your toes.', 'Hold the position for a moment, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/XIHEoCG.gif'),
('01a0baa8-424c-7034-b26c-8afdfa865754', 'barbell sumo deadlift', 'barbell-sumo-deadlift', 'barbell sumo deadlift using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet wider than shoulder-width apart, toes pointing outwards.', 'Place a barbell on the ground in front of you, centered between your feet.', 'Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.', 'Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.', 'As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/KgI0tqW.gif'),
('01a0baa8-424c-7034-b26d-6e9e9d3c1ee0', 'dumbbell side plank with rear fly', 'dumbbell-side-plank-with-rear-fly', 'dumbbell side plank with rear fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by lying on your side with your legs extended and stacked on top of each other.', 'Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.', 'Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.', 'Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.', 'While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.', 'Lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/X6ytgYZ.gif'),
('01a0baa8-424c-7034-b26e-79fd598efbc5', 'dumbbell biceps curl (with arm blaster)', 'dumbbell-biceps-curl-with-arm-blaster', 'dumbbell biceps curl (with arm blaster) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing forward.', 'Keep your elbows close to your torso and your upper arms stationary.', 'Exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/nlJsbkW.gif'),
('01a0baa8-424c-7034-b26f-6f87a18a8dca', 'dumbbell standing kickback', 'dumbbell-standing-kickback', 'dumbbell standing kickback using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Extend your arms straight back, squeezing your triceps at the top of the movement.', 'Pause for a moment, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/UmpPAAe.gif'),
('01a0baa8-424c-7034-b270-0dc5af96f8e9', 'exercise ball back extension with arms extended', 'exercise-ball-back-extension-with-arms-extended', 'exercise ball back extension with arms extended using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.', 'Extend your arms straight out in front of you, with your palms facing down.', 'Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/PERjVm8.gif'),
('01a0baa8-424c-7034-b271-0c1b4947cc0f', 'weighted kneeling step with swing', 'weighted-kneeling-step-with-swing', 'weighted kneeling step with swing using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a kneeling position with your knees hip-width apart and your back straight.', 'Hold a weight in each hand, with your arms extended straight down in front of you.', 'Engage your core and swing the weights up and overhead, keeping your arms straight.', 'Lower the weights back down to the starting position and repeat for the desired number of repetitions.'], 'exercises/7uFJuXp.gif'),
('01a0baa8-424c-7034-b272-3125e1a6537a', 'dumbbell shrug', 'dumbbell-shrug', 'dumbbell shrug using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.', 'Keep your arms straight and let the dumbbells hang by your sides.', 'Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.', 'Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/NJzBsGJ.gif'),
('01a0baa8-424c-7034-b273-d059a65e0b68', 'reverse crunch', 'reverse-crunch', 'reverse crunch using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your arms extended along your sides.', 'Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.', 'Contract your abs and curl your hips off the floor, bringing your knees towards your chest.', 'Pause for a moment at the top, then slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/nCU1Ekp.gif'),
('01a0baa8-424c-7034-b274-d2edf6e3c783', 'world greatest stretch', 'world-greatest-stretch', 'world greatest stretch using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Start in a lunge position with your right foot forward and your left foot back.', 'Place your hands on the ground on either side of your right foot.', 'Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.', 'Rotate your torso to the right, reaching your right arm up towards the ceiling.', 'Hold this position for a few seconds, then return to the starting position.', 'Switch sides and repeat the stretch with your left foot forward.'], 'exercises/DFGXwZr.gif'),
('01a0baa8-424c-7034-b275-e0af9da7b542', 'deep push up', 'deep-push-up', 'deep push up using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.', 'Lower your chest towards the ground by bending your elbows, keeping them close to your body.', 'Push through your palms to extend your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vptOQ4N.gif'),
('01a0baa8-424c-7034-b276-4ef26e52000e', 'weighted pull-up', 'weighted-pull-up', 'weighted pull-up using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.', 'Hang from the bar with your arms fully extended and your body straight.', 'Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/HMzLjXx.gif'),
('01a0baa8-424c-7034-b277-b2afd31c8f9c', 'band two legs calf raise - (band under both legs) v. 2', 'band-two-legs-calf-raise---band-under-both-legs-v-2', 'band two legs calf raise - (band under both legs) v. 2 using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and place a resistance band under both feet.', 'Hold the ends of the band with your hands for stability.', 'Raise your heels off the ground as high as possible, using your calves.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/jl6uxZV.gif'),
('01a0baa8-424c-7034-b278-ea7390cd42a3', 'triceps dip (between benches)', 'triceps-dip-between-benches', 'triceps dip (between benches) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.', 'Slide your butt off the bench, supporting your weight with your hands.', 'Bend your elbows and lower your body towards the ground, keeping your back close to the bench.', 'Pause for a moment at the bottom, then push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Wgbn9qo.gif'),
('01a0baa8-424c-7034-b279-74fc8024896c', 'dumbbell one arm standing hammer curl', 'dumbbell-one-arm-standing-hammer-curl', 'dumbbell one arm standing hammer curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with a dumbbell in each hand, palms facing your torso.', 'Keep your elbows close to your torso and your upper arms stationary.', 'Exhale and curl the weights while contracting your biceps.', 'Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly begin to lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/2sQGZ5b.gif'),
('01a0baa8-424c-7034-b27a-d6dbe8eb0c63', 'sled 45Ð²Â° leg wide press', 'sled-45-leg-wide-press', 'sled 45Ð²Â° leg wide press using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the sled machine to a 45-degree angle.', 'Sit on the sled machine with your back against the pad and your feet on the foot platform.', 'Position your feet wider than shoulder-width apart.', 'Push against the foot platform to extend your legs and straighten your knees.', 'Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/tj41Nu6.gif'),
('01a0baa8-424c-7034-b27b-268e3e5b46ac', 'cable rope one arm hammer preacher curl', 'cable-rope-one-arm-hammer-preacher-curl', 'cable rope one arm hammer preacher curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope handle to a low pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the rope handle with an underhand grip, palms facing up.', 'Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.', 'Keep your back straight and your core engaged throughout the exercise.', 'Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.', 'Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/4hATdoB.gif'),
('01a0baa8-424c-7034-b27c-204fca35e9bd', 'cable squatting curl', 'cable-squatting-curl', 'cable squatting curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a cable handle to the lowest setting on a cable machine.', 'Stand facing the machine with your feet shoulder-width apart.', 'Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.', 'Lower your body into a squat position, keeping your back straight and knees behind your toes.', 'As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.', 'Pause for a moment at the top of the curl, squeezing your biceps.', 'Slowly lower the cable handle back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/3XFdb1Z.gif'),
('01a0baa8-424c-7034-b27d-3bc41e3548df', 'dumbbell decline hammer press', 'dumbbell-decline-hammer-press', 'dumbbell decline hammer press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with your feet secured and your head lower than your hips.', 'Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.', 'Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.', 'Press the dumbbells back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/1qrWgZ2.gif'),
('01a0baa8-424c-7034-b27e-18f64f669dca', 'calf push stretch with hands against wall', 'calf-push-stretch-with-hands-against-wall', 'calf push stretch with hands against wall using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand facing a wall with your feet hip-width apart.', 'Place your hands against the wall at shoulder height.', 'Step back with one foot, keeping your heel on the ground and your leg straight.', 'Bend your front knee slightly and lean forward, feeling a stretch in your calf.', 'Hold the stretch for 20-30 seconds.', 'Switch legs and repeat the stretch.'], 'exercises/PzNxakt.gif'),
('01a0baa8-424c-7034-b27f-668e17bf64db', 'dumbbell seated one leg calf raise - palm up', 'dumbbell-seated-one-leg-calf-raise---palm-up', 'dumbbell seated one leg calf raise - palm up using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your back straight and your feet flat on the ground.', 'Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.', 'Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.', 'Raise your heel as high as possible by pushing through the ball of your foot.', 'Pause for a moment at the top, then slowly lower your heel back down.', 'Repeat for the desired number of repetitions, then switch legs and repeat.'], 'exercises/VW88JNd.gif'),
('01a0baa8-424c-7034-b280-95d8fdfbee2c', 'negative crunch', 'negative-crunch', 'negative crunch using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/szIn2UK.gif'),
('01a0baa8-424c-7034-b281-a3eeb0b8fbe3', 'barbell lying triceps extension skull crusher', 'barbell-lying-triceps-extension-skull-crusher', 'barbell lying triceps extension skull crusher using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', 'Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.', 'Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.', 'Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/h8LFzo9.gif'),
('01a0baa8-424c-7034-b282-e71d69b0f971', 'dumbbell standing one arm curl (over incline bench)', 'dumbbell-standing-one-arm-curl-over-incline-bench', 'dumbbell standing one arm curl (over incline bench) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.', 'Place your other hand on an incline bench for support.', 'Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/BIb1tGo.gif'),
('01a0baa8-424c-7034-b283-b83fc7979714', 'cable high row (kneeling)', 'cable-high-row-kneeling', 'cable high row (kneeling) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a cable machine at chest height.', 'Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.', 'Sit back on your heels, keeping your back straight and your core engaged.', 'Pull the bar towards your upper abdomen, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ZSJNetl.gif'),
('01a0baa8-424c-7034-b284-d8458c3129ae', 'pull-up', 'pull-up', 'pull-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with your palms facing away from you and your arms fully extended.', 'Engage your core and squeeze your shoulder blades together.', 'Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.', 'Pause at the top of the movement, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/lBDjFxJ.gif'),
('01a0baa8-424c-7034-b285-3db05ae7b18f', 'roller seated shoulder flexor depresor retractor', 'roller-seated-shoulder-flexor-depresor-retractor', 'roller seated shoulder flexor depresor retractor using roller.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a flat surface with your legs extended in front of you.', 'Hold the roller with both hands, palms facing down, and place it on your thighs.', 'Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.', 'Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.', 'Repeat for the desired number of repetitions.'], 'exercises/8coXSYU.gif'),
('01a0baa8-424c-7034-b286-b60fe3b7ca62', 'dumbbell seated palms up wrist curl', 'dumbbell-seated-palms-up-wrist-curl', 'dumbbell seated palms up wrist curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.', 'Rest your forearms on your thighs, allowing your wrists to hang off the edge.', 'Slowly curl your wrists upward, squeezing your forearms at the top of the movement.', 'Pause for a moment, then lower your wrists back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/2dImyQ8.gif'),
('01a0baa8-424c-7034-b287-fb66599be88f', 'cable triceps pushdown (v-bar)', 'cable-triceps-pushdown-v-bar', 'cable triceps pushdown (v-bar) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a v-bar attachment to the cable machine at the highest setting.', 'Stand facing the cable machine with your feet shoulder-width apart.', 'Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.', 'Keep your elbows close to your sides and your upper arms stationary throughout the exercise.', 'Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.', 'Pause for a moment at the bottom of the movement, squeezing your triceps.', 'Inhale as you slowly return the v-bar to the starting position, maintaining control.', 'Repeat for the desired number of repetitions.'], 'exercises/gAwDzB3.gif'),
('01a0baa8-424c-7034-b288-e3e2f11aed36', 'barbell one arm side deadlift', 'barbell-one-arm-side-deadlift', 'barbell one arm side deadlift using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.', 'Keep your back straight and your core engaged.', 'Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.', 'Lower the barbell as far as you can while maintaining good form.', 'Pause for a moment, then slowly return to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/2DxtqHL.gif'),
('01a0baa8-424c-7034-b289-e5cfcd6266b4', 'assisted motion russian twist', 'assisted-motion-russian-twist', 'assisted motion russian twist using medicine ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the ground with your knees bent and feet flat on the floor.', 'Hold the medicine ball with both hands in front of your chest.', 'Lean back slightly, engaging your abs and keeping your back straight.', 'Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.', 'Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/r7cT9YD.gif'),
('01a0baa8-424c-7034-b28a-2a5729bc068c', 'dumbbell deadlift', 'dumbbell-deadlift', 'dumbbell deadlift using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes pointing forward.', 'Hold a dumbbell in each hand, palms facing your body, arms extended downwards.', 'Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.', 'Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/nUwVh7b.gif'),
('01a0baa8-424c-7034-b28b-0d4813717656', 'assisted lying leg raise with lateral throw down', 'assisted-lying-leg-raise-with-lateral-throw-down', 'assisted lying leg raise with lateral throw down using assisted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your legs extended and your arms by your sides.', 'Place your hands under your glutes for support.', 'Engage your abs and lift your legs off the ground, keeping them straight.', 'While keeping your legs together, lower them to one side until they are a few inches above the ground.', 'Pause for a moment, then lift your legs back to the starting position.', 'Repeat the movement to the other side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/UGhRD1A.gif'),
('01a0baa8-424c-7034-b28c-d1ce1aa71809', 'sled forward angled calf raise', 'sled-forward-angled-calf-raise', 'sled forward angled calf raise using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.', 'Place your hands on the handles or the sides of the machine for support.', 'Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.', 'Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/XDOiFns.gif'),
('01a0baa8-424c-7034-b28d-7a4f91ad6d97', 'cable overhead curl on exercise ball', 'cable-overhead-curl-on-exercise-ball', 'cable overhead curl on exercise ball using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball and hold the cable handle with an underhand grip.', 'Extend your arms fully overhead, keeping your elbows close to your ears.', 'Slowly curl the cable down towards your forehead, keeping your upper arms stationary.', 'Pause for a moment at the bottom of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ioTf098.gif'),
('01a0baa8-424c-7034-b28e-1b5105cb8d01', 'dumbbell one arm shoulder press', 'dumbbell-one-arm-shoulder-press', 'dumbbell one arm shoulder press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.', 'Press the dumbbell upward until your arm is fully extended overhead.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/84RyJf8.gif'),
('01a0baa8-424c-7034-b28f-eb0fba60999f', 'cable underhand pulldown', 'cable-underhand-pulldown', 'cable underhand pulldown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine so that the pulldown bar is at a height above your head.', 'Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.', 'Keep your back straight and lean back slightly.', 'Pull the bar down towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/xBYcQHj.gif'),
('01a0baa8-424c-7034-b290-7d5cc1326a21', 'dumbbell tricep kickback with stork stance', 'dumbbell-tricep-kickback-with-stork-stance', 'dumbbell tricep kickback with stork stance using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Bring your right elbow up to your side, keeping it bent at a 90-degree angle.', 'Extend your right arm straight back, squeezing your triceps.', 'Pause for a moment, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/wOLmCXc.gif'),
('01a0baa8-424c-7034-b291-a7fdff4b8694', 'cocoons', 'cocoons', 'cocoons using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/SLKj2pX.gif'),
('01a0baa8-424c-7034-b292-87ed3732197e', 'cable reverse wrist curl', 'cable-reverse-wrist-curl', 'cable reverse wrist curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a cable to a low pulley and sit on a bench facing the cable machine.', 'Grasp the cable handle with an overhand grip, palms facing down.', 'Rest your forearms on your thighs, with your wrists hanging off the edge.', 'Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.', 'Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/eYmsEPR.gif'),
('01a0baa8-424c-7034-b293-1eee83bb7471', 'exercise ball hug', 'exercise-ball-hug', 'exercise ball hug using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the stability ball with your feet flat on the ground and your back straight.', 'Hold the stability ball with both hands, hugging it close to your chest.', 'Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.', 'Continue leaning back until you feel a stretch in your back muscles.', 'Hold the position for a few seconds, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/d7z1Y7V.gif'),
('01a0baa8-424c-7034-b294-2d51c1b9befc', 'drop push up', 'drop-push-up', 'drop push up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands slightly wider than shoulder-width apart.', 'Lower your chest towards the ground, keeping your elbows close to your body.', 'Once your chest is just above the ground, quickly drop your knees to the ground.', 'Push yourself back up to the starting position by extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/Q497lAE.gif'),
('01a0baa8-424c-7034-b295-2ed6b16d027f', 'dumbbell decline one arm fly', 'dumbbell-decline-one-arm-fly', 'dumbbell decline one arm fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.', 'Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.', 'Rotate your wrist so that the palm of your hand is facing forward.', 'As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.', 'Exhale and use your chest muscles to bring the dumbbell back up to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/NL6YBwN.gif'),
('01a0baa8-424c-7034-b296-f2e37c2ca173', 'close grip chin-up', 'close-grip-chin-up', 'close grip chin-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.', 'Hang from the bar with your arms fully extended and your feet off the ground.', 'Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/VnfUNW7.gif'),
('01a0baa8-424c-7034-b297-5816a5df3ed6', 'narrow push-up on exercise ball', 'narrow-push-up-on-exercise-ball', 'narrow push-up on exercise ball using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.', 'Engage your core and keep your body in a straight line from head to toe.', 'Lower your chest towards the ball by bending your elbows, keeping them close to your body.', 'Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/4cWjYEN.gif'),
('01a0baa8-424c-7034-b298-d7aed203c4fa', 'dumbbell bicep curl lunge with bowling motion', 'dumbbell-bicep-curl-lunge-with-bowling-motion', 'dumbbell bicep curl lunge with bowling motion using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.', 'Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.', 'As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.', 'At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.', 'Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.', 'Repeat the lunge and curl motion, this time rotating your torso to the left.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/1VpF8db.gif'),
('01a0baa8-424c-7034-b299-9f34037f1ddd', 'resistance band leg extension', 'resistance-band-leg-extension', 'resistance band leg extension using resistance band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the resistance band to a sturdy anchor point and secure it around your ankle.', 'Stand facing the anchor point with your feet shoulder-width apart.', 'Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.', 'Pause for a moment at the top, then slowly return your leg to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/Y1MsI1l.gif'),
('01a0baa8-424c-7034-b29a-94b45ee281bb', 'dumbbell bench squat', 'dumbbell-bench-squat', 'dumbbell bench squat using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place a dumbbell on the ground in front of a bench.', 'Stand facing away from the bench with your feet shoulder-width apart.', 'Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.', 'Once your glutes touch the bench, push through your heels to stand back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/mnzcrIB.gif'),
('01a0baa8-424c-7034-b29b-0749fa1ee407', 'cable reverse one arm curl', 'cable-reverse-one-arm-curl', 'cable reverse one arm curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Grasp the cable handle with an underhand grip, palm facing down.', 'Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.', 'Pause for a moment at the top, then slowly lower your forearm back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/gVlnLIJ.gif'),
('01a0baa8-424c-7034-b29c-b172f5babd7a', 'arms overhead full sit-up (male)', 'arms-overhead-full-sit-up-male', 'arms overhead full sit-up (male) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Extend your arms overhead, keeping them straight.', 'Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/NAkmgdx.gif'),
('01a0baa8-424c-7034-b29d-664b7cebec27', 'cable decline one arm press', 'cable-decline-one-arm-press', 'cable decline one arm press using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the cable machine to a decline position.', 'Stand facing away from the machine and grab the handle with one hand.', 'Position yourself with your back against the decline bench and your arm extended straight in front of you.', 'Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.', 'Pause for a moment at the bottom, then push the handle back up to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/KHGNa16.gif'),
('01a0baa8-424c-7034-b29e-7ed15495b501', 'cable lying extension pullover (with rope attachment)', 'cable-lying-extension-pullover-with-rope-attachment', 'cable lying extension pullover (with rope attachment) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope to a cable machine and set the pulley at the highest position.', 'Lie down on a bench with your head towards the cable machine.', 'Hold the rope with both hands and extend your arms straight up above your chest.', 'Keeping your arms straight, slowly lower the rope behind your head while maintaining control.', 'Pause for a moment at the bottom, then slowly raise the rope back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Q2Eu1Ax.gif'),
('01a0baa8-424c-7034-b29f-e51d78271dff', 'cable upper chest crossovers', 'cable-upper-chest-crossovers', 'cable upper chest crossovers using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the handles to the cables at chest height.', 'Stand in the center of the cable machine with one foot slightly in front of the other.', 'Grasp the handles with your palms facing down and your arms extended out to the sides.', 'Keep a slight bend in your elbows and engage your core.', 'Pull the cables together in front of your chest, crossing them over each other.', 'Squeeze your chest muscles at the peak of the movement.', 'Slowly release the cables back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/j7XMAyn.gif'),
('01a0baa8-424c-7034-b2a0-f07503ba4e1a', 'sled calf press on leg press', 'sled-calf-press-on-leg-press', 'sled calf press on leg press using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.', 'Place your feet shoulder-width apart on the sled, with your toes pointing forward.', 'Release the safety handles and push the sled away from you by extending your knees and ankles.', 'Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.', 'Repeat for the desired number of repetitions.'], 'exercises/ykHcWme.gif'),
('01a0baa8-424c-7034-b2a1-256677b29ee5', 'barbell standing back wrist curl', 'barbell-standing-back-wrist-curl', 'barbell standing back wrist curl using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.', 'Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.', 'Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.', 'Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/2qTvJAZ.gif'),
('01a0baa8-424c-7034-b2a2-8286406b9cd2', 'lower back curl', 'lower-back-curl', 'lower back curl using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your stomach with your legs extended and your arms by your sides.', 'Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ANbbry2.gif'),
('01a0baa8-424c-7034-b2a3-9261a6bae422', 'standing archer', 'standing-archer', 'standing archer using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and your knees slightly bent.', 'Extend your arms straight out in front of you at shoulder height, parallel to the ground.', 'Rotate your torso to the right, keeping your arms extended and your back straight.', 'As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.', 'Hold the position for a moment, then return to the starting position.', 'Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/JF8AkMX.gif'),
('01a0baa8-424c-7034-b2a4-eb43874d7398', 'dumbbell seated bent over triceps extension', 'dumbbell-seated-bent-over-triceps-extension', 'dumbbell seated bent over triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.', 'Bend forward at the waist, keeping your back straight and your head up.', 'Extend your arms straight back, keeping your elbows close to your head.', 'Pause for a moment, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/4ievMJ9.gif'),
('01a0baa8-424c-7034-b2a5-a9fd6deda062', 'crunch floor', 'crunch-floor', 'crunch floor using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engage your abs and lift your shoulders off the ground, curling forward towards your knees.', 'Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/TFqbd8t.gif'),
('01a0baa8-424c-7034-b2a6-d031e828e0b7', 'barbell jump squat', 'barbell-jump-squat', 'barbell jump squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.', 'Lower your body into a squat position by bending your knees and pushing your hips back.', 'Once you reach the bottom of the squat, explode upwards by jumping off the ground.', 'As you jump, extend your hips, knees, and ankles, pushing through your toes.', 'Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions.'], 'exercises/1gFNTZV.gif'),
('01a0baa8-424c-7034-b2a7-e8f0b159690c', 'barbell decline bent arm pullover', 'barbell-decline-bent-arm-pullover', 'barbell decline bent arm pullover using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie down on a decline bench with your head lower than your hips and your feet secured.', 'Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.', 'Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.', 'Pause for a moment, then raise the barbell back to the starting position by contracting your lats.', 'Repeat for the desired number of repetitions.'], 'exercises/hMEptv0.gif'),
('01a0baa8-424c-7034-b2a8-af8da78cb2e1', 'push-up close-grip off dumbbell', 'push-up-close-grip-off-dumbbell', 'push-up close-grip off dumbbell using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands placed close together, directly under your shoulders.', 'Hold a dumbbell in each hand, resting them on the ground.', 'Lower your body towards the ground by bending your elbows, keeping them close to your sides.', 'Push through your palms to extend your arms and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/KZXAtKQ.gif'),
('01a0baa8-424c-7034-b2a9-2e1be33c880b', 'cable rear delt row (with rope)', 'cable-rear-delt-row-with-rope', 'cable rear delt row (with rope) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope handle to a low pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the rope handle with an overhand grip, palms facing each other.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/wqNPGCg.gif'),
('01a0baa8-424c-7034-b2aa-b60e549c0c42', 'band bent-over hip extension', 'band-bent-over-hip-extension', 'band bent-over hip extension using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach the band to a sturdy anchor point at ankle height.', 'Stand facing away from the anchor point with your feet shoulder-width apart.', 'Step back to create tension in the band, keeping your knees slightly bent.', 'Hinge at the hips and lean forward, maintaining a neutral spine.', 'Extend your right leg straight back, squeezing your glutes at the top.', 'Lower your right leg back down and repeat with the left leg.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/wSScovH.gif'),
('01a0baa8-424c-7034-b2ab-352a793f1523', 'dumbbell alternate biceps curl (with arm blaster)', 'dumbbell-alternate-biceps-curl-with-arm-blaster', 'dumbbell alternate biceps curl (with arm blaster) using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.', 'Place the arm blaster on your upper arms, ensuring a secure fit.', 'Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.', 'Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale and slowly lower the dumbbell back to the starting position.', 'Repeat the movement with the opposite arm.', 'Continue alternating arms for the desired number of repetitions.'], 'exercises/CfKsRbG.gif'),
('01a0baa8-424c-7034-b2ac-06f8282874f0', 'weighted decline sit-up', 'weighted-decline-sit-up', 'weighted decline sit-up using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a decline bench with your feet secured under the foot pads.', 'Place your hands behind your head or across your chest.', 'Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/EZeDVzO.gif'),
('01a0baa8-424c-7034-b2ad-6417d7641928', 'barbell deadlift', 'barbell-deadlift', 'barbell deadlift using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and the barbell on the ground in front of you.', 'Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.', 'As you stand up straight, squeeze your glutes and keep your core engaged.', 'Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.', 'Repeat for the desired number of repetitions.'], 'exercises/ila4NZS.gif'),
('01a0baa8-424c-7034-b2ae-c39609e95f20', 'dumbbell romanian deadlift', 'dumbbell-romanian-deadlift', 'dumbbell romanian deadlift using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', 'Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.', 'Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/rR0LJzx.gif'),
('01a0baa8-424c-7034-b2af-a8740d7dfa43', 'ez bar lying bent arms pullover', 'ez-bar-lying-bent-arms-pullover', 'ez bar lying bent arms pullover using ez barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your head at one end and your feet on the floor.', 'Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.', 'Extend your arms straight above your chest, keeping a slight bend in your elbows.', 'Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.', 'Pause for a moment, then return the barbell to the starting position by reversing the arc motion.', 'Repeat for the desired number of repetitions.'], 'exercises/nDK1HJ0.gif'),
('01a0baa8-424c-7034-b2b0-58d5805d6968', 'calf stretch with hands against wall', 'calf-stretch-with-hands-against-wall', 'calf stretch with hands against wall using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand facing a wall with your feet hip-width apart.', 'Place your hands against the wall at shoulder height.', 'Step your right foot back, keeping your heel on the ground and your leg straight.', 'Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.', 'Hold the stretch for 20-30 seconds.', 'Switch legs and repeat the stretch.'], 'exercises/m0tCHqc.gif'),
('01a0baa8-424c-7034-b2b1-a5e05e03a4b8', 'curtsey squat', 'curtsey-squat', 'curtsey squat using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.', 'Bend both knees as if you were curtsying, lowering your body towards the ground.', 'Keep your torso upright and your weight on your front foot.', 'Push through your front foot to return to the starting position.', 'Repeat on the other side, stepping diagonally behind and across your body with your left foot.'], 'exercises/gUjqdei.gif'),
('01a0baa8-424c-7034-b2b2-04a50f9b0124', 'cable seated wide-grip row', 'cable-seated-wide-grip-row', 'cable seated wide-grip row using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.', 'Grasp the handle with a wide overhand grip, palms facing down.', 'Keep your back straight and lean slightly forward from the hips.', 'Pull the handle towards your lower chest, squeezing your shoulder blades together.', 'Pause for a moment at the peak of the contraction.', 'Slowly release the handle back to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/qcY50ZD.gif'),
('01a0baa8-424c-7034-b2b3-b6fb4e45927a', 'cable pushdown (straight arm) v. 2', 'cable-pushdown-straight-arm-v-2', 'cable pushdown (straight arm) v. 2 using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a high pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.', 'Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.', 'Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.', 'Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.', 'Repeat for the desired number of repetitions.'], 'exercises/PskORrA.gif'),
('01a0baa8-424c-7034-b2b4-e8be8de99bb3', 'dumbbell one arm lateral raise with support', 'dumbbell-one-arm-lateral-raise-with-support', 'dumbbell one arm lateral raise with support using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.', 'Place your other hand on a stable surface, such as a bench or wall, for support.', 'Keep your back straight and engage your core.', 'Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.', 'Continue lifting until your arm is parallel to the ground.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/Yg7MJAT.gif'),
('01a0baa8-424c-7034-b2b5-f2ea005a6829', 'barbell bent over row', 'barbell-bent-over-row', 'barbell bent over row using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and knees slightly bent.', 'Bend forward at the hips while keeping your back straight and chest up.', 'Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.', 'Pause for a moment at the top, then slowly lower the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/eZyBC3j.gif'),
('01a0baa8-424c-7034-b2b6-0b477e364a1c', 'dumbbell pronate-grip triceps extension', 'dumbbell-pronate-grip-triceps-extension', 'dumbbell pronate-grip triceps extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench or chair with your back straight and feet flat on the ground.', 'Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.', 'Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.', 'Pause for a moment, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/bpJL2Qs.gif'),
('01a0baa8-424c-7034-b2b7-70b3ea2f9386', 'barbell bench front squat', 'barbell-bench-front-squat', 'barbell bench front squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.', 'Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.', 'Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.', 'Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Y7YcmIJ.gif'),
('01a0baa8-424c-7034-b2b8-3e464051d17c', 'cable shrug', 'cable-shrug', 'cable shrug using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing the cable machine with your feet shoulder-width apart.', 'Grasp the cable handles with an overhand grip and let your arms hang down in front of you.', 'Keeping your arms straight, shrug your shoulders up towards your ears.', 'Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Eg98Ft9.gif'),
('01a0baa8-424c-7034-b2b9-be90fbcd01d7', 'smith bench press', 'smith-bench-press', 'smith bench press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the height of the smith machine bar to chest level.', 'Lie flat on the bench with your feet firmly planted on the ground.', 'Grip the bar with an overhand grip slightly wider than shoulder-width apart.', 'Unrack the bar and lower it towards your chest, keeping your elbows tucked in.', 'Pause for a moment when the bar touches your chest.', 'Push the bar back up to the starting position, fully extending your arms.', 'Repeat for the desired number of repetitions.'], 'exercises/trqKQv2.gif'),
('01a0baa8-424c-7034-b2ba-61869d3111c9', 'dumbbell front raise', 'dumbbell-front-raise', 'dumbbell front raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.', 'Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.', 'Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/3eGE2JC.gif'),
('01a0baa8-424c-7034-b2bb-42b49d1359a5', 'scissor jumps (male)', 'scissor-jumps-male', 'scissor jumps (male) using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Jump off the ground and simultaneously cross your right leg in front of your left leg.', 'As you land, quickly switch legs, crossing your left leg in front of your right leg.', 'Continue alternating legs and jumping as quickly as possible.', 'Repeat for the desired number of repetitions.'], 'exercises/Eh2v5Iu.gif'),
('01a0baa8-424c-7034-b2bc-d14201b134ef', 'weighted russian twist (legs up)', 'weighted-russian-twist-legs-up', 'weighted russian twist (legs up) using weighted.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.', 'Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.', 'Lean back slightly to engage your core muscles.', 'Twist your torso to the right, bringing the weight towards the ground on your right side.', 'Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/WU9BLIs.gif'),
('01a0baa8-424c-7034-b2bd-7fe7d8160dc6', 'barbell wide bench press', 'barbell-wide-bench-press', 'barbell wide bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.', 'Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.', 'Pause for a moment when the barbell touches your chest, then push it back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/JsKq9so.gif'),
('01a0baa8-424c-7034-b2be-6135307dfb87', 'cross body crunch', 'cross-body-crunch', 'cross body crunch using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat on the other side, bringing your left elbow towards your right knee.', 'Repeat for the desired number of repetitions.'], 'exercises/rbu5UUb.gif'),
('01a0baa8-424c-7034-b2bf-01db36c14001', 'dumbbell one arm fly on exercise ball', 'dumbbell-one-arm-fly-on-exercise-ball', 'dumbbell one arm fly on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.', 'Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.', 'Extend your arm with the dumbbell straight up above your chest, palm facing inwards.', 'Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.', 'Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/Am02iPd.gif'),
('01a0baa8-424c-7034-b2c0-1cc11e7a2c02', 'smith toe raise', 'smith-toe-raise', 'smith toe raise using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.', 'Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.', 'Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.', 'Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.', 'Engage your core and keep your back straight throughout the exercise.', 'Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Y4QlY8z.gif'),
('01a0baa8-424c-7034-b2c1-6150d2722373', 'band seated hip internal rotation', 'band-seated-hip-internal-rotation', 'band seated hip internal rotation using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a chair or bench with your back straight and feet flat on the ground.', 'Place a resistance band around your thighs, just above your knees.', 'Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.', 'Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.', 'Pause for a moment at the end of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/9gbyYKk.gif'),
('01a0baa8-424c-7034-b2c2-4843057a1b7f', 'band bench press', 'band-bench-press', 'band bench press using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.', 'Extend your arms fully, pushing the bands away from your chest.', 'Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.', 'Repeat for the desired number of repetitions.'], 'exercises/khlHMqs.gif'),
('01a0baa8-424c-7034-b2c3-61f2b6d31503', 'dumbbell incline fly', 'dumbbell-incline-fly', 'dumbbell incline fly using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Set an incline bench to a 45-degree angle.', 'Sit on the bench with a dumbbell in each hand, palms facing each other.', 'Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.', 'Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.', 'Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ESOd5Pl.gif'),
('01a0baa8-424c-7034-b2c4-6cb28198dafc', 'dumbbell incline hammer press on exercise ball', 'dumbbell-incline-hammer-press-on-exercise-ball', 'dumbbell incline hammer press on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with a dumbbell in each hand, palms facing each other.', 'Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.', 'Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.', 'Press the dumbbells up and slightly inward, keeping your palms facing each other.', 'Extend your arms fully, squeezing your triceps at the top of the movement.', 'Slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/wkgnGfb.gif'),
('01a0baa8-424c-7034-b2c5-0ba06560a3fe', 'dumbbell fly on exercise ball', 'dumbbell-fly-on-exercise-ball', 'dumbbell fly on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball and hold a dumbbell in each hand.', 'Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.', 'Extend your arms straight up above your chest, palms facing each other.', 'Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.', 'Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Lt3iWnf.gif'),
('01a0baa8-424c-7034-b2c6-66bfe9fe10f3', 'cable rope incline tricep extension', 'cable-rope-incline-tricep-extension', 'cable rope incline tricep extension using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.', 'Stand facing away from the pulley with your feet shoulder-width apart.', 'Grasp the rope with an overhand grip and extend your arms straight overhead.', 'Keep your elbows close to your head and your upper arms stationary throughout the exercise.', 'Lower the rope behind your head by bending your elbows until your forearms touch your biceps.', 'Pause for a moment, then extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ZujAdR9.gif'),
('01a0baa8-424c-7034-b2c7-0007cf4d1784', 'barbell standing rocking leg calf raise', 'barbell-standing-rocking-leg-calf-raise', 'barbell standing rocking leg calf raise using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a barbell across your upper back.', 'Raise your heels off the ground as high as possible, balancing on the balls of your feet.', 'Slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/6HiHHe0.gif'),
('01a0baa8-424c-7034-b2c8-2d9152de7d05', 'rear decline bridge', 'rear-decline-bridge', 'rear decline bridge using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your back with your feet flat on the ground and your knees bent.', 'Place your arms by your sides with your palms facing down.', 'Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.', 'Hold this position for a few seconds, then slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/UpAlold.gif'),
('01a0baa8-424c-7034-b2c9-02e8de0e0087', 'cable alternate shoulder press', 'cable-alternate-shoulder-press', 'cable alternate shoulder press using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.', 'Position your hands at shoulder height, with your palms facing forward.', 'Keep your core engaged and your back straight.', 'Press one handle up and forward until your arm is fully extended.', 'Pause for a moment at the top, then slowly lower the handle back to the starting position.', 'Repeat with the other arm.', 'Alternate between arms for the desired number of repetitions.'], 'exercises/KHPZL0b.gif'),
('01a0baa8-424c-7034-b2ca-0662806aeebb', 'dumbbell one arm decline chest press', 'dumbbell-one-arm-decline-chest-press', 'dumbbell one arm decline chest press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on a decline bench with a dumbbell in one hand, resting on your chest.', 'Place your feet flat on the ground and keep your back pressed against the bench.', 'Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.', 'Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/REGM1dE.gif'),
('01a0baa8-424c-7034-b2cb-e91c03ad4e92', 'smith one leg floor calf raise', 'smith-one-leg-floor-calf-raise', 'smith one leg floor calf raise using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Position yourself on the floor under the smith machine bar, facing away from the machine.', 'Place the balls of your feet on a raised surface, such as a weight plate or block.', 'Position the smith machine bar across your lower legs, just above your ankles.', 'Hold onto the bar with your hands for stability.', 'Raise your heels off the ground by extending your ankles, lifting your body up.', 'Pause at the top of the movement, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/9GXrTE6.gif'),
('01a0baa8-424c-7034-b2cc-b27500801abd', 'barbell standing front raise over head', 'barbell-standing-front-raise-over-head', 'barbell standing front raise over head using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.', 'Keep your back straight and engage your core.', 'Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.', 'Continue lifting until the barbell is slightly above shoulder level.', 'Pause for a moment at the top, then slowly lower the barbell back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/S8mo30S.gif'),
('01a0baa8-424c-7034-b2cd-330cc260f203', 'reverse grip machine lat pulldown', 'reverse-grip-machine-lat-pulldown', 'reverse grip machine lat pulldown using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.', 'Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.', 'Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.', 'Pull the handles down towards your chest, squeezing your shoulder blades together.', 'Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ecpY0rH.gif'),
('01a0baa8-424c-7034-b2ce-6c8819dae78d', 'chest stretch with exercise ball', 'chest-stretch-with-exercise-ball', 'chest stretch with exercise ball using stability ball.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the stability ball with your feet flat on the ground and your back straight.', 'Hold the exercise ball with both hands and extend your arms straight out in front of you.', 'Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.', 'Hold the stretch for a few seconds, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ykA5tU7.gif'),
('01a0baa8-424c-7034-b2cf-767816bf2f44', 'straddle maltese', 'straddle-maltese', 'straddle maltese using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.', 'Spread your legs wide apart, forming a straddle position.', 'Engage your core and slowly lower your body until your arms are parallel to the ground.', 'Hold this position for a few seconds, then push yourself back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/HfqciZF.gif'),
('01a0baa8-424c-7034-b2d0-6dc4bdf314a7', 'cable reverse-grip pushdown', 'cable-reverse-grip-pushdown', 'cable reverse-grip pushdown using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a straight bar to a high pulley cable machine.', 'Stand facing the machine with your feet shoulder-width apart.', 'Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.', 'Keep your elbows close to your sides and your upper arms stationary throughout the exercise.', 'Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.', 'Pause for a moment, then slowly return the bar to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/VjYliFZ.gif'),
('01a0baa8-424c-7034-b2d1-f7f93a60b0c2', 'seated wide angle pose sequence', 'seated-wide-angle-pose-sequence', 'seated wide angle pose sequence using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the ground with your legs extended in a wide angle.', 'Flex your feet and engage your quadriceps.', 'Place your hands on the ground behind you for support.', 'Keeping your back straight, lean forward from your hips.', 'Continue leaning forward until you feel a stretch in your hamstrings.', 'Hold this position for a few breaths.', 'Slowly release the stretch and return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/HIgYKAB.gif'),
('01a0baa8-424c-7034-b2d2-cce921fce0b7', 'dumbbell lying single extension', 'dumbbell-lying-single-extension', 'dumbbell lying single extension using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.', 'Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.', 'Pause briefly at the bottom of the movement, then extend your arm back to the starting position.', 'Repeat for the desired number of repetitions, then switch arms.'], 'exercises/6MfS53i.gif'),
('01a0baa8-424c-7034-b2d3-a998a18bc9ef', 'barbell wide squat', 'barbell-wide-squat', 'barbell wide squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.', 'Hold the barbell across your upper back, resting it on your traps or rear delts.', 'Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.', 'Lower until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/s7HX1BY.gif'),
('01a0baa8-424c-7034-b2d4-6aebddf906e1', 'cable twist (up-down)', 'cable-twist-up-down', 'cable twist (up-down) using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, facing the cable machine.', 'Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.', 'Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.', 'Pause for a moment at the end of the rotation, then slowly return to the starting position.', 'Repeat the rotation to the opposite side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/fhZQPlV.gif'),
('01a0baa8-424c-7034-b2d5-785b40f81deb', 'smith standing behind head military press', 'smith-standing-behind-head-military-press', 'smith standing behind head military press using smith machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat height of the smith machine so that the bar is at shoulder level.', 'Stand with your feet shoulder-width apart and your knees slightly bent.', 'Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.', 'Lift the bar off the rack and step back, maintaining a stable stance.', 'Position the bar behind your head, resting on your upper traps.', 'Keep your core engaged and your chest lifted throughout the exercise.', 'Press the bar overhead by extending your arms, fully straightening them.', 'Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/ht8xDrP.gif'),
('01a0baa8-424c-7034-b2d6-7025cdb63be0', 'reverse plank with leg lift', 'reverse-plank-with-leg-lift', 'reverse plank with leg lift using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.', 'Press through your hands and lift your hips off the ground, coming into a reverse plank position.', 'Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.', 'Hold for a moment, then lower your leg back down.', 'Repeat with the other leg.', 'Continue alternating legs for the desired number of repetitions.'], 'exercises/tFToB7l.gif'),
('01a0baa8-424c-7034-b2d7-c7d378d728a0', 'dumbbell standing alternate raise', 'dumbbell-standing-alternate-raise', 'dumbbell standing alternate raise using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.', 'Keep your back straight and your core engaged.', 'Raise one dumbbell to the side, keeping your arm straight and your palm facing down.', 'Continue lifting until your arm is parallel to the ground.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat with the other arm.', 'Alternate between arms for the desired number of repetitions.'], 'exercises/SxHteRW.gif'),
('01a0baa8-424c-7034-b2d8-081f6e807168', 'backward jump', 'backward-jump', 'backward jump using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Bend your knees slightly and jump backwards, pushing off with both feet.', 'Land softly on the balls of your feet, bending your knees to absorb the impact.', 'Repeat for the desired number of repetitions.'], 'exercises/SaDOwk7.gif'),
('01a0baa8-424c-7034-b2d9-49a3ee3c5c89', 'archer push up', 'archer-push-up', 'archer push up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a push-up position with your hands slightly wider than shoulder-width apart.', 'Extend one arm straight out to the side, parallel to the ground.', 'Lower your body by bending your elbows, keeping your back straight and core engaged.', 'Push back up to the starting position.', 'Repeat on the other side, extending the opposite arm out to the side.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/A9qxk2F.gif'),
('01a0baa8-424c-7034-b2da-d51904799eac', 'barbell seated bradford rocky press', 'barbell-seated-bradford-rocky-press', 'barbell seated bradford rocky press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.', 'Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.', 'Press the barbell overhead, fully extending your arms.', 'Lower the barbell back to shoulder height and repeat for the desired number of repetitions.'], 'exercises/0dCyly0.gif'),
('01a0baa8-424c-7034-b2db-54698100555a', 'lying elbow to knee', 'lying-elbow-to-knee', 'lying elbow to knee using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.', 'At the same time, extend your right leg straight out and lift it off the ground.', 'Pause for a moment, then return to the starting position.', 'Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/AQIhRjM.gif'),
('01a0baa8-424c-7034-b2dc-3a42e7856b81', 'chin-ups (narrow parallel grip)', 'chin-ups-narrow-parallel-grip', 'chin-ups (narrow parallel grip) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.', 'Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.', 'Continue pulling until your chin is above the bar.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/G70mEAJ.gif'),
('01a0baa8-424c-7034-b2dd-0313f9b9ee73', 'semi squat jump (male)', 'semi-squat-jump-male', 'semi squat jump (male) using body weight.', 'CARDIO', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart.', 'Bend your knees and lower your body into a squat position.', 'Jump explosively, extending your hips and knees while swinging your arms for momentum.', 'Land softly on the balls of your feet and immediately go into the next repetition.', 'Repeat for the desired number of repetitions.'], 'exercises/6FMU51h.gif'),
('01a0baa8-424c-7034-b2de-77689282a7e1', 'barbell narrow stance squat', 'barbell-narrow-stance-squat', 'barbell narrow stance squat using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and toes pointing slightly outward.', 'Hold the barbell across your upper back, resting it on your traps or rear delts.', 'Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.', 'Continue lowering until your thighs are parallel to the ground or slightly below.', 'Pause for a moment, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/elhhVgj.gif'),
('01a0baa8-424c-7034-b2df-17a75896e5be', 'crunch (hands overhead)', 'crunch-hands-overhead', 'crunch (hands overhead) using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on your back with your knees bent and feet flat on the ground.', 'Extend your arms straight above your head.', 'Engaging your abs, lift your upper body off the ground, curling forward towards your knees.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/kjJ3VoQ.gif'),
('01a0baa8-424c-7034-b2e0-d4ad7b18c708', 'cable standing back wrist curl', 'cable-standing-back-wrist-curl', 'cable standing back wrist curl using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand facing a cable machine with your feet shoulder-width apart.', 'Hold the cable handle with an overhand grip, palms facing down.', 'Keep your arms straight and your elbows close to your sides.', 'Slowly curl your wrists upward, bringing the cable handle towards your body.', 'Pause for a moment at the top, then slowly lower the cable handle back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/VhX2JdE.gif'),
('01a0baa8-424c-7034-b2e1-836732e94353', 'dumbbell seated biceps curl to shoulder press', 'dumbbell-seated-biceps-curl-to-shoulder-press', 'dumbbell seated biceps curl to shoulder press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a bench with your back straight and feet flat on the ground.', 'Hold a dumbbell in each hand with your palms facing forward and arms fully extended.', 'Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.', 'Once your forearms are vertical, rotate your wrists so that your palms are facing forward.', 'Press the dumbbells overhead until your arms are fully extended.', 'Lower the dumbbells back down to the starting position by reversing the movement.', 'Repeat for the desired number of repetitions.'], 'exercises/OeL23VY.gif'),
('01a0baa8-424c-7034-b2e2-6992ba568cb7', 'back extension on exercise ball', 'back-extension-on-exercise-ball', 'back extension on exercise ball using stability ball.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.', 'Position your hands behind your head or crossed over your chest.', 'Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.', 'Pause for a moment at the top, then slowly lower your upper body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/qLpO4vV.gif'),
('01a0baa8-424c-7034-b2e3-8ea65dca183f', 'dumbbell close grip press', 'dumbbell-close-grip-press', 'dumbbell close grip press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a flat bench with a dumbbell in each hand, resting on your thighs.', 'Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.', 'As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.'], 'exercises/7jGOBF3.gif'),
('01a0baa8-424c-7034-b2e4-3fe8ceb2dd45', 'dumbbell one arm press on exercise ball', 'dumbbell-one-arm-press-on-exercise-ball', 'dumbbell one arm press on exercise ball using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.', 'Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.', 'Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/QZFv5ui.gif'),
('01a0baa8-424c-7034-b2e5-ab14eaefbf60', 'barbell pullover', 'barbell-pullover', 'barbell pullover using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your head at one end and your feet on the floor.', 'Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.', 'Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.', 'Pause for a moment, then raise the barbell back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/i6LWjok.gif'),
('01a0baa8-424c-7034-b2e6-ab8fbe813e3c', 'dumbbell one arm kickback', 'dumbbell-one-arm-kickback', 'dumbbell one arm kickback using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Bring your right elbow up to your side, keeping it bent at a 90-degree angle.', 'Extend your right arm straight back, squeezing your triceps at the top of the movement.', 'Slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch sides.'], 'exercises/bQy2Eni.gif'),
('01a0baa8-424c-7034-b2e7-ebb4765b4749', 'band single leg reverse calf raise', 'band-single-leg-reverse-calf-raise', 'band single leg reverse calf raise using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet hip-width apart and place the band around the ball of your foot.', 'Hold onto a stable object for balance.', 'Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.', 'Pause for a moment at the top, then slowly lower your heel back down to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other leg.'], 'exercises/QsSQWbf.gif'),
('01a0baa8-424c-7034-b2e8-0dbd43da0815', 'one leg donkey calf raise', 'one-leg-donkey-calf-raise', 'one leg donkey calf raise using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, toes pointing forward.', 'Place your hands on a stable surface for support, such as a wall or a bar.', 'Lift one leg off the ground, keeping your knee slightly bent.', 'Raise your heel as high as possible, using your calf muscles.', 'Pause for a moment at the top, then slowly lower your heel back down.', 'Repeat for the desired number of repetitions, then switch legs.'], 'exercises/A2upspL.gif'),
('01a0baa8-424c-7034-b2e9-2681cd0eaa83', 'cable seated crunch', 'cable-seated-crunch', 'cable seated crunch using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Sit on a cable machine with your feet flat on the ground and your knees bent.', 'Hold the cable handle with both hands and position it behind your head.', 'Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.', 'Pause for a moment at the top, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/8xUv4J7.gif'),
('01a0baa8-424c-7034-b2ea-4f2ab62c8d19', 'band lying hip internal rotation', 'band-lying-hip-internal-rotation', 'band lying hip internal rotation using band.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie on your back with your legs straight and a resistance band looped around your feet.', 'Bend your knees and bring them towards your chest, keeping your feet together.', 'Slowly rotate your knees outwards, away from each other, while keeping your feet together.', 'Pause for a moment at the end of the rotation, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vIICElP.gif'),
('01a0baa8-424d-7cbf-90a0-4efe57f59ac2', 'barbell wide reverse grip bench press', 'barbell-wide-reverse-grip-bench-press', 'barbell wide reverse grip bench press using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', 'Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.', 'Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.', 'Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.', 'Pause for a moment when the barbell touches your chest, then push it back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/945zpRg.gif'),
('01a0baa8-424d-7cbf-90a1-3f7ad6b45425', 'cable standing crunch', 'cable-standing-crunch', 'cable standing crunch using cable.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Attach a cable handle to a high pulley and stand facing away from the machine.', 'Hold the handle with both hands and place it behind your head, keeping your elbows bent.', 'Stand with your feet shoulder-width apart and your knees slightly bent.', 'Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.', 'Pause for a moment at the bottom of the movement, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/jpgqxiS.gif'),
('01a0baa8-424d-7cbf-90a2-e17d28b06585', 'calf stretch with rope', 'calf-stretch-with-rope', 'calf stretch with rope using rope.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Stand facing a wall or sturdy object with your feet hip-width apart.', 'Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.', 'Step back with your left foot, keeping your heel on the ground and your leg straight.', 'Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.', 'Hold the stretch for 20-30 seconds, then release.', 'Repeat on the other leg.'], 'exercises/1LVFcEn.gif'),
('01a0baa8-424d-7cbf-90a3-9da5a57977d5', 'sled hack squat', 'sled-hack-squat', 'sled hack squat using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the sled machine to a comfortable position for your height.', 'Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.', 'Hold onto the handles or bars for stability.', 'Lower your body by bending your knees and hips, keeping your back straight and chest up.', 'Continue lowering until your thighs are parallel to the ground or slightly below.', 'Pause for a moment, then push through your heels to raise your body back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/Qa55kX1.gif'),
('01a0baa8-424d-7cbf-90a4-e69811e3d07c', 'shoulder tap push-up', 'shoulder-tap-push-up', 'shoulder tap push-up using body weight.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.', 'Lower your body towards the ground by bending your elbows, keeping them close to your sides.', 'As you push back up, lift your right hand off the ground and tap your left shoulder.', 'Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.', 'Continue alternating shoulder taps with each push-up repetition.', 'Maintain a stable core and avoid excessive hip rotation throughout the exercise.', 'Repeat for the desired number of repetitions.'], 'exercises/qEse6fe.gif'),
('01a0baa8-424d-7cbf-90a5-5f693c5ac1fd', 'dumbbell lunge with bicep curl', 'dumbbell-lunge-with-bicep-curl', 'dumbbell lunge with bicep curl using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.', 'Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.', 'As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.', 'Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.', 'Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.', 'Continue alternating sides for the desired number of repetitions.'], 'exercises/Mz6lLcW.gif'),
('01a0baa8-424d-7cbf-90a6-837174a03c75', 'butterfly yoga pose', 'butterfly-yoga-pose', 'butterfly yoga pose using body weight.', 'MOBILITY', 'INTERMEDIATE', ARRAY['Sit on the floor with your legs extended in front of you.', 'Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.', 'Hold onto your ankles or feet with your hands.', 'Sit up tall and lengthen your spine.', 'Gently press your knees down towards the floor, feeling a stretch in your inner thighs.', 'Hold this position for a few breaths.', 'To release, slowly bring your knees back up and extend your legs.'], 'exercises/bWlZvXh.gif'),
('01a0baa8-424d-7cbf-90a7-abf07a636447', 'barbell reverse grip skullcrusher', 'barbell-reverse-grip-skullcrusher', 'barbell reverse grip skullcrusher using barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', 'Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.', 'Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.', 'Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.', 'Pause for a moment at the bottom, then extend your arms back up to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/yRLPCLu.gif'),
('01a0baa8-424d-7cbf-90a8-b005ff1ec7af', 'dumbbell kickback', 'dumbbell-kickback', 'dumbbell kickback using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, keeping your back straight.', 'Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.', 'Extend your arms straight back, squeezing your triceps at the top of the movement.', 'Pause for a moment, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/W6PxUkg.gif'),
('01a0baa8-424d-7cbf-90a9-78610a162e55', 'sled 45Â° leg press (side pov)', 'sled-45-leg-press-side-pov', 'sled 45Â° leg press (side pov) using sled machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.', 'Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.', 'Grip the handles on the sides of the seat for stability.', 'Push against the footplate to extend your legs, straightening them completely.', 'Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/2Qh2J1e.gif'),
('01a0baa8-424d-7cbf-90aa-58bcf49ff31c', 'dumbbell lying one arm press', 'dumbbell-lying-one-arm-press', 'dumbbell lying one arm press using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.', 'Hold the dumbbell at shoulder level with your palm facing forward.', 'Press the dumbbell upward until your arm is fully extended.', 'Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.', 'Repeat for the desired number of repetitions, then switch to the other arm.'], 'exercises/zGSIWQi.gif'),
('01a0baa8-424d-7cbf-90ab-3686f3f59a6b', 'olympic barbell triceps extension', 'olympic-barbell-triceps-extension', 'olympic barbell triceps extension using olympic barbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.', 'Raise the barbell above your head, fully extending your arms.', 'Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.', 'Pause for a moment, then extend your arms back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/wu5LXwz.gif'),
('01a0baa8-424d-7cbf-90ac-09703a97cff4', 'assisted parallel close grip pull-up', 'assisted-parallel-close-grip-pull-up', 'assisted parallel close grip pull-up using leverage machine.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Adjust the machine to your desired weight and height.', 'Place your hands on the parallel bars with a close grip, palms facing each other.', 'Hang from the bars with your arms fully extended and your feet off the ground.', 'Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.', 'Continue pulling until your chin is above the bars.', 'Pause for a moment at the top, then slowly lower your body back down to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/vrhHa6D.gif'),
('01a0baa8-424d-7cbf-90ad-e63abecadc2e', 'dumbbell standing front raise above head', 'dumbbell-standing-front-raise-above-head', 'dumbbell standing front raise above head using dumbbell.', 'STRENGTH', 'INTERMEDIATE', ARRAY['Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', 'Keep your arms straight and lift the dumbbells in front of you, raising them above your head.', 'Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.', 'Repeat for the desired number of repetitions.'], 'exercises/laVRfDf.gif');
